    <script>
        (function() {
            // === V6 SCANNER ===
            const nodes = document.querySelectorAll(\'.node-v6\');
            const dataP = document.getElementById(\'v6DataPanel\');
            const placeholder = document.getElementById(\'v6Placeholder\');
            const content = document.getElementById(\'v6Content\');
            const tit = document.getElementById(\'v6Title\');
            const desc = document.getElementById(\'v6Desc\');
            const extra = document.getElementById(\'v6Extra\');

            nodes.forEach(n => {
                n.onclick = () => {
                    nodes.forEach(x => x.classList.remove(\'active\'));
                    n.classList.add(\'active\');
                    placeholder.style.display = \'none\';
                    content.style.display = \'block\';
                    tit.innerText = n.dataset.t;
                    desc.innerText = n.dataset.d;
                    extra.innerText = "Nivel Jerárquico: " + n.dataset.id + " | Propiedades detectadas.";
                    console.log("[V6] Analyzing Level " + n.dataset.id);
                };
            });

            // === V6 LAB 1: GAIA ===
            const hIn = document.getElementById(\'v6HIn\');
            const hVal = document.getElementById(\'v6HVal\');
            const lab1Feed = document.getElementById(\'v6Lab1Feed\');
            const ecoIcon = document.getElementById(\'v6EcoIcon\');
            const ecoName = document.getElementById(\'v6EcoName\');

            hIn.oninput = (e) => {
                const v = e.target.value;
                hVal.innerText = v;
                if(v < 30) { ecoIcon.innerText = "🌵"; ecoName.innerText = "ECOSISTEMA ÁRIDO"; }
                else if(v > 70) { ecoIcon.innerText = "🌊"; ecoName.innerText = "ECOSISTEMA MARINO"; }
                else { ecoIcon.innerText = "🌳"; ecoName.innerText = "ECOSISTEMA TEMPLADO"; }
            };

            document.getElementById(\'v6BtnLab1\').onclick = () => {
                const v = parseInt(hIn.value);
                lab1Feed.innerHTML = (v >= 30 && v <= 70) ? \'<span class="v6-feedback-success">✅ ÉXITO: Biosfera estable. El biotopo soporta la biocenosis.</span>\' : \'<span class="v6-feedback-error">❌ COLAPSO: Factor abiótico letal para la población local.</span>\';
            };

            // === V6 LAB 2: SANDBOX ===
            const assembly = document.getElementById(\'v6Assembly\');
            const parts = [];
            document.querySelectorAll(\'.leccion-biologia-niveles-v6 .q-option[draggable]\').forEach(t => {
                t.addEventListener(\'dragstart\', (e) => e.dataTransfer.setData(\'type\', t.dataset.type));
            });
            assembly.addEventListener(\'dragover\', (e) => e.preventDefault());
            assembly.addEventListener(\'drop\', (e) => {
                e.preventDefault();
                const type = e.dataTransfer.getData(\'type\');
                if(!type || parts.includes(type)) return;
                parts.push(type);
                const div = document.createElement(\'div\');
                div.className = \'badge-v6\';
                div.innerText = type.toUpperCase();
                assembly.appendChild(div);
                assembly.querySelector(\'span\').style.display = \'none\';
            });

            document.getElementById(\'v6BtnLab2\').onclick = () => {
                const f = document.getElementById(\'v6Lab2Feed\');
                if(parts.includes(\'dna\') && parts.includes(\'atp\')) {
                    f.innerHTML = \'<span class="v6-feedback-success">✅ VIDA DETECTADA: El Nivel 5 ha emergido con éxito.</span>\';
                } else {
                    f.innerHTML = \'<span class="v6-feedback-error">❌ INERTES: Faltan componentes para la maquinaria celular.</span>\';
                }
            };

            // === V6 QUIZ ENGINE ===
            const quizState = {
                streak: 0,
                mode: \'normal\',
                lastScore: 0,
                timeoutId: null,
                history: []
            };

            const difficultyMap = {
                repaso: { label: \'Repaso\', time: 240, next: \'Refuerza la teoría y vuelve a intentar.\' },
                normal: { label: \'Normal\', time: 180, next: \'Sigue con la práctica guiada.\' },
                reto: { label: \'Reto\', time: 120, next: \'Avanza al módulo desafío.\' }
            };

            const resourceBank = {
                repaso: [
                    [\'Revisión Ley de Liebig\', \'https://es.wikipedia.org/wiki/Ley_de_Liebig\'],
                    [\'Video: Factor limitante\', \'https://www.youtube.com/watch?v=example\']
                ],
                normal: [
                    [\'Ejercicios de ecosistemas\', \'https://www.khanacademy.org/science\'],
                    [\'Caso práctico de cuencas\', \'https://www.nationalgeographic.com/science\']
                ],
                reto: [
                    [\'Investigación avanzada\', \'https://www.sciencedaily.com/news/earth_climate/\'],
                    [\'Simulación de gestión de recursos\', \'https://www.unesco.org\']
                ]
            };

            const quizData = [
                { q: "¿En qué nivel se detectan por primera vez las propiedades de la vida?", a: ["Atómico", "Orgánulo", "Celular", "Molecular"], ok: 2, f: "La célula es la unidad mínima con metabolismo propio." },
                { q: "El conjunto de individuos de una misma especie se denomina:", a: ["Comunidad", "Ecosistema", "Población", "Organismo"], ok: 2, f: "Población: Misma especie, tiempo y espacio." },
                { q: "Si agregamos suelo, agua y clima a una comunidad, obtenemos un:", a: ["Bioma", "Ecosistema", "Biosfera", "Nicho"], ok: 1, f: "Ecosistema = Biocenosis + Biotopo." },
                { q: "Las proteínas y el ADN pertenecen al nivel:", a: ["Atómico", "Molecular", "Celular", "Tisular"], ok: 1, f: "Son biomoléculas complejas." },
                { q: "¿Cuál es el nivel en el que la homeostasis se regula totalmente?", a: ["Celular", "Tisular", "Sistema", "Biosfera"], ok: 2, f: "La homeostasis se gestiona en sistemas de órganos en animales/planta." },
                { q: "¿Un conjunto de comunidades más factores abióticos es:", a: ["Población", "Ecosistema", "Tisular", "Orgánulo"], ok: 1, f: "Ecosistema incluye biocenosis + biotopo." },
                { q: "¿Dónde se encuentra el ADN compacto en eucariotas?", a: ["Orgánulo", "Célula", "Tisular", "Órgano"], ok: 0, f: "El ADN está en el núcleo y mitocondrias (orgánulos)." },
                { q: "¿El metabolito ATP es característica de qué nivel?", a: ["Molecular", "Orgánulo", "Célula", "Sistema"], ok: 2, f: "ATP es biomolécula pero su uso regulado es nivel celular." }
            ];

            const qCont = document.getElementById(\'v6QuizCont\');
            const statusPanel = document.createElement(\'div\');
            statusPanel.id = \'v6QuizStatus\';
            statusPanel.className = \'quiz-status\';
            statusPanel.style.marginTop = \'10px\';
            document.querySelector(\'.evaluation-actions\').appendChild(statusPanel);

            const aiContainer = document.createElement(\'div\');
            aiContainer.id = \'v6AiTutorContainer\';
            aiContainer.className = \'ai-tutor\';
            aiContainer.style.marginTop = \'12px\';
            aiContainer.innerHTML = `<button id="v6AiTutorBtn" class="btn-bio" style="font-size:0.8rem;">🤖 Tutor AI (Generación)</button><div id="v6AiTutorOutput" class="ai-output" style="margin-top:8px; font-size:0.85rem; color:#c8f7ff;"></div>`;
            document.querySelector(\'.evaluation-actions\').appendChild(aiContainer);

            const resourcesContainer = document.createElement(\'div\');
            resourcesContainer.id = \'v6ResourceRecommendations\';
            resourcesContainer.style.marginTop = \'14px\';
            resourcesContainer.innerHTML = \'<h4 style="font-size:14px; margin-bottom:8px; color:#00ffbb;">📚 Recomendaciones</h4><ul id="v6ResourceList" style="padding-left:16px; color:#9be7ff;"></ul>\';
            document.querySelector(\'.evaluation-actions\').appendChild(resourcesContainer);

            function getMode(correct, total) {
                const ratio = total ? correct / total : 0;
                if (ratio < 0.5) return \'repaso\';
                if (ratio < 0.85) return \'normal\';
                return \'reto\';
            }

            function updateQuizStatus() {
                const s = difficultyMap[quizState.mode];
                statusPanel.innerHTML = `<strong>Modo:</strong> ${s.label} | <strong>Racha:</strong> ${quizState.streak} | <strong>Score:</strong> ${quizState.lastScore}% | <strong>Temporizador:</strong> ${s.time}s`;
                if (quizState.timeoutId) clearTimeout(quizState.timeoutId);
                quizState.timeoutId = setTimeout(() => {
                    statusPanel.innerHTML += \' | ⏰ Tiempo completado. Revisa recursos y vuelve a evaluar.\';
                }, s.time * 1000);
            }

            function renderResources(mode) {
                const list = document.getElementById(\'v6ResourceList\');
                list.innerHTML = \'\';
                const recs = resourceBank[mode] || [];
                recs.forEach(([text, href]) => {
                    const li = document.createElement(\'li\');
                    li.innerHTML = `<a href="${href}" target="_blank" style="color:#c4fffd; text-decoration:none;">${text}</a>`;
                    list.appendChild(li);
                });
            }

            function setQuizState(mode) {
                quizState.mode = mode;
                updateQuizStatus();
                const label = document.getElementById(\'v6QuizModeLabel\');
                if (label) {
                    label.textContent = mode.toUpperCase();
                }
            }

            async function fetchAiTutor(correct, total) {
                const out = document.getElementById(\'v6AiTutorOutput\');
                const slug = new URLSearchParams(window.location.search).get(\'slug\') || (window.LC_LECCION_SLUG || \'\');
                if (!slug) {
                    out.innerHTML = \'<p style="color:#ffa;">No se pudo identificar la lección actual.</p>\';
                    return;
                }

                out.innerHTML = \'<p>Generando respuesta del tutor AI local...</p>\';

                try {
                    const resp = await fetch(\'ai_tutor.php\', {
                        method: \'POST\',
                        credentials: \'same-origin\',
                        headers: { \'Content-Type\': \'application/x-www-form-urlencoded\' },
                        body: new URLSearchParams({
                            slug,
                            correctas: correct,
                            total,
                            csrf_token: window.LC_CSRF_TOKEN
                        })
                    });

                    const data = await resp.json();
                    if (!data.ok) {
                        throw new Error(data.error || \'No se obtuvo respuesta de IA\');
                    }

                    const reviewLine = Array.isArray(data.spaced_review) && data.spaced_review.length
                        ? `<p><strong>Repetición espaciada:</strong> ${data.spaced_review.join(\', \')}</p>`
                        : \'\';

                    const errorLine = data.ai_error
                        ? `<p style="color:#ffa; font-size:0.85rem;">Nota: ${data.ai_error}</p>`
                        : \'\';

                    out.innerHTML = `
                        <p><strong>Modo adaptativo:</strong> ${data.mode.toUpperCase()} (${data.difficulty})</p>
                        <p>${data.ai_text}</p>
                        ${reviewLine}
                        <p style="font-size:0.85rem; color:#c8f7ff;">${data.history}</p>
                        ${errorLine}
                    `;
                } catch (err) {
                    out.innerHTML = `<p style="color:#ff9999;">Error tutor AI local: ${err.message}</p>`;
                }
            }

            document.getElementById(\'v6AiTutorBtn\').addEventListener(\'click\', () => {
                const answeredBlocks = document.querySelectorAll(\'.q-v6-block\');
                let correct = 0, total = 0;
                answeredBlocks.forEach(block => {
                    const option = block.querySelector(\'.v6-opt.selected\');
                    if (!option) return;
                    total++;
                    if (option.classList.contains(\'correct\')) correct++;
                });
                fetchAiTutor(correct, total);
            });

            quizData.forEach((q, i) => {
                let h = `<div class="q-v6-block"><p class="q-v6-question">${i+1}. ${q.q}</p>`;
                q.a.forEach((ans, ai) => {
                    h += `<div class="q-option v6-opt" onclick="checkV6(${i}, ${ai})">${ans}</div>`;
                });
                h += `</div>`;
                qCont.innerHTML += h;
            });

            window.checkV6 = (qI, aI) => {
                const block = document.querySelectorAll(\'.q-v6-block\')[qI];
                const opts = block.querySelectorAll(\'.v6-opt\');
                const ok = quizData[qI].ok;
                opts.forEach(o => {
                    o.classList.add(\'disabled\');
                    o.classList.remove(\'selected\');
                });
                opts[aI].classList.add(\'selected\');
                if (aI === ok) {
                    opts[aI].classList.add(\'correct\');
                    opts[aI].setAttribute(\'data-result\', \'correct\');
                } else {
                    opts[aI].classList.add(\'wrong\');
                    opts[ok].classList.add(\'correct\');
                    opts[aI].setAttribute(\'data-result\', \'wrong\');
                }
                block.insertAdjacentHTML(\'beforeend\', `<p class="feedback v6-feedback-info">${quizData[qI].f}</p>`);
            };

            document.getElementById(\'v6BtnEvalQuiz\').onclick = () => {
                const answeredBlocks = document.querySelectorAll(\'.q-v6-block\');
                let correct = 0, wrong = 0;
                answeredBlocks.forEach((block) => {
                    const option = block.querySelector(\'.v6-opt.selected\');
                    if (!option) return;
                    if (option.classList.contains(\'correct\')) correct++; else wrong++;
                });

                const total = answeredBlocks.length;
                const ratio = total ? ((correct / total) * 100).toFixed(0) : 0;
                const mode = getMode(correct, total);
                quizState.mode = mode;
                quizState.lastScore = ratio;
                if (mode === \'reto\') {
                    quizState.streak += 1;
                } else {
                    quizState.streak = 0;
                }
                quizState.history.push({ correct, wrong, total, mode, timestamp: Date.now() });

                setQuizState(mode);
                renderResources(mode);

                const modeHint = mode === \'reto\' ? \'🔥 ¡Modo Reto!\' : mode === \'normal\' ? \'💡 Modo Normal\' : \'🔁 Modo Repaso\';
                let message = `RESULTADO: ${correct}/${total} correctas (${ratio}%). ${modeHint}`;
                if (mode !== \'reto\') message += \' Revisa la sugerencia y vuelve a intentarlo.\';
                document.getElementById(\'v6QuizFinalFeed\').innerText = message;

                if (quizState.streak >= 2) {
                    document.getElementById(\'v6QuizFinalFeed\').innerHTML += `<p style="color:#ffd700;">🎯 Racha x${quizState.streak}! Desafío desbloqueado: intenta 2 preguntas extra en modo Reto.</p>`;
                }

                const s = difficultyMap[mode];
                setTimeout(() => {
                    document.getElementById(\'v6QuizFinalFeed\').innerHTML += \'<p style="color:#66ffdd;">⏱️ Tiempo adaptativo terminado: puedes revisar recursos o reiniciar.</p>\';
                }, s.time * 1000);

                // Mapa de dificultad simple
                const difficultyMapText = `Mapa: Fase Repaso < 50%, Normal 50-85%, Reto > 85%. (Tu nivel: ${s.label})`;
                document.getElementById(\'v6QuizStatus\').innerHTML += `<br>${difficultyMapText}`;
            };

            document.getElementById(\'v6BtnResetQuiz\').onclick = () => {
                document.querySelectorAll(\'.q-v6-block\').forEach((block) => {
                    block.querySelectorAll(\'.v6-opt\').forEach((opt) => {
                        opt.classList.remove(\'disabled\', \'selected\', \'correct\', \'wrong\');
                    });
                    const feedback = block.querySelector(\'p.feedback\');
                    if (feedback) feedback.remove();
                });
                document.getElementById(\'v6QuizFinalFeed\').innerText = \'Evaluación reiniciada. Responde de nuevo para confirmar tu conocimiento.\';
                quizState.mode = \'normal\';
                quizState.streak = 0;
                quizState.lastScore = 0;
                if (quizState.timeoutId) clearTimeout(quizState.timeoutId);
                setQuizState(\'normal\');
                renderResources(\'normal\');
                document.getElementById(\'v6AiTutorOutput\').innerHTML = \'\';
            };

            // Inicializar estado
            setQuizState(\'normal\');
            renderResources(\'normal\');
        })();
    </script>
</div>',
