    'contenido' => '<div class="leccion-ecosistemas-rem">

    <!-- ==================== CABECERA CYBERPUNK ==================== -->
    <div class="rem-header">
        <div class="header-badges">
            <span class="materia-badge">🌍 ECOSISTEMAS</span>
            <span class="nivel-badge">⚡ NIVEL AVANZADO</span>
            <span class="tiempo-badge">⏱️ 55 MIN</span>
        </div>
        <h1 class="titulo-leccion">
            <span class="neon-icon">☀️</span> Radiación Electromagnética
        </h1>
        <p class="leccion-subtitulo">Energía solar • Espectro electromagnético • Fotosíntesis • Impactos ecológicos</p>
    </div>

    <!-- ==================== OBJETIVOS RÁPIDOS ==================== -->
    <div class="objetivos-rapidos">
        <div class="objetivo-card">
            <div class="obj-icon">🎯</div>
            <div class="obj-text">
                <h4>Comprender la naturaleza dual</h4>
                <p>Onda-partícula y su relación con energía y longitud de onda</p>
            </div>
        </div>
        <div class="objetivo-card">
            <div class="obj-icon">📊</div>
            <div class="obj-text">
                <h4>Analizar el espectro</h4>
                <p>Identificar regiones y sus efectos biológicos</p>
            </div>
        </div>
        <div class="objetivo-card">
            <div class="obj-icon">🌿</div>
            <div class="obj-text">
                <h4>Relacionar con ecosistemas</h4>
                <p>Desde fotosíntesis hasta cambio climático</p>
            </div>
        </div>
    </div>

    <!-- ==================== INTRO CONCEPTUAL ==================== -->
    <section class="intro-conceptual">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">⚡</span> La energía que mueve el mundo
        </h2>
        <div class="concept-card">
            <p>La <strong>radiación electromagnética (REM)</strong> es la principal fuente de energía para los ecosistemas terrestres. El Sol emite un espectro continuo que atraviesa la atmósfera, donde parte es absorbido y otra parte llega a la superficie. Solo una fracción estrecha (400-700 nm) es aprovechable para la fotosíntesis, mientras que el resto contribuye al balance térmico o resulta dañina.</p>
            <div class="formula-center">
                \\[ c = \\lambda \\cdot f \\quad \\text{(velocidad de la luz)} \\]
                \\[ E = h \\cdot f = \\frac{h c}{\\lambda} \\quad \\text{(energía del fotón)} \\]
            </div>
            <p>La atmósfera actúa como un filtro: el ozono bloquea los rayos UV más energéticos, y los gases de efecto invernadero retienen el infrarrojo, regulando la temperatura planetaria.</p>
        </div>
    </section>

    <!-- ==================== ESPECTRO INTERACTIVO MEJORADO ==================== -->
    <section class="espectro-interactivo">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">🌈</span> Espectro electromagnético interactivo
        </h2>
        <p>Desliza el cursor sobre la barra espectral o selecciona una región para conocer sus efectos ecológicos.</p>
        <div class="scenario-controls">
            <label>Escenario atmosférico:
                <select id="atmScenario">
                    <option value="normal">Normal (ozono intacto)</option>
                    <option value="ozonoBajo">Baja capa de ozono (más UV-B)</option>
                    <option value="altaCO2">Alto CO₂ (más IR retenido)</option>
                </select>
            </label>
            <button onclick="applyAtmosphere()">Aplicar escenario</button>
            <span id="atmInfo" class="mini-info">Escenario: normal. UV-B limitado.</span>
        </div>
        <div class="spectrum-container">
            <svg id="spectrumSVG" viewBox="0 0 1000 350" style="background:#000; border-radius:16px;">
                <defs>
                    <linearGradient id="specGrad" x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stop-color="#7b1fa2"/>
                        <stop offset="12%" stop-color="#3949ab"/>
                        <stop offset="25%" stop-color="#039be5"/>
                        <stop offset="38%" stop-color="#00bcd4"/>
                        <stop offset="50%" stop-color="#00e676"/>
                        <stop offset="62%" stop-color="#ffee58"/>
                        <stop offset="75%" stop-color="#ff9800"/>
                        <stop offset="88%" stop-color="#f44336"/>
                        <stop offset="100%" stop-color="#b71c1c"/>
                    </linearGradient>
                </defs>
                <rect x="50" y="120" width="900" height="70" fill="url(#specGrad)" stroke="#0ff" stroke-width="3" rx="35"/>
                <text x="80" y="100" fill="#0ff">Gamma</text>
                <text x="180" y="100" fill="#0ff">Rayos X</text>
                <text x="280" y="100" fill="#0ff">UV</text>
                <text x="500" y="100" fill="#ff0" font-weight="bold">Visible</text>
                <text x="700" y="100" fill="#0ff">IR</text>
                <text x="870" y="100" fill="#0ff">Radio</text>
                <circle id="specCursor" cx="500" cy="155" r="12" fill="#ff0" stroke="#000" stroke-width="2"/>
                <text id="specEnergy" x="500" y="200" text-anchor="middle" fill="#ff0">Energía media</text>
            </svg>
            <div id="specInfo" class="spectrum-info"></div>
        </div>
    </section>

    <!-- ==================== DESARROLLO TEÓRICO: TABLA COMPARATIVA ==================== -->
    <section class="tabla-regiones">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">📊</span> Regiones del espectro y sus interacciones biológicas
        </h2>
        <div class="table-wrapper">
            <table class="neon-table">
                <thead>
                    <tr><th>Región</th><th>λ (nm)</th><th>Energía</th><th>Efecto ecológico principal</th></tr>
                </thead>
                <tbody>
                    <tr><td>Gamma</td><td>&lt;0.01</td><td>Muy alta</td><td>Ionización letal; bloqueado por atmósfera</td></tr>
                    <tr><td>Rayos X</td><td>0.01–10</td><td>Alta</td><td>Daño celular grave; filtrado por atmósfera</td></tr>
                    <tr><td>UV-C</td><td>100–280</td><td>Alta</td><td>Absorbido por ozono; letal para organismos</td></tr>
                    <tr><td>UV-B</td><td>280–315</td><td>Media-alta</td><td>Daño ADN, disminuye fotosíntesis</td></tr>
                    <tr><td>UV-A</td><td>315–400</td><td>Media</td><td>Estrés oxidativo, efectos a largo plazo</td></tr>
                    <tr><td>Visible (PAR)</td><td>400–700</td><td>Media</td><td>Fotosíntesis, visión, productividad primaria</td></tr>
                    <tr><td>Infrarrojo</td><td>700–10⁶</td><td>Baja</td><td>Calor, efecto invernadero, termorregulación</td></tr>
                    <tr><td>Microondas/Radio</td><td>&gt;10⁶</td><td>Muy baja</td><td>Comunicación, poco impacto directo</td></tr>
                </tbody>
            </table>
        </div>
    </section>

    <!-- ==================== SIMULADOR: EFICIENCIA FOTOSINTÉTICA ==================== -->
    <section class="simulador-fotosintesis">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">🌿</span> Simulador: Impacto de la REM en la fotosíntesis
        </h2>
        <p>Ajusta las intensidades relativas de UV, visible (PAR) e infrarrojo y observa cómo afecta la producción primaria.</p>
        <div class="photosynth-sim">
            <div class="sliders">
                <label>🌞 UV (280-400 nm): <span id="uvVal">30</span>%</label>
                <input type="range" id="uvSlider" min="0" max="100" value="30">
                <label>🍃 Visible (PAR): <span id="visVal">80</span>%</label>
                <input type="range" id="visSlider" min="0" max="100" value="80">
                <label>🔥 Infrarrojo: <span id="irVal">70</span>%</label>
                <input type="range" id="irSlider" min="0" max="100" value="70">
            </div>
            <div class="meter">
                <div class="meter-fill" id="photoFill"></div>
            </div>
            <div class="stats">
                <span>Tasa fotosintética: <strong id="photoRate">0%</strong></span>
                <div id="photoFeedback" class="feedback-message"></div>
            </div>
        </div>
    </section>

    <!-- ==================== ANIMACIÓN DAÑO UV ==================== -->
    <section class="uv-damage">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">🧬</span> Daño por radiación UV: simulación molecular
        </h2>
        <p>Los fotones UV de alta energía pueden romper enlaces en el ADN, formando dímeros de timina. Observa cómo el daño se acumula.</p>
        <div class="dna-sim">
            <div class="dna-strand">
                <div class="base" style="left:20%">A</div>
                <div class="base" style="left:40%">T</div>
                <div class="base" style="left:60%">G</div>
                <div class="base" style="left:80%">C</div>
            </div>
            <div class="damage-bar">
                <div class="damage-fill" id="dnaDamageFill"></div>
            </div>
            <div class="damage-stats">
                <span>Daño acumulado: <strong id="dnaDamageValue">0</strong>%</span>
                <button onclick="resetDNADamage()">🔄 Reiniciar</button>
            </div>
        </div>
    </section>

    <!-- ==================== ERRORES COMUNES INTERACTIVOS ==================== -->
    <section class="errores-comunes">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">⚠️</span> Errores comunes (¡evítalos!)
        </h2>
        <div class="errores-grid">
            <div class="error-card" onclick="this.classList.toggle(\'expandido\')">
                <strong>❌ Creer que toda la radiación solar es útil para la fotosíntesis</strong>
                <div class="error-detail">Solo la luz visible (400-700 nm) es aprovechable por los pigmentos fotosintéticos. UV e IR no producen fijación de carbono.</div>
            </div>
            <div class="error-card" onclick="this.classList.toggle(\'expandido\')">
                <strong>❌ Confundir efecto térmico del IR con energía fotosintética</strong>
                <div class="error-detail">El IR calienta los tejidos, pero no impulsa la conversión de energía química; la fotosíntesis requiere fotones visibles.</div>
            </div>
            <div class="error-card" onclick="this.classList.toggle(\'expandido\')">
                <strong>❌ Subestimar el rol protector del ozono</strong>
                <div class="error-detail">La capa de ozono absorbe más del 95% de la radiación UV-B/C. Su depleción aumenta el daño genético y reduce la productividad primaria.</div>
            </div>
        </div>
    </section>

    <!-- ==================== CONEXIÓN CURRICULAR ==================== -->
    <section class="curricular">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">📘</span> Vínculo con el programa oficial
        </h2>
        <div class="curricular-content">
            <p><strong>Competencias:</strong> Explica el flujo de energía en los ecosistemas y los efectos de la radiación solar sobre los seres vivos.</p>
            <p><strong>Contenidos:</strong> Espectro electromagnético, radiación solar, fotosíntesis, capa de ozono, efecto invernadero.</p>
            <p><strong>Evaluación:</strong> Interpretación de gráficos de irradiancia, análisis de impactos ambientales y cálculos básicos de energía.</p>
        </div>
    </section>

    <!-- ==================== PROBLEMAS TIPO EXAMEN ==================== -->
    <section class="problemas-examen">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">📝</span> Problemas tipo examen
        </h2>
        <div class="problema-lista">
            <div class="problema-item">
                <h3>Problema 1</h3>
                <p>Explica por qué la luz visible es el principal motor energético de los ecosistemas, mientras que el IR y UV no lo son.</p>
                <button onclick="mostrarSolucion(1)">Ver solución</button>
                <div id="solucion1" style="display:none;">Solución: La luz visible (400-700 nm) es absorbida por los pigmentos fotosintéticos (clorofila, carotenoides) y su energía se transforma en energía química. El IR tiene menor energía por fotón y no puede excitar los electrones de los centros de reacción; el UV es dañino y no es utilizado eficientemente en la fotosíntesis.</div>
            </div>
            <div class="problema-item">
                <h3>Problema 2</h3>
                <p>Predice el impacto ecológico de un aumento del 20% en radiación UV-B debido a depleción de ozono en un ecosistema marino.</p>
                <button onclick="mostrarSolucion(2)">Ver solución</button>
                <div id="solucion2" style="display:none;">Respuesta: El aumento de UV-B reduciría la productividad del fitoplancton (daño en ADN y fotosistemas), disminuyendo la base de la cadena trófica. Esto afectaría a consumidores y pesquerías, además de aumentar la mortalidad de larvas de organismos marinos.</div>
            </div>
            <div class="problema-item">
                <h3>Problema 3</h3>
                <p>Justifica por qué los organismos terrestres han desarrollado pigmentos que absorben principalmente en 400-700 nm.</p>
                <button onclick="mostrarSolucion(3)">Ver solución</button>
                <div id="solucion3" style="display:none;">La evolución seleccionó pigmentos que absorben en el rango de máxima intensidad solar que llega a la superficie y que es menos dañino. Además, los fotones de luz visible tienen la energía adecuada para excitar electrones sin romper enlaces químicos esenciales.</div>
            </div>
        </div>
    </section>

    <!-- ==================== QUIZ AUTOEVALUADO ==================== -->
    <section class="quiz-autoevaluado">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">🧠</span> Quiz de autoevaluación
        </h2>
        <div class="quiz-container">
            <div class="quiz-pregunta">
                <p><strong>1.</strong> ¿Qué región del espectro impulsa directamente la fotosíntesis?</p>
                <label><input type="radio" name="q1" value="a"> UV</label>
                <label><input type="radio" name="q1" value="b"> Luz visible (PAR)</label>
                <label><input type="radio" name="q1" value="c"> Infrarrojo</label>
            </div>
            <div class="quiz-pregunta">
                <p><strong>2.</strong> El aumento de UV-B debido a la depleción de ozono afecta principalmente a:</p>
                <label><input type="radio" name="q2" value="a"> La temperatura global</label>
                <label><input type="radio" name="q2" value="b"> El ADN y la fotosíntesis</label>
                <label><input type="radio" name="q2" value="c"> Las mareas</label>
            </div>
            <div class="quiz-pregunta">
                <p><strong>3.</strong> ¿Qué rol cumple el infrarrojo en los ecosistemas?</p>
                <label><input type="radio" name="q3" value="a"> Es la principal fuente de energía para la fotosíntesis</label>
                <label><input type="radio" name="q3" value="b"> Contribuye al balance térmico y efecto invernadero</label>
                <label><input type="radio" name="q3" value="c"> Es completamente absorbido por la atmósfera sin efectos</label>
            </div>
            <button onclick="evaluateQuiz()">📊 Corregir quiz</button>
            <div id="quizResult" class="quiz-feedback"></div>
        </div>
    </section>

    <!-- ==================== CIERRE METACOGNITIVO ==================== -->
    <section class="cierre">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">🤔</span> Reflexión final
        </h2>
        <div class="reflexion-box">
            <p><strong>Reflexiona sobre tu aprendizaje:</strong></p>
            <ul>
                <li>¿Cómo cambia tu comprensión del flujo energético al saber que solo una fracción estrecha del espectro solar es biológicamente útil?</li>
                <li>¿De qué manera las perturbaciones antropogénicas en la REM (ozono, gases invernadero) afectan la estabilidad ecosistémica?</li>
                <li>¿Qué estrategias usarás para relacionar física de la radiación con procesos ecológicos en futuros exámenes?</li>
            </ul>
            <textarea rows="3" placeholder="Escribe aquí tu reflexión..."></textarea>
        </div>
        <div class="autoevaluacion">
            <h3>📊 Autoevaluación</h3>
            <div class="eval-sliders">
                <div class="eval-item">
                    <span>Comprensión del espectro REM</span>
                    <input type="range" min="1" max="5" value="3" id="eval1" oninput="updateEval(1,this.value)">
                    <span id="evalVal1">3/5</span>
                </div>
                <div class="eval-item">
                    <span>Impactos ecológicos de la radiación</span>
                    <input type="range" min="1" max="5" value="3" id="eval2" oninput="updateEval(2,this.value)">
                    <span id="evalVal2">3/5</span>
                </div>
                <div class="eval-item">
                    <span>Relación con fotosíntesis y clima</span>
                    <input type="range" min="1" max="5" value="3" id="eval3" oninput="updateEval(3,this.value)">
                    <span id="evalVal3">3/5</span>
                </div>
            </div>
            <button onclick="guardarAutoevaluacion()">💾 Guardar autoevaluación</button>
            <div id="autoEvalFeedback" class="auto-feedback"></div>
        </div>
        <div class="recursos">
            <h3>🔗 Recursos adicionales</h3>
            <ul>
                <li><a href="https://earthobservatory.nasa.gov/features/Spectra" target="_blank">NASA: Espectro electromagnético</a></li>
