<!-- ==================== JAVASCRIPT INTERACTIVO ==================== -->
<script>
// ==================== ESPECTRO INTERACTIVO ====================
(function(){
    const svg = document.getElementById("spectrumSVG");
    const cursor = document.getElementById("specCursor");
    const energyLabel = document.getElementById("specEnergy");
    const infoDiv = document.getElementById("specInfo");
    const zones = [
        { xMin: 50, xMax: 150, name: "Rayos Gamma", energy: "Extremadamente alta", desc: "Ionizan átomos; letales para vida; bloqueados por atmósfera." },
        { xMin: 150, xMax: 250, name: "Rayos X", energy: "Muy alta", desc: "Penetran tejidos; causa daño celular grave; filtrados por atmósfera." },
        { xMin: 250, xMax: 350, name: "Ultravioleta", energy: "Alta", desc: "UV-C absorbido por ozono; UV-B daña ADN; UV-A causa estrés oxidativo." },
        { xMin: 350, xMax: 650, name: "Luz visible (PAR)", energy: "Media", desc: "Impulsa fotosíntesis; base de productividad primaria." },
        { xMin: 650, xMax: 800, name: "Infrarrojo", energy: "Baja", desc: "Calor; efecto invernadero; termorregulación." },
        { xMin: 800, xMax: 950, name: "Radio/Microondas", energy: "Muy baja", desc: "Comunicación; poco impacto directo en organismos." }
    ];
    svg.addEventListener("mousemove", (e) => {
        const rect = svg.getBoundingClientRect();
        const scaleX = svg.viewBox.baseVal.width / rect.width;
        let x = (e.clientX - rect.left) * scaleX;
        x = Math.min(950, Math.max(50, x));
        cursor.setAttribute("cx", x);
        const zone = zones.find(z => x >= z.xMin && x <= z.xMax);
        if (zone) {
            energyLabel.textContent = zone.energy;
            energyLabel.setAttribute("x", x);
            infoDiv.innerHTML = `<h4>${zone.name}</h4><p><strong>Energía:</strong> ${zone.energy}</p><p>${zone.desc}</p>`;
        }
    });
})();

function applyAtmosphere() {
    const scenario = document.getElementById(\'atmScenario\').value;
    const atmInfo = document.getElementById(\'atmInfo\');
    let message = \'\';
    if (scenario === \'normal\') {
        message = \'Escenario: Normal. Capa de ozono efectiva, UV-B reducida, IR estable.\';
    } else if (scenario === \'ozonoBajo\') {
        message = \'Escenario: Ozono bajo. Mayor penetración UV-B y UV-C, riesgo mayor de daño genético.\';
    } else if (scenario === \'altaCO2\') {
        message = \'Escenario: Alto CO₂. Mayor absorción de IR, efecto invernadero acentuado, temperatura aumentada.\';
    }
    atmInfo.textContent = message;

    // Efecto visual: ajustar color del cursor según intensidad de UV/IR
    const cursor = document.getElementById(\'specCursor\');
    const spectrum = document.getElementById(\'spectrumSVG\');
    if (scenario === \'ozonoBajo\') {
        cursor.setAttribute(\'fill\', \'#ff6b6b\');
        spectrum.style.filter = \'brightness(1.15) saturate(1.15)\';
    } else if (scenario === \'altaCO2\') {
        cursor.setAttribute(\'fill\', \'#ffc107\');
        spectrum.style.filter = \'hue-rotate(10deg) brightness(1.05)\';
    } else {
        cursor.setAttribute(\'fill\', \'#ff0\');
        spectrum.style.filter = \'none\';
    }
}

// Aplicar escenario por defecto al cargar
applyAtmosphere();

// ==================== SIMULADOR FOTOSÍNTESIS ====================
const uvSlider = document.getElementById("uvSlider");
const visSlider = document.getElementById("visSlider");
const irSlider = document.getElementById("irSlider");
const uvVal = document.getElementById("uvVal");
const visVal = document.getElementById("visVal");
const irVal = document.getElementById("irVal");
const fill = document.getElementById("photoFill");
const rateSpan = document.getElementById("photoRate");
const feedbackDiv = document.getElementById("photoFeedback");

function updatePhotosynthesis() {
    const uv = parseInt(uvSlider.value);
    const vis = parseInt(visSlider.value);
    const ir = parseInt(irSlider.value);
    uvVal.textContent = uv;
    visVal.textContent = vis;
    irVal.textContent = ir;
    let efficiency = vis * 0.9 - uv * 0.4 + ir * 0.1;
    efficiency = Math.max(0, Math.min(100, efficiency));
    fill.style.width = efficiency + "%";
    rateSpan.textContent = Math.round(efficiency) + "%";
    let msg = "";
    if (uv > 60) msg += "⚠️ Alto UV: inhibe fotosíntesis y daña ADN. ";
    if (vis > 70) msg += "✅ Óptima PAR: máxima producción. ";
    if (ir > 80) msg += "🔥 Alto IR: estrés térmico. ";
    if (efficiency < 40) msg += "🌱 Baja productividad ecosistémica.";
    feedbackDiv.textContent = msg || "Condiciones equilibradas para fotosíntesis.";
}
uvSlider.addEventListener("input", updatePhotosynthesis);
visSlider.addEventListener("input", updatePhotosynthesis);
irSlider.addEventListener("input", updatePhotosynthesis);
updatePhotosynthesis();

// ==================== SIMULADOR DAÑO UV ====================
let dnaDamage = 0;
const dnaFill = document.getElementById("dnaDamageFill");
const dnaValue = document.getElementById("dnaDamageValue");
function addDamage() {
    dnaDamage = Math.min(100, dnaDamage + Math.random() * 8);
    dnaFill.style.width = dnaDamage + "%";
    dnaValue.textContent = Math.floor(dnaDamage);
    // Efecto visual en las bases
    document.querySelectorAll(".base").forEach(base => {
        base.style.backgroundColor = `rgba(255,0,0,${dnaDamage/100})`;
    });
}
window.resetDNADamage = function() {
    dnaDamage = 0;
    dnaFill.style.width = "0%";
    dnaValue.textContent = "0";
    document.querySelectorAll(".base").forEach(base => {
        base.style.backgroundColor = "rgba(0,255,255,0.2)";
    });
};
setInterval(addDamage, 1500);

// ==================== QUIZ ====================
function evaluateQuiz() {
    let score = 0;
    if (document.querySelector(\'input[name="q1"]:checked\')?.value === "b") score++;
    if (document.querySelector(\'input[name="q2"]:checked\')?.value === "b") score++;
    if (document.querySelector(\'input[name="q3"]:checked\')?.value === "b") score++;
    const resultDiv = document.getElementById("quizResult");
    if (score === 3) resultDiv.innerHTML = \'<span class="success">🎉 ¡Excelente! 3/3. Dominas la radiación electromagnética.</span>\';
    else resultDiv.innerHTML = `<span class="error">📘 Tienes ${score}/3. Revisa el espectro y sus efectos ecológicos.</span>`;
}

// ==================== AUTOEVALUACIÓN ====================
function updateEval(num, val) {
    document.getElementById(`evalVal${num}`).innerText = val + "/5";
}
function guardarAutoevaluacion() {
    const v1 = document.getElementById(\'eval1\').value;
    const v2 = document.getElementById(\'eval2\').value;
    const v3 = document.getElementById(\'eval3\').value;
    const promedio = ((parseInt(v1)+parseInt(v2)+parseInt(v3))/3).toFixed(1);
    document.getElementById(\'autoEvalFeedback\').innerHTML = `📊 Autoevaluación guardada. Promedio: ${promedio}/5. ¡Sigue explorando!`;
}

// ==================== SOLUCIONES PROBLEMAS ====================
function mostrarSolucion(num) {
    const div = document.getElementById(`solucion${num}`);
    if (div.style.display === "none") div.style.display = "block";
    else div.style.display = "none";
}
</script>
