    'slug' => 'movimientos-tierra',
    'titulo' => 'Movimientos de la Tierra: El Ritmo Cósmico que Moldea Clima, Estaciones y Vida',
    'contenido' => '<div class="leccion-movimientos-tierra">

    <!-- ==================== CABECERA CYBERPUNK ==================== -->
    <div class="earth-header">
        <div class="header-badges">
            <span class="materia-badge">🌍 ECOSISTEMAS</span>
            <span class="nivel-badge">⚡ NIVEL AVANZADO</span>
            <span class="tiempo-badge">⏱️ 50 MIN</span>
        </div>
        <h1 class="titulo-leccion">
            <span class="neon-icon">🌍</span> Movimientos de la Tierra
        </h1>
        <p class="leccion-subtitulo">Rotación • Traslación • Inclinación axial • Ciclos de Milankovitch</p>
    </div>

    <!-- ==================== OBJETIVOS RÁPIDOS ==================== -->
    <div class="objetivos-rapidos">
        <div class="objetivo-card">
            <div class="obj-icon">🎯</div>
            <div class="obj-text">
                <h4>Comprender los movimientos</h4>
                <p>Rotación, traslación, precesión y nutación</p>
            </div>
        </div>
        <div class="objetivo-card">
            <div class="obj-icon">🌡️</div>
            <div class="obj-text">
                <h4>Explicar las estaciones</h4>
                <p>Rol de la inclinación axial y distribución solar</p>
            </div>
        </div>
        <div class="objetivo-card">
            <div class="obj-icon">❄️</div>
            <div class="obj-text">
                <h4>Analizar ciclos glaciales</h4>
                <p>Ciclos de Milankovitch y su impacto ecológico</p>
            </div>
        </div>
    </div>

    <!-- ==================== CONTEXTO REAL ==================== -->
    <section class="contexto-real">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">🌎</span> Contexto real
        </h2>
        <div class="context-card">
            <p>Los movimientos de la Tierra determinan la cantidad y distribución de energía solar que recibe cada región, dando lugar a climas diferenciados, estaciones del año, ritmos biológicos (circadianos, migraciones, floraciones) y ciclos glaciales que han moldeado la evolución de las especies. Comprenderlos es esencial para explicar desde la fenología hasta el cambio climático actual.</p>
            <div class="real-data">
                <span class="data-tag">🌞 Fenología</span>
                <span class="data-tag">🐦 Migraciones</span>
                <span class="data-tag">❄️ Glaciaciones</span>
            </div>
        </div>
    </section>

    <!-- ==================== DESARROLLO TEÓRICO ==================== -->
    <section class="desarrollo-teorico">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">📚</span> Principales movimientos de la Tierra
        </h2>

        <div class="table-wrapper">
            <table class="neon-table">
                <thead>
                    <tr><th>Movimiento</th><th>Periodo</th><th>Efecto físico</th><th>Impacto ecológico</th></tr>
                </thead>
                <tbody>
                    <tr><td>Rotación</td><td>23 h 56 min</td><td>Día/noche</td><td>Ritmos circadianos, fotosíntesis diaria</td></tr>
                    <tr><td>Traslación + inclinación axial</td><td>365.25 días</td><td>Estaciones</td><td>Fenología, migraciones, reproducción</td></tr>
                    <tr><td>Precesión</td><td>≈ 25 772 años</td><td>Desplazamiento equinoccios</td><td>Ciclos glaciales (Milankovitch)</td></tr>
                    <tr><td>Nutación</td><td>18.6 años</td><td>Oscilación axial</td><td>Ajustes en modelos paleoclimáticos</td></tr>
                </tbody>
            </table>
        </div>

        <h3 class="subsection-title">🌞 Rotación: el pulso diario</h3>
        <p>La rotación sobre el eje inclinado (23.44°) genera alternancia día-noche, creando ciclos de luz y temperatura que regulan procesos fisiológicos: ritmos circadianos, apertura estomática, patrones de actividad animal.</p>

        <h3 class="subsection-title">🌍 Traslación e inclinación axial: las estaciones</h3>
        <p>La órbita elíptica combinada con la inclinación axial causa variación estacional en la insolación. <strong>¡Importante!</strong> Las estaciones no se deben a cambios en la distancia Tierra-Sol (variación < 3%), sino al ángulo de incidencia y duración del día.</p>
        <div class="formula-center">
            \\[ \\text{Oblicuidad} = 23.44^\\circ \\]
        </div>

        <h3 class="subsection-title">🔄 Precesión y nutación: ciclos largos (Milankovitch)</h3>
        <p>Los ciclos de Milankovitch explican la alternancia entre periodos glaciales e interglaciares:</p>
        <ul class="neon-list">
            <li><strong>Precesión:</strong> 26 000 años (desplazamiento de los equinoccios)</li>
            <li><strong>Oblicuidad:</strong> 41 000 años (variación de la inclinación axial)</li>
            <li><strong>Excentricidad:</strong> 100 000 años (forma de la órbita)</li>
        </ul>
        <p>Estos cambios modulan la insolación estacional en altas latitudes, desencadenando avances y retrocesos glaciares.</p>
    </section>

    <!-- ==================== SIMULADOR INTERACTIVO MEJORADO ==================== -->
    <section class="simulador-orbital">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">🪐</span> Simulador: Efecto de la inclinación axial y ciclos de Milankovitch
        </h2>
        <p>Ajusta la inclinación axial y la intensidad de los ciclos de Milankovitch para observar cambios en las estaciones y el clima global.</p>
        <div class="orbital-sim">
            <div class="control-panel">
                <label>Inclinación axial: <span id="tiltValue">23.44</span>°</label>
                <input type="range" id="tiltSlider" min="0" max="90" value="23.44" step="0.1">
                <label>Intensidad ciclos Milankovitch: <span id="milankValue">50</span>%</label>
                <input type="range" id="milankSlider" min="0" max="100" value="50">
                <label>Velocidad orbital: <span id="speedValue">1.0</span>x</label>
                <input type="range" id="speedSlider" min="0" max="3" value="1" step="0.1">
            </div>
            <div class="orbit-visual">
                <svg id="orbitSVG" viewBox="0 0 900 500">
                    <circle cx="450" cy="250" r="45" fill="#ffb300" filter="url(#glowSun)"/>
                    <ellipse cx="450" cy="250" rx="300" ry="180" fill="none" stroke="#0ff" stroke-width="3" stroke-dasharray="8 6"/>
                    <g id="earthGroup">
                        <circle r="22" fill="#2196f3"/>
                        <line id="axisLine" x1="0" y1="-35" x2="0" y2="35" stroke="#ff00ff" stroke-width="5"/>
                    </g>
                </svg>
                <div class="sim-feedback" id="simFeedback"></div>
            </div>
        </div>
    </section>

    <!-- ==================== DIAGRAMA DE INSOLACIÓN ==================== -->
    <section class="insolacion">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">📈</span> Insolación estacional según latitud
        </h2>
        <p>La inclinación axial determina la energía solar que recibe cada hemisferio a lo largo del año.</p>
        <canvas id="insolationCanvas" width="800" height="300" style="background:#000; border-radius:16px;"></canvas>
    </section>

    <!-- ==================== ERRORES COMUNES INTERACTIVOS ==================== -->
    <section class="errores-comunes">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">⚠️</span> Errores comunes (¡evítalos!)
        </h2>
        <div class="errores-grid">
            <div class="error-card" onclick="this.classList.toggle(\'expandido\')">
                <strong>❌ Creer que las estaciones se deben a la distancia Tierra-Sol</strong>
                <div class="error-detail">La variación de distancia es solo del 3%. La causa real es la inclinación axial y la duración del día.</div>
            </div>
            <div class="error-card" onclick="this.classList.toggle(\'expandido\')">
                <strong>❌ Confundir día sideral con día solar</strong>
                <div class="error-detail">Día sideral: 23h56min (respecto estrellas). Día solar: 24h (respecto Sol).</div>
            </div>
            <div class="error-card" onclick="this.classList.toggle(\'expandido\')">
                <strong>❌ Ignorar el rol de la precesión en ciclos glaciales</strong>
                <div class="error-detail">La precesión, junto con la oblicuidad y excentricidad, forma parte de los ciclos de Milankovitch.</div>
            </div>
        </div>
    </section>

    <!-- ==================== CONEXIÓN CURRICULAR ==================== -->
    <section class="curricular">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">📘</span> Vínculo con el programa oficial
        </h2>
        <div class="curricular-content">
            <p><strong>Competencias:</strong> Explica los movimientos de la Tierra y sus consecuencias en la distribución de la energía solar, el clima y los ecosistemas.</p>
            <p><strong>Contenidos:</strong> Rotación, traslación, inclinación axial, estaciones, ciclos de Milankovitch, ritmos biológicos.</p>
            <p><strong>Evaluación:</strong> Identificación de causas de las estaciones, análisis de gráficos de insolación, interpretación de ciclos paleoclimáticos.</p>
        </div>
    </section>

    <!-- ==================== PROBLEMAS TIPO EXAMEN ==================== -->
    <section class="problemas-examen">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">📝</span> Problemas tipo examen
        </h2>
        <div class="problema-lista">
            <div class="problema-item">
                <h3>Problema 1</h3>
                <p>Explica por qué en el hemisferio sur el verano ocurre cuando la Tierra está más cerca del Sol (perihelio).</p>
                <button onclick="mostrarSolucion(1)">Ver solución</button>
                <div id="solucion1" style="display:none;">El perihelio ocurre alrededor del 4 de enero. En esa fecha, el hemisferio sur está inclinado hacia el Sol, recibiendo más radiación a pesar de la menor distancia; el efecto de la inclinación domina sobre la distancia.</div>
            </div>
            <div class="problema-item">
                <h3>Problema 2</h3>
                <p>Predice las consecuencias ecológicas si la inclinación axial fuera 0°.</p>
                <button onclick="mostrarSolucion(2)">Ver solución</button>
                <div id="solucion2" style="display:none;">No habría estaciones. La luz solar sería constante durante todo el año en cada latitud, eliminando ritmos estacionales (floración, migraciones, hibernación). Los ecosistemas se homogeneizarían, reduciendo la biodiversidad.</div>
            </div>
            <div class="problema-item">
                <h3>Problema 3</h3>
                <p>Relaciona los ciclos de Milankovitch con la alternancia de periodos glaciales e interglaciares en el Cuaternario.</p>
                <button onclick="mostrarSolucion(3)">Ver solución</button>
                <div id="solucion3" style="display:none;">Las variaciones en excentricidad, oblicuidad y precesión modifican la insolación estacional en latitudes altas, desencadenando avances o retrocesos glaciares. Los mínimos de insolación estival favorecen la acumulación de hielo, dando lugar a glaciaciones.</div>
            </div>
        </div>
    </section>

    <!-- ==================== QUIZ AUTOEVALUADO ==================== -->
    <section class="quiz-autoevaluado">
