<!-- ==================== JAVASCRIPT INTERACTIVO ==================== -->
<script>
// ==================== SIMULADOR ORBITAL ====================
const earthGroup = document.getElementById("earthGroup");
const axisLine = document.getElementById("axisLine");
const tiltSlider = document.getElementById("tiltSlider");
const tiltValue = document.getElementById("tiltValue");
const milankSlider = document.getElementById("milankSlider");
const milankValue = document.getElementById("milankValue");
const speedSlider = document.getElementById("speedSlider");
const speedValue = document.getElementById("speedValue");
const feedbackDiv = document.getElementById("simFeedback");

let angle = 0;
let speed = 1;

function updateSimulation() {
    const tilt = parseFloat(tiltSlider.value);
    const milank = parseFloat(milankSlider.value);
    tiltValue.textContent = tilt.toFixed(1);
    milankValue.textContent = milank;
    axisLine.setAttribute("transform", `rotate(${tilt})`);

    let climate = "";
    if (tilt < 10) climate = "🌍 Inclinación baja: estaciones casi inexistentes. Climas ecuatoriales globales.";
    else if (tilt > 40) climate = "🔥 Inclinación alta: estaciones extremas, polos con 6 meses de luz/oscuridad.";
    else climate = "🌿 Inclinación moderada: estaciones bien marcadas, zonas templadas biodiversas.";

    if (milank < 30) climate += "  Periodo interglacial cálido.";
    if (milank > 70) climate += "  Era glacial: expansión de casquetes polares.";

    feedbackDiv.textContent = climate;
}

function animate() {
    speed = parseFloat(speedSlider.value) || 1;
    speedValue.textContent = speed.toFixed(1);
    angle += 0.003 * speed;
    const x = 450 + 280 * Math.cos(angle);
    const y = 250 + 160 * Math.sin(angle);
    earthGroup.setAttribute("transform", `translate(${x},${y})`);
    requestAnimationFrame(animate);
}

tiltSlider.addEventListener("input", updateSimulation);
milankSlider.addEventListener("input", updateSimulation);
speedSlider.addEventListener("input", () => { speed = parseFloat(speedSlider.value); speedValue.textContent = speed.toFixed(1); });
updateSimulation();
animate();

// ==================== INSOLACIÓN ====================
const canvas = document.getElementById("insolationCanvas");
if (canvas) {
    const ctx = canvas.getContext("2d");
    function drawInsolation() {
        const width = canvas.width, height = canvas.height;
        ctx.clearRect(0, 0, width, height);
        ctx.strokeStyle = "#0ff";
        ctx.fillStyle = "#0ff";
        ctx.font = "12px monospace";
        // Ejes
        ctx.beginPath();
        ctx.moveTo(50, 20); ctx.lineTo(50, height-30); ctx.lineTo(width-30, height-30);
        ctx.stroke();
        ctx.fillText("Latitud", width-50, height-15);
        ctx.save();
        ctx.translate(25, 150);
        ctx.rotate(-Math.PI/2);
        ctx.fillText("Insolación relativa", 0, 0);
        ctx.restore();

        // Curvas para solsticios y equinoccios
        const latitudes = [];
        for (let lat = -90; lat <= 90; lat += 5) {
            latitudes.push(lat);
        }
        const solsticeJune = latitudes.map(lat => Math.max(0, Math.cos((lat-23.44)*Math.PI/180)));
        const solsticeDec = latitudes.map(lat => Math.max(0, Math.cos((lat+23.44)*Math.PI/180)));
        const equinox = latitudes.map(lat => Math.max(0, Math.cos(lat*Math.PI/180)));

        function drawCurve(data, color, label, yOffset) {
            ctx.beginPath();
            ctx.strokeStyle = color;
            for (let i=0; i<data.length; i++) {
                let x = 50 + (latitudes[i] + 90) / 180 * (width-80);
                let y = height-30 - data[i] * (height-60);
                if (i===0) ctx.moveTo(x,y);
                else ctx.lineTo(x,y);
            }
            ctx.stroke();
            ctx.fillStyle = color;
            ctx.fillText(label, width-100, yOffset);
        }

        drawCurve(solsticeJune, "#ff6b6b", "Solsticio junio (verano NH)", 30);
        drawCurve(solsticeDec, "#6bff6b", "Solsticio diciembre (invierno NH)", 50);
        drawCurve(equinox, "#ffff6b", "Equinoccios", 70);
    }
    drawInsolation();
    window.addEventListener("resize", drawInsolation);
}

// ==================== QUIZ ====================
function evaluateQuiz() {
    let score = 0;
    if (document.querySelector(\'input[name="q1"]:checked\')?.value === "b") score++;
    if (document.querySelector(\'input[name="q2"]:checked\')?.value === "b") score++;
    if (document.querySelector(\'input[name="q3"]:checked\')?.value === "a") score++;
    const resultDiv = document.getElementById("quizResult");
    if (score === 3) resultDiv.innerHTML = \'<span class="success">🎉 ¡Excelente! 3/3. Dominas los movimientos terrestres.</span>\';
    else resultDiv.innerHTML = `<span class="error">📘 Tienes ${score}/3. Revisa la inclinación axial y los ciclos de Milankovitch.</span>`;
}

// ==================== AUTOEVALUACIÓN ====================
function updateEval(num, val) {
    document.getElementById(`evalVal${num}`).innerText = val + "/5";
}
function guardarAutoevaluacion() {
    const v1 = document.getElementById(\'eval1\').value;
    const v2 = document.getElementById(\'eval2\').value;
    const v3 = document.getElementById(\'eval3\').value;
    const promedio = ((parseInt(v1)+parseInt(v2)+parseInt(v3))/3).toFixed(1);
    document.getElementById(\'autoEvalFeedback\').innerHTML = `📊 Autoevaluación guardada. Promedio: ${promedio}/5. ¡Sigue explorando!`;
}

// ==================== SOLUCIONES PROBLEMAS ====================
function mostrarSolucion(num) {
    const div = document.getElementById(`solucion${num}`);
    if (div.style.display === "none") div.style.display = "block";
    else div.style.display = "none";
}
</script>
