    'contenido' => '
<div class="leccion-respiracion" role="main" aria-label="Lección: Respiración Celular">
    <!-- CABECERA CYBERPUNK -->
    <header class="resp-header">
        <div class="header-badges">
            <span class="materia-badge">⚡ ECOSISTEMAS</span>
            <span class="nivel-badge">🧬 NIVEL AVANZADO</span>
            <span class="tiempo-badge">⏱️ 60 MIN</span>
        </div>
        <h1 class="titulo-leccion"><span class="neon-icon">🔥</span> Respiración Celular</h1>
        <p class="leccion-subtitulo">De la glucosa al ATP: la danza molecular que sostiene la vida</p>
    </header>

    <!-- OBJETIVOS CYBERPUNK -->
    <section class="objetivos-grid">
        <div class="obj-card"><div class="obj-icon">🎯</div><div><strong>Comprender</strong> las etapas y su lógica energética.</div></div>
        <div class="obj-card"><div class="obj-icon">⚡</div><div><strong>Comparar</strong> respiración aeróbica y fermentación.</div></div>
        <div class="obj-card"><div class="obj-icon">🧬</div><div><strong>Relacionar</strong> con el flujo de energía en ecosistemas.</div></div>
        <div class="obj-card"><div class="obj-icon">🦾</div><div><strong>Aplicar</strong> el conocimiento en simulaciones y retos gamificados.</div></div>
        <div class="obj-card"><div class="obj-icon">🔬</div><div><strong>Explorar</strong> aplicaciones biotecnológicas y médicas.</div></div>
        <div class="obj-card"><div class="obj-icon">📜</div><div><strong>Conectar</strong> con la historia y evolución del concepto.</div></div>
    </section>

    <!-- INTRODUCCIÓN MOTIVADORA Y CONTEXTO HISTÓRICO -->
    <section class="seccion">
        <h2>🌌 ¿Por qué importa?</h2>
        <p>Imagina una ciudad cyberpunk: luces, movimiento, energía. Cada célula es una metrópolis viva, y la <strong>respiración celular</strong> es su planta de energía. Sin ella, no hay vida, solo oscuridad molecular.</p>
        <ul class="ejemplos-reales">
            <li>🏃‍♂️ <strong>Movimiento</strong>: tus músculos usan ATP generado aquí.</li>
            <li>🧠 <strong>Pensamiento</strong>: tu cerebro consume el 20% de tu energía.</li>
            <li>🌱 <strong>Ciclo del carbono</strong>: conecta la vida con la atmósfera.</li>
            <li>🦠 <strong>Biotecnología</strong>: la respiración celular es clave en la producción de fármacos y biocombustibles.</li>
        </ul>
        <blockquote class="definicion">La respiración celular transforma la energía química de la glucosa en ATP, la moneda energética universal.</blockquote>
        <div class="concept-box">
            <strong>Historia:</strong> El concepto de respiración celular evolucionó desde las primeras observaciones de Pasteur sobre la fermentación hasta la elucidación de la cadena de transporte de electrones en el siglo XX.
        </div>
    </section>

    <!-- DESARROLLO TEÓRICO Y VISUAL -->
    <section class="seccion">
        <h2>📚 Etapas y lógica energética</h2>
        <div class="teoria-grid">
            <div class="card-concepto">
                <h3>Glicólisis</h3>
                <p>Ocurre en el citosol. Rompe la glucosa (6C) en 2 piruvatos (3C). Produce 2 ATP y 2 NADH. Es universal y puede funcionar sin oxígeno.</p>
            </div>
            <div class="card-concepto">
                <h3>Ciclo de Krebs</h3>
                <p>En la matriz mitocondrial. Cada piruvato se convierte en CO₂, generando NADH, FADH₂ y 2 ATP. Es el centro metabólico de la célula.</p>
            </div>
            <div class="card-concepto">
                <h3>Cadena de transporte de electrones (ETC)</h3>
                <p>En la membrana interna mitocondrial. Los electrones de NADH y FADH₂ crean un gradiente de H⁺, que impulsa la <strong>ATP sintasa</strong> para producir hasta 34 ATP. El O₂ es el aceptor final y se convierte en agua.</p>
            </div>
        </div>
        <div class="formula-center">
            <p>Ecuación global:</p>
            <span>\\( \\ce{C6H12O6 + 6O2 -> 6CO2 + 6H2O + 36-38 ATP} \\)</span>
        </div>
        <div class="table-wrapper">
            <table class="neon-table">
                <thead><tr><th>Etapa</th><th>Ubicación</th><th>ATP neto</th></tr></thead>
                <tbody>
                    <tr><td>Glicólisis</td><td>Citosol</td><td>2</td></tr>
                    <tr><td>Ciclo de Krebs</td><td>Matriz mitocondrial</td><td>2</td></tr>
                    <tr><td>Cadena de electrones</td><td>Membrana interna</td><td>32–34</td></tr>
                </tbody>
                <tfoot><tr><td colspan="2"><strong>Total aeróbica</strong></td><td><strong>36–38</strong></td></tr></tfoot>
            </table>
        </div>
        <div class="concept-box">
            <strong>Dato Cyberpunk:</strong> La eficiencia de la respiración celular supera a la de la mayoría de las baterías modernas. ¡La mitocondria es la "batería" biológica definitiva!
        </div>
    </section>

    <!-- VISUALIZACIÓN INTERACTIVA: MITOCONDRIA CYBERPUNK -->
    <section class="seccion">
        <h2>🖼️ Diagrama interactivo: Mitocondria Cyberpunk</h2>
        <div class="svg-mito-flex">
            <div class="svg-container">
                <svg id="mitoSVG" viewBox="0 0 900 400" aria-label="Diagrama de mitocondria" tabindex="0" style="background:#000;min-width:340px;min-height:300px;"></svg>
            </div>
            <div id="mitoInfoPanel" class="mito-info-panel">
                <h3 id="mitoInfoTitle">Mitocondria</h3>
                <div id="mitoInfoText">Selecciona una etapa para ver su función.</div>
            </div>
        </div>
        <p class="caption">Haz clic o usa Tab/Enter sobre cada etapa para ver su función. Si no ves el diagrama, revisa el brillo de tu pantalla o el modo oscuro.</p>
    </section>

    <!-- SIMULADOR AVANZADO: ATP, INHIBIDORES Y FERMENTACIÓN -->
    <section class="seccion">
        <h2>⚙️ Simulador avanzado: ATP, inhibidores y fermentación</h2>
        <div class="resp-sim">
            <div class="control-panel">
                <label for="oxygenSelect">Oxígeno:</label>
                <select id="oxygenSelect">
                    <option value="high">Alto (aeróbica)</option>
                    <option value="low">Bajo (fermentación láctica)</option>
                    <option value="none">Nulo (fermentación alcohólica)</option>
                </select>
                <label for="inhibitorSelect">Inhibidor:</label>
                <select id="inhibitorSelect">
                    <option value="none">Ninguno</option>
                    <option value="cyanide">Cianuro</option>
                    <option value="oligomycin">Oligomicina</option>
                </select>
                <button onclick="runSimulation()">Simular</button>
            </div>
            <div class="atp-meter">
                <div class="meter-track"><div id="atpFill" class="meter-fill"></div></div>
                <div class="meter-labels"><span>0 ATP</span><span id="atpValue">0 ATP</span><span>38 ATP</span></div>
            </div>
            <div id="simResult" class="sim-result"></div>
        </div>
    </section>

    <!-- ANIMACIÓN ETC (CANVAS) -->
    <section class="seccion">
        <h2>🔋 Animación: Cadena de Transporte de Electrones</h2>
        <div class="etc-canvas-container">
            <canvas id="etcCanvas" width="600" height="180" aria-label="Animación ETC" tabindex="0"></canvas>
            <div class="etc-info">
                <span>Electrones: <span id="electronCount">0</span></span>
                <span>Protones: <span id="protonCount">0</span></span>
            </div>
        </div>
        <div class="sim-legend">
            <span class="legend-box" style="background:#ff0;"></span> Electrón
            <span class="legend-box" style="background:#0ff;"></span> Protón
        </div>
    </section>

    <!-- GLOSARIO INTERACTIVO -->
    <section class="seccion">
        <h2>📖 Glosario interactivo</h2>
        <ul class="glosario-lista">
            <li tabindex="0"><strong>ATP:</strong> Adenosín trifosfato, la molécula energética universal.</li>
            <li tabindex="0"><strong>NADH/FADH₂:</strong> Transportadores de electrones generados en glicólisis y Krebs.</li>
            <li tabindex="0"><strong>Fermentación:</strong> Proceso anaeróbico que permite la producción limitada de ATP.</li>
            <li tabindex="0"><strong>ATP sintasa:</strong> Enzima que sintetiza ATP usando el gradiente de protones.</li>
            <li tabindex="0"><strong>Gradiente de protones:</strong> Diferencia de concentración de H⁺ a través de la membrana mitocondrial.</li>
        </ul>
    </section>

    <!-- LOGROS Y GAMIFICACIÓN -->
    <section class="seccion">
        <h2>🏆 Logros desbloqueados</h2>
        <ul class="logros-lista">
            <li id="logro1" class="logro">🔓 <strong>Primer Simulador:</strong> Usaste el simulador de ATP.</li>
            <li id="logro2" class="logro">🔓 <strong>Animación ETC:</strong> Observaste la animación de electrones.</li>
            <li id="logro3" class="logro">🔓 <strong>Quiz Perfecto:</strong> Obtuviste 5/5 en el quiz.</li>
        </ul>
    </section>

    <!-- QUIZ AUTOEVALUADO -->
    <section class="quiz-autoevaluado">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">🧠</span> Quiz de autoevaluación
        </h2>
        <div class="quiz-container">
            <div class="quiz-pregunta">
                <p><strong>1.</strong> ¿Dónde ocurre la glicólisis?</p>
                <label><input type="radio" name="q1" value="a"> Mitocondria</label>
                <label><input type="radio" name="q1" value="b"> Citosol</label>
                <label><input type="radio" name="q1" value="c"> Núcleo</label>
            </div>
            <div class="quiz-pregunta">
                <p><strong>2.</strong> El NADH se genera principalmente en:</p>
                <label><input type="radio" name="q2" value="a"> Solo glicólisis</label>
                <label><input type="radio" name="q2" value="b"> Solo ciclo de Krebs</label>
                <label><input type="radio" name="q2" value="c"> Glicólisis y Krebs</label>
            </div>
            <div class="quiz-pregunta">
                <p><strong>3.</strong> Rendimiento ATP en fermentación láctica:</p>
                <label><input type="radio" name="q3" value="a"> 2</label>
                <label><input type="radio" name="q3" value="b"> 36</label>
                <label><input type="radio" name="q3" value="c"> 0</label>
            </div>
            <div class="quiz-pregunta">
                <p><strong>4.</strong> El aceptor final de electrones en la respiración aeróbica es:</p>
                <label><input type="radio" name="q4" value="a"> CO₂</label>
                <label><input type="radio" name="q4" value="b"> O₂</label>
                <label><input type="radio" name="q4" value="c"> NAD⁺</label>
            </div>
            <div class="quiz-pregunta">
