<script>
// ========== DIAGRAMA INTERACTIVO MITOCONDRIA CYBERPUNK ==========
document.addEventListener("DOMContentLoaded", function() {
    const svg = document.getElementById("mitoSVG");
    if (!svg) return;
    // Limpia SVG
    svg.innerHTML = "";
    // Dibuja la mitocondria (forma, membranas, etapas)
    // Cuerpo principal
    svg.innerHTML += `<ellipse cx="450" cy="200" rx="340" ry="140" fill="#111" stroke="#39ff14" stroke-width="5" filter="url(#glow)" />`;
    // Membrana interna (ondulada)
    let cristae = \'\';
    for (let i = 0; i < 6; i++) {
        let y = 120 + i*40;
        cristae += `<path d="M170,${y} Q300,${y+30} 450,${y} Q600,${y-30} 730,${y}" stroke="#0ff" stroke-width="4" fill="none" opacity="0.7"/>`;
    }
    svg.innerHTML += cristae;
    // Etapas (círculos interactivos)
    const etapas = [
        {cx: 250, cy: 200, r: 38, color: \'#ff44ff\', label: \'Glicólisis\', key: \'glicolisis\', desc: \'Ocurre en el citosol. Rompe glucosa en 2 piruvatos.\'},
        {cx: 450, cy: 120, r: 38, color: \'#00e676\', label: \'Krebs\', key: \'krebs\', desc: \'En la matriz mitocondrial. Genera NADH, FADH₂ y CO₂.\'},
        {cx: 650, cy: 200, r: 38, color: \'#00bcd4\', label: \'ETC\', key: \'etc\', desc: \'Cadena de electrones en la membrana interna. Produce la mayor parte del ATP.\'}
    ];
    etapas.forEach((et, i) => {
        svg.innerHTML += `<circle class="mito-etapa" data-key="${et.key}" cx="${et.cx}" cy="${et.cy}" r="${et.r}" fill="${et.color}" opacity="0.85" stroke="#fff" stroke-width="3" tabindex="0" style="cursor:pointer;filter:drop-shadow(0 0 12px ${et.color})" />`;
        svg.innerHTML += `<text x="${et.cx}" y="${et.cy+6}" text-anchor="middle" font-size="18" fill="#fff" font-weight="bold" pointer-events="none">${et.label}</text>`;
    });
    // Glow filter
    svg.innerHTML = `<defs><filter id="glow"><feGaussianBlur stdDeviation="6" result="coloredBlur"/><feMerge><feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>` + svg.innerHTML;

    // Interactividad
    const infoPanel = document.getElementById("mitoInfoPanel");
    const infoTitle = document.getElementById("mitoInfoTitle");
    const infoText = document.getElementById("mitoInfoText");
    function highlightEtapa(key) {
        svg.querySelectorAll(\'.mito-etapa\').forEach(c => {
            c.setAttribute(\'opacity\', c.getAttribute(\'data-key\') === key ? \'1\' : \'0.5\');
            c.setAttribute(\'stroke\', c.getAttribute(\'data-key\') === key ? \'#fff\' : \'#888\');
        });
    }
    svg.querySelectorAll(\'.mito-etapa\').forEach((c, i) => {
        c.addEventListener(\'click\', () => {
            highlightEtapa(etapas[i].key);
            infoTitle.textContent = etapas[i].label;
            infoText.textContent = etapas[i].desc;
        });
        c.addEventListener(\'keydown\', (e) => {
            if (e.key === \'Enter\' || e.key === \' \') {
                highlightEtapa(etapas[i].key);
                infoTitle.textContent = etapas[i].label;
                infoText.textContent = etapas[i].desc;
            }
        });
    });
    // Accesibilidad: reset info
    svg.addEventListener(\'mouseleave\', () => {
        highlightEtapa(null);
        infoTitle.textContent = \'Mitocondria\';
        infoText.textContent = \'Selecciona una etapa para ver su función.\';
    });
});
</script>


