<!-- ==================== JAVASCRIPT INTERACTIVO ==================== -->
<script>
// ==================== SIMULADOR RENDIMIENTO ====================
function runSimulation() {
    const oxygen = document.getElementById("oxygenSelect").value;
    const inhibitor = document.getElementById("inhibitorSelect").value;
    const fill = document.getElementById("atpFill");
    const valueSpan = document.getElementById("atpValue");
    const resultDiv = document.getElementById("simResult");

    let atp = 0;
    let products = "";
    let explanation = "";

    if (oxygen === "high") {
        atp = 36;
        fill.style.background = "linear-gradient(90deg, #00ffff, #00ff99)";
        products = "6 CO₂ + 6 H₂O";
        explanation = "Rendimiento máximo. Cadena ETC completa.";
        if (inhibitor === "cyanide") {
            atp = 2;
            explanation = "Cianuro bloquea complejo IV: se detiene ETC, solo glicólisis.";
        } else if (inhibitor === "oligomycin") {
            atp = 2;
            explanation = "Oligomicina bloquea ATP sintasa: gradiente se disipa, no se produce ATP.";
        }
    } else if (oxygen === "low") {
        atp = 2;
        fill.style.background = "linear-gradient(90deg, #ff1744, #ff5252)";
        products = "2 Ácido láctico";
        explanation = "Fermentación láctica: regeneración de NAD⁺ sin O₂.";
    } else {
        atp = 2;
        fill.style.background = "linear-gradient(90deg, #ff9100, #ff6d00)";
        products = "2 Etanol + 2 CO₂";
        explanation = "Fermentación alcohólica: típica en levaduras.";
    }
    const maxATP = 38;
    const percent = (atp / maxATP) * 100;
    fill.style.width = percent + "%";
    valueSpan.textContent = atp + " ATP";
    resultDiv.innerHTML = `<strong>Productos:</strong> ${products}<br><strong>Explicación:</strong> ${explanation}`;
}

// ==================== ANIMACIÓN ETC (CANVAS) ====================
const canvas = document.getElementById("etcCanvas");
if (canvas) {
    const ctx = canvas.getContext("2d");
    let electrons = [];
    let protons = [];
    let electronCount = 0;
    let protonCount = 0;
    const electronCountSpan = document.getElementById("electronCount");
    const protonCountSpan = document.getElementById("protonCount");

    function drawComplex(x, y, label) {
        ctx.fillStyle = "#333";
        ctx.fillRect(x, y, 60, 40);
        ctx.fillStyle = "#0ff";
        ctx.font = "12px monospace";
        ctx.fillText(label, x+20, y+25);
    }

    function animate() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        // Dibujar complejos I, II, III, IV
        drawComplex(50, 80, "I");
        drawComplex(150, 80, "II");
        drawComplex(250, 80, "III");
        drawComplex(350, 80, "IV");
        // ATP sintasa
        ctx.fillStyle = "#f0f";
        ctx.fillRect(500, 80, 60, 40);
        ctx.fillStyle = "#fff";
        ctx.fillText("ATP", 525, 105);
        ctx.fillText("sintasa", 520, 120);

        // Electrones
        for (let i=0; i<electrons.length; i++) {
            const e = electrons[i];
            ctx.fillStyle = "#ff0";
            ctx.beginPath();
            ctx.arc(e.x, e.y, 5, 0, Math.PI*2);
            ctx.fill();
            e.x += e.vx;
            if (e.x > 600) {
                electrons.splice(i,1);
                electronCount++;
                electronCountSpan.textContent = electronCount;
                if (electronCount % 3 === 0) {
                    protons.push({x: 450, y: 60, vy: 2});
                }
                i--;
            }
        }
        // Protones
        for (let i=0; i<protons.length; i++) {
            const p = protons[i];
            ctx.fillStyle = "#0ff";
            ctx.beginPath();
            ctx.arc(p.x, p.y, 4, 0, Math.PI*2);
            ctx.fill();
            p.y += p.vy;
            if (p.y > 140) {
                protons.splice(i,1);
                protonCount++;
                protonCountSpan.textContent = protonCount;
                i--;
            }
        }
        requestAnimationFrame(animate);
    }

    setInterval(() => {
        electrons.push({x: 20, y: 100, vx: 3});
    }, 800);

    animate();
}

// ==================== QUIZ ====================
function evaluateQuiz() {
    let score = 0;
    if (document.querySelector(\'input[name="q1"]:checked\')?.value === "b") score++;
    if (document.querySelector(\'input[name="q2"]:checked\')?.value === "c") score++;
    if (document.querySelector(\'input[name="q3"]:checked\')?.value === "a") score++;
    if (document.querySelector(\'input[name="q4"]:checked\')?.value === "b") score++;
    if (document.querySelector(\'input[name="q5"]:checked\')?.value === "a") score++;
    const resultDiv = document.getElementById("quizResult");
    if (score === 5) resultDiv.innerHTML = \'<span class="success">🎉 ¡Excelente! 5/5. Dominas la respiración celular.</span>\';
    else resultDiv.innerHTML = `<span class="error">📘 Tienes ${score}/5. Revisa las etapas y el rendimiento energético.</span>`;
}

// ==================== AUTOEVALUACIÓN ====================
function updateEval(num, val) {
    document.getElementById(`evalVal${num}`).innerText = val + "/5";
}
function guardarAutoevaluacion() {
    const v1 = document.getElementById(\'eval1\').value;
    const v2 = document.getElementById(\'eval2\').value;
    const v3 = document.getElementById(\'eval3\').value;
    const promedio = ((parseInt(v1)+parseInt(v2)+parseInt(v3))/3).toFixed(1);
    document.getElementById(\'autoEvalFeedback\').innerHTML = `📊 Autoevaluación guardada. Promedio: ${promedio}/5. ¡Sigue explorando!`;
}

// ==================== SOLUCIONES PROBLEMAS ====================
function mostrarSolucion(num) {
    const div = document.getElementById(`solucion${num}`);
    if (div.style.display === "none") div.style.display = "block";
    else div.style.display = "none";
}

// Inicializar simulador
runSimulation();
</script>
