        <p class="leccion-subtitulo">Atmósfera • Hidrosfera • Criosfera • Litosfera • Biosfera • Interacciones</p>
    </div>

    <!-- ==================== INTRO ==================== -->
    <p class="intro">
        El <strong>sistema climático terrestre</strong> es un complejo conjunto de componentes físicos y biológicos que interactúan continuamente intercambiando energía, materia y momentum. Este sistema determina la temperatura global, los patrones de precipitación, los vientos, el nivel del mar y la estabilidad de los ecosistemas. Comprender sus componentes y sus interacciones es esencial para predecir el cambio climático y evaluar impactos antropogénicos.
    </p>

    <div class="formula-neon text-center">
        Balance energético global (simplificado):<br>
        \\[ \\frac{S(1 - \\alpha)}{4} = \\sigma T_e^4 (1 - \\epsilon) + F_{\\text{GEI}} \\]
    </div>

    <hr class="divider-neon">

    <!-- ==================== DESARROLLO TEÓRICO ==================== -->
    <h2 class="section-title">
        <span class="neon-bullet">📚</span> I. Los Cinco Componentes del Sistema Climático
    </h2>

    <div class="table-wrapper">
        <table class="neon-table">
            <thead>
                <tr><th>Esfera</th><th>Descripción</th><th>Reservorios clave</th><th>Rol climático principal</th></tr>
            </thead>
            <tbody>
                <tr><td>🌬️ Atmósfera</td><td>Capa gaseosa</td><td>N₂ (78%), O₂ (21%), CO₂ (0.042%)</td><td>Transporte de calor y vapor, efecto invernadero</td></tr>
                <tr><td>💧 Hidrosfera</td><td>Agua líquida</td><td>Océanos (97% del agua total)</td><td>Almacén térmico, circulación termohalina</td></tr>
                <tr><td>🧊 Criosfera</td><td>Hielo y nieve</td><td>Casquetes polares, glaciares</td><td>Albedo alto, retroalimentación positiva</td></tr>
                <tr><td>⛰️ Litosfera</td><td>Corteza terrestre</td><td>Rocas, suelos, carbono fósil</td><td>Reservorio de carbono a largo plazo</td></tr>
                <tr><td>🌿 Biosfera</td><td>Vida</td><td>Biomasa terrestre y marina</td><td>Regulación de CO₂ y O₂, albedo vegetal</td></tr>
            </tbody>
        </table>
    </div>

    <div class="concept-box">
        <strong>⚠️ Interacciones:</strong> Ningún componente actúa aislado. Por ejemplo, el aumento de CO₂ (atmósfera) acidifica océanos (hidrosfera), afecta fitoplancton (biosfera) y acelera el derretimiento del hielo (criosfera).
    </div>

    <hr class="divider-neon">

    <!-- ==================== DIAGRAMA INTERACTIVO PROFESIONAL ==================== -->
    <h2 class="section-title">
        <span class="neon-bullet">🖼️</span> II. Diagrama del Sistema Climático (Interactivo)
    </h2>
    <p>Representación esquemática de las cinco esferas y sus interacciones principales. Haz clic en cada esfera para ver más información.</p>

    <div class="svg-container">
        <svg class="climate-svg" viewBox="0 0 1000 720" preserveAspectRatio="xMidYMid meet">
            <defs>
                <filter id="glow">
                    <feGaussianBlur stdDeviation="4" result="blur"/>
                    <feFlood flood-color="#00ffff" flood-opacity="0.6"/>
                    <feComposite in2="blur" operator="in" result="glow"/>
                    <feMerge>
                        <feMergeNode in="glow"/>
                        <feMergeNode in="SourceGraphic"/>
                    </feMerge>
                </filter>
                <filter id="glow-magenta">
                    <feGaussianBlur stdDeviation="6" result="blur"/>
                    <feFlood flood-color="#ff00ff" flood-opacity="0.5"/>
                    <feComposite in2="blur" operator="in"/>
                    <feMerge>
                        <feMergeNode/>
                        <feMergeNode in="SourceGraphic"/>
                    </feMerge>
                </filter>
                <marker id="arrow" markerWidth="12" markerHeight="12" refX="10" refY="6" orient="auto">
                    <path d="M0,0 L10,6 L0,12 Z" fill="#00ffff"/>
                </marker>
            </defs>

            <rect width="100%" height="100%" fill="none"/>

            <!-- Título principal -->
            <text x="500" y="60" text-anchor="middle" font-size="32" fill="#ff00ff" filter="url(#glow-magenta)" font-weight="bold">SISTEMA CLIMÁTICO TERRESTRE</text>

            <!-- Atmósfera -->
            <g class="sphere" data-sphere="Atmósfera" transform="translate(500,150)">
                <circle r="80" fill="rgba(30,144,255,0.7)" stroke="#00ffff" stroke-width="3" filter="url(#glow)"/>
                <text text-anchor="middle" dy="-15" fill="white" font-size="20" font-weight="bold">ATMÓSFERA</text>
                <text text-anchor="middle" dy="15" fill="#00ffff" font-size="12">Gases · Vapor · Nubes</text>
            </g>

            <!-- Hidrosfera -->
            <g class="sphere" data-sphere="Hidrosfera" transform="translate(180,330)">
                <circle r="75" fill="rgba(0,94,255,0.7)" stroke="#00ffff" stroke-width="3" filter="url(#glow)"/>
                <text text-anchor="middle" dy="-12" fill="white" font-size="20" font-weight="bold">HIDROSFERA</text>
                <text text-anchor="middle" dy="15" fill="#00ffff" font-size="12">Océanos · Ríos · Lagos</text>
            </g>

            <!-- Criosfera -->
            <g class="sphere" data-sphere="Criosfera" transform="translate(820,330)">
                <circle r="75" fill="rgba(224,247,250,0.9)" stroke="#00ffff" stroke-width="3" filter="url(#glow)"/>
                <text text-anchor="middle" dy="-12" fill="#000" font-size="20" font-weight="bold">CRIOSFERA</text>
                <text text-anchor="middle" dy="15" fill="#00ffff" font-size="12">Hielo · Glaciares · Nieve</text>
            </g>

            <!-- Litosfera -->
            <g class="sphere" data-sphere="Litosfera" transform="translate(320,550)">
