            </g>

            <!-- Biosfera -->
            <g class="sphere" data-sphere="Biosfera" transform="translate(680,550)">
                <circle r="75" fill="rgba(34,139,34,0.8)" stroke="#00ffff" stroke-width="3" filter="url(#glow)"/>
