<!-- ==================== JAVASCRIPT INTERACTIVO ==================== -->
<script>
(function() {
    // ========== DIAGRAMA INTERACTIVO ==========
    const spheres = document.querySelectorAll(\'.sphere\');
    const infoDiv = document.getElementById(\'sphereInfo\');
    const descriptions = {
        \'Atmósfera\': \'🌬️ La atmósfera regula la temperatura mediante gases de efecto invernadero, transporta calor y humedad, y es el componente más dinámico.\',
        \'Hidrosfera\': \'💧 Los océanos almacenan el 90% del calor antropogénico, regulan el clima a través de corrientes y absorben CO₂.\',
        \'Criosfera\': \'🧊 El hielo refleja la radiación solar (alto albedo). Su derretimiento amplifica el calentamiento global (retroalimentación positiva).\',
        \'Litosfera\': \'⛰️ La corteza terrestre almacena carbono a largo plazo en rocas y combustibles fósiles; los volcanes liberan CO₂ a la atmósfera.\',
        \'Biosfera\': \'🌿 Los ecosistemas actúan como sumideros de carbono (bosques, océanos) y modifican el albedo local. La deforestación reduce su capacidad reguladora.\'
    };
    spheres.forEach(sphere => {
        sphere.addEventListener(\'click\', () => {
            const name = sphere.getAttribute(\'data-sphere\');
            infoDiv.innerHTML = `<strong>${name}</strong><br>${descriptions[name]}`;
        });
    });

    // ========== SIMULADOR ALBEDO ==========
    const iceSlider = document.getElementById(\'iceSlider\');
    const iceValue = document.getElementById(\'iceValue\');
    const iceFill = document.getElementById(\'iceFill\');
    const iceResult = document.getElementById(\'iceResult\');
    function updateAlbedo() {
        const ice = parseInt(iceSlider.value);
        iceValue.textContent = ice;
        iceFill.style.width = ice + \'%\';
        const albedo = 0.3 + (ice / 100) * 0.5;
        const deltaT = ((1 - albedo) * 10 - 5).toFixed(1);
        let feedback = \'\';
        if (ice > 70) feedback = \'🧊 Retroalimentación negativa: enfriamiento adicional.\';
        else if (ice < 40) feedback = \'🔥 Retroalimentación positiva: calentamiento acelerado (amplificación ártica).\';
        else feedback = \'🌍 Equilibrio relativo.\';
        iceResult.innerHTML = `<strong>Albedo efectivo:</strong> ${albedo.toFixed(2)}<br>
                               <strong>Variación térmica estimada:</strong> ${deltaT > 0 ? \'+\' : \'\'}${deltaT} °C<br>
                               ${feedback}`;
    }
    if (iceSlider) iceSlider.addEventListener(\'input\', updateAlbedo);
    updateAlbedo();

    // ========== SIMULADOR CO₂ ==========
    const co2Slider = document.getElementById(\'co2Slider\');
    const co2Value = document.getElementById(\'co2Value\');
    const co2Fill = document.getElementById(\'co2Fill\');
    const co2Result = document.getElementById(\'co2Result\');
    function updateCO2() {
        const co2 = parseInt(co2Slider.value);
        co2Value.textContent = co2;
        co2Fill.style.width = ((co2 - 180) / 820 * 100) + \'%\';
        const preind = 280;
        const forcing = (5.35 * Math.log(co2 / preind)).toFixed(2);
        const tempChange = (forcing * 0.8).toFixed(2);
        let state = \'\';
        if (co2 < 300) state = \'🧊 Condiciones glaciales\';
        else if (co2 < 420) state = \'🌍 Clima preindustrial\';
        else state = \'🔥 Calentamiento antropogénico\';
        co2Result.innerHTML = `<strong>Forzamiento radiativo:</strong> ${forcing} W/m²<br>
                               <strong>Incremento térmico estimado:</strong> +${tempChange} °C<br>
                               ${state}`;
    }
    if (co2Slider) co2Slider.addEventListener(\'input\', updateCO2);
    updateCO2();

    // ========== LABORATORIO CLIMÁTICO ==========
    const sunSelect = document.getElementById(\'sunSelect\');
    const iceSelect = document.getElementById(\'iceSelect\');
    const co2Select = document.getElementById(\'co2Select\');
    const labResult = document.getElementById(\'labResult\');
    function evaluateLab() {
        let score = 0;
        if (sunSelect.value === \'high\') score += 3;
        if (sunSelect.value === \'low\') score -= 2;
        if (iceSelect.value === \'low\') score += 3;
        if (iceSelect.value === \'high\') score -= 3;
        if (co2Select.value === \'high\') score += 4;
        if (co2Select.value === \'low\') score -= 3;
        let state = \'\', icon = \'\';
        if (score <= -4) { state = \'Era glacial\'; icon = \'🧊\'; }
        else if (score <= 2) { state = \'Clima estable preindustrial\'; icon = \'🌍\'; }
        else { state = \'Calentamiento global acelerado\'; icon = \'🔥\'; }
        labResult.innerHTML = `<h5>${icon} Estado climático simulado</h5>
                               <p><strong>${state}</strong></p>
                               <p>Puntaje de forzamiento: ${score > 0 ? \'+\' : \'\'}${score}</p>`;
    }
    if (sunSelect && iceSelect && co2Select && labResult) {
        [sunSelect, iceSelect, co2Select].forEach(el => el.addEventListener(\'change\', evaluateLab));
        evaluateLab();
    }

    // ========== QUIZ ==========
    const questions = document.querySelectorAll(\'.quiz-question\');
    let totalScore = 0;
    const maxScore = questions.length;
    const scoreDisplay = document.getElementById(\'quizScore\');

    function updateTotalScore() {
        const answeredCorrect = document.querySelectorAll(\'.quiz-question.answered .quiz-option.correct.correct-answer\').length;
        totalScore = answeredCorrect;
        if (scoreDisplay) scoreDisplay.textContent = `Puntuación: ${totalScore}/${maxScore}`;
    }

    questions.forEach(question => {
        const correctValue = question.getAttribute(\'data-correct\');
        const options = question.querySelectorAll(\'.quiz-option\');
        const feedbackDiv = question.querySelector(\'.quiz-feedback\');

        options.forEach(opt => {
            opt.addEventListener(\'click\', () => {
                if (question.classList.contains(\'answered\')) return; // bloqueo tras respuesta

                question.classList.add(\'answered\');

                const chosenValue = opt.getAttribute(\'data-value\');
                const isCorrect = (chosenValue === correctValue);

                options.forEach(o => o.classList.remove(\'selected\', \'correct\', \'incorrect\', \'correct-answer\'));
                opt.classList.add(\'selected\');

                if (isCorrect) {
                    opt.classList.add(\'correct\', \'correct-answer\');
                    feedbackDiv.textContent = \'✅ Correcto\';
                    feedbackDiv.style.color = \'#39ff14\';
                } else {
                    opt.classList.add(\'incorrect\');
                    const correctOpt = Array.from(options).find(o => o.getAttribute(\'data-value\') === correctValue);
                    if (correctOpt) correctOpt.classList.add(\'correct\');

                    let correctAnswerText = correctValue;
                    if (correctValue === \'hidrosfera\') correctAnswerText = \'Hidrosfera (océanos)\';
                    else if (correctValue === \'positiva\') correctAnswerText = \'Retroalimentación positiva\';
                    else if (correctValue === \'litosfera\') correctAnswerText = \'Litosfera\';
                    else if (correctValue === \'biosfera_atmosfera\') correctAnswerText = \'Biosfera y atmósfera\';

                    feedbackDiv.textContent = `❌ Incorrecto. La respuesta correcta es: ${correctAnswerText}`;
                    feedbackDiv.style.color = \'#ff6b6b\';
                }

                updateTotalScore();
            });
        });
    });

    const resetBtn = document.getElementById(\'resetQuiz\');
    if (resetBtn) {
        resetBtn.addEventListener(\'click\', () => {
            questions.forEach(question => {
                question.classList.remove(\'answered\');
                const options = question.querySelectorAll(\'.quiz-option\');
                options.forEach(opt => {
                    opt.classList.remove(\'selected\', \'correct\', \'incorrect\', \'correct-answer\');
                });
                const feedbackDiv = question.querySelector(\'.quiz-feedback\');
                if (feedbackDiv) {
                    feedbackDiv.textContent = \'\';
                    feedbackDiv.style.color = \'\';
                }
            });
            totalScore = 0;
            if (scoreDisplay) scoreDisplay.textContent = `Puntuación: 0/${maxScore}`;
        });
    }

    // ========== ERRORES COMUNES TOGGLE ==========
    const checkboxes = document.querySelectorAll(\'.error-item input[type="checkbox"]\');
    checkboxes.forEach(cb => {
        cb.addEventListener(\'change\', function() {
            const explain = this.parentElement.querySelector(\'.error-explain\');
            if (explain) explain.style.display = this.checked ? \'block\' : \'none\';
        });
        // Inicializar estado
        const explain = cb.parentElement.querySelector(\'.error-explain\');
        if (explain) explain.style.display = cb.checked ? \'block\' : \'none\';
    });

    // ========== BARRA DE PROGRESO DE LECTURA ==========
    const progressBar = document.getElementById(\'leccionProgress\');
    function updateScrollProgress() {
        const docHeight = document.documentElement.scrollHeight - window.innerHeight;
        const scrollTop = window.scrollY || window.pageYOffset;
        const percent = docHeight ? Math.min(100, Math.round((scrollTop / docHeight) * 100)) : 0;
        if (progressBar) progressBar.style.width = `${percent}%`;
    }
    window.addEventListener(\'scroll\', updateScrollProgress);
    updateScrollProgress();

    // ========== MODO EXPLICACIÓN ==========
    const autoExplainBtn = document.getElementById(\'autoExplainBtn\');
    const quickSummary = document.getElementById(\'quickSummary\');
    if (autoExplainBtn && quickSummary) {
        autoExplainBtn.addEventListener(\'click\', () => {
            quickSummary.textContent = \'⏳ Generando resúmenes inteligentes...\';
            setTimeout(() => {
                quickSummary.innerHTML = `🌱 Panel de revisión:
                <ul style="padding-left:1rem; margin-top:.4rem;">
                    <li>Incremento de CO₂ → +8% radiación atrapada.</li>
                    <li>Menos hielo → menor albedo → más absorción solar.</li>
                    <li>Océanos almacenan ~90% del calor extra; impacto lento pero persistente.</li>
                </ul>`;
            }, 380);
        });
    }

    console.log(\'✅ Lección de Sistema Climático mejorada y funcional.\');
})();
</script>
',
