    'contenido' => '
<!-- INICIO LECCIÓN CYBERPUNK OPTIMIZADA -->
<div class="leccion-container leccion-ecosistemas-carbono" data-tema="ciclo-carbono" data-materia="Ecosistemas">

    <!-- ============================================================ -->
    <!-- SECCIÓN 1: CABECERA Y CONTEXTO INTRODUCTORIO -->
    <!-- ============================================================ -->
    <header class="leccion-header compact">
        <div class="header-top">
            <span class="materia-badge" aria-label="Materia">🌍 ECOSISTEMAS</span>
            <span class="nivel-badge" aria-label="Nivel dificultad">⚡ NIVEL AVANZADO</span>
            <span class="tiempo-badge" aria-label="Tiempo estimado">⏱️ 60 MIN</span>
        </div>
        <h1 class="titulo-leccion">
            <span class="neon-icon">≈</span>CICLO DEL CARBONO
        </h1>
        <p class="leccion-subtitulo">Flujos Biogeoquímicos • Cambio Climático • Regulación Global</p>
    </header>

    <!-- PANEL RÁPIDO DE OBJETIVOS -->
    <section class="objetivos-rapidos" role="region" aria-label="Objetivos de aprendizaje">
        <div class="objetivos-grid">
            <div class="objetivo-card">
                <div class="obj-icon">🎯</div>
                <div class="obj-text">
                    <h4>Comprender reservorios</h4>
                    <p>Identificar dónde está el carbono en el planeta</p>
                </div>
            </div>
            <div class="objetivo-card">
                <div class="obj-icon">⚙️</div>
                <div class="obj-text">
                    <h4>Analizar flujos naturales</h4>
                    <p>Fotosíntesis, respiración, intercambio oceánico</p>
                </div>
            </div>
            <div class="objetivo-card">
                <div class="obj-icon">🚨</div>
                <div class="obj-text">
                    <h4>Evaluar impacto humano</h4>
                    <p>Emisiones antropogénicas y desequilibrio</p>
                </div>
            </div>
            <div class="objetivo-card">
                <div class="obj-icon">📊</div>
                <div class="obj-text">
                    <h4>Interpretar datos reales</h4>
                    <p>IPCC, tendencias climáticas, soluciones</p>
                </div>
            </div>
        </div>
    </section>

    <!-- CONTEXTO REAL APLICADO -->
    <section class="contexto-realidad" role="region" aria-label="Contexto y aplicación real">
        <div class="contexto-card">
            <h3>🌍 ¿Por qué importa?</h3>
            <p>
                El ciclo del carbono controla el clima de la Tierra. Cada año, los humanos emitimos ~11.5 GtC (gigatoneladas de carbono), 
                rompiendo un equilibrio que existía hace 3 millones de años. Las consecuencias: 
                <strong>calentamiento global 1.1°C, acidificación oceánica, eventos climáticos extremos</strong>.
            </p>
            <div class="dato-importante">
                <span class="icono-dato">📈</span>
                <strong>2025:</strong> Concentración de CO₂ = 425 ppm (vs. 280 ppm en 1750)
            </div>
        </div>
    </section>

    <!-- ============================================================ -->
    <!-- SECCIÓN 2: DESARROLLO TEÓRICO ESTRUCTURADO -->
    <!-- ============================================================ -->
    <section class="seccion-desarrollo" role="region" aria-label="Desarrollo teórico">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">▶</span> I. RESERVORIOS Y FLUJOS DEL CICLO
        </h2>

        <p class="formula-neon text-center" role="doc-example">
            <strong>Ecuaciones clave:</strong><br>
            Fotosíntesis: \\( \\ce{6CO2 + 6H2O -> C6H12O6 + 6O2} \\)<br>
            Respiración: \\( \\ce{C6H12O6 + 6O2 -> 6CO2 + 6H2O} \\)
        </p>

        <table class="neon-table" role="table" aria-label="Reservorios de carbono y tiempos de residencia">
            <thead>
                <tr>
                    <th scope="col">Reservorio</th>
                    <th scope="col">Cantidad (GtC)</th>
                    <th scope="col">Tiempo de Residencia</th>
                    <th scope="col">Procesos Clave</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td><strong>Atmósfera</strong></td>
                    <td>≈ 900</td>
                    <td>Años</td>
                    <td>Intercambio con océanos y biosfera</td>
                </tr>
                <tr>
                    <td><strong>Biosfera Terrestre</strong></td>
                    <td>≈ 550</td>
                    <td>Décadas a siglos</td>
                    <td>Fotosíntesis, respiración, descomposición</td>
                </tr>
                <tr>
                    <td><strong>Hidrosfera (Océanos)</strong></td>
                    <td>≈ 38,000</td>
                    <td>Miles de años</td>
                    <td>Disolución, bomba biológica, termoclina</td>
                </tr>
                <tr>
                    <td><strong>Litosfera</strong></td>
                    <td>> 60,000,000</td>
                    <td>Millones de años</td>
                    <td>Meteorización, fósiles, sedimentación</td>
                </tr>
            </tbody>
        </table>

        <div class="concept-box" role="note">
            <strong>Flujos Naturales Equilibrados (pre-industrial):</strong> 
            Fotosíntesis ≈ 120 GtC/año | Respiración ≈ 120 GtC/año | Océanos ↔ Atmósfera ≈ 90 GtC/año
            <br><strong style="color: #ff3366;">Desequilibrio actual:</strong> +11.5 GtC/año (2025)
        </div>
    </section>

    <!-- ============================================================ -->
    <!-- SECCIÓN 3: VISUALIZACIÓN DIDÁCTICA INTERACTIVA -->
    <!-- ============================================================ -->
    <section class="seccion-visual" role="region" aria-label="Visualización del ciclo global del carbono">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">▶</span> II. DIAGRAMA INTERACTIVO DEL CICLO GLOBAL
        </h2>

        <div class="svg-container" role="img" aria-label="Diagrama del ciclo del carbono con flujos anuales">
            <svg class="carbon-svg" viewBox="0 0 1600 900" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">
                <defs>
                    <filter id="glow-cyan"><feGaussianBlur stdDeviation="6" result="blur"/><feFlood flood-color="#00ffff"/><feComposite in2="blur" operator="in"/><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter>
                    <filter id="glow-green"><feGaussianBlur stdDeviation="6" result="blur"/><feFlood flood-color="#00ff88"/><feComposite in2="blur" operator="in"/><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter>
                    <filter id="glow-orange"><feGaussianBlur stdDeviation="6" result="blur"/><feFlood flood-color="#ffaa00"/><feComposite in2="blur" operator="in"/><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter>
                    <filter id="glow-red"><feGaussianBlur stdDeviation="6" result="blur"/><feFlood flood-color="#ff3366"/><feComposite in2="blur" operator="in"/><feMerge><feMergeNode/><feMergeNode in="SourceGraphic"/></feMerge></filter>
                    <marker id="arrow" markerWidth="18" markerHeight="18" refX="16" refY="9" orient="auto"><path d="M0,0 L18,9 L0,18 Z" fill="#00ffff"/></marker>
                </defs>
                <rect width="1600" height="900" fill="#070714"/>
                <text x="800" y="50" text-anchor="middle" font-size="48" fill="#39ff14" filter="url(#glow-cyan)">CICLO GLOBAL DEL CARBONO</text>
                
                <!-- Atmósfera -->
                <g transform="translate(220,130)">
                    <rect width="320" height="150" rx="12" fill="#0b1a33" stroke="#00ffff" stroke-width="4" filter="url(#glow-cyan)"/>
                    <text x="160" y="45" text-anchor="middle" fill="#00ffff" font-size="28" font-weight="bold">ATMÓSFERA</text>
                    <text x="160" y="85" text-anchor="middle" fill="#ffffff" font-size="22">~900 GtC</text>
                    <text x="160" y="115" text-anchor="middle" fill="#88ffff" font-size="18">425 ppm CO₂</text>
                </g>
                
                <!-- Biosfera -->
                <g transform="translate(1060,130)">
                    <rect width="320" height="150" rx="12" fill="#0b2a1a" stroke="#00ff88" stroke-width="4" filter="url(#glow-green)"/>
                    <text x="160" y="45" text-anchor="middle" fill="#00ff88" font-size="28" font-weight="bold">BIOSFERA</text>
                    <text x="160" y="85" text-anchor="middle" fill="#ffffff" font-size="22">~550 GtC</text>
                    <text x="160" y="115" text-anchor="middle" fill="#88ffcc" font-size="18">Plantas • Suelo</text>
                </g>
                
                <!-- Hidrosfera -->
                <g transform="translate(220,480)">
                    <rect width="320" height="150" rx="12" fill="#081c33" stroke="#00ffff" stroke-width="4" filter="url(#glow-cyan)"/>
                    <text x="160" y="45" text-anchor="middle" fill="#00ffff" font-size="28" font-weight="bold">HIDROSFERA</text>
                    <text x="160" y="85" text-anchor="middle" fill="#ffffff" font-size="22">38,000 GtC</text>
                    <text x="160" y="115" text-anchor="middle" fill="#88ccff" font-size="18">Océanos</text>
                </g>
                
                <!-- Litosfera -->
                <g transform="translate(1060,480)">
                    <rect width="320" height="150" rx="12" fill="#2a1a0b" stroke="#ffaa00" stroke-width="4" filter="url(#glow-orange)"/>
                    <text x="160" y="45" text-anchor="middle" fill="#ffaa00" font-size="28" font-weight="bold">LITOSFERA</text>
                    <text x="160" y="85" text-anchor="middle" fill="#ffffff" font-size="22">>60 M GtC</text>
                    <text x="160" y="115" text-anchor="middle" fill="#ffcc88" font-size="18">Rocas • Fósiles</text>
                </g>
                
                <!-- Flujos -->
                <path d="M540 205 L1060 205" stroke="#00ff88" stroke-width="6" marker-end="url(#arrow)" filter="url(#glow-green)"/>
                <text x="800" y="190" text-anchor="middle" fill="#00ff88" font-size="18" font-weight="bold">Fotosíntesis: 120 GtC/año</text>
                
                <path d="M1060 295 L540 295" stroke="#ff3366" stroke-width="6" marker-end="url(#arrow)" filter="url(#glow-red)"/>
                <text x="800" y="325" text-anchor="middle" fill="#ff99bb" font-size="18" font-weight="bold">Respiración: 120 GtC/año</text>
                
                <path d="M380 280 L380 480" stroke="#00ffff" stroke-width="6" marker-end="url(#arrow)" filter="url(#glow-cyan)"/>
                <text x="300" y="390" fill="#88ffff" font-size="16" font-weight="bold">Intercambio: 90 GtC/año</text>
                
                <path d="M1220 480 L1220 295" stroke="#ff3366" stroke-width="7" marker-end="url(#arrow)" filter="url(#glow-red)" stroke-dasharray="15,10"/>
                <text x="1280" y="390" fill="#ff3366" font-size="17" font-weight="bold">+11.5 GtC/año</text>
                <text x="1280" y="410" fill="#ff3366" font-size="14">(HUMANO)</text>
                
                <text x="800" y="820" text-anchor="middle" fill="#ff3366" font-size="28" font-weight="bold" filter="url(#glow-red)">⚠️ Equilibrio Natural Roto por Actividad Antropogénica</text>
            </svg>
        </div>
    </section>

    <!-- ============================================================ -->
    <!-- SECCIÓN 4: SIMULADORES INTERACTIVOS -->
    <!-- ============================================================ -->
    <section class="simuladores-section" role="region" aria-label="Simuladores interactivos">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">▶</span> III. SIMULADORES INTERACTIVOS AVANZADOS
        </h2>

        <!-- SIMULADOR 1: EMISIONES -->
        <div class="simulator-container carbon-sim-advanced">
            <h3 class="simulator-title">Simulador 1️⃣: Impacto de Emisiones Antropogénicas</h3>
            <p class="simulator-desc">Ajusta la tasa de emisiones y observa el cambio en CO₂ atmosférico 2025-2050</p>
            
            <div class="simulator-controls">
                <div class="control-item">
                    <label for="emissionSlider" lang="{{ lang }}">Emisiones (GtC/año):</label>
                    <div class="slider-display">
                        <input type="range" id="emissionSlider" min="0" max="20" value="11.5" step="0.5" aria-label="Emisiones antropogénicas en gigatoneladas de carbono por año" role="slider" aria-valuemin="0" aria-valuemax="20" aria-valuenow="11.5">
                        <span id="emissionValue" class="value-display" aria-live="polite">11.5</span>
                    </div>
                </div>
                <button class="btn-reset" onclick="resetEmissionSlider()" aria-label="Reiniciar valores del simulador de emisiones">🔄 Reiniciar</button>
            </div>

            <div class="meter-track">
                <div class="meter-fill" id="co2Fill"></div>
            </div>

            <div class="sim-result" id="emissionResult" role="status" aria-live="polite" aria-label="Resultados del simulador"></div>
        </div>

        <script>
        (function(){
            const slider = document.getElementById("emissionSlider");
            const value = document.getElementById("emissionValue");
            const fill = document.getElementById("co2Fill");
            const result = document.getElementById("emissionResult");

            function update(){
                const emission = parseFloat(slider.value);
                value.textContent = emission.toFixed(1);
                slider.setAttribute("aria-valuenow", emission);

                const naturalSink = 4.5;
                const net = emission - naturalSink;
                const co2Level = 425 + net * 8;

                fill.style.width = (emission / 20 * 100) + "%";
                fill.style.background = emission > 15 ? "#ff1744" : emission > 11.5 ? "#ffaa00" : "#00ff88";

                let feedback = "";
                let scenario = "";
                if (emission < 5) {
                    feedback = "Mitigación agresiva: estabilización posible antes de 2050";
                    scenario = "🌱 Escenario Optimista";
                } else if (emission < 11.5) {
                    feedback = "Transición hacia descarbonización moderada";
                    scenario = "⚠️ Escenario de Transición";
                } else if (emission < 15) {
                    feedback = "Escenario actual: calentamiento persistente";
                    scenario = "🔥 Escenario Actual";
                } else {
                    feedback = "Emisiones aceleradas: cambio climático catastrófico";
                    scenario = "💥 Escenario Crítico";
                }

                result.innerHTML = `
                    <div class="result-row"><strong>${scenario}</strong></div>
                    <div class="result-row">CO₂ Proyectado 2050: ~${co2Level.toFixed(0)} ppm</div>
                    <div class="result-row">Flujo Neto: +${net.toFixed(1)} GtC/año</div>
                    <div class="result-row feedback">${feedback}</div>
                `;
            }
            window.resetEmissionSlider = function() {
                slider.value = 11.5;
                update();
            };
            slider.addEventListener("input", update);
            update();
        })();
        </script>

        <!-- SIMULADOR 2: DEFORESTACIÓN -->
        <div class="simulator-container carbon-sim-advanced">
            <h3 class="simulator-title">Simulador 2️⃣: Deforestación y Sumideros de Carbono</h3>
            <p class="simulator-desc">Modifica la deforestación neta y su impacto en la biosfera como sumidero</p>
            
            <div class="simulator-controls">
                <div class="control-item">
                    <label for="deforestSlider">Deforestación Neta (millones ha/año):</label>
                    <div class="slider-display">
                        <input type="range" id="deforestSlider" min="-15" max="25" value="10" step="1" aria-label="Tasa de deforestación en millones de hectáreas por año" role="slider" aria-valuemin="-15" aria-valuemax="25" aria-valuenow="10">
                        <span id="deforestValue" class="value-display" aria-live="polite">10</span>
                    </div>
                </div>
                <button class="btn-reset" onclick="resetDeforestSlider()" aria-label="Reiniciar valores del simulador de deforestación">🔄 Reiniciar</button>
            </div>

            <div class="meter-track">
                <div class="meter-fill" id="bioFill"></div>
            </div>

            <div class="sim-result" id="deforestResult" role="status" aria-live="polite" aria-label="Resultados del simulador de deforestación"></div>
        </div>

        <script>
        (function(){
            const slider = document.getElementById("deforestSlider");
            const value = document.getElementById("deforestValue");
            const fill = document.getElementById("bioFill");
            const result = document.getElementById("deforestResult");

            function update(){
                const deforest = parseInt(slider.value);
                value.textContent = deforest;
                slider.setAttribute("aria-valuenow", deforest);

                const emission = deforest * 0.15;
                const level = Math.max(0, Math.min(100, 50 + deforest * 3));

                fill.style.width = level + "%";
                if (deforest > 5) {
                    fill.style.background = "linear-gradient(90deg, #ff1744, #ff5252)";
                } else if (deforest > 0) {
                    fill.style.background = "linear-gradient(90deg, #ffaa00, #ffbb33)";
                } else {
                    fill.style.background = "linear-gradient(90deg, #00e676, #00ff88)";
                }

                result.innerHTML = `
                    <div class="result-row"><strong>Emisiones por Deforestación:</strong> ~${emission.toFixed(2)} GtC/año</div>
                    ${deforest > 5 ? \'<div class="result-row feedback">🔥 Pérdida severa de sumidero de carbono</div>\' : 
                      deforest > 0 ? \'<div class="result-row feedback">⚠️ Pérdida neta de sumidero: aumento de CO₂</div>\' :
                      deforest < 0 ? \'<div class="result-row feedback">🌱 Reforestación activa: sumidero positivo</div>\' :
                      \'<div class="result-row feedback">⚖️ Equilibrio en el cambio de uso de tierra</div>\'}
                `;
            }
            window.resetDeforestSlider = function() {
                slider.value = 10;
                update();
            };
            slider.addEventListener("input", update);
            update();
        })();
        </script>
    </section>

    <!-- ============================================================ -->
    <!-- SECCIÓN 5: QUIZ AUTOEVALUADO CON FEEDBACK DETALLADO -->
    <!-- ============================================================ -->
    <section class="quiz-section" role="region" aria-label="Autoevaluación: Quiz sobre ciclo del carbono">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">▶</span> IV. QUIZ AUTOEVALUADO: CICLO DEL CARBONO
        </h2>

        <div class="quiz-container">
            <div class="quiz-question" data-correct="c">
                <p class="quiz-text"><strong>1.</strong> ¿Cuál es el MAYOR reservorio de carbono del planeta?</p>
                <div class="quiz-options" role="group" aria-label="Opciones de respuesta pregunta 1">
                    <button class="quiz-option" data-value="a" onclick="checkQuizAnswer(this)">A) Atmósfera (~900 GtC)</button>
                    <button class="quiz-option" data-value="b" onclick="checkQuizAnswer(this)">B) Biosfera (~550 GtC)</button>
                    <button class="quiz-option" data-value="c" onclick="checkQuizAnswer(this)">C) Litosfera (>60M GtC)</button>
                </div>
                <div class="quiz-feedback" role="status"></div>
            </div>

            <div class="quiz-question" data-correct="a">
                <p class="quiz-text"><strong>2.</strong> El flujo NATURAL más grande del ciclo es:</p>
                <div class="quiz-options" role="group" aria-label="Opciones de respuesta pregunta 2">
                    <button class="quiz-option" data-value="a" onclick="checkQuizAnswer(this)">A) Fotosíntesis (~120 GtC/año)</button>
                    <button class="quiz-option" data-value="b" onclick="checkQuizAnswer(this)">B) Intercambio océano-atmósfera</button>
                    <button class="quiz-option" data-value="c" onclick="checkQuizAnswer(this)">C) Emisiones antropogénicas</button>
                </div>
                <div class="quiz-feedback" role="status"></div>
            </div>

            <div class="quiz-question" data-correct="a">
                <p class="quiz-text"><strong>3.</strong> La acidificación oceánica es causada principalmente por:</p>
                <div class="quiz-options" role="group" aria-label="Opciones de respuesta pregunta 3">
                    <button class="quiz-option" data-value="a" onclick="checkQuizAnswer(this)">A) Absorción de CO₂ antropogénico</button>
                    <button class="quiz-option" data-value="b" onclick="checkQuizAnswer(this)">B) Aumento de O₂ disuelto</button>
                    <button class="quiz-option" data-value="c" onclick="checkQuizAnswer(this)">C) Deforestación directa</button>
                </div>
                <div class="quiz-feedback" role="status"></div>
            </div>

            <div class="quiz-question" data-correct="b">
                <p class="quiz-text"><strong>4:</strong> Si fotosíntesis = 120 GtC/año y respiración = 118 GtC/año, el flujo neto NATURAL es:</p>
                <div class="quiz-options" role="group" aria-label="Opciones de respuesta pregunta 4">
                    <button class="quiz-option" data-value="a" onclick="checkQuizAnswer(this)">A) +120 GtC/año</button>
                    <button class="quiz-option" data-value="b" onclick="checkQuizAnswer(this)">B) +2 GtC/año</button>
                    <button class="quiz-option" data-value="c" onclick="checkQuizAnswer(this)">C) 0 GtC/año</button>
                </div>
                <div class="quiz-feedback" role="status"></div>
            </div>

            <div class="quiz-question" data-correct="c">
                <p class="quiz-text"><strong>5.</strong> El tiempo de residencia MÁS LARGO del carbono es en:</p>
                <div class="quiz-options" role="group" aria-label="Opciones de respuesta pregunta 5">
                    <button class="quiz-option" data-value="a" onclick="checkQuizAnswer(this)">A) Biosfera (décadas)</button>
                    <button class="quiz-option" data-value="b" onclick="checkQuizAnswer(this)">B) Oceanos (miles de años)</button>
                    <button class="quiz-option" data-value="c" onclick="checkQuizAnswer(this)">C) Litosfera (millones años)</button>
                </div>
                <div class="quiz-feedback" role="status"></div>
            </div>

            <div id="quizScore" class="score-display" role="status" aria-live="polite" aria-label="Puntuación final del quiz">
                <strong>Puntuación: 0/5</strong>
            </div>
        </div>

        <script>
        let quizScore = 0;
        const quizTotal = 5;

        window.checkQuizAnswer = function(button) {
            const question = button.closest(".quiz-question");
            if (!question) return;
            
            const correct = question.getAttribute("data-correct");
            const selected = button.getAttribute("data-value");
            const feedback = question.querySelector(".quiz-feedback");
            const allOptions = question.querySelectorAll(".quiz-option");

            allOptions.forEach(opt => opt.disabled = true);

            if (selected === correct) {
                button.classList.add("correct");
                feedback.innerHTML = "✅ <strong>¡Correcto!</strong> Buena comprensión del concepto.";
                feedback.classList.add("feedback-correct");
                feedback.style.display = "block";
                quizScore++;
            } else {
                button.classList.add("incorrect");
                const correctBtn = question.querySelector(`[data-value="${correct}"]`);
                if (correctBtn) {
                    correctBtn.classList.add("correct");
                    feedback.innerHTML = `❌ <strong>Incorrecto.</strong> La respuesta correcta es: <strong>${correctBtn.textContent}</strong>`;
                }
                feedback.classList.add("feedback-incorrect");
                feedback.style.display = "block";
            }

            const scoreDisplay = document.getElementById("quizScore");
            if (scoreDisplay) {
                scoreDisplay.innerHTML = `<strong>Puntuación: ${quizScore}/${quizTotal}</strong>`;
            }
        };
        </script>
    </section>

    <!-- ============================================================ -->
    <!-- SECCIÓN 6: ERRORES COMUNES INTERACTIVOS -->
    <!-- ============================================================ -->
    <section class="errores-section" role="region" aria-label="Errores comunes y sus correcciones">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">⚠️</span> V. ERRORES COMUNES DEL ESTUDIANTE
        </h2>

        <div class="errors-interactive">
            <div class="error-item">
                <input type="checkbox" id="err1" aria-label="Expandir error común 1" onchange="toggleError(1)">
                <label for="err1" class="error-label">
                    <span class="error-icon">❌</span>
                    Creer que la ATMÓSFERA es el mayor reservorio de carbono
                </label>
                <div class="error-explain" id="exp1">
                    <p><strong>Por qué es incorrecto:</strong> La atmósfera tiene solo ~900 GtC, mientras que la litosfera contiene <strong>más de 66,600,000 GtC</strong>. Esto es un millón de veces más.</p>
                    <p><strong>Concepto clave:</strong> Los reservorios MÁS GRANDES son los MÁS LENTOS (millones de años). Los reservorios rápidos son pequeños.</p>
                </div>
            </div>

            <div class="error-item">
                <input type="checkbox" id="err2" aria-label="Expandir error común 2" onchange="toggleError(2)">
                <label for="err2" class="error-label">
                    <span class="error-icon">❌</span>
                    Subestimar el rol de los océanos como sumidero de CO₂
                </label>
                <div class="error-explain" id="exp2">
                    <p><strong>Dato real:</strong> Los océanos absorben ~25% de las emisiones antropogénicas (2.5 GtC/año de las 11.5 actuales).</p>
                    <p><strong>Consecuencia:</strong> Esta absorción causa <strong>acidificación oceánica</strong>, que daña corales, moluscos y toda la cadena trófica marina.</p>
                    <p><strong>Conclusión:</strong> El océano NO es una solución; es una víctima y un regulador automático que paga un precio.</p>
                </div>
            </div>

            <div class="error-item">
                <input type="checkbox" id="err3" aria-label="Expandir error común 3" onchange="toggleError(3)">
                <label for="err3" class="error-label">
                    <span class="error-icon">❌</span>
                    Confundir flujos naturales CON perturbaciones antropogénicas
                </label>
                <div class="error-explain" id="exp3">
                    <p><strong>Diferencia crítica:</strong></p>
                    <ul>
                        <li><strong>Flujos naturales:</strong> Fotosíntesis = 120 GtC/año ↔ Respiración = 120 GtC/año (EQUILIBRIO)</li>
                        <li><strong>Perturbación humana:</strong> +11.5 GtC/año (flujo NETO adicional, desequilibrio)</li>
                    </ul>
                    <p><strong>Analogía:</strong> Tu cuerpo produce CO₂ respirando (flujo natural). Si respiras+sudas+corres, añades CO₂ (perturbación). El ciclo no puede absorber ese exceso.</p>
                </div>
            </div>

            <div class="error-item">
                <input type="checkbox" id="err4" aria-label="Expandir error común 4" onchange="toggleError(4)">
                <label for="err4" class="error-label">
                    <span class="error-icon">❌</span>
                    Pensar que "el carbono desaparece" en la atmosphere
                </label>
                <div class="error-explain" id="exp4">
                    <p><strong>Ley de conservación:</strong> El carbono NO desaparece. Solo CAMBIA DE FORMA y RESERVORIO.</p>
                    <p><strong>Ejemplo:</strong> CO₂ atmosférico → Glucosa (planta) → O₂ + emisión → CO₂ nuevamente. Es un ciclo eterno.</p>
                    <p><strong>El problema:</strong> Estamos extrayendo C del sistema lentísimo (fósiles de millones de años) e inyectándolo al sistema rápido (atmósfera) a velocidad que nadie puede absorber.</p>
                </div>
            </div>
        </div>

        <script>
        function toggleError(n){
            const exp = document.getElementById("exp" + n);
            const isVisible = exp.style.display === "block";
            exp.style.display = isVisible ? "none" : "block";
        }
        </script>
    </section>

