    <!-- ============================================================ -->
    <!-- SECCIÓN 8: PROBLEMAS TIPO EXAMEN -->
    <!-- ============================================================ -->
    <section class="exam-section" role="region" aria-label="Problemas tipo examen">
        <h2 class="seccion-titulo">
            <span class="neon-bullet">▶</span> VII. PROBLEMAS TIPO EXAMEN
        </h2>

        <div class="exam-problems-container">
            <div class="exam-problem">
                <div class="problem-header">
                    <span class="problem-num">PROBLEMA 1</span>
                    <span class="problem-difficulty">★★☆</span>
                </div>
                <p><strong>Pregunta:</strong> Explica por qué el ciclo del carbono es "rápido" en la atmósfera y biosfera, pero "lento" en la litosfera. Usa los tiempos de residencia para justificar tu respuesta.</p>
                <details>
                    <summary class="solution-toggle">Ver solución modelo</summary>
                    <div class="solution-text">
                        <p><strong>Respuesta:</strong> El tiempo de residencia es el factor clave:</p>
                        <ul>
                            <li><strong>Atmósfera:</strong> Años (intercambio rápido con océanos/biosfera)</li>
                            <li><strong>Biosfera:</strong> Décadas-siglos (fotosíntesis, descomposición)</li>
                            <li><strong>Litosfera:</strong> Millones de años (fósiles, rocas sedimentarias)</li>
                        </ul>
                        <p>El ciclo es rápido cuando el carbono se mueve entre reservorios activos. Es lento en la litosfera porque una vez "enterrado", el carbono requiere millones años de procesos geológicos para regresar.</p>
                    </div>
                </details>
            </div>

            <div class="exam-problem">
                <div class="problem-header">
                    <span class="problem-num">PROBLEMA 2</span>
                    <span class="problem-difficulty">★★★</span>
                </div>
                <p><strong>Pregunta (Cálculo):</strong> Si fotosíntesis = 120 GtC/año, respiración = 118 GtC/año, y emisiones humanas = 11.5 GtC/año, calcula:</p>
                <ol>
                    <li>Flujo neto natural (biosfera ↔ atmósfera)</li>
                    <li>Flujo neto TOTAL atmosférico</li>
                    <li>¿A dónde va el carbono "faltante"?</li>
                </ol>
                <details>
                    <summary class="solution-toggle">Ver solución modelo</summary>
                    <div class="solution-text">
                        <p><strong>Cálculos:</strong></p>
                        <ol>
                            <li>Flujo neto natural = 120 - 118 = <strong>+2 GtC/año</strong> (acumulación lenta)</li>
                            <li>Flujo neto total = 2 + 11.5 = <strong>+13.5 GtC/año</strong></li>
                            <li>El carbono va a:
                                <ul>
                                    <li>~25% a océanos (2.5 GtC) → acidificación</li>
                                    <li>~25% a biosfera terrestre (reforestación, aumento biomasa)</li>
                                    <li>~50% permanece en atmósfera (5-6 GtC) → aumento de CO₂</li>
                                </ul>
                            </li>
                        </ol>
                        <p style="color: #ffff00;">Conclusión: Atmósfera gana ~6 ppm CO₂/año</p>
                    </div>
                </details>
            </div>

            <div class="exam-problem">
                <div class="problem-header">
                    <span class="problem-num">PROBLEMA 3</span>
                    <span class="problem-difficulty">★★★★</span>
                </div>
                <p><strong>Pregunta (Análisis integrador):</strong> La deforestación amazónica anual es ~1 millón ha. Si cada hectárea almacena ~100 tC (toneladas de carbono), analiza el impacto TOTAL en el ciclo global del carbono (emisión directa + pérdida de sumidero).</p>
                <details>
                    <summary class="solution-toggle">Ver solución modelo</summary>
                    <div class="solution-text">
                        <p><strong>Análisis:</strong></p>
                        <ul>
                            <li><strong>Emisión directa:</strong> 1 M ha × 100 tC/ha = 100 MtC = 0.1 GtC/año</li>
                            <li><strong>Pérdida de sumidero:</strong> Ecosistema vivo absorbe ~2-3 tC/(ha·año). Pérdida = 2-3 MtC/año</li>
                            <li><strong>Impacto TOTAL muy superior:</strong> La pérdida de función como "pulmón" es más grave a largo plazo</li>
                        </ul>
                        <p>Conclusión: Deforestación = emisión + destrucción de sumidero natural</p>
                    </div>
                </details>
            </div>
        </div>
    </section>

