    'contenido' => '<p class="intro">
    La <strong>Ley del Mínimo</strong> de Justus von Liebig (1840) establece que el crecimiento y la productividad de un organismo o población están determinados no por la cantidad total de recursos disponibles, sino por el recurso esencial presente en menor cantidad relativa a las necesidades. Esta ley, ilustrada clásicamente con el “barril de Liebig”, es un principio fundamental en ecología, agricultura y gestión de recursos naturales, y explica fenómenos como la eutrofización, la limitación por nutrientes en océanos y la optimización de cultivos.
</p>

<p class="formula-neon text-center">
    Productividad real:<br>
    \\[ P = k \\cdot \\min(r_1, r_2, \\dots, r_n) \\]
</p>

<hr class="divider-neon">

