<!-- DESARROLLO TEÓRICO -->
<!-- ================================================= -->

<h3 class="section-title">
    I. Principios y Extensión de la Ley de Liebig
</h3>

<p>
    La ley se aplica a factores abióticos esenciales (nutrientes, agua, luz, temperatura) y se complementa con la <strong>Ley de Tolerancia</strong> de Victor Shelford (1913), que añade que el exceso también puede ser limitante.
</p>

<table class="neon-table">
    <thead>
        <tr>
            <th>Concepto</th>
            <th>Liebig (Mínimo)</th>
            <th>Shelford (Tolerancia)</th>
        </tr>
    </thead>
    <tbody>
        <tr>
            <td>Enfoque</td>
            <td>Déficit del recurso crítico</td>
            <td>Rango óptimo (mínimo y máximo)</td>
        </tr>
        <tr>
            <td>Ejemplo</td>
            <td>Fósforo limita fitoplancton</td>
            <td>Exceso de salinidad mata plantas</td>
        </tr>
        <tr>
            <td>Aplicación</td>
            <td>Fertilización balanceada</td>
            <td>Zonas de estrés ecológico</td>
        </tr>
    </tbody>
</table>

<div class="concept-box">
    <strong>Limitación secuencial:</strong> Al corregir un factor limitante, otro se convierte en el nuevo cuello de botella.
</div>

<hr class="divider-neon">

