<h4 class="subsection-title">Simulador: Barril de Liebig Dinámico</h4>

<p>
    Ajusta la disponibilidad de cada recurso y observa cómo el factor limitante determina la productividad máxima.
</p>
<div class="cyber-monitor" id="cyberSystem">
    <div class="monitor-header">
        > ANALYSIS_SYSTEM_V4.2: FACTORES LIMITANTES
    </div>

    <div class="controls-grid" style="display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; margin-bottom: 20px; background: rgba(0,0,0,0.3); padding: 10px; border: 1px solid #333;">
        <div class="control-item">
            <label style="font-size: 10px; color: var(--cyan); display: block;">N - NITRÓGENO</label>
            <input type="range" class="factor-slider" data-factor="N" min="10" max="100" value="80" style="width: 100%;">
        </div>
        <div class="control-item">
            <label style="font-size: 10px; color: var(--cyan); display: block;">P - FÓSFORO</label>
            <input type="range" class="factor-slider" data-factor="P" min="10" max="100" value="70" style="width: 100%;">
        </div>
        <div class="control-item">
            <label style="font-size: 10px; color: var(--cyan); display: block;">K - POTASIO</label>
            <input type="range" class="factor-slider" data-factor="K" min="10" max="100" value="90" style="width: 100%;">
        </div>
        <div class="control-item">
            <label style="font-size: 10px; color: var(--cyan); display: block;">H2O - AGUA</label>
            <input type="range" class="factor-slider" data-factor="H2O" min="10" max="100" value="60" style="width: 100%;">
        </div>
        <div class="control-item">
            <label style="font-size: 10px; color: var(--cyan); display: block;">Fe - HIERRO</label>
            <input type="range" class="factor-slider" data-factor="Fe" min="10" max="100" value="40" style="width: 100%;">
        </div>
    </div>

    <div class="factors-grid" id="monitorGrid">
        </div>

    <div class="system-status" id="systemStatus">
        </div>
</div>



<script>
(function(){
    const sliders = document.querySelectorAll(".factor-slider");
    const grid = document.getElementById("monitorGrid");
    const status = document.getElementById("systemStatus");

    const factorNames = {
        "N": "Nitrógeno",
        "P": "Fósforo",
        "K": "Potasio",
        "H2O": "Agua",
        "Fe": "Hierro"
    };

    function update(){
        let minValue = 101;
        let limitingKey = "";
        let html = "";

        // 1. Encontrar el valor mínimo primero
        sliders.forEach(s => {
            if(parseInt(s.value) < minValue) {
                minValue = parseInt(s.value);
                limitingKey = s.dataset.factor;
            }
        });

        // 2. Generar el HTML de las tarjetas
        sliders.forEach(s => {
            const key = s.dataset.factor;
            const val = s.value;
            const isLimiting = (key === limitingKey);

            html += `
                <div class="factor-card ${isLimiting ? \'limiting\' : \'\'}">
                    <span class="factor-name" ${isLimiting ? \'style="color: var(--red);"\' : \'\'}>${factorNames[key]}</span>
                    <div class="progress-container">
                        <div class="progress-bar" style="width: ${val}%; ${isLimiting ? \'background: var(--red);\' : \'\'}"></div>
                    </div>
                    <span class="factor-value">${val}%</span>
                </div>
            `;
        });

        grid.innerHTML = html;

        // 3. Actualizar el panel de status inferior
        status.innerHTML = `
            <span class="status-tag">[ ALERTA DE SISTEMA ]</span><br>
            FACTOR LIMITANTE DETECTADO: <span style="color: var(--red);">${factorNames[limitingKey].toUpperCase()}</span>.<br>
            PRODUCTIVIDAD MÁXIMA DEL ECOSISTEMA: <span style="color: var(--yellow);">${minValue}%</span>.
        `;
    }

    sliders.forEach(s => s.addEventListener("input", update));
    update(); // Ejecución inicial
})();
</script>

<h4 class="subsection-title">Mini-Laboratorio: Identificación del Factor Limitante</h4>

<p>
    Selecciona un ecosistema y analiza el factor limitante principal con su explicación y consecuencia ecológica.
</p>

<div class="mini-lab">
    <div class="lab-header">
        <span class="lab-label">Ecosistema:</span>
        <select id="ecosystemSelect">
            <option value="temperate-forest">Bosque templado</option>
            <option value="open-ocean">Océano abierto</option>
            <option value="desert">Desierto</option>
            <option value="eutrophic-lake">Lago eutrófico</option>
            <option value="tropical-rainforest" selected>Selva tropical</option>
            <option value="arctic-tundra">Tundra ártica</option>
        </select>
    </div>

    <div class="lab-card">
        <div class="card-title">Factor limitante principal:</div>
        <div class="card-limiting" id="labContent"></div>
        
        <div class="card-section">
            <div class="section-title">Explicación:</div>
            <div class="section-content" id="labExplanation"></div>
        </div>
        
        <div class="card-section">
            <div class="section-title">Consecuencia ecológica:</div>
            <div class="section-content" id="labConsequence"></div>
        </div>
    </div>
</div>

<script>
(function(){
    const select = document.getElementById("ecosystemSelect");
    const limiting = document.getElementById("labContent");
    const explanation = document.getElementById("labExplanation");
    const consequence = document.getElementById("labConsequence");

    const ecosystems = {
        "temperate-forest": {
            limiting: "Luz (en el sotobosque)",
            explanation: "La densa cobertura arbórea reduce la luz disponible para plántulas y hierbas del suelo.",
            consequence: "Regeneración forestal limitada; favorece especies tolerantes a sombra y estratificación vertical."
        },
        "open-ocean": {
            limiting: "Hierro (en zonas HNLC) o Nitrógeno",
            explanation: "En regiones de alta concentración de nutrientes pero baja clorofila (HNLC), el hierro es crítico para la fotosíntesis.",
            consequence: "Productividad fitoplanctónica baja pese a otros nutrientes; afecta toda la cadena trófica marina."
        },
        "desert": {
            limiting: "Agua",
            explanation: "La escasez hídrica controla todos los procesos biológicos en estos ambientes extremos.",
            consequence: "Adaptaciones extremas (suculentas, dormancia); baja biomasa y diversidad específica."
        },
        "eutrophic-lake": {
            limiting: "Fósforo",
            explanation: "Clásico ejemplo de limitación por P en aguas dulces continentales debido a su baja movilidad.",
            consequence: "Eutrofización: blooms de algas, anoxia y pérdida de biodiversidad acuática."
        },
        "tropical-rainforest": {
            limiting: "Fósforo (en suelos antiguos)",
            explanation: "Suelos altamente lixiviados carecen de P disponible pese a alta precipitación y temperatura.",
            consequence: "Estrategias de reciclaje eficiente de nutrientes; alta biodiversidad pero vulnerable a perturbaciones."
        },
        "arctic-tundra": {
            limiting: "Temperatura / Nutrientes (por permafrost)",
            explanation: "Bajas temperaturas y suelo congelado limitan la disponibilidad y descomposición de nutrientes.",
            consequence: "Crecimiento vegetal lento; ecosistema frágil al calentamiento global y liberación de carbono."
        }
    };

    function evaluate(){
        const data = ecosystems[select.value];
        limiting.textContent = data.limiting;
        explanation.textContent = data.explanation;
        consequence.textContent = data.consequence;
    }

    select.addEventListener("change", evaluate);
    evaluate();
})();
</script>

