            <button class="quiz-liebig-btn" data-correct="false" onclick="window.checkLiebigQuiz(this)">Solo importa el mínimo</button>
            <button class="quiz-liebig-btn" data-correct="false" onclick="window.checkLiebigQuiz(this)">No hay límites superiores</button>
        </div>
        <div class="quiz-liebig-feedback"></div>
    </div>

    <div class="quiz-liebig-question" data-question="3">
        <p class="quiz-liebig-text">3. En lagos eutróficos continentales, el nutriente limitante típico es:</p>
        <div class="quiz-liebig-options">
            <button class="quiz-liebig-btn" data-correct="true" onclick="window.checkLiebigQuiz(this)">Fósforo</button>
            <button class="quiz-liebig-btn" data-correct="false" onclick="window.checkLiebigQuiz(this)">Nitrógeno</button>
            <button class="quiz-liebig-btn" data-correct="false" onclick="window.checkLiebigQuiz(this)">Hierro</button>
        </div>
        <div class="quiz-liebig-feedback"></div>
    </div>

    <div class="quiz-liebig-question" data-question="4">
        <p class="quiz-liebig-text">4. En océanos abiertos (zonas HNLC), el limitante suele ser:</p>
        <div class="quiz-liebig-options">
            <button class="quiz-liebig-btn" data-correct="true" onclick="window.checkLiebigQuiz(this)">Hierro</button>
            <button class="quiz-liebig-btn" data-correct="false" onclick="window.checkLiebigQuiz(this)">Fósforo</button>
            <button class="quiz-liebig-btn" data-correct="false" onclick="window.checkLiebigQuiz(this)">Luz</button>
        </div>
        <div class="quiz-liebig-feedback"></div>
    </div>

    <div class="quiz-liebig-question" data-question="5">
        <p class="quiz-liebig-text">5. La limitación es secuencial porque:</p>
        <div class="quiz-liebig-options">
            <button class="quiz-liebig-btn" data-correct="true" onclick="window.checkLiebigQuiz(this)">Al corregir un factor, otro se vuelve limitante</button>
            <button class="quiz-liebig-btn" data-correct="false" onclick="window.checkLiebigQuiz(this)">Todos los factores son iguales</button>
            <button class="quiz-liebig-btn" data-correct="false" onclick="window.checkLiebigQuiz(this)">No cambia nunca</button>
        </div>
        <div class="quiz-liebig-feedback"></div>
    </div>

    <div id="liebigQuizScore" class="quiz-liebig-score">Puntuación: 0/5</div>
</div>

<script>
window.liebigQuizState = { score: 0, total: 5, answered: new Set() };
window.checkLiebigQuiz = function(button){
    if(!button) return;
    const question = button.closest(".quiz-liebig-question");
    if(!question) return;
    const questionNum = question.getAttribute("data-question");
    if(window.liebigQuizState.answered.has(questionNum)) return;
    
    const correct = button.getAttribute("data-correct") === "true";
    const feedback = question.querySelector(".quiz-liebig-feedback");
    const allButtons = question.querySelectorAll(".quiz-liebig-btn");
    
    allButtons.forEach(btn => {
        btn.disabled = true;
        if(btn.getAttribute("data-correct") === "true") btn.classList.add("quiz-liebig-correct");
        if(btn === button && !correct) btn.classList.add("quiz-liebig-incorrect");
    });
    
    window.liebigQuizState.answered.add(questionNum);
    if(correct) {
        window.liebigQuizState.score++;
        feedback.textContent = "✅ ¡Correcto!";
        feedback.classList.add("feedback-correct");
    } else {
        feedback.textContent = "❌ Incorrecto. La respuesta correcta está marcada.";
        feedback.classList.add("feedback-incorrect");
    }
    feedback.style.display = "block";
    const scoreEl = document.getElementById("liebigQuizScore");
    if(scoreEl) scoreEl.textContent = "Puntuación: " + window.liebigQuizState.score + "/" + window.liebigQuizState.total;
};
</script>

