<script>
window.toggleLiebigError = function(checkbox){
    const item = checkbox.closest(".error-liebig-item");
    if(!item) return;
    const explain = item.querySelector(".error-liebig-explain");
    if(explain) explain.style.display = checkbox.checked ? "block" : "none";
};
</script>

