</h3>

<p>
    Este tema pertenece al bloque "Factores bióticos y abióticos" y "Productividad de ecosistemas" en Biología y Ciencias Ambientales. Se evalúa en exámenes oficiales junto a cadenas tróficas, ciclos biogeoquímicos y manejo sostenible de recursos. Es fundamental para interpretar fenómenos como la eutrofización y la fertilización agrícola.
</p>

