</h3>

<ol class="exam-problems">
    <li>Explica con un ejemplo por qué añadir un nutriente en exceso no garantiza mayor productividad.</li>
    <li>Analiza la diferencia entre la Ley de Liebig y la Ley de Shelford con casos reales.</li>
    <li>En un lago eutrófico, ¿por qué el fósforo suele ser el factor limitante y no el nitrógeno?</li>
    <li>Predice el efecto de la acidificación oceánica sobre la limitación por hierro en fitoplancton.</li>
    <li>Justifica la aplicación de la Ley del Mínimo en la gestión sostenible de agroecosistemas.</li>
</ol>

