<h3 class="section-title">
    VII. Reflexión Metacognitiva
</h3>

<ul class="reflection-list">
    <li>¿Cómo cambia tu comprensión de la productividad ecosistémica al reconocer que siempre existe un factor limitante?</li>
    <li>¿En qué situaciones reales (agricultura, conservación) aplicarías la Ley de Liebig para tomar decisiones?</li>
    <li>¿Qué estrategia usarás para identificar el verdadero factor limitante en problemas complejos de examen?</li>
</ul>

<p class="conclusion">
    La Ley de Liebig nos recuerda que en la naturaleza, el equilibrio depende de no fallar en lo esencial. Dominar este principio permite gestionar recursos de forma inteligente y sostenible.
</p>

