    'contenido' => '<p class="intro">
    La <strong>Ley de la Tolerancia</strong> (Victor Ernest Shelford, 1913) establece que la existencia, abundancia y distribución de una especie están determinadas por el rango de valores que puede tolerar cada factor ambiental. No solo el déficit (como en la Ley de Liebig), sino también el exceso de cualquier factor puede limitar o eliminar una población. Esta ley es clave para entender la distribución de especies, la sucesión ecológica, la vulnerabilidad al cambio climático y la gestión de ecosistemas.
</p>

<p class="formula-neon text-center">
    Rendimiento biológico:<br>
    \\[ R(F) = 
    \\begin{cases} 
    0 & \\text{si } F < F_{\\min} \\text{ o } F > F_{\\max} \\\\
    >0 & \\text{si } F_{\\min} \\leq F \\leq F_{\\max}
    \\end{cases}
    \\]
</p>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- DESARROLLO TEÓRICO -->
<!-- ================================================= -->

<h3 class="section-title">
    I. Principios de la Ley de la Tolerancia
</h3>

<p>
    Cada factor ambiental presenta un rango de tolerancia definido por valores mínimos, óptimos y máximos. Dentro del rango óptimo, la especie alcanza su máximo rendimiento fisiológico y reproductivo.
</p>

<table class="neon-table">
    <thead>
        <tr>
            <th>Zona</th>
            <th>Descripción</th>
            <th>Efecto biológico</th>
            <th>Ejemplo</th>
        </tr>
    </thead>
    <tbody>
        <tr>
            <td>Zona letal mínima</td>
            <td>F < F<sub>min</sub></td>
            <td>Muerte por déficit</td>
            <td>Congelación celular</td>
        </tr>
        <tr>
            <td>Zona de estrés mínima</td>
            <td>F<sub>min</sub> – F<sub>opt min</sub></td>
            <td>Reducción de crecimiento</td>
            <td>Deficiencia nutricional</td>
        </tr>
        <tr>
            <td>Zona óptima</td>
            <td>F<sub>opt min</sub> – F<sub>opt max</sub></td>
            <td>Máximo rendimiento</td>
            <td>Condiciones ideales</td>
        </tr>
        <tr>
            <td>Zona de estrés máxima</td>
            <td>F<sub>opt max</sub> – F<sub>max</sub></td>
            <td>Reducción progresiva</td>
            <td>Toxicidad por exceso</td>
        </tr>
        <tr>
            <td>Zona letal máxima</td>
            <td>F > F<sub>max</sub></td>
            <td>Muerte por exceso</td>
            <td>Hipertermia</td>
        </tr>
    </tbody>
</table>

<div class="concept-box">
    <strong>Estenoicas vs Eurioicas:</strong> Las especies estenoicas tienen rangos estrechos (especialistas), mientras que las eurioicas tienen rangos amplios (generalistas). En escenarios de cambio ambiental, las estenoicas son más vulnerables.
</div>

