<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Curva de Tolerancia Dinámica</h4>

<p>
    Ajusta la intensidad del factor ambiental (ej. temperatura) y observa la respuesta biológica de una especie hipotética.
</p>

<div class="shelford-sim">
    <label>Intensidad del factor (% del rango total): <span id="factorValue">50</span>%</label>
    <input type="range" id="factorSlider" min="0" max="100" value="50">

    <div class="meter-track">
        <div class="meter-fill" id="toleranceFill"></div>
    </div>

    <div class="sim-result" id="toleranceResult"></div>
</div>

<script>
(function(){
    const slider = document.getElementById("factorSlider");
    const value = document.getElementById("factorValue");
    const fill = document.getElementById("toleranceFill");
    const result = document.getElementById("toleranceResult");

    function update(){
        const v = parseInt(slider.value);
        value.textContent = v;

        let zone = "", message = "", color = "";

        if (v < 15) {
            zone = "Zona letal mínima";
            message = "Déficit extremo: muerte celular por falta del factor.";
            color = "#ff1744";
        } else if (v < 30) {
            zone = "Estrés mínimo";
            message = "Crecimiento reducido, menor reproducción.";
            color = "#ff9800";
        } else if (v <= 70) {
            zone = "Zona óptima";
            message = "Máximo rendimiento fisiológico y reproductivo.";
            color = "#00e676";
        } else if (v <= 85) {
            zone = "Estrés máximo";
            message = "Toxicidad progresiva, reducción de fitness.";
            color = "#ff9800";
        } else {
            zone = "Zona letal máxima";
            message = "Exceso letal: colapso metabólico.";
            color = "#ff1744";
        }

        fill.style.width = v + "%";
        fill.style.background = color;

        result.innerHTML = `<strong>${zone}</strong><br>${message}`;
    }

    slider.addEventListener("input", update);
    update();
})();
</script>

<h4 class="subsection-title">Mini-Laboratorio: Comparación Estenoica vs Eurioica</h4>

<p>
    Selecciona el tipo de especie y el cambio ambiental para analizar su resiliencia.
</p>

<div class="mini-lab">
    <div class="lab-header">
        <label>Tipo de especie:</label>
        <select id="speciesType">
            <option value="steno">Estenoica (rango estrecho)</option>
            <option value="eurio">Eurioica (rango amplio)</option>
        </select>

        <label>Cambio ambiental:</label>
        <select id="changeType">
            <option value="temp-up">Aumento temperatura +4°C</option>
            <option value="ph-down">Acidificación pH -0.3</option>
            <option value="salinity-up">Aumento salinidad +5 ppt</option>
        </select>
    </div>

    <div class="lab-output" id="resilienceResult"></div>
</div>

<script>
(function(){
    const typeSelect = document.getElementById("speciesType");
    const changeSelect = document.getElementById("changeType");
    const output = document.getElementById("resilienceResult");

    function evaluate(){
        const type = typeSelect.value;
        const change = changeSelect.value;

        let risk = "", explanation = "";

        if (type === "steno") {
            risk = "ALTO RIESGO";
            explanation = "Especies con rangos estrechos son altamente vulnerables a cambios ambientales. Probable reducción poblacional o extinción local.";
        } else {
            risk = "BAJO A MEDIO RIESGO";
            explanation = "Especies eurioicas toleran mayor variabilidad. Pueden adaptarse o migrar con menor impacto.";
        }

        output.innerHTML = `<strong>Riesgo de impacto:</strong> ${risk}<br>
                            <strong>Análisis:</strong> ${explanation}<br>
                            <em>Ejemplo real: ${type === "steno" ? "Corales en blanqueamiento" : "Ratas urbanas en contaminación"}</em>`;
    }

    typeSelect.addEventListener("change", evaluate);
    changeSelect.addEventListener("change", evaluate);
    evaluate();
})();
</script>

<h4 class="subsection-title">Quiz Autoevaluado: Ley de la Tolerancia</h4>

<div class="quiz-shelford-container">
    <div class="quiz-shelford-question" data-question="1">
        <p class="quiz-shelford-text">1. La Ley de Shelford enfatiza que:</p>
        <div class="quiz-shelford-options">
            <button class="quiz-shelford-btn" data-correct="false" onclick="window.checkShelfordQuiz(this)">Solo el déficit limita</button>
            <button class="quiz-shelford-btn" data-correct="true" onclick="window.checkShelfordQuiz(this)">Tanto el déficit como el exceso pueden limitar</button>
            <button class="quiz-shelford-btn" data-correct="false" onclick="window.checkShelfordQuiz(this)">No existen límites superiores</button>
        </div>
        <div class="quiz-shelford-feedback"></div>
    </div>

    <div class="quiz-shelford-question" data-question="2">
        <p class="quiz-shelford-text">2. En la zona óptima:</p>
        <div class="quiz-shelford-options">
            <button class="quiz-shelford-btn" data-correct="true" onclick="window.checkShelfordQuiz(this)">Se alcanza el máximo rendimiento biológico</button>
            <button class="quiz-shelford-btn" data-correct="false" onclick="window.checkShelfordQuiz(this)">Hay estrés fisiológico</button>
            <button class="quiz-shelford-btn" data-correct="false" onclick="window.checkShelfordQuiz(this)">La supervivencia es imposible</button>
        </div>
        <div class="quiz-shelford-feedback"></div>
    </div>

    <div class="quiz-shelford-question" data-question="3">
        <p class="quiz-shelford-text">3. Las especies estenoicas son:</p>
        <div class="quiz-shelford-options">
            <button class="quiz-shelford-btn" data-correct="true" onclick="window.checkShelfordQuiz(this)">Especialistas con rangos estrechos</button>
            <button class="quiz-shelford-btn" data-correct="false" onclick="window.checkShelfordQuiz(this)">Generalistas con rangos amplios</button>
            <button class="quiz-shelford-btn" data-correct="false" onclick="window.checkShelfordQuiz(this)">Indiferentes a factores ambientales</button>
        </div>
        <div class="quiz-shelford-feedback"></div>
    </div>

    <div class="quiz-shelford-question" data-question="4">
        <p class="quiz-shelford-text">4. En cambio climático, las más vulnerables son:</p>
        <div class="quiz-shelford-options">
            <button class="quiz-shelford-btn" data-correct="true" onclick="window.checkShelfordQuiz(this)">Especies estenoicas</button>
            <button class="quiz-shelford-btn" data-correct="false" onclick="window.checkShelfordQuiz(this)">Especies eurioicas</button>
            <button class="quiz-shelford-btn" data-correct="false" onclick="window.checkShelfordQuiz(this)">Todas por igual</button>
        </div>
        <div class="quiz-shelford-feedback"></div>
    </div>

    <div id="shelfordQuizScore" class="quiz-shelford-score">Puntuación: 0/4</div>
</div>

<script>
window.shelfordQuizState = { score: 0, total: 4, answered: new Set() };
window.checkShelfordQuiz = function(button){
    if(!button) return;
    const question = button.closest(".quiz-shelford-question");
    if(!question) return;
    const questionNum = question.getAttribute("data-question");
    if(window.shelfordQuizState.answered.has(questionNum)) return;
    
    const correct = button.getAttribute("data-correct") === "true";
    const feedback = question.querySelector(".quiz-shelford-feedback");
    const allButtons = question.querySelectorAll(".quiz-shelford-btn");
    
    allButtons.forEach(btn => {
        btn.disabled = true;
        if(btn.getAttribute("data-correct") === "true") btn.classList.add("quiz-shelford-correct");
        if(btn === button && !correct) btn.classList.add("quiz-shelford-incorrect");
    });
    
    window.shelfordQuizState.answered.add(questionNum);
    if(correct) {
        window.shelfordQuizState.score++;
        feedback.textContent = "✅ ¡Correcto!";
        feedback.classList.add("feedback-correct");
    } else {
        feedback.textContent = "❌ Incorrecto. La respuesta correcta está marcada.";
        feedback.classList.add("feedback-incorrect");
    }
    feedback.style.display = "block";
    const scoreEl = document.getElementById("shelfordQuizScore");
    if(scoreEl) scoreEl.textContent = "Puntuación: " + window.shelfordQuizState.score + "/" + window.shelfordQuizState.total;
};
</script>

