        <div class="error-shelford-explain" style="display:none;">Ejemplo: eutrofización por exceso de nutrientes causa blooms tóxicos.</div>
    </div>
</div>

<script>
window.toggleShelfordError = function(checkbox){
    const item = checkbox.closest(".error-shelford-item");
    if(!item) return;
    const explain = item.querySelector(".error-shelford-explain");
    if(explain) explain.style.display = checkbox.checked ? "block" : "none";
};
</script>

