<h3 class="section-title">
    V. Conexión con el Currículo de Ecosistemas
</h3>

<p>
    La Ley de Shelford forma parte del bloque "Interacciones organismo-ambiente" y "Distribución de especies" en Biología y Ecología (secundaria y universitaria). Se evalúa junto a la Ley de Liebig, nicho ecológico y respuesta al cambio global. Es esencial para interpretar patrones de biodiversidad y diseñar estrategias de conservación en contextos de cambio climático.
</p>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- PROBLEMAS TIPO EXAMEN -->
<!-- ================================================= -->

<h3 class="section-title">
    VI. Problemas Tipo Examen
</h3>

<ol class="exam-problems">
    <li>Explica por qué una especie estenoica térmica es más vulnerable al calentamiento global que una eurioica, usando la Ley de Shelford.</li>
    <li>Analiza el impacto de la acidificación oceánica (disminución de pH) en corales según rangos de tolerancia.</li>
    <li>Dibuja y etiqueta una curva de tolerancia típica, identificando zonas y explicando implicaciones ecológicas.</li>
    <li>Justifica cómo la Ley de Shelford complementa la Ley de Liebig en la explicación de la distribución de especies.</li>
    <li>Predice el efecto de un aumento de salinidad en un estuario sobre especies dulceacuícolas y marinas.</li>
</ol>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- CIERRE METACOGNITIVO -->
<!-- ================================================= -->

<h3 class="section-title">
    VII. Reflexión Metacognitiva
</h3>

<ul class="reflection-list">
    <li>¿Cómo cambia tu visión de la vulnerabilidad ecológica al entender que el exceso puede ser tan limitante como el déficit?</li>
    <li>¿En qué problemas ambientales actuales (calentamiento, contaminación) ves aplicada la Ley de Shelford?</li>
    <li>¿Qué estrategia usarás para analizar rangos de tolerancia en futuros temas de ecología o conservación?</li>
</ul>

<p class="conclusion">
    La Ley de la Tolerancia nos enseña que la vida prospera en equilibrio delicado. Comprender sus límites es esencial para preservar la biodiversidad en un planeta en transformación.
</p>

<blockquote class="neon-quote">
