    'contenido' => '
<p class="intro">
    Los <strong>factores ambientales</strong> son todos los elementos del entorno que influyen en la supervivencia, crecimiento, reproducción y distribución de los organismos. Se clasifican en <strong>abióticos</strong> (componentes no vivos: físicos y químicos) y <strong>bióticos</strong> (interacciones con otros organismos vivos). Su interacción determina la estructura, funcionamiento y dinámica de los ecosistemas, así como la adaptación de las especies.
</p>

<p class="formula-neon text-center">
    Nicho ecológico simplificado:<br>
    \\[ N = f(A_1, A_2, \\dots, B_1, B_2, \\dots) \\]
</p>

