<h3 class="section-title">
    I. Clasificación y Características
</h3>

<table class="neon-table">
    <thead>
        <tr>
            <th>Tipo</th>
            <th>Características</th>
            <th>Ejemplos principales</th>
            <th>Efecto en organismos</th>
        </tr>
    </thead>
    <tbody>
        <tr>
            <td>Abióticos</td>
            <td>Físicos y químicos, no vivos</td>
            <td>Temperatura, luz, agua, pH, nutrientes, salinidad, O₂</td>
            <td>Definen límites fisiológicos (Ley de Shelford)</td>
        </tr>
        <tr>
            <td>Bióticos</td>
            <td>Interacciones entre organismos</td>
            <td>Competencia, depredación, mutualismo, parasitismo, comensalismo</td>
            <td>Regulan poblaciones y estructura comunitaria</td>
        </tr>
    </tbody>
</table>

<div class="concept-box">
    <strong>Interacción clave:</strong> Los factores abióticos establecen los límites posibles de vida; los bióticos determinan quién ocupa esos límites.
</div>

