<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Intensidad de Factores Ambientales</h4>

<p>
    Ajusta la intensidad de un factor ambiental y observa su impacto en la supervivencia de una población.
</p>

<div class="factors-sim">
    <label>Factor seleccionado:</label>
    <select id="factorSelect">
        <option value="temp">Temperatura (°C)</option>
        <option value="water">Disponibilidad de agua (%)</option>
        <option value="light">Intensidad lumínica (lux)</option>
        <option value="ph">pH del suelo</option>
    </select>

    <label>Intensidad: <span id="intensityValue">50</span></label>
    <input type="range" id="intensitySlider" min="0" max="100" value="50">

    <div class="sim-result" id="factorResult"></div>
</div>

<script>
(function(){
    const select = document.getElementById("factorSelect");
    const slider = document.getElementById("intensitySlider");
    const value = document.getElementById("intensityValue");
    const result = document.getElementById("factorResult");

    function update(){
        const factor = select.value;
        const v = parseInt(slider.value);
        value.textContent = v;

        let zone = "", message = "";

        if (v < 20 || v > 80) {
            zone = "Zona letal";
            message = "Supervivencia imposible: población colapsa.";
        } else if (v < 35 || v > 65) {
            zone = "Estrés elevado";
            message = "Crecimiento y reproducción reducidos.";
        } else {
            zone = "Condiciones óptimas";
            message = "Máxima productividad y abundancia.";
        }

        result.innerHTML = `<strong>${zone}</strong><br>${message}`;
    }

    select.addEventListener("change", update);
    slider.addEventListener("input", update);
    update();
})();
</script>

<h4 class="subsection-title">Simulador: Interacciones Bióticas</h4>

<p>
    Selecciona una interacción biótica y analiza su efecto en dos especies.
</p>

<div class="factors-sim">
    <label>Interacción:</label>
    <select id="bioticSelect">
        <option value="comp">Competencia (-/-)</option>
        <option value="pred">Depredación (+/-)</option>
        <option value="mut">Mutualismo (+/+)</option>
        <option value="par">Parasitismo (+/-)</option>
        <option value="com">Comensalismo (+/0)</option>
    </select>

    <div class="sim-result" id="bioticResult"></div>
</div>

<script>
(function(){
    const select = document.getElementById("bioticSelect");
    const result = document.getElementById("bioticResult");

    const interactions = {
        "comp": { effect: "- / -", desc: "Ambas especies compiten por recursos limitados → reducción poblacional mutua.", example: "Árboles por luz en bosque." },
        "pred": { effect: "+ / -", desc: "Depredador beneficia, presa perjudicada → control poblacional.", example: "Lince y liebre." },
        "mut": { effect: "+ / +", desc: "Beneficio mutuo → estabilidad y coevolución.", example: "Polinizadores y plantas." },
        "par": { effect: "+ / -", desc: "Parásito beneficia, huésped perjudicado.", example: "Garrapatas en mamíferos." },
        "com": { effect: "+ / 0", desc: "Una especie beneficia sin afectar a la otra.", example: "Rémora y tiburón." }
    };

    function update(){
        const data = interactions[select.value];
        result.innerHTML = `<strong>Efecto:</strong> ${data.effect}<br>
                            <strong>Descripción:</strong> ${data.desc}<br>
                            <strong>Ejemplo:</strong> ${data.example}`;
    }

    select.addEventListener("change", update);
    update();
})();
</script>

<h4 class="subsection-title">Quiz Autoevaluado: Factores Ambientales</h4>

<div class="quiz-container">
    <div class="quiz-question">
        <p>1. Los factores abióticos son:</p>
        <button onclick="checkQuiz(1,false)">Interacciones entre organismos</button>
        <button onclick="checkQuiz(1,true)">Componentes físicos y químicos no vivos</button>
        <button onclick="checkQuiz(1,false)">Solo relaciones tróficas</button>
        <div id="fb1"></div>
    </div>

    <div class="quiz-question">
        <p>2. Un ejemplo de interacción biótica +/+ es:</p>
        <button onclick="checkQuiz(2,true)">Mutualismo</button>
        <button onclick="checkQuiz(2,false)">Competencia</button>
        <button onclick="checkQuiz(2,false)">Depredación</button>
        <div id="fb2"></div>
    </div>

    <div class="quiz-question">
        <p>3. La luz solar es un factor:</p>
        <button onclick="checkQuiz(3,true)">Abiótico</button>
        <button onclick="checkQuiz(3,false)">Biótico</button>
        <button onclick="checkQuiz(3,false)">Ninguno</button>
        <div id="fb3"></div>
    </div>

    <div id="quizScore" class="score-display">Puntuación: 0/3</div>
</div>

<script>
let score = 0;
const total = 3;
const answeredQuestions = new Set();
function checkQuiz(q, correct){
    if (answeredQuestions.has(q)) {
        return; // evita recuento múltiple y cambios de respuesta repetidos
    }
    answeredQuestions.add(q);

    const fb = document.getElementById("fb" + q);
    const container = fb.closest(\'.quiz-question\');
    const btns = container.querySelectorAll(\'button\');

    if (correct){
        fb.innerHTML = "✅ Correcto";
        fb.style.color = "#00e676";
        score++;
    } else {
        fb.innerHTML = "❌ Incorrecto";
        fb.style.color = "#ff1744";
    }

    btns.forEach(b => b.disabled = true);
    document.getElementById("quizScore").textContent = "Puntuación: " + score + "/" + total;
}
</script>

