</h3>

<div class="errors-interactive">
    <div class="error-item">
        <input type="checkbox" id="err1" onchange="toggleError(1)">
        <label for="err1">Confundir factores abióticos con bióticos.</label>
        <div class="error-explain" id="exp1">Ejemplo: considerar la depredación como abiótica (es biótica).</div>
    </div>
    <div class="error-item">
        <input type="checkbox" id="err2" onchange="toggleError(2)">
        <label for="err2">Ignorar que los factores interactúan simultáneamente.</label>
        <div class="error-explain" id="exp2">Un cambio abiótico (sequía) puede intensificar competencia biótica.</div>
    </div>
    <div class="error-item">
        <input type="checkbox" id="err3" onchange="toggleError(3)">
        <label for="err3">Pensar que todos los factores bióticos son negativos.</label>
        <div class="error-explain" id="exp3">Mutualismo y comensalismo son positivos o neutros.</div>
    </div>
</div>

<script>
function toggleError(n){
    const exp = document.getElementById("exp" + n);
    exp.style.display = document.getElementById("err" + n).checked ? "block" : "none";
}
</script>

