<h3 class="section-title">
    V. Conexión con el Currículo de Ecosistemas
</h3>

<p>
    Este tema es central en el bloque "Interacciones en ecosistemas" y "Dinámica poblacional" en Biología y Ciencias Ambientales. Se evalúa en exámenes oficiales junto a nicho ecológico, Ley de Liebig/Shelford y estructura trófica. Es base para comprender biodiversidad, sucesión y respuesta al cambio ambiental.
</p>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- PROBLEMAS TIPO EXAMEN -->
<!-- ================================================= -->

<h3 class="section-title">
    VI. Problemas Tipo Examen
</h3>

<ol class="exam-problems">
    <li>Clasifica como abiótico o biótico: temperatura, depredación, salinidad, mutualismo. Justifica cada uno.</li>
    <li>Explica cómo un factor abiótico (sequía) puede modificar una interacción biótica (competencia).</li>
    <li>Analiza el signo (+/−/0) de una interacción comensalismo y compáralo con parasitismo.</li>
    <li>En un ecosistema acuático, identifica factores abióticos clave y su posible rol limitante.</li>
    <li>Justifica por qué los factores ambientales determinan la distribución geográfica de una especie.</li>
</ol>

<hr class="divider-neon">

