<h3 class="section-title">
    VII. Reflexión Metacognitiva
</h3>

<ul class="reflection-list">
    <li>¿Cómo cambia tu comprensión de los ecosistemas al ver la interacción constante entre factores abióticos y bióticos?</li>
    <li>¿En qué situaciones reales (conservación, agricultura) considerarías ambos tipos de factores para tomar decisiones?</li>
    <li>¿Qué estrategia usarás para clasificar y analizar factores ambientales en problemas complejos de examen?</li>
</ul>

<p class="conclusion">
    Los factores ambientales no actúan aislados: su interacción define la vida en el planeta. Dominar esta clasificación es esencial para entender y gestionar ecosistemas sostenibles.
</p>

