    'contenido' => '<div class="leccion-biomas">
<p class="intro">
    Un <strong>bioma</strong> es una gran comunidad biológica caracterizada por una vegetación dominante y fauna adaptada a condiciones climáticas específicas. Los biomas representan patrones convergentes de la evolución: climas similares producen ecosistemas estructuralmente parecidos aunque con especies diferentes. Comprender los biomas permite predecir la distribución de la vida, evaluar impactos del cambio climático y gestionar recursos naturales a escala global.
</p>

<p class="formula-neon text-center">
    Diagrama de Whittaker (1975):<br>
    Bioma ≈ f(Temperatura media, Precipitación anual)
</p>

