<h3 class="section-title">
    I. Concepto y Clasificación de Biomas
</h3>

<p>
    Los biomas se definen principalmente por el clima (temperatura y precipitación), que determina la fisonomía vegetal y, consecuentemente, la fauna asociada.
</p>

<table class="neon-table">
    <thead>
        <tr>
            <th>Bioma Terrestre</th>
            <th>Temperatura media (°C)</th>
            <th>Precipitación (mm/año)</th>
            <th>Vegetación dominante</th>
            <th>Biodiversidad</th>
        </tr>
    </thead>
    <tbody>
        <tr><td>Tundra</td><td><0</td><td><400</td><td>Musgos, líquenes</td><td>Baja</td></tr>
        <tr><td>Taiga</td><td>0–10</td><td>300–800</td><td>Coníferas</td><td>Media-baja</td></tr>
        <tr><td>Bosque templado</td><td>5–20</td><td>750–1500</td><td>Caducifolios</td><td>Media-alta</td></tr>
        <tr><td>Selva tropical</td><td>>25</td><td>>2000</td><td>Evergreen estratificado</td><td>Muy alta</td></tr>
        <tr><td>Sabana</td><td>>20</td><td>500–1500 (estacional)</td><td>Pastos + árboles dispersos</td><td>Alta</td></tr>
        <tr><td>Pradera</td><td>0–20</td><td>300–1000</td><td>Gramíneas</td><td>Media</td></tr>
        <tr><td>Desierto</td><td>Variable</td><td><250</td><td>Suculentas, xerófitas</td><td>Baja-media</td></tr>
    </tbody>
</table>

<div class="concept-box">
    <strong>Biomas acuáticos:</strong> No dependen del área, sino de luz, nutrientes y temperatura. Ejemplos: arrecifes coralinos (alta productividad), océano abierto (baja productividad), humedales (muy alta).
</div>

