<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Predicción de Bioma por Clima</h4>

<p>
    Ajusta temperatura y precipitación para predecir el bioma terrestre dominante (basado en diagrama de Whittaker).
</p>

<div class="biomes-sim">
    <label>Temperatura media anual (°C): <span id="tempValue">15</span> °C</label>
    <input type="range" id="tempSlider" min="-20" max="35" value="15">

    <label>Precipitación anual (mm): <span id="rainValue">800</span> mm</label>
    <input type="range" id="rainSlider" min="0" max="4000" value="800">

    <div class="sim-result" id="biomeResult"></div>
</div>

<script>
(function(){
    const tempSlider = document.getElementById("tempSlider");
    const rainSlider = document.getElementById("rainSlider");
    const tempValue = document.getElementById("tempValue");
    const rainValue = document.getElementById("rainValue");
    const result = document.getElementById("biomeResult");

    function predictBiome(){
        const temp = parseInt(tempSlider.value);
        const rain = parseInt(rainSlider.value);

        tempValue.textContent = temp;
        rainValue.textContent = rain;

        let biome = "", icon = "", desc = "";

        if (rain < 250) {
            biome = "Desierto";
            icon = "🏜️";
            desc = "Aridez extrema limita vegetación.";
        } else if (temp < 0) {
            biome = "Tundra";
            icon = "🧊";
            desc = "Frío permanente y permafrost.";
        } else if (temp < 10 && rain > 300) {
            biome = "Taiga";
            icon = "🌲";
            desc = "Bosques boreales de coníferas.";
        } else if (temp > 22 && rain > 2000) {
            biome = "Selva tropical";
            icon = "🌴";
            desc = "Máxima biodiversidad y productividad.";
        } else if (temp > 20 && rain > 600 && rain < 2000) {
            biome = "Sabana";
            icon = "🦁";
            desc = "Pastizales con árboles dispersos y fuego estacional.";
        } else if (temp > 5 && rain > 600) {
            biome = "Bosque templado";
            icon = "🍂";
            desc = "Caducifolios con estaciones marcadas.";
        } else {
            biome = "Pradera / Estepa";
            icon = "🌾";
            desc = "Dominio de gramíneas y suelos fértiles.";
        }

        result.innerHTML = `<h5>${icon} Bioma predicho: ${biome}</h5>
                            <p>${desc}</p>`;
    }

    tempSlider.addEventListener("input", predictBiome);
    rainSlider.addEventListener("input", predictBiome);
    predictBiome();
})();
</script>

<h4 class="subsection-title">Análisis: Distribución Global de Biomas</h4>

<p>
    Selecciona una zona climática para explorar su bioma característico.
</p>

<div class="biomes-sim">
    <div class="map-controls">
        <button data-zone="polar">❄️ Polar</button>
        <button data-zone="subpolar">🌲 Subpolar</button>
        <button data-zone="temperate">🍁 Templada</button>
        <button data-zone="tropical">🌴 Tropical</button>
        <button data-zone="arid">🏜️ Árida</button>
    </div>

    <div class="sim-result" id="zoneResult">Selecciona una zona para ver detalles.</div>
</div>

<script>
(function(){
    const buttons = document.querySelectorAll(".map-controls button");
    const result = document.getElementById("zoneResult");

    const zones = {
        polar: "❄️ Zonas Polares: Tundra ártica y antártica. Baja productividad, permafrost.",
        subpolar: "🌲 Subpolar: Taiga o bosque boreal. Coníferas adaptadas al frío.",
        temperate: "🍁 Templada: Bosques caducifolios y praderas. Alta productividad estacional.",
        tropical: "🌴 Tropical: Selvas y sabanas. Máxima biodiversidad y biomasa.",
        arid: "🏜️ Árida: Desiertos cálidos y fríos. Adaptaciones extremas al déficit hídrico."
    };

    buttons.forEach(btn => {
        btn.addEventListener("click", () => {
            buttons.forEach(b => b.classList.remove("active"));
            btn.classList.add("active");
            result.innerHTML = `<strong>${btn.textContent}</strong><br>${zones[btn.dataset.zone]}`;
        });
    });
})();
</script>

<h4 class="subsection-title">Quiz Autoevaluado: Biomas</h4>

<div class="quiz-container">
    <div class="quiz-question">
        <p>1. El bioma con mayor biodiversidad terrestre es:</p>
        <button onclick="checkQuiz(1,false)">Desierto</button>
        <button onclick="checkQuiz(1,true)">Selva tropical</button>
        <button onclick="checkQuiz(1,false)">Tundra</button>
        <div id="fb1"></div>
    </div>

    <div class="quiz-question">
        <p>2. La vegetación dominante en sabanas es:</p>
        <button onclick="checkQuiz(2,true)">Pastos con árboles dispersos</button>
        <button onclick="checkQuiz(2,false)">Coníferas</button>
        <button onclick="checkQuiz(2,false)">Suculentas</button>
        <div id="fb2"></div>
    </div>

    <div class="quiz-question">
        <p>3. El factor clave que diferencia taiga de bosque templado es:</p>
        <button onclick="checkQuiz(3,true)">Temperatura (más fría en taiga)</button>
        <button onclick="checkQuiz(3,false)">Precipitación</button>
        <button onclick="checkQuiz(3,false)">Luz solar</button>
        <div id="fb3"></div>
    </div>

    <div id="quizScore" class="score-display">Puntuación: 0/3</div>
    <button class="btn-reset-quiz" id="resetQuizBtn">Reiniciar Mini-Quiz</button>
</div>

<script>
let score = 0;
const total = 3;
const answeredQuestions = new Set();
function updateQuizScore(){
    document.getElementById("quizScore").textContent = "Puntuación: " + score + "/" + total;
}
function checkQuiz(q, correct){
    if (answeredQuestions.has(q)) return;
    answeredQuestions.add(q);

    const fb = document.getElementById("fb" + q);
    const questionEl = fb.closest(\'.quiz-question\');
    const buttons = questionEl.querySelectorAll(\'button\');

    if (correct){
        fb.innerHTML = "✅ Correcto";
        fb.style.color = "#00e676";
        score++;
        questionEl.classList.add(\'quiz-answered-correct\');
    } else {
        fb.innerHTML = "❌ Incorrecto";
        fb.style.color = "#ff1744";
        questionEl.classList.add(\'quiz-answered-incorrect\');
    }

    buttons.forEach(b => b.disabled = true);
    updateQuizScore();
}

function resetQuiz(){
    score = 0;
    answeredQuestions.clear();
    updateQuizScore();

    document.querySelectorAll(\'.quiz-question\').forEach(q => {
        q.querySelector(\'div[id^="fb"]\').innerHTML = \'\';
        q.classList.remove(\'quiz-answered-correct\', \'quiz-answered-incorrect\');
        q.querySelectorAll(\'button\').forEach(b => { b.disabled = false; b.style.opacity = \'1\'; });
    });
}

document.getElementById(\'resetQuizBtn\').addEventListener(\'click\', resetQuiz);
</script>

