<h3 class="section-title">
    V. Conexión con el Currículo de Ecosistemas
</h3>

<p>
    Este tema pertenece al bloque "Estructura y funcionamiento de ecosistemas" y "Distribución global de la vida" en Biología y Ciencias Ambientales. Se evalúa en exámenes oficiales junto a factores abióticos/bióticos, productividad primaria y cambio global. Es fundamental para interpretar mapas biogeográficos y modelos de impacto climático.
</p>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- PROBLEMAS TIPO EXAMEN -->
<!-- ================================================= -->

<h3 class="section-title">
    VI. Problemas Tipo Examen
</h3>

<ol class="exam-problems">
    <li>Explica por qué dos continentes con climas similares presentan biomas convergentes aunque con especies diferentes.</li>
    <li>Predice el cambio en biomas si la temperatura global aumenta 3°C y la precipitación disminuye en zonas subtropicales.</li>
    <li>Compara productividad y biodiversidad entre selva tropical y tundra, justificando con factores climáticos.</li>
    <li>Analiza por qué los humedales tienen alta productividad a pesar de no ser biomas terrestres extensos.</li>
    <li>Justifica la distribución latitudinal de biomas usando circulación atmosférica.</li>
</ol>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- CIERRE METACOGNITIVO -->
<!-- ================================================= -->

<h3 class="section-title">
    VII. Reflexión Metacognitiva
</h3>

<ul class="reflection-list">
    <li>¿Cómo cambia tu percepción del cambio climático al ver que pequeños cambios en temperatura/precipitación pueden transformar biomas enteros?</li>
    <li>¿En qué regiones del planeta consideras más urgente la conservación de biomas actuales y por qué?</li>
    <li>¿Qué estrategia usarás para predecir biomas en problemas de examen o análisis ambiental?</li>
</ul>

<p class="conclusion">
    Los biomas son la expresión visible del clima sobre la vida. Comprenderlos permite anticipar el futuro del planeta en un contexto de cambio global.
</p>

<blockquote class="neon-quote">
    “El clima escribe el guion; los biomas son los actores.”
</blockquote>
