<h3 class="section-title">
    I. De Cadenas a Redes Tróficas
</h3>

<p>
    Las cadenas alimentarias son simplificaciones didácticas; las redes tróficas capturan la realidad: omnivoría, múltiples presas y rutas alternativas de flujo energético.
</p>

<table class="neon-table">
    <thead>
        <tr>
            <th>Concepto</th>
            <th>Cadena Alimentaria</th>
            <th>Red Trófica</th>
        </tr>
    </thead>
    <tbody>
        <tr>
            <td>Estructura</td>
            <td>Lineal</td>
            <td>Compleja, interconectada</td>
        </tr>
        <tr>
            <td>Realismo</td>
            <td>Bajo</td>
            <td>Alto</td>
        </tr>
        <tr>
            <td>Estabilidad</td>
            <td>Frágil</td>
            <td>Resiliente (mayor conectancia)</td>
        </tr>
    </tbody>
</table>

<div class="concept-box">
    <strong>Conectancia:</strong> \\( C = \\frac{L}{S^2} \\) (L = enlaces, S = especies). Valores altos (>0.3) indican mayor resiliencia.
</div>

