<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Cascada Trófica por Eliminación de Especies</h4>

<p>
    Elimina un nivel trófico y observa el impacto en el ecosistema.
</p>

<div class="trophic-sim">
    <div class="species-controls">
        <button data-impact="producers">Eliminar productores</button>
        <button data-impact="herbivores">Eliminar herbívoros</button>
        <button data-impact="predators">Eliminar depredadores</button>
        <button data-impact="none">Restablecer</button>
    </div>

    <div class="sim-result" id="cascadeResult">Estado inicial: ecosistema equilibrado.</div>
</div>

<script>
(function(){
    const buttons = document.querySelectorAll(".species-controls button");
    const result = document.getElementById("cascadeResult");

    const impacts = {
        producers: "🔥 Colapso total: sin entrada de energía → extinción en cascada de todos los niveles.",
        herbivores: "⚠️ Desbalance: productores crecen descontroladamente; depredadores disminuyen por falta de presas.",
        predators: "🌪️ Cascada descendente: herbívoros aumentan → sobreexplotación vegetal → degradación del hábitat.",
        none: "🌿 Ecosistema equilibrado: flujo energético normal y regulación poblacional."
    };

    buttons.forEach(btn => {
        btn.addEventListener("click", () => {
            buttons.forEach(b => b.classList.remove("active"));
            if (btn.dataset.impact !== "none") btn.classList.add("active");
            result.innerHTML = impacts[btn.dataset.impact];
        });
    });
})();
</script>

<h4 class="subsection-title">Análisis: Conectancia y Estabilidad de la Red</h4>

<p>
    Ingresa número de especies y enlaces para calcular conectancia y evaluar resiliencia.
</p>

<div class="trophic-sim">
    <label>Especies (S): <input type="number" id="speciesInput" value="15" min="2"></label>
    <label>Enlaces (L): <input type="number" id="linksInput" value="45" min="1"></label>
    <button id="calcConnect">Calcular</button>

    <div class="sim-result" id="connectResult"></div>
</div>

<script>
(function(){
    const sInput = document.getElementById("speciesInput");
    const lInput = document.getElementById("linksInput");
    const result = document.getElementById("connectResult");

    document.getElementById("calcConnect").addEventListener("click", () => {
        const S = parseInt(sInput.value);
        const L = parseInt(lInput.value);

        if (S < 2 || L < 1) {
            result.innerHTML = "⚠️ Valores inválidos.";
            return;
        }

        const C = (L / (S * S)).toFixed(3);
        let stability = "";

        if (C < 0.1) stability = "🔴 Baja resiliencia: vulnerable a perturbaciones.";
        else if (C < 0.3) stability = "🟡 Moderada: estabilidad limitada.";
        else stability = "🟢 Alta resiliencia: amortigua impactos.";

        result.innerHTML = `<strong>Conectancia C = ${C}</strong><br>${stability}`;
    });
})();
</script>

