        <p>3. Una cascada trófica típica ocurre cuando:</p>
        <button onclick="checkQuiz(3,true)">Se elimina un superpredador</button>
        <button onclick="checkQuiz(3,false)">Aumentan productores</button>
        <button onclick="checkQuiz(3,false)">Se añaden descomponedores</button>
        <div id="fb3"></div>
    </div>

    <div id="quizScore" class="score-display">Puntuación: 0/3</div>
</div>

<script>
let score = 0;
const total = 3;
function checkQuiz(q, correct){
    const fb = document.getElementById("fb" + q);
    if (correct){
        fb.innerHTML = "✅ Correcto";
        fb.style.color = "#00e676";
        score++;
    } else {
        fb.innerHTML = "❌ Incorrecto";
        fb.style.color = "#ff1744";
    }
    document.getElementById("quizScore").textContent = "Puntuación: " + score + "/" + total;
}
</script>

