</h3>

<p>
    Este tema es central en "Flujo de energía y ciclos de materia" y "Dinámica de poblaciones y comunidades". Se evalúa en exámenes oficiales junto a productividad primaria, pirámides tróficas y servicios ecosistémicos. Es clave para analizar impactos antropogénicos como sobrepesca o pérdida de depredadores apicales.
</p>

