</h3>

<ol class="exam-problems">
    <li>Explica por qué la eficiencia energética limita el número de niveles tróficos en un ecosistema.</li>
    <li>Analiza el efecto de eliminar un superpredador en una red trófica compleja vs. simple.</li>
    <li>Calcula la conectancia de una red con 12 especies y 54 enlaces. Interpreta su estabilidad.</li>
    <li>Describe una cascada trófica real (ej. lobos en Yellowstone) y sus implicaciones.</li>
    <li>Justifica la importancia de la complejidad en redes tróficas para la resiliencia ecosistémica.</li>
</ol>

