<h3 class="section-title">
    I. Clasificación de las Relaciones Ecológicas
</h3>

<table class="neon-table">
    <thead>
        <tr>
            <th>Interacción</th>
            <th>Notación</th>
            <th>Descripción</th>
            <th>Ejemplo clásico</th>
            <th>Implicación evolutiva</th>
        </tr>
    </thead>
    <tbody>
        <tr><td>Mutualismo</td><td>+ / +</td><td>Beneficio recíproco</td><td>Micorrizas (planta-hongo)</td><td>Coevolución obligatoria</td></tr>
        <tr><td>Comensalismo</td><td>+ / 0</td><td>Beneficio unilateral</td><td>Rémora-tiburón</td><td>Adaptación oportunista</td></tr>
        <tr><td>Parasitismo</td><td>+ / −</td><td>Beneficio a costa del huésped</td><td>Pulga-perro</td><td>Carrera armamentista</td></tr>
        <tr><td>Depredación</td><td>+ / −</td><td>Captura y muerte de presa</td><td>Lobo-ciervo</td><td>Cascadas tróficas</td></tr>
        <tr><td>Competencia</td><td>− / −</td><td>Uso compartido de recurso limitado</td><td>Plantas por luz</td><td>Partición de nicho</td></tr>
        <tr><td>Amensalismo</td><td>− / 0</td><td>Inhibición unilateral</td><td>Penicillium-bacteria</td><td>Alebopatía</td></tr>
    </tbody>
</table>

<div class="concept-box">
    <strong>Simbiosis:</strong> Relación íntima y prolongada (incluye mutualismo, comensalismo y parasitismo). Puede ser obligatoria (indispensable) o facultativa.
</div>

