<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Impacto de una Relación Ecológica</h4>

<p>
    Selecciona una interacción y observa su efecto neto en ambas especies.
</p>

<div class="relations-sim">
    <label>Interacción:</label>
    <select id="relationSelect">
        <option value="mutualismo">Mutualismo (+/+)</option>
        <option value="comensalismo">Comensalismo (+/0)</option>
        <option value="parasitismo">Parasitismo (+/-)</option>
        <option value="depredacion">Depredación (+/-)</option>
        <option value="competencia">Competencia (-/-)</option>
        <option value="amensalismo">Amensalismo (-/0)</option>
    </select>

    <div class="sim-result" id="relationResult"></div>
</div>

<script>
(function(){
    const select = document.getElementById("relationSelect");
    const result = document.getElementById("relationResult");

    const relations = {
        mutualismo: { sign: "+/+", desc: "Ambas especies aumentan su aptitud. Ej: micorrizas.", impact: "Estabilidad y coevolución." },
        comensalismo: { sign: "+/0", desc: "Una se beneficia sin afectar a la otra. Ej: rémora-tiburón.", impact: "Beneficio oportunista." },
        parasitismo: { sign: "+/-", desc: "Parásito beneficia, huésped perjudicado. Ej: pulga-perro.", impact: "Carrera armamentista evolutiva." },
        depredacion: { sign: "+/-", desc: "Depredador beneficia, presa perjudicada. Ej: lobo-ciervo.", impact: "Regulación poblacional y cascadas." },
        competencia: { sign: "-/-", desc: "Ambas reducen aptitud por recurso limitado.", impact: "Partición de nicho o exclusión." },
        amensalismo: { sign: "-/0", desc: "Una inhibe a la otra sin costo propio. Ej: alelopatía.", impact: "Inhibición química." }
    };

    function update(){
        const data = relations[select.value];
        result.innerHTML = `<strong>${data.sign}</strong><br>
                            <strong>Descripción:</strong> ${data.desc}<br>
                            <strong>Implicación:</strong> ${data.impact}`;
    }

    select.addEventListener("change", update);
    update();
})();
</script>

<h4 class="subsection-title">Simulador: Carrera Coevolutiva</h4>

<p>
    Ajusta la longitud del tubo floral y observa la adaptación de la probóscide del polinizador.
</p>

<div class="relations-sim">
    <label>Longitud tubo floral (cm): <span id="flowerValue">5</span></label>
    <input type="range" id="flowerSlider" min="1" max="15" value="5">

    <label>Longitud probóscide (cm): <span id="probeValue">5</span></label>
    <input type="range" id="probeSlider" min="1" max="15" value="5">

    <div class="sim-result" id="coevoResult"></div>
</div>

<script>
(function(){
    const flower = document.getElementById("flowerSlider");
    const probe = document.getElementById("probeSlider");
    const fValue = document.getElementById("flowerValue");
    const pValue = document.getElementById("probeValue");
    const result = document.getElementById("coevoResult");

    function update(){
        const f = parseInt(flower.value);
        const p = parseInt(probe.value);
        fValue.textContent = f;
        pValue.textContent = p;

        const diff = Math.abs(f - p);
        let message = "";

        if (diff <= 1) message = "🟢 Adaptación óptima: polinización eficiente.";
        else if (diff <= 4) message = "🟡 Adaptación parcial: eficiencia reducida.";
        else message = "🔴 Desacoplamiento: interacción ineficaz o imposible.";

        result.innerHTML = `<strong>Estado coevolutivo:</strong><br>${message}`;
    }

    flower.addEventListener("input", update);
    probe.addEventListener("input", update);
    update();
})();
</script>

<h4 class="subsection-title">Quiz Autoevaluado: Relaciones Ecológicas</h4>

<div class="quiz-container">
    <div class="quiz-question">
        <p>1. La relación entre pez payaso y anémona es:</p>
        <button onclick="checkQuiz(1,true)">Mutualismo</button>
