        </tr>
    </thead>
    <tbody>
        <tr>
            <td>Organismos</td>
            <td>Retroalimentación negativa</td>
            <td>Control glucémico (insulina/glucagón)</td>
            <td>Mantenimiento fisiológico</td>
        </tr>
        <tr>
            <td>Ecosistemas</td>
            <td>Regulación poblacional, ciclos nutrientes</td>
            <td>Depredador-presa en taiga</td>
            <td>Resiliencia comunitaria</td>
        </tr>
        <tr>
            <td>Biosfera</td>
            <td>Ciclos globales (Gaia)</td>
            <td>Regulación CO₂ por océanos</td>
            <td>Estabilidad planetaria</td>
        </tr>
    </tbody>
</table>

