<h3 class="section-title">
    III. Bloques Interactivos
</h3>

<h4 class="subsection-title">Simulador: Regulación Homeostática de Temperatura</h4>

<p>
    Ajusta la temperatura externa y observa la respuesta homeostática del organismo.
</p>

<div class="homeo-sim">
    <label>Temperatura externa (°C): <span id="extTempValue">37</span></label>
    <input type="range" id="extTempSlider" min="0" max="50" value="37">

    <div class="sim-result" id="homeoResult"></div>
</div>

<script>
(function(){
    const slider = document.getElementById("extTempSlider");
    const value = document.getElementById("extTempValue");
    const result = document.getElementById("homeoResult");

    function update(){
        const ext = parseInt(slider.value);
        value.textContent = ext;

        let response = "", mech = "";

        if (ext < 35) {
            response = "Hipotermia inminente";
            mech = "Activación de escalofríos y vasoconstricción para generar/conservar calor.";
        } else if (ext > 39) {
            response = "Hipertermia inminente";
            mech = "Sudoración y vasodilatación para disipar calor.";
        } else {
            response = "Homeostasis estable";
            mech = "Sin ajustes mayores necesarios.";
        }

        result.innerHTML = `<strong>Estado:</strong> ${response}<br>
                            <strong>Mecanismo:</strong> ${mech}`;
    }

    slider.addEventListener("input", update);
    update();
})();
</script>

<h4 class="subsection-title">Análisis: Conectancia en Red Homeostática</h4>

<p>
    Ingresa especies e interacciones para calcular conectancia y evaluar estabilidad homeostática.
</p>

<div class="homeo-sim">
    <label>Especies (S): <input type="number" id="speciesCount" min="2" value="10"></label>
    <label>Interacciones (L): <input type="number" id="linksCount" min="0" value="25"></label>
    <button id="calcBtn">Analizar</button>

    <div class="sim-result" id="connectResult"></div>
</div>

<script>
(function(){
    const sInput = document.getElementById("speciesCount");
    const lInput = document.getElementById("linksCount");
    const result = document.getElementById("connectResult");

    document.getElementById("calcBtn").addEventListener("click", () => {
        const S = parseInt(sInput.value);
        const L = parseInt(lInput.value);

        if (S < 2) {
            result.innerHTML = "⚠️ Mínimo 2 especies.";
            return;
        }

        const C = (L / (S * (S - 1) / 2)).toFixed(3);
        let stability = "";

        if (C < 0.1) stability = "🔴 Baja: vulnerable a perturbaciones.";
        else if (C < 0.3) stability = "🟡 Media: resiliencia moderada.";
        else stability = "🟢 Alta: fuerte homeostasis.";

        result.innerHTML = `<strong>Conectancia C = ${C}</strong><br>${stability}`;
    });
})();
</script>

<h4 class="subsection-title">Quiz Autoevaluado: Homeostasis</h4>

<div class="quiz-container">
    <div class="quiz-question">
        <p>1. El mecanismo principal de homeostasis es:</p>
        <button onclick="checkQuiz(1,false)">Retroalimentación positiva</button>
        <button onclick="checkQuiz(1,true)">Retroalimentación negativa</button>
        <div id="fb1"></div>
    </div>

    <div class="quiz-question">
        <p>2. En ecosistemas, homeostasis implica:</p>
        <button onclick="checkQuiz(2,true)">Regulación poblacional</button>
        <button onclick="checkQuiz(2,false)">Estabilidad absoluta</button>
        <div id="fb2"></div>
    </div>

    <div class="quiz-question">
        <p>3. Hipótesis Gaia se refiere a:</p>
        <button onclick="checkQuiz(3,true)">Homeostasis biosférica</button>
        <button onclick="checkQuiz(3,false)">Regulación celular</button>
        <div id="fb3"></div>
    </div>

    <div class="quiz-question">
        <p>4. Un ejemplo de retroalimentación positiva es:</p>
        <button onclick="checkQuiz(4,false)">Control de temperatura</button>
        <button onclick="checkQuiz(4,true)">Coagulación sanguínea</button>
        <div id="fb4"></div>
    </div>

    <div class="quiz-question">
        <p>5. En biosfera, homeostasis regula:</p>
        <button onclick="checkQuiz(5,true)">Ciclos globales como CO₂</button>
        <button onclick="checkQuiz(5,false)">Solo poblaciones locales</button>
        <div id="fb5"></div>
    </div>

    <div id="quizScore" class="score-display">Puntuación: 0/5</div>
</div>

<script>
let score = 0;
const total = 5;
function checkQuiz(q, correct){
    const fb = document.getElementById("fb" + q);
    if (correct){
        fb.innerHTML = "✅ Correcto";
        fb.style.color = "#00e676";
        score++;
    } else {
        fb.innerHTML = "❌ Incorrecto";
        fb.style.color = "#ff1744";
    }
    document.getElementById("quizScore").textContent = "Puntuación: " + score + "/" + total;
}
</script>

