        <div class="error-explain" id="exp1">Es equilibrio dinámico: constante ajuste.</div>
    </div>
    <div class="error-item">
        <input type="checkbox" id="err2" onchange="toggleError(2)">
        <label for="err2">Confundir retroalimentación positiva con negativa.</label>
        <div class="error-explain" id="exp2">Positiva amplifica; negativa estabiliza.</div>
    </div>
    <div class="error-item">
        <input type="checkbox" id="err3" onchange="toggleError(3)">
        <label for="err3">Pensar que homeostasis solo aplica a organismos.</label>
        <div class="error-explain" id="exp3">Se extiende a ecosistemas y biosfera.</div>
    </div>
    <div class="error-item">
        <input type="checkbox" id="err4" onchange="toggleError(4)">
        <label for="err4">Ignorar umbrales de resiliencia.</label>
        <div class="error-explain" id="exp4">Sistemas pueden colapsar si se exceden límites.</div>
    </div>
</div>

<script>
function toggleError(n){
    const exp = document.getElementById("exp" + n);
    exp.style.display = document.getElementById("err" + n).checked ? "block" : "none";
}
</script>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- CONEXIÓN CON LA MATERIA BASE -->
<!-- ================================================= -->

<h3 class="section-title">
    V. Conexión con el Currículo de Ecosistemas
</h3>

<p>
    La homeostasis integra bloques como "Fisiología ambiental" y "Dinámica ecosistémica" en Biología y Ecología. Se evalúa con Leyes de Liebig/Shelford, ciclos biogeoquímicos y resiliencia. Es clave para temas de sostenibilidad y cambio global en currículos oficiales.
</p>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- PROBLEMAS TIPO EXAMEN -->
<!-- ================================================= -->

<h3 class="section-title">
    VI. Problemas Tipo Examen
</h3>

<ol class="exam-problems">
    <li>Explica el rol de la retroalimentación negativa en la termorregulación humana.</li>
    <li>Analiza cómo un ecosistema recupera homeostasis post-perturbación (ej. incendio).</li>
    <li>Compara homeostasis fisiológica con ecosistémica, con ejemplos.</li>
    <li>Predice el impacto de CO₂ elevado en homeostasis biosférica (Gaia).</li>
    <li>Justifica por qué la retroalimentación positiva puede llevar a inestabilidad.</li>
</ol>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- CIERRE METACOGNITIVO -->
<!-- ================================================= -->

<h3 class="section-title">
    VII. Reflexión Metacognitiva
</h3>

<ul class="reflection-list">
    <li>¿Cómo aplica la homeostasis a problemas globales como el cambio climático?</li>
    <li>¿En qué nivel (organismo/ecosistema/biosfera) ves mayor vulnerabilidad y por qué?</li>
    <li>¿Qué estrategia usarás para analizar mecanismos homeostáticos en exámenes?</li>
</ul>

<p class="conclusion">
    La homeostasis revela la resiliencia de la vida, pero también sus límites. Entenderla es vital para intervenir en sistemas biológicos de forma ética y efectiva.
</p>

<blockquote class="neon-quote">
    “La vida es cambio constante; la homeostasis, su ancla.”
</blockquote>
