    'contenido' => '<p class="intro">
    La <strong>producción primaria</strong> es la base energética de todos los ecosistemas: los autótrofos capturan energía solar (o química) y la convierten en biomasa. Esta energía fluye unidireccionalmente a través de los niveles tróficos con una eficiencia baja (~10%), lo que explica la forma de las pirámides tróficas y la escasez relativa de superpredadores. Comprender estos procesos es clave para analizar productividad ecosistémica, servicios ambientales y límites a la explotación de recursos.
</p>

<p class="formula-neon text-center">
