<!-- ================================================= -->
<!-- DESARROLLO TEÓRICO -->
<!-- ================================================= -->

<h3 class="section-title">
    I. Producción Primaria: GPP y NPP
</h3>

<p>
    La producción primaria bruta (GPP) es la energía total fijada por autótrofos. La producción primaria neta (NPP) es la energía disponible para heterótrofos tras restar la respiración autótrofa (Rₐ).
</p>

<table class="neon-table">
    <thead>
        <tr>
            <th>Concepto</th>
            <th>Definición</th>
            <th>Unidades típicas</th>
            <th>Factores limitantes</th>
        </tr>
    </thead>
    <tbody>
        <tr>
            <td>GPP</td>
            <td>Energía total capturada</td>
            <td>g C m⁻² año⁻¹ o MJ m⁻² año⁻¹</td>
            <td>Luz, CO₂, temperatura</td>
        </tr>
        <tr>
            <td>NPP</td>
            <td>Biomasa disponible</td>
            <td>g C m⁻² año⁻¹</td>
            <td>GPP − Rₐ (respiración)</td>
        </tr>
        <tr>
            <td>Rₐ</td>
            <td>Consumo energético productores</td>
            <td>—</td>
            <td>Temperatura (Q₁₀)</td>
        </tr>
    </tbody>
</table>

<div class="concept-box">
    <strong>Ecosistemas de alta NPP:</strong> Selvas tropicales y arrecifes coralinos. Baja NPP: Desiertos y océano abierto.
</div>

<hr class="divider-neon">

