<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Transferencia Energética entre Niveles Tróficos</h4>

<p>
    Ingresa NPP inicial y eficiencia promedio para calcular energía disponible en cada nivel.
</p>

<div class="energy-sim">
    <label>NPP inicial (MJ m⁻² año⁻¹): <input type="number" id="nppInput" value="10000" min="1000"></label>
    <label>Eficiencia trófica (%): <span id="effValue">10</span></label>
    <input type="range" id="effSlider" min="5" max="25" value="10">

    <button id="calcEnergy">Calcular</button>

    <div class="sim-result" id="energyResult"></div>
</div>

<script>
(function(){
    const nppInput = document.getElementById("nppInput");
    const effSlider = document.getElementById("effSlider");
    const effValue = document.getElementById("effValue");
    const result = document.getElementById("energyResult");

    effSlider.addEventListener("input", () => effValue.textContent = effSlider.value);

    document.getElementById("calcEnergy").addEventListener("click", () => {
        const npp = parseFloat(nppInput.value) || 10000;
        const eff = parseFloat(effSlider.value) / 100;

        result.innerHTML = `
            <strong>NPP inicial:</strong> ${npp.toLocaleString()} MJ<br>
            <strong>Herbívoros:</strong> ${(npp * eff).toFixed(0)} MJ<br>
            <strong>Carnívoros primarios:</strong> ${(npp * eff ** 2).toFixed(0)} MJ<br>
            <strong>Depredadores ápice:</strong> ${(npp * eff ** 3).toFixed(0)} MJ<br><br>
            <em>Máximo niveles viables: ${eff >= 0.15 ? \'5–6\' : \'4–5\'}</em>
        `;
    });
})();
</script>

<h4 class="subsection-title">Análisis: Productividad por Ecosistema</h4>

<p>
    Selecciona un ecosistema para ver su NPP típica y factores limitantes.
</p>

<div class="energy-sim">
    <select id="ecoSelect">
        <option value="tropical">Selva tropical</option>
        <option value="temperate">Bosque templado</option>
        <option value="grassland">Pradera</option>
        <option value="desert">Desierto</option>
        <option value="ocean">Océano abierto</option>
        <option value="reef">Arrecife coralino</option>
    </select>

    <div class="sim-result" id="ecoResult"></div>
</div>

<script>
(function(){
    const select = document.getElementById("ecoSelect");
    const result = document.getElementById("ecoResult");

    const data = {
        tropical: { npp: "2000–3500", limit: "Alta radiación y agua → máxima productividad" },
        temperate: { npp: "1000–2000", limit: "Estacionalidad limita crecimiento anual" },
        grassland: { npp: "500–1500", limit: "Agua y fuego regulan biomasa" },
        desert: { npp: "<250", limit: "Escasez hídrica extrema" },
        ocean: { npp: "100–400", limit: "Nutrientes en zona fótica" },
        reef: { npp: "2000–5000", limit: "Simbiosis y alta luz" }
    };

    function update(){
        const d = data[select.value];
        result.innerHTML = `<strong>NPP ≈ ${d.npp} g C m⁻² año⁻¹</strong><br>${d.limit}`;
    }

    select.addEventListener("change", update);
    update();
})();
</script>

<h4 class="subsection-title">Quiz Autoevaluado: Producción y Transferencia</h4>

<div class="quiz-container">
    <div class="quiz-question">
        <p>1. NPP representa:</p>
        <button onclick="checkQuiz(1,true)">Energía disponible para heterótrofos</button>
        <button onclick="checkQuiz(1,false)">Energía total capturada</button>
        <div id="fb1"></div>
    </div>

    <div class="quiz-question">
        <p>2. La eficiencia trófica típica es ≈:</p>
        <button onclick="checkQuiz(2,true)">10%</button>
        <button onclick="checkQuiz(2,false)">50%</button>
        <div id="fb2"></div>
    </div>

    <div class="quiz-question">
        <p>3. Ecosistema terrestre con mayor NPP:</p>
        <button onclick="checkQuiz(3,true)">Selva tropical</button>
        <button onclick="checkQuiz(3,false)">Desierto</button>
        <div id="fb3"></div>
    </div>

    <div class="quiz-question">
        <p>4. Principal causa de pérdida energética:</p>
        <button onclick="checkQuiz(4,true)">Respiración (calor)</button>
        <button onclick="checkQuiz(4,false)">Excreción</button>
        <div id="fb4"></div>
    </div>

    <div id="quizScore" class="score-display">Puntuación: 0/4</div>
</div>

<script>
let score = 0;
const total = 4;
function checkQuiz(q, correct){
    const fb = document.getElementById("fb" + q);
    if (correct){
        fb.innerHTML = "✅ Correcto";
        fb.style.color = "#00e676";
        score++;
    } else {
        fb.innerHTML = "❌ Incorrecto";
        fb.style.color = "#ff1744";
    }
    document.getElementById("quizScore").textContent = "Puntuación: " + score + "/" + total;
}
</script>

