<h3 class="section-title">
    V. Conexión con el Currículo de Ecosistemas
</h3>

<p>
    Tema central en "Flujo de energía y productividad" en Biología y Ecología. Se evalúa con pirámides tróficas, ciclos biogeoquímicos y servicios ecosistémicos. Es base para analizar sostenibilidad y cambio global.
</p>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- PROBLEMAS TIPO EXAMEN -->
<!-- ================================================= -->

<h3 class="section-title">
    VI. Problemas Tipo Examen
</h3>

<ol class="exam-problems">
    <li>Calcula energía disponible para carnívoros si NPP = 8000 MJ m⁻² año⁻¹ y eficiencia = 12%.</li>
    <li>Explica por qué pirámides de energía siempre son rectas.</li>
    <li>Compara NPP entre selva tropical y desierto. Justifica factores limitantes.</li>
    <li>Analiza implicaciones de baja eficiencia trófica en explotación pesquera.</li>
    <li>Predice efecto de eutrofización en NPP acuática.</li>
</ol>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- CIERRE METACOGNITIVO -->
<!-- ================================================= -->

<h3 class="section-title">
    VII. Reflexión Metacognitiva
</h3>

<ul class="reflection-list">
    <li>¿Cómo limita la baja eficiencia trófica el número de niveles en cadenas alimentarias?</li>
    <li>¿Por qué conservar productores primarios es prioritario en gestión ambiental?</li>
    <li>¿Qué estrategia usarás para calcular flujos energéticos en exámenes?</li>
</ul>

<p class="conclusion">
    La energía fluye, no se recicla. La baja eficiencia trófica define la estructura y límites de los ecosistemas.
</p>

<blockquote class="neon-quote">
    “La energía es el currency de la vida; su flujo, el latido del ecosistema.”
</blockquote>
