    'contenido' => '<p class="intro">
    La <strong>huella de carbono</strong> mide la cantidad total de gases de efecto invernadero (GEI) emitidos directa o indirectamente por actividades humanas, expresada en toneladas de CO₂ equivalente (CO₂e). Utiliza el Potencial de Calentamiento Global (GWP) para normalizar distintos gases. Es una herramienta clave para evaluar responsabilidad climática, diseñar estrategias de mitigación y avanzar hacia la neutralidad carbono (Net Zero).
</p>

<p class="formula-neon text-center">
    Huella de Carbono (CO₂e):<br>
    \\[ HC = \\sum (m_i \\times GWP_i) \\]
</p>

