<h3 class="section-title">
    I. Concepto y Alcances de la Huella de Carbono
</h3>

<table class="neon-table">
    <thead>
        <tr>
            <th>Alcance</th>
            <th>Descripción</th>
            <th>Ejemplos</th>
            <th>Importancia</th>
        </tr>
    </thead>
    <tbody>
        <tr>
            <td>Alcance 1</td>
            <td>Emisiones directas</td>
            <td>Combustión vehicular, calefacción</td>
            <td>Fuentes propias controlables</td>
        </tr>
        <tr>
            <td>Alcance 2</td>
            <td>Emisiones indirectas por energía</td>
            <td>Electricidad consumida</td>
            <td>Depende del mix energético</td>
        </tr>
        <tr>
            <td>Alcance 3</td>
            <td>Otras indirectas (cadena de valor)</td>
            <td>Proveedores, transporte, uso producto, residuos</td>
            <td>70–90% en muchas empresas</td>
        </tr>
    </tbody>
</table>

