<h3 class="section-title">
    II. Flujo Antropogénico de Carbono
</h3>

<p>
    Representación del ciclo alterado por actividades humanas.
</p>

<div class="svg-container">
    <svg class="carbon-svg" viewBox="0 0 1000 600" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">
        <defs>
            <filter id="glow-cyan">
                <feGaussianBlur stdDeviation="6" result="blur"/>
                <feFlood flood-color="#00ffff"/>
                <feComposite in2="blur" operator="in"/>
                <feMerge>
                    <feMergeNode/>
                    <feMergeNode in="SourceGraphic"/>
                </feMerge>
            </filter>
        </defs>

        <rect width="1000" height="600" fill="#000022"/>

        <text x="500" y="70" text-anchor="middle" font-size="42" fill="#00ffff" filter="url(#glow-cyan)">FLUJO ANTROPOGÉNICO DE CARBONO</text>

        <!-- Atmósfera -->
        <rect x="0" y="0" width="1000" height="150" fill="#ff4444" opacity="0.2"/>
        <text x="500" y="90" text-anchor="middle" font-size="36" fill="#ff8888">ATMÓSFERA (+CO₂e)</text>

        <!-- Fuentes antropogénicas -->
        <rect x="100" y="450" width="180" height="100" fill="#333" stroke="#ff4444" stroke-width="4" filter="url(#glow-cyan)"/>
        <text x="190" y="500" text-anchor="middle" font-size="24" fill="#ff8888">INDUSTRIA</text>

        <rect x="410" y="450" width="180" height="100" fill="#333" stroke="#ff4444" stroke-width="4" filter="url(#glow-cyan)"/>
        <text x="500" y="500" text-anchor="middle" font-size="24" fill="#ff8888">TRANSPORTE</text>

        <rect x="720" y="450" width="180" height="100" fill="#333" stroke="#ff4444" stroke-width="4" filter="url(#glow-cyan)"/>
        <text x="810" y="500" text-anchor="middle" font-size="24" fill="#ff8888">AGRICULTURA</text>

        <!-- Flujos -->
        <path d="M190 450 L190 150" stroke="#ff4444" stroke-width="8" opacity="0.8"/>
        <path d="M500 450 L500 150" stroke="#ff4444" stroke-width="8" opacity="0.8"/>
        <path d="M810 450 L810 150" stroke="#ff4444" stroke-width="8" opacity="0.8"/>

        <!-- Secuestro -->
        <circle cx="500" cy="300" r="80" fill="#006400" stroke="#00ff00" stroke-width="6" filter="url(#glow-cyan)"/>
        <text x="500" y="300" text-anchor="middle" font-size="28" fill="#ffffff">BIO-SECUESTRO</text>

        <text x="500" y="560" text-anchor="middle" font-size="30" fill="#88ffff">Emisiones ↑ → Forzamiento radiativo ↑</text>
    </svg>
</div>

