<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Cálculo de Huella Personal (Alcances 1–3)</h4>

<p>
    Ajusta hábitos para estimar tu huella anual.
</p>

<div class="carbon-sim">
    <label>Vuelos internacionales/año: <span id="vuelosVal">1</span></label>
    <input type="range" id="vuelos" min="0" max="10" value="1">

    <label>Consumo eléctrico mensual (kWh): <span id="kwVal">300</span></label>
    <input type="range" id="kw" min="100" max="1000" value="300">

    <label>Tipo de dieta:</label>
    <select id="dieta">
        <option value="1.5">Vegana</option>
        <option value="2.5">Vegetariana</option>
        <option value="4.5" selected>Mixta con carne</option>
    </select>

    <div class="sim-result" id="totalCarbon">Huella: 0 t CO₂e/año</div>
</div>

<script>
(function(){
    const vuelos = document.getElementById("vuelos");
    const kw = document.getElementById("kw");
    const dieta = document.getElementById("dieta");
    const vVal = document.getElementById("vuelosVal");
    const kVal = document.getElementById("kwVal");
    const result = document.getElementById("totalCarbon");

    function update(){
        const v = parseInt(vuelos.value);
        const k = parseInt(kw.value);
        const d = parseFloat(dieta.value);

        vVal.textContent = v;
        kVal.textContent = k;

        // Estimación aproximada realista (toneladas CO₂e/año)
        const total = (v * 1.2) + (k * 12 * 0.00045) + d;

        result.innerHTML = `<strong>Huella estimada: ${total.toFixed(2)} t CO₂e/año</strong><br>
                            ${total < 4 ? "🟢 Bajo impacto" : total < 8 ? "🟡 Moderado" : "🔴 Alto impacto"}`;
    }

    vuelos.addEventListener("input", update);
    kw.addEventListener("input", update);
    dieta.addEventListener("change", update);
    update();
})();
</script>

<h4 class="subsection-title">Análisis: Equivalencia de GEI (GWP)</h4>

<p>
    Calcula el impacto equivalente de diferentes gases.
</p>

<div class="carbon-sim">
    <label>Gas:</label>
    <select id="gasType">
        <option value="1">CO₂</option>
        <option value="28">CH₄ (metano)</option>
        <option value="265">N₂O (óxido nitroso)</option>
        <option value="23500">SF₆</option>
    </select>

    <label>Cantidad (kg): <input type="number" id="gasAmount" value="1" min="0.1"></label>

    <div class="sim-result" id="gwpResult"></div>
</div>

<script>
(function(){
    const type = document.getElementById("gasType");
    const amount = document.getElementById("gasAmount");
    const result = document.getElementById("gwpResult");

    function update(){
        const gwp = parseInt(type.value);
        const qty = parseFloat(amount.value) || 0;

        result.innerHTML = `<strong>Equivalente:</strong> ${ (qty * gwp).toFixed(2) } kg CO₂e`;
    }

    type.addEventListener("change", update);
    amount.addEventListener("input", update);
    update();
})();
</script>

