    'contenido' => '<p class="intro">
    El cambio climático antropogénico es una alteración del balance radiativo terrestre por acumulación de gases de efecto invernadero (GEI). Reduce la escape de radiación infrarroja, generando forzamiento positivo que eleva la temperatura global. Sus impactos incluyen acidificación oceánica, puntos de no retorno (tipping points) y pérdida de servicios ecosistémicos. Comprender sus mecanismos es esencial para evaluar riesgos y diseñar estrategias de adaptación/mitigación.
</p>

