<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Activación de Puntos de No Retorno</h4>

<p>
    Aumenta la temperatura global y observa activación de retroalimentaciones irreversibles.
</p>

<div class="climate-sim">
    <label>Anomalía térmica (°C): <span id="tempVal">1.2</span></label>
    <input type="range" id="tempSlider" min="0" max="5" step="0.1" value="1.2">

    <div class="sim-result" id="tippingResult">
        <div>Puntos críticos:</div>
        <div id="coralStatus">Corales: Riesgo moderado</div>
        <div id="permafrostStatus">Permafrost: Estable</div>
        <div id="amocStatus">AMOC: Funcional</div>
    </div>
</div>

<script>
(function(){
    const slider = document.getElementById("tempSlider");
    const val = document.getElementById("tempVal");
    const coral = document.getElementById("coralStatus");
    const permafrost = document.getElementById("permafrostStatus");
    const amoc = document.getElementById("amocStatus");

    function update(){
        const t = parseFloat(slider.value);
        val.textContent = t.toFixed(1);

        coral.textContent = t >= 1.5 ? "Corales: Colapso masivo (blanqueamiento irreversible)" : "Corales: Riesgo creciente";
        permafrost.textContent = t >= 2.0 ? "Permafrost: Liberación masiva CH₄ (retroalimentación fuerte)" : "Permafrost: Derretimiento parcial";
        amoc.textContent = t >= 3.5 ? "AMOC: Colapso probable (cambio circulación)" : "AMOC: Debilitamiento";
    }

    slider.addEventListener("input", update);
    update();
})();
</script>

<h4 class="subsection-title">Análisis: Proyección hacia Net Zero</h4>

<p>
    Ajusta políticas para evaluar trayectoria emisora.
</p>

<div class="climate-sim">
    <label>Transición renovables (%): <span id="renVal">30</span></label>
    <input type="range" id="renSlider" min="0" max="100" value="30">

    <label>Precio carbono ($/t): <span id="taxVal">50</span></label>
    <input type="range" id="taxSlider" min="0" max="200" value="50">

    <div class="sim-result" id="netzeroResult"></div>
</div>

<script>
(function(){
    const ren = document.getElementById("renSlider");
    const tax = document.getElementById("taxSlider");
    const renVal = document.getElementById("renVal");
    const taxVal = document.getElementById("taxVal");
    const result = document.getElementById("netzeroResult");

    function update(){
        const r = parseInt(ren.value);
        const t = parseInt(tax.value);
        renVal.textContent = r;
        taxVal.textContent = t;

        const emissions = 40 * (1 - (r/100 * 0.6 + t/200 * 0.4));
        let scenario = "";

        if (emissions < 10) scenario = "Compatible 1.5°C (Acuerdo París)";
        else if (emissions < 25) scenario = "Riesgo 2–2.5°C";
        else scenario = "Catastrófico >3°C";

        result.innerHTML = `<strong>Emisiones 2050: ${emissions.toFixed(1)} Gt CO₂</strong><br>${scenario}`;
    }

    ren.addEventListener("input", update);
    tax.addEventListener("input", update);
    update();
})();
</script>

