    'contenido' => '<p class="intro">
    La <strong>variabilidad climática</strong> describe las oscilaciones internas del sistema climático Tierra en escalas temporales de meses a décadas. A diferencia del cambio climático antropogénico (tendencia unidireccional), estas oscilaciones son cíclicas y generan patrones de teleconexión que afectan ecosistemas distantes. Comprenderlas es clave para distinguir señal antropogénica de ruido natural y predecir impactos regionales.
</p>

<p class="formula-neon text-center">
    Temperatura observada:<br>
    \\[ T_{obs}(t) = T_{tendencia} + \\sum A_i \\sin(\\omega_i t + \\phi_i) + \\epsilon \\]
</p>

