<h3 class="section-title">
    II. Dinámica del ENSO: Transición La Niña → El Niño
</h3>

<p>
    Animación simplificada del acoplamiento océano-atmósfera.
</p>

<div class="svg-container">
    <svg class="variability-svg" viewBox="0 0 800 400" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">
        <defs>
            <filter id="glow-cyan">
                <feGaussianBlur stdDeviation="6" result="blur"/>
                <feFlood flood-color="#00ffff"/>
                <feComposite in2="blur" operator="in"/>
                <feMerge>
                    <feMergeNode/>
                    <feMergeNode in="SourceGraphic"/>
                </feMerge>
            </filter>
        </defs>

        <rect width="800" height="400" fill="#001a33"/>

        <!-- Termoclina -->
        <path id="thermocline" d="M0 200 Q400 200 800 250" stroke="#00ffff" stroke-width="4" fill="none" filter="url(#glow-cyan)">
            <animate attributeName="d" 
                     values="M0 200 Q400 200 800 250;M0 250 Q400 250 800 250;M0 280 Q400 200 800 200;M0 250 Q400 250 800 250;M0 200 Q400 200 800 250" 
                     dur="12s" repeatCount="indefinite"/>
        </path>

        <!-- Convección -->
        <circle cx="200" cy="100" r="40" fill="#ffffff" opacity="0.3" filter="url(#glow-cyan)">
            <animate attributeName="cx" values="200;600;200" dur="12s" repeatCount="indefinite"/>
        </circle>
        <text x="400" y="60" text-anchor="middle" font-size="32" fill="#00ffff" filter="url(#glow-cyan)">CONVECCIÓN (PRECIPITACIÓN)</text>

        <!-- Vientos alisios -->
        <path d="M700 150 L100 150" stroke="#ffcc00" stroke-width="6" opacity="0.7">
            <animate attributeName="opacity" values="1;0.3;1" dur="12s" repeatCount="indefinite"/>
        </path>

        <text x="400" y="360" text-anchor="middle" font-size="28" fill="#88ffff">TRANSICIÓN LA NIÑA → EL NIÑO</text>
    </svg>
</div>

<hr class="divider-neon">

