<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Teleconexiones de Modos Oscilatorios</h4>

<p>
    Selecciona modo y fase para ver impactos ecosistémicos globales.
</p>

<div class="variability-sim">
    <label>Modo oscilatorio:</label>
    <select id="modeSelect">
        <option value="elnino">ENSO: El Niño</option>
        <option value="lanina">ENSO: La Niña</option>
        <option value="naopos">NAO: Positiva</option>
        <option value="naoneg">NAO: Negativa</option>
        <option value="pdopos">PDO: Positiva</option>
    </select>

    <div class="sim-result" id="teleconnResult"></div>
</div>

<script>
(function(){
    const select = document.getElementById("modeSelect");
    const result = document.getElementById("teleconnResult");

    const impacts = {
        elnino: "🌧️ Sequías Amazonía y Australia • Inundaciones EE.UU. sur • Colapso pesquerías Perú",
        lanina: "🔥 Sequías Argentina • Lluvias intensas Indonesia • Upwelling fuerte Pacífico Este",
        naopos: "❄️ Inviernos suaves Europa Norte • Sequías Mediterráneo • Huracanes Atlántico débiles",
        naoneg: "🥶 Inviernos fríos Europa • Precipitación Mediterráneo • Mayor actividad ciclónica",
        pdopos: "🌊 Temperaturas cálidas Pacífico Norte • Sequías EE.UU. oeste • Mayor productividad salmón Alaska"
    };

    function update(){
        result.innerHTML = `<strong>Teleconexiones:</strong><br>${impacts[select.value]}`;
    }

    select.addEventListener("change", update);
    update();
})();
</script>

<h4 class="subsection-title">Análisis: Clasificación de Eventos ENSO (Índice ONI)</h4>

<p>
    Ajusta anomalía de TSM en región Niño 3.4.
</p>

<div class="variability-sim">
    <label>Anomalía TSM (°C): <span id="oniVal">0.0</span></label>
    <input type="range" id="oniSlider" min="-3" max="3" step="0.1" value="0">

    <div class="sim-result" id="oniResult">NEUTRO</div>
</div>

<script>
(function(){
    const slider = document.getElementById("oniSlider");
    const val = document.getElementById("oniVal");
    const result = document.getElementById("oniResult");

    function update(){
        const v = parseFloat(slider.value);
        val.textContent = (v >= 0 ? "+" : "") + v.toFixed(1);

        if (v >= 2.0) result.innerHTML = "<strong>EL NIÑO MUY FUERTE</strong>";
        else if (v >= 1.5) result.innerHTML = "<strong>EL NIÑO FUERTE</strong>";
        else if (v >= 0.5) result.innerHTML = "<strong>EL NIÑO DÉBIL</strong>";
        else if (v <= -2.0) result.innerHTML = "<strong>LA NIÑA MUY FUERTE</strong>";
        else if (v <= -1.5) result.innerHTML = "<strong>LA NIÑA FUERTE</strong>";
        else if (v <= -0.5) result.innerHTML = "<strong>LA NIÑA DÉBIL</strong>";
        else result.innerHTML = "<strong>NEUTRO</strong>";
    }

    slider.addEventListener("input", update);
    update();
})();
</script>

