        <rect width="800" height="450" fill="#001122"/>

        <text x="400" y="60" text-anchor="middle" font-size="36" fill="#00ffff" filter="url(#glow-cyan)">CICLO HÍDRICO ANTROPOGÉNICO</text>

        <!-- Precipitación (Verde) -->
        <path d="M50 100 Q150 50 250 100 T450 100" stroke="#00ff00" stroke-width="6" opacity="0.6" filter="url(#glow-cyan)"/>
        <text x="200" y="80" text-anchor="middle" font-size="28" fill="#00ff00">HH VERDE (Lluvia)</text>

        <!-- Acuífero (Azul) -->
        <rect x="550" y="300" width="200" height="80" fill="#001a33" stroke="#00ccff" stroke-width="6" filter="url(#glow-cyan)"/>
