<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Agua Virtual en Productos</h4>

<p>
    Selecciona productos para ver su huella hídrica típica.
</p>

<div class="water-sim">
    <select id="productSelect">
        <option value="carne">1 kg Carne bovina</option>
        <option value="algodon">1 kg Algodón</option>
        <option value="cafe">1 Taza café</option>
        <option value="chocolate">1 Tableta chocolate</option>
        <option value="arroz">1 kg Arroz</option>
    </select>

    <div class="sim-result" id="virtualResult"></div>
</div>

<script>
(function(){
    const select = document.getElementById("productSelect");
    const result = document.getElementById("virtualResult");

    const data = {
        carne: { vol: "15 400 L", desc: "94% verde (pasturas), alto impacto en deforestación." },
        algodon: { vol: "10 000 L", desc: "Principalmente azul, estrés en cuencas áridas." },
        cafe: { vol: "140 L", desc: "Por taza; cultivo intensivo en regiones tropicales." },
        chocolate: { vol: "17 000 L", desc: "Por kg; cacao + leche." },
        arroz: { vol: "2 500 L", desc: "Alto consumo azul en arrozales inundados." }
    };

    function update(){
        const d = data[select.value];
        result.innerHTML = `<strong>${d.vol}</strong><br>${d.desc}`;
    }

    select.addEventListener("change", update);
    update();
})();
</script>

<h4 class="subsection-title">Análisis: Cálculo de Huella Gris</h4>

<p>
    Calcula volumen necesario para diluir contaminante.
</p>

<div class="water-sim">
    <label>Carga nitrógeno (kg): <input type="number" id="loadInput" value="1" min="0.1"></label>
    <label>Concentración máxima permitida (mg/L): <span id="maxVal">10</span></label>
    <input type="range" id="maxSlider" min="1" max="50" value="10">

    <div class="sim-result" id="grisResult"></div>
</div>

<script>
(function(){
    const load = document.getElementById("loadInput");
    const maxSlider = document.getElementById("maxSlider");
    const maxVal = document.getElementById("maxVal");
    const result = document.getElementById("grisResult");

    function update(){
        const l = parseFloat(load.value) || 0;
        const c = parseInt(maxSlider.value);
        maxVal.textContent = c;

        const vol = (l * 1000000) / c; // mg a L

        result.innerHTML = `<strong>HH Gris: ${vol.toLocaleString()} L</strong><br>
                            Volumen necesario para diluir carga hasta estándar.`;
    }

    load.addEventListener("input", update);
    maxSlider.addEventListener("input", update);
    update();
})();
</script>

