    'contenido' => '<p class="intro">
    La <strong>huella ecológica</strong> mide la demanda humana sobre la biocapacidad del planeta en hectáreas globales (gha). Compara consumo renovable con regeneración biológica, revelando déficit o reserva ecológica. Incluye Factores de Equivalencia (EQF) y Rendimiento (YF) para normalizar productividad. Es herramienta clave para evaluar sostenibilidad, deuda ecológica y Día del Sobregiro Global.
</p>

<p class="formula-neon text-center">
    Huella Ecológica:<br>
    \\[ EF = \\sum \\left( \\frac{C_i}{Y_i} \\times EQF_i \\times YF_i \\right) \\]
</p>

