<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: ¿Cuántas Tierras Necesitas?</h4>

<p>
    Ajusta hábitos para calcular tu huella personal y Día del Sobregiro.
</p>

<div class="footprint-sim">
    <label>Consumo carne (porciones/semana): <span id="meatVal">7</span></label>
    <input type="range" id="meatSlider" min="0" max="21" value="7">

    <label>Viajes en auto (km/semana): <span id="carVal">200</span></label>
    <input type="range" id="carSlider" min="0" max="500" value="200">

    <label>Vivienda (m²/persona): <span id="houseVal">50</span></label>
    <input type="range" id="houseSlider" min="20" max="150" value="50">

    <div class="sim-result" id="earthResult"></div>
</div>

<script>
(function(){
    const meat = document.getElementById("meatSlider");
    const car = document.getElementById("carSlider");
    const house = document.getElementById("houseSlider");
    const mVal = document.getElementById("meatVal");
    const cVal = document.getElementById("carVal");
    const hVal = document.getElementById("houseVal");
    const result = document.getElementById("earthResult");

    function update(){
        const m = parseInt(meat.value);
        const c = parseInt(car.value);
        const h = parseInt(house.value);
        mVal.textContent = m;
        cVal.textContent = c;
        hVal.textContent = h;

        const base = 1.6; // gha promedio bajo
        const total = base + (m/7 * 2) + (c/100 * 1.5) + (h/50 * 0.8);
        const earths = total / 1.6;

        const day = Math.min(365, Math.floor(365 / earths));
        const date = new Date(2025, 0, day);
        const months = ["ENE","FEB","MAR","ABR","MAY","JUN","JUL","AGO","SEP","OCT","NOV","DIC"];

        result.innerHTML = `<strong>${earths.toFixed(1)} Tierras necesarias</strong><br>
                            Día del Sobregiro: ${date.getDate()} ${months[date.getMonth()]}`;
    }

    meat.addEventListener("input", update);
    car.addEventListener("input", update);
    house.addEventListener("input", update);
    update();
})();
</script>

<h4 class="subsection-title">Análisis: Déficit Ecológico por País</h4>

<p>
    Selecciona país para comparar huella y biocapacidad.
</p>

<div class="footprint-sim">
    <select id="countrySelect">
        <option value="usa">EE.UU.</option>
        <option value="china">China</option>
        <option value="india">India</option>
        <option value="brazil">Brasil</option>
        <option value="spain">España</option>
        <option value="global">Media Global</option>
    </select>

    <div class="sim-result" id="countryResult"></div>
</div>

<script>
(function(){
    const select = document.getElementById("countrySelect");
    const result = document.getElementById("countryResult");

    const data = {
        usa: { footprint: 8.1, bio: 3.6, status: "Déficit severo (-4.5 gha)" },
        china: { footprint: 3.8, bio: 1.0, status: "Déficit alto (-2.8 gha)" },
        india: { footprint: 1.2, bio: 0.7, status: "Déficit moderado (-0.5 gha)" },
        brazil: { footprint: 2.8, bio: 8.9, status: "Reserva alta (+6.1 gha)" },
        spain: { footprint: 4.5, bio: 1.4, status: "Déficit (-3.1 gha)" },
        global: { footprint: 2.8, bio: 1.6, status: "Déficit global (-1.2 gha)" }
    };

    function update(){
        const d = data[select.value];
        result.innerHTML = `<strong>Huella: ${d.footprint} gha/persona</strong><br>
                            <strong>Biocapacidad: ${d.bio} gha/persona</strong><br>
                            ${d.status}`;
    }

    select.addEventListener("change", update);
    update();
})();
</script>

