    'titulo' => 'La Flecha Dorada: Rediseñando el Metabolismo Industrial hacia la Circularidad',
    'contenido' => '<p class="intro">
    La <strong>Flecha Dorada</strong> representa el desacoplamiento entre crecimiento económico y consumo de recursos mediante economía circular. Inspirada en Cradle to Cradle y el Diagrama de Mariposa de la Ellen MacArthur Foundation, prioriza ciclos cerrados (técnicos y biológicos) sobre el modelo lineal "extraer-producir-desechar". Su implementación reduce entropía industrial y regenera capital natural.
</p>

<p class="formula-neon text-center">
    Índice de Circularidad Material (MCI):<br>
    \\[ MCI = \\frac{V + W_{in}}{V + W_{in} + W_{out} + L} \\]
</p>

<hr class="divider-neon">

<!-- ================================================= -->
<!-- DESARROLLO TEÓRICO -->
<!-- ================================================= -->

<h3 class="section-title">
    I. Diagrama de Mariposa: Ciclos Técnicos y Biológicos
</h3>

<table class="neon-table">
    <thead>
        <tr>
            <th>Ciclo</th>
            <th>Estrategias clave</th>
            <th>Jerarquía valor</th>
            <th>Ejemplo</th>
        </tr>
    </thead>
    <tbody>
        <tr>
            <td>Técnicos</td>
            <td>Mantenimiento → Reutilización → Remanufactura → Reciclaje</td>
            <td>Alta (preserva diseño)</td>
            <td>Electrónica modular</td>
        </tr>
        <tr>
            <td>Biológicos</td>
            <td>Cascadas → Extracción → Compostaje → Biogás</td>
            <td>Regenerativa</td>
            <td>Residuos orgánicos</td>
        </tr>
    </tbody>
</table>

<div class="concept-box">
    <strong>9 R\'s (jerarquía):</strong> Refuse → Reduce → Reuse → Repair → Refurbish → Remanufacture → Repurpose → Recycle → Recover
</div>

<hr class="divider-neon">

