<h3 class="section-title">
    II. Transición Lineal → Circular (Flecha Dorada)
</h3>

<p>
    Evolución del impacto ambiental con adopción circular.
</p>

<div class="svg-container">
    <svg class="golden-svg" viewBox="0 0 800 400" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg">
        <defs>
            <filter id="glow-cyan">
                <feGaussianBlur stdDeviation="6" result="blur"/>
                <feFlood flood-color="#00ffff"/>
                <feComposite in2="blur" operator="in"/>
                <feMerge>
                    <feMergeNode/>
                    <feMergeNode in="SourceGraphic"/>
                </feMerge>
            </filter>
        </defs>

        <rect width="800" height="400" fill="#050505"/>

        <text x="400" y="60" text-anchor="middle" font-size="36" fill="#00ffff" filter="url(#glow-cyan)">FLECHA DORADA: TRANSICIÓN CIRCULAR</text>

        <!-- Línea base (impacto) -->
        <line x1="50" y1="350" x2="750" y2="350" stroke="#444444" stroke-width="4"/>
        <text x="400" y="380" text-anchor="middle" font-size="24" fill="#888888">IMPACTO AMBIENTAL</text>

        <!-- Trayectoria lineal -->
        <path d="M50 350 L750 150" stroke="#ff3333" stroke-width="6" opacity="0.6"/>

        <!-- Trayectoria circular (dorada) -->
        <path id="golden-path" d="M50 350 Q400 300 750 350" fill="none" stroke="#ffcc00" stroke-width="8" filter="url(#glow-cyan)">
            <animate attributeName="stroke-dashoffset" from="800" to="0" dur="6s" repeatCount="indefinite"/>
            <animate attributeName="stroke-dasharray" values="0,800;800,0" dur="6s" repeatCount="indefinite"/>
        </path>

        <text x="400" y="200" text-anchor="middle" font-size="32" fill="#ffcc00" filter="url(#glow-cyan)">DESACOPLAMIENTO</text>
    </svg>
</div>

