<h3 class="section-title">
    III. Simuladores Interactivos
</h3>

<h4 class="subsection-title">Simulador: Producto vs Servicio (PaaS)</h4>

<p>
    Compara modelo lineal vs circular en bombillas Philips.
</p>

<div class="golden-sim">
    <button data-type="linear">Modelo Lineal (Venta)</button>
    <button data-type="circular">Modelo Circular (Servicio)</button>

    <div class="sim-result" id="paasResult"></div>
</div>

<script>
(function(){
    const buttons = document.querySelectorAll(".golden-sim button");
    const result = document.getElementById("paasResult");

    const data = {
        linear: "🔴 Obsolescencia programada<br>Alta producción → vertederos<br>Huella creciente",
        circular: "🟢 Diseño duradero + reciclable<br>Philips mantiene propiedad<br>↓60% materiales, ↑eficiencia energética"
    };

    buttons.forEach(btn => {
        btn.addEventListener("click", () => {
            const type = btn.dataset.type;
            result.innerHTML = `<strong>${type === "linear" ? "MODELO LINEAL" : "MODELO CIRCULAR"}</strong><br>${data[type]}`;
        });
    });
})();
</script>

<h4 class="subsection-title">Análisis: Índice de Circularidad (MCI)</h4>

<p>
    Calcula MCI aproximado de un producto.
</p>

<div class="golden-sim">
    <label>Material virgen (%): <span id="virginVal">80</span></label>
    <input type="range" id="virginSlider" min="0" max="100" value="80">

    <label>Material reciclado/reutilizado (%): <span id="circVal">20</span></label>

    <div class="sim-result" id="mciResult"></div>
</div>

<script>
(function(){
    const slider = document.getElementById("virginSlider");
    const virgin = document.getElementById("virginVal");
    const circ = document.getElementById("circVal");
    const result = document.getElementById("mciResult");

    function update(){
        const v = parseInt(slider.value);
        virgin.textContent = v;
        circ.textContent = 100 - v;

        const mci = ((100 - v) / 100).toFixed(2);
        result.innerHTML = `<strong>MCI ≈ ${mci}</strong><br>${mci >= 0.7 ? "Alta circularidad" : mci >= 0.4 ? "Media" : "Baja (lineal dominante)"}`;
    }

    slider.addEventListener("input", update);
    update();
})();
</script>

<h4 class="subsection-title">Quiz Autoevaluado: Flecha Dorada</h4>

<div class="quiz-container">
    <div class="quiz-question">
        <p>1. Prioridad en ciclo técnico:</p>
