        <div id="fb1"></div>
    </div>

    <div class="quiz-question">
        <p>2. Modelo PaaS incentiva:</p>
        <button onclick="checkQuiz(2,true)">Durabilidad y eficiencia</button>
        <button onclick="checkQuiz(2,false)">Obsolescencia</button>
        <div id="fb2"></div>
    </div>

