        <p>4. Objetivo Flecha Dorada:</p>
        <button onclick="checkQuiz(4,true)">Desacoplamiento crecimiento-impacto</button>
        <button onclick="checkQuiz(4,false)">Maximizar producción</button>
        <div id="fb4"></div>
    </div>

    <div id="quizScore" class="score-display">Puntuación: 0/4</div>
</div>

<script>
let score = 0;
const total = 4;
function checkQuiz(q, correct){
    const fb = document.getElementById("fb" + q);
    if (correct){
        fb.innerHTML = "✅ Correcto";
        fb.style.color = "#00e676";
        score++;
    } else {
        fb.innerHTML = "❌ Incorrecto";
        fb.style.color = "#ff1744";
    }
    document.getElementById("quizScore").textContent = "Puntuación: " + score + "/" + total;
}
</script>

