    'slug' => 'obsolescencia-percibida-master',
    'titulo' => 'Obsolescencia Percibida: La Psique del Desperdicio',
    'contenido' => '
<div class="opm-lesson-carbon perceived-obsolescence-master">

    <div class="intro-header text-center mb-5">
        <h1 class="display-3 opm-text-neon-pink">EL ENGAÑO DEL "NUEVO"</h1>
        <p class="fs-4 mx-auto" style="max-width: 900px;">
            La <strong>Obsolescencia Percibida</strong> es el motor psicológico del hiperconsumismo. No es una falla del objeto, sino una <strong>falla inducida en la satisfacción del usuario</strong> a través de la manipulación semiótica y estética. En contextos reales, esto impulsa el desperdicio masivo, afectando ecosistemas globales al aumentar la extracción de recursos y la contaminación.
        </p>
    </div>

    <div class="row mb-5">
        <div class="col-md-12">
            <div class="opm-alert-carbon opm-border-pink text-center">
                <h4 class="opm-text-magenta"><i class="fas fa-brain"></i> El Índice de Obsolescencia Psicológica (\\( I_{op} \\))</h4>
                <p>El deseo de reemplazo aumenta exponencialmente conforme el producto actual se aleja del "estándar estético" vigente:</p>
                <div class="opm-eq-box fs-3 py-4">
                    \\[ I_{op} = \\frac{\\Delta \\text{Marketing}}{\\Delta \\text{Utilidad Real}} \\cdot t \\]
                </div>
                <small class="text-muted">Si la utilidad es constante pero el marketing aumenta, la percepción de obsolescencia se dispara.</small>
            </div>
        </div>
    </div>

    <h2 class="opm-section-title opm-text-pink">1. El Efecto Diderot: La Espiral del Consumo</h2>
    <div class="row mb-5">
        <div class="col-md-7">
            <p>Este fenómeno social explica cómo la adquisición de un objeto nuevo (ej. un iPhone 16) crea una <strong>insatisfacción sistémica</strong> con los objetos actuales (cargadores, fundas, audífonos), forzando una espiral de consumo innecesario.</p>
            <div class="opm-stats-box p-3 bg-dark opm-border-left-magenta">
                <h5 class="opm-text-yellow">Impacto Crítico: Fast Fashion</h5>
                <ul>
                    <li><strong>Huella Hídrica:</strong> 7,500 litros de agua para 1 solo jean.</li>
                    <li><strong>Microplásticos:</strong> 35% de los microplásticos en el océano provienen del lavado de ropa sintética.</li>
                    <li><strong>Desecho:</strong> Un camión de basura de textiles se quema o entierra <strong>cada segundo</strong>.</li>
                </ul>
            </div>
        </div>
        <div class="col-md-5">
            <!-- Espacio para visual adicional si se necesita -->
        </div>
    </div>

    <h2 class="opm-section-title opm-text-cyan">2. E-Waste: La Tragedia del Silicio</h2>
    <div class="row mb-4 text-center">
        <div class="col-md-3">
            <div class="opm-counter-card">
                <h2 class="opm-text-neon-red">62Mt</h2>
                <p>E-Waste generado/año</p>
            </div>
        </div>
        <div class="col-md-3">
            <div class="opm-counter-card">
                <h2 class="opm-text-neon-blue">22.3%</h2>
                <p>Reciclaje Formal</p>
            </div>
        </div>
        <div class="col-md-3">
            <div class="opm-counter-card">
                <h2 class="opm-text-neon-yellow">$91B</h2>
                <p>Valor de materiales perdidos</p>
            </div>
        </div>
        <div class="col-md-3">
            <div class="opm-counter-card">
                <h2 class="opm-text-neon-green">1000+</h2>
                <p>Sustancias Tóxicas</p>
            </div>
        </div>
    </div>

    <h4 class="text-center mb-4">Mecánica de la Obsolescencia Percibida</h4>
    <div class="opm-svg-container mb-5" style="background: #0a0a0a; border-radius: 20px; border: 1px solid #333;">
        <svg viewBox="0 0 800 450" xmlns="http://www.w3.org/2000/svg">
            <circle cx="400" cy="225" r="150" fill="none" stroke="#444" stroke-width="2" stroke-dasharray="10,5" />
            
            <circle cx="400" cy="225" r="40" fill="#ff00ff" filter="url(#glow)">
                <animate attributeName="r" values="40;45;40" dur="2s" repeatCount="indefinite" />
            </circle>
            <text x="400" y="230" fill="white" font-size="12" text-anchor="middle" font-weight="bold">DESEO</text>

            <g transform="rotate(0 400 225)">
                <circle cx="400" cy="75" r="30" fill="#333" stroke="#00ffff" />
                <text x="400" y="80" fill="#00ffff" font-size="10" text-anchor="middle">Moda</text>
                <animateTransform attributeName="transform" attributeType="XML" type="rotate" from="0 400 225" to="360 400 225" dur="20s" repeatCount="indefinite" />
            </g>

            <g transform="rotate(90 400 225)">
                <circle cx="550" cy="225" r="30" fill="#333" stroke="#ffcc00" />
                <text x="550" y="230" fill="#ffcc00" font-size="10" text-anchor="middle">Estatus</text>
                <animateTransform attributeName="transform" attributeType="XML" type="rotate" from="90 400 225" to="450 400 225" dur="20s" repeatCount="indefinite" />
            </g>

            <g transform="rotate(180 400 225)">
                <circle cx="400" cy="375" r="30" fill="#333" stroke="#ff3333" />
                <text x="400" y="380" fill="#ff3333" font-size="10" text-anchor="middle">Marketing</text>
                <animateTransform attributeName="transform" attributeType="XML" type="rotate" from="180 400 225" to="540 400 225" dur="20s" repeatCount="indefinite" />
            </g>

            <g transform="rotate(270 400 225)">
                <circle cx="250" cy="225" r="30" fill="#333" stroke="#32cd32" />
                <text x="250" y="230" fill="#32cd32" font-size="10" text-anchor="middle">Tendencias</text>
                <animateTransform attributeName="transform" attributeType="XML" type="rotate" from="270 400 225" to="630 400 225" dur="20s" repeatCount="indefinite" />
            </g>

            <path d="M550 350 L750 350" stroke="#ff3333" stroke-width="4" marker-end="url(#arrow-red)" />
            <text x="650" y="380" fill="#ff3333" font-size="14" font-weight="bold">FLUJO LINEAL (DESECHO)</text>

            <defs>
                <filter id="glow"><feGaussianBlur stdDeviation="3" result="coloredBlur"/><feMerge><feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
                <marker id="arrow-red" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto">
                    <path d="M0,0 L10,5 L0,10 Z" fill="#ff3333" />
                </marker>
            </defs>
        </svg>
    </div>

    <div class="opm-interactive-block mb-5 p-4 bg-panel opm-border-cyan">
        <h4 class="opm-text-cyan mb-4"><i class="fas fa-tools"></i> Simulador de Decisión Sostenible</h4>
        <p>Tu smartphone tiene la pantalla rota. ¿Qué impacto generas según tu decisión?</p>
        <div class="row">
            <div class="col-md-6 text-center">
                <button class="opm-btn-outline-danger w-100 mb-2" onclick="calcObs(\'buy\')">Comprar el Nuevo Modelo</button>
                <button class="opm-btn-outline-success w-100" onclick="calcObs(\'repair\')">Reparar Pantalla (iFixit)</button>
            </div>
            <div class="col-md-6">
                <div id="impactOutput" class="p-3 opm-bg-black opm-border-dashed-orange" style="min-height: 100px; font-family: \'VT323\';">
                    Esperando decisión del usuario...
                </div>
            </div>
        </div>
        <div class="mt-4">
            <h5 class="opm-text-yellow">Análisis Interactivo</h5>
            <label for="marketingSlider">Nivel de Exposición a Marketing (1-10):</label>
            <input type="range" id="marketingSlider" min="1" max="10" value="5" oninput="updateIop(this.value)">
            <p id="iopResult">Índice de Obsolescencia Psicológica: Calculando...</p>
        </div>
    </div>

    <h2 class="opm-section-title opm-text-green">3. El Contraataque: Right to Repair</h2>
    <div class="row">
        <div class="col-md-12">
            <div class="table-responsive">
                <table class="table opm-table-dark opm-table-hover">
                    <thead class="opm-text-yellow">
                        <tr>
                            <th>Estrategia Anti-Reparación</th>
                            <th>Consecuencia</th>
                            <th>Solución Sostenible</th>
                        </tr>
                    </thead>
                    <tbody>
                        <tr><td><strong>Serialización</strong></td><td>Piezas bloqueadas por software.</td><td>Legislación de Interoperabilidad.</td></tr>
                        <tr><td><strong>Pegamento/Soldadura</strong></td><td>Imposible abrir sin romper.</td><td>Diseño Modular (Fairphone).</td></tr>
                        <tr><td><strong>Falta de Manuales</strong></td><td>Monopolio del servicio técnico.</td><td>Plataformas Open Source (iFixit).</td></tr>
                    </tbody>
                </table>
            </div>
        </div>
    </div>

    <div class="opm-interactive-block mt-5 p-4 opm-border-magenta">
        <h4 class="opm-text-magenta">🧠 Desafío Crítico</h4>
        <div id="quiz-obs">
            <p class="fs-5">Si un producto funciona perfectamente pero decides tirarlo porque "ya no se usa ese color", ¿qué tipo de obsolescencia estás validando?</p>
            <button class="opm-btn-quiz-obs w-100 mb-2" onclick="ansObs(1)">Obsolescencia Percibida</button>
            <button class="opm-btn-quiz-obs w-100 mb-2" onclick="ansObs(2)">Obsolescencia Planificada</button>
            <button class="opm-btn-quiz-obs w-100 mb-2" onclick="ansObs(3)">Obsolescencia Técnica</button>
            <div id="obsFeedback" class="mt-3"></div>
        </div>
    </div>

    <h2 class="opm-section-title opm-text-yellow">4. Errores Comunes del Estudiante</h2>
    <p>En exámenes y prácticas, los estudiantes suelen cometer estos errores típicos. Haz clic para ver explicaciones:</p>
    <ul class="opm-errors-list">
        <li onclick="showError(1)">Confundir obsolescencia percibida con planificada.</li>
        <div id="error1" style="display:none;">Explicación: La percibida es psicológica (moda), mientras que la planificada es intencional por el fabricante (falla programada). Esto afecta el análisis de impactos ecosistémicos.</div>
        <li onclick="showError(2)">Subestimar el impacto en ecosistemas marinos de microplásticos.</li>
        <div id="error2" style="display:none;">Explicación: Ignorar que el 35% proviene de textiles lleva a evaluaciones incompletas de contaminación en océanos, clave en exámenes de ecosistemas.</div>
        <li onclick="showError(3)">No relacionar el E-Waste con extracción de minerales raros.</li>
        <div id="error3" style="display:none;">Explicación: Olvidar que el desperdicio implica más minería (cobalto, litio) que destruye hábitats, un error común en razonamientos sistémicos.</div>
    </ul>

    <h2 class="opm-section-title opm-text-cyan">5. Conexión con la Materia Base: Ecosistemas</h2>
    <p>Esta lección se alinea directamente con los contenidos oficiales del curso de Ecosistemas, específicamente en temas de sostenibilidad, ciclos de materiales y perturbaciones antropogénicas. La obsolescencia percibida agrava la desechabilidad sistémica, alterando flujos de nutrientes y aumentando la entropía en ecosistemas (ej. acidificación oceánica por plásticos). Este contenido es evaluable en exámenes formales, enfocándose en análisis de impactos humanos en biodiversidad y ciclos biogeoquímicos.</p>

    <h2 class="opm-section-title opm-text-green">6. Problemas Tipo Examen</h2>
    <div class="opm-exam-problem">
        <p><strong>Problema 1:</strong> Calcula el impacto hídrico acumulado si una persona reemplaza 5 jeans al año por obsolescencia percibida. Justifica cómo esto afecta ecosistemas acuáticos.</p>
    </div>
    <div class="opm-exam-problem">
        <p><strong>Problema 2:</strong> Describe un ciclo vicioso entre el Efecto Diderot y el E-Waste, incluyendo razonamiento sobre sustancias tóxicas y su dispersión en el medio ambiente.</p>
    </div>
    <div class="opm-exam-problem">
        <p><strong>Problema 3:</strong> Propón una política pública basada en "Right to Repair" para reducir la obsolescencia percibida en electrónicos. Interpreta su efecto en la biodiversidad.</p>
    </div>

    <h2 class="opm-section-title opm-text-magenta">7. Cierre Metacognitivo</h2>
    <p class="opm-reflection">Reflexiona: ¿Cómo ha cambiado tu percepción del consumo personal tras esta lección? ¿Qué estrategias implementarías para contrarrestar la obsolescencia percibida en tu vida diaria, considerando impactos ecosistémicos? ¿Por qué es crucial diferenciar tipos de obsolescencia en evaluaciones ambientales?</p>

</div>

<script>
function calcObs(choice) {
    const out = document.getElementById(\'impactOutput\');
    if(choice === \'buy\') {
        out.innerHTML = "<span class=\'text-danger\'>IMPACTO ALTO:</span><br>+80kg CO2 eq. (producción)<br>+200g E-Waste tóxico<br>+Extracción de Cobalto en RDC.";
    } else {
        out.innerHTML = "<span class=\'text-success\'>IMPACTO BAJO:</span><br>-90% emisiones evitadas<br>Ahorro de $600 USD<br>Apoyo a economía local de reparación.";
    }
}

function updateIop(value) {
    const utilidadReal = 1; // Constante para simplicidad
    const t = 1; // Tiempo unitario
    const iop = (value / utilidadReal) * t;
    document.getElementById(\'iopResult\').innerHTML = `Índice de Obsolescencia Psicológica: ${iop.toFixed(2)} (Mayor exposición acelera el deseo de reemplazo)`;
}

function ansObs(option) {
    const fb = document.getElementById(\'obsFeedback\');
    if(option === 1) {
        fb.innerHTML = "<div class=\'opm-alert-success\'>¡Exacto! El objeto es técnicamente funcional, pero el marketing ha \'vencido\' su valor social en tu mente.</div>";
    } else {
        fb.innerHTML = "<div class=\'opm-alert-danger\'>Incorrecto. Si el producto funciona pero lo tiras por moda, es Percibida. La Planificada es cuando el fabricante lo rompe a propósito.</div>";
    }
}

function showError(id) {
    const errorDiv = document.getElementById(`error${id}`);
    errorDiv.style.display = errorDiv.style.display === \'none\' ? \'block\' : \'none\';
}
</script>',
    'ejercicios' => 
