    'slug' => 'obsolescencia-programada-master',
    'titulo' => 'Obsolescencia Programada: Ingeniería del Desperdicio',
    'contenido' => '
<div class="opp-lesson-carbon planned-obsolescence-master">

    <div class="intro-header text-center mb-5">
        <h1 class="display-3 opp-text-neon-orange">DISEÑADO PARA MORIR</h1>
        <p class="fs-4 mx-auto" style="max-width: 900px;">
            La <strong>Obsolescencia Programada</strong> es una estrategia deliberada de diseño donde se acorta intencionalmente la vida útil de un producto para estimular el reemplazo frecuente. Esto genera impactos masivos en ecosistemas: mayor extracción de recursos, contaminación tóxica y acumulación de residuos (e-waste global: 62 Mt en 2022).
        </p>
    </div>

    <div class="row mb-5">
        <div class="col-md-12">
            <div class="opp-alert-carbon opp-border-orange text-center">
                <h4 class="opp-text-orange"><i class="fas fa-chart-line"></i> Modelo de Reemplazo Óptimo (\\( R_o \\))</h4>
                <p>Las empresas optimizan la duración para maximizar beneficios a largo plazo:</p>
                <div class="opp-eq-box fs-3 py-4">
                    \\[ R_o = \\max_T \\int_{0}^{T} [V(t) - C(t)] \\, dt \\]
                </div>
                <small class="text-muted">Donde \\( V(t) \\) son ventas recurrentes y \\( C(t) \\) costos de garantías y pérdida de reputación.</small>
            </div>
        </div>
    </div>

    <h2 class="opp-section-title opp-text-yellow">1. El Pecado Original: El Cártel Phoebus</h2>
    <div class="row mb-5">
        <div class="col-md-6">
            <p>En 1924-1925, fabricantes líderes (Osram, Philips, GE) formaron el cártel Phoebus para limitar la vida útil de bombillas incandescentes de ~2,500 horas a 1,000 horas, multando a quien excediera el límite. Fue el primer caso documentado de obsolescencia programada a escala global.</p>
            <div class="p-3 bg-dark opp-border-left-orange">
                <h5 class="opp-text-neon-yellow">Cronología Histórica:</h5>
                <ul class="list-unstyled">
                    <li><i class="fas fa-lightbulb text-yellow"></i> <strong>Pre-1924:</strong> Bombillas duraban 1,500-2,500 horas.</li>
                    <li><i class="fas fa-handshake text-orange"></i> <strong>1924:</strong> Formación del cártel Phoebus.</li>
                    <li><i class="fas fa-ban text-danger"></i> <strong>1939:</strong> Disolución por WWII, pero práctica persiste.</li>
                </ul>
            </div>
        </div>
        <div class="col-md-6">
            <div class="table-responsive">
                <table class="table opp-table-dark opp-table-hover opp-border-orange">
                    <thead class="opp-text-yellow">
                        <tr><th>Caso Moderno</th><th>Mecanismo de Obsolescencia</th></tr>
                    </thead>
                    <tbody>
                        <tr><td><strong>Impresoras</strong></td><td>Chips contadores que bloquean tras "X" páginas.</td></tr>
                        <tr><td><strong>Smartphones</strong></td><td>Baterías soldadas y ralentización por software (ej. Batterygate).</td></tr>
                        <tr><td><strong>Electrodomésticos</strong></td><td>Componentes frágiles (condensadores baratos en TVs).</td></tr>
                    </tbody>
                </table>
            </div>
        </div>
    </div>

    <h2 class="opp-section-title opp-text-cyan">2. Arquitectura de la Inutilidad</h2>
    <div class="row mb-5">
        <div class="col-md-4">
            <div class="card opp-card opp-border-cyan p-3 h-100">
                <h4 class="opp-text-cyan text-center">Software</h4>
                <p>Actualizaciones que degradan rendimiento en hardware antiguo o cesan soporte.</p>
            </div>
        </div>
        <div class="col-md-4">
            <div class="card opp-card opp-border-magenta p-3 h-100">
                <h4 class="opp-text-magenta text-center">Sistémica</h4>
                <p>Cambios incompatibles en conectores o estándares.</p>
            </div>
        </div>
        <div class="col-md-4">
            <div class="card opp-card opp-border-yellow p-3 h-100">
                <h4 class="opp-text-yellow text-center">Materiales</h4>
                <p>Uso de componentes de baja durabilidad cerca de partes críticas.</p>
            </div>
        </div>
    </div>

    <h4 class="text-center mb-4">Simulación de Degradación Programada</h4>
    <div class="opp-svg-container mb-5" style="background: #0a0a0a; border-radius: 20px; border: 1px solid #ff4500;">
        <svg viewBox="0 0 800 400" xmlns="http://www.w3.org/2000/svg">
            <line x1="100" y1="350" x2="700" y2="350" stroke="#666" stroke-width="2" />
            <line x1="100" y1="350" x2="100" y2="50" stroke="#666" stroke-width="2" />
            <text x="600" y="380" fill="#666" font-size="14">TIEMPO (Meses)</text>
            <text x="50" y="100" fill="#666" font-size="14" transform="rotate(-90 50 200)">FUNCIONALIDAD (%)</text>

            <path d="M100 80 Q400 90 700 100" fill="none" stroke="#00ff00" stroke-width="3" stroke-dasharray="10,5" opacity="0.6" />
            <text x="500" y="70" fill="#00ff00" font-size="12">Diseño Duradero</text>

            <path d="M100 80 Q350 100 400 350" fill="none" stroke="#ff3333" stroke-width="5" filter="url(#glow)">
                <animate attributeName="stroke-dashoffset" from="1000" to="0" dur="5s" repeatCount="indefinite" />
            </path>
            <text x="350" y="330" fill="#ff3333" font-size="14" font-weight="bold">FALLA PROGRAMADA</text>

            <defs>
                <filter id="glow"><feGaussianBlur stdDeviation="4" result="coloredBlur"/><feMerge><feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
            </defs>
        </svg>
    </div>

    <div class="opp-interactive-block mb-5 p-4 opp-border-yellow">
        <h4 class="opp-text-yellow mb-4"><i class="fas fa-balance-scale"></i> Simulador: El Dilema del Fabricante</h4>
        <p>Eres CEO de una empresa de TVs. Elige la durabilidad de condensadores:</p>
        <div class="row">
            <div class="col-md-6 text-center">
                <button class="opp-btn-outline-danger w-100 mb-2" onclick="simPlann(\'evil\')">Condensadores baratos (vida ~2 años)</button>
                <button class="opp-btn-outline-success w-100" onclick="simPlann(\'good\')">Condensadores premium (vida ~10 años)</button>
            </div>
            <div class="col-md-6">
                <div id="simFeedback" class="p-3 opp-bg-black" style="min-height: 150px; font-family: \'VT323\';"></div>
            </div>
        </div>
        <div class="mt-4">
            <label for="durabilitySlider">Ajusta vida útil planeada (meses): </label>
            <input type="range" id="durabilitySlider" min="12" max="120" value="24" oninput="updateDegrad(this.value)">
            <p id="degradResult">Impacto ambiental: Calculando...</p>
        </div>
    </div>

    <h2 class="opp-section-title opp-text-green">3. Hacia el Diseño Ético y Sostenible</h2>
    <div class="row mb-5">
        <div class="col-md-12">
            <div class="p-3 bg-dark opp-border-green">
                <h4 class="opp-text-green">Avances Regulatorios (UE 2025)</h4>
                <ul>
                    <li><strong>Ecodesign 2025:</strong> Mayor durabilidad, resistencia y reparabilidad obligatoria en smartphones/tablets.</li>
                    <li><strong>Baterías 2027:</strong> Removibles y reemplazables por el usuario sin herramientas especiales.</li>
                    <li><strong>Índice de Reparabilidad:</strong> Etiquetado obligatorio y prohibición de prácticas anti-reparación.</li>
                </ul>
            </div>
        </div>
    </div>

    <div class="opp-interactive-block mt-5 p-4 opp-border-magenta">
        <h4 class="opp-text-magenta">🧠 Quiz Autoevaluado</h4>
        <p class="fs-5">¿Qué diferencia principal hay entre obsolescencia programada y percibida?</p>
        <button class="opp-btn-outline-danger w-100 mb-2" onclick="ansQuiz(1)">Programada es por moda, percibida por falla técnica.</button>
        <button class="opp-btn-outline-success w-100 mb-2" onclick="ansQuiz(2)">Programada es intencional del fabricante, percibida es psicológica.</button>
        <button class="opp-btn-outline-danger w-100 mb-2" onclick="ansQuiz(3)">Ambas son lo mismo.</button>
        <div id="quizFeedback" class="mt-3"></div>
    </div>

    <h2 class="opp-section-title opp-text-yellow">4. Errores Comunes del Estudiante</h2>
    <p>Haz clic para revelar explicaciones de errores típicos en exámenes:</p>
    <ul class="opp-errors-list">
        <li onclick="showError(1)">Confundir programada con percibida.</li>
        <div id="error1" style="display:none;">Explicación: Programada es falla inducida por diseño; percibida es deseo por novedad. Error común al analizar impactos ecosistémicos.</div>
        <li onclick="showError(2)">Ignorar el rol histórico del cártel Phoebus.</li>
        <div id="error2" style="display:none;">Explicación: Fue el origen moderno; omitirlo debilita argumentos sobre ética empresarial en evaluaciones.</div>
        <li onclick="showError(3)">Subestimar avances regulatorios UE.</li>
        <div id="error3" style="display:none;">Explicación: Ecodesign 2025 y baterías 2027 son clave para razonar soluciones sostenibles.</div>
    </ul>

    <h2 class="opp-section-title opp-text-cyan">5. Conexión con la Materia Base: Ecosistemas</h2>
    <p>Este tema se integra en los contenidos oficiales de Ecosistemas, enfocando perturbaciones antropogénicas, ciclos biogeoquímicos alterados por contaminantes tóxicos (e-waste) y pérdida de biodiversidad por minería intensiva. La obsolescencia programada agrava la crisis de residuos, evaluable en análisis de sostenibilidad y ética ambiental.</p>

    <h2 class="opp-section-title opp-text-green">6. Problemas Tipo Examen</h2>
    <div class="opp-exam-problem">
        <p><strong>Problema 1:</strong> Explica cómo el cártel Phoebus ejemplifica obsolescencia programada y calcula su impacto hipotético en generación de residuos si bombillas duraran 2,500 vs 1,000 horas (asumiendo uso anual promedio).</p>
    </div>
    <div class="opp-exam-problem">
        <p><strong>Problema 2:</strong> Analiza el dilema ético del fabricante: justifica por qué elegir durabilidad reduce impactos ecosistémicos (contaminación, extracción recursos).</p>
    </div>
    <div class="opp-exam-problem">
        <p><strong>Problema 3:</strong> Evalúa el efecto de las regulaciones UE (2025-2027) en reducción de e-waste global, proponiendo extensiones a otros continentes.</p>
    </div>

    <h2 class="opp-section-title opp-text-magenta">7. Cierre Metacognitivo</h2>
    <p class="opp-reflection">Reflexiona: ¿Cómo influye la obsolescencia programada en tus decisiones de consumo? ¿Qué acciones personales o políticas promoverías para un diseño ético que preserve ecosistemas? ¿Por qué es esencial diferenciarla de otros tipos en análisis ambientales?</p>

</div>

<script>
function simPlann(type) {
    const out = document.getElementById(\'simFeedback\');
    if(type === \'evil\') {
        out.innerHTML = "<span class=\'text-danger\'>GANANCIAS CORToplacistas:</span><br>+20% ventas iniciales<br>Pero: +1M toneladas e-waste<br>Multas UE post-2025 y pérdida reputación.";
    } else {
        out.innerHTML = "<span class=\'text-success\'>LIDERAZGO SOSTENIBLE:</span><br>+40% lealtad clientes<br>Cumplimiento regulaciones UE<br>Reducción emisiones y residuos.";
    }
}

function updateDegrad(months) {
    const wasteFactor = 120 / months; // Mayor si vida corta
    document.getElementById(\'degradResult\').innerHTML = `Vida útil: ${months} meses<br>Factor multiplicador residuos: ${wasteFactor.toFixed(1)}x<br>(Mayor duración = menor impacto ecosistémico)`;
}

function ansQuiz(option) {
    const fb = document.getElementById(\'quizFeedback\');
    if(option === 2) {
        fb.innerHTML = "<div class=\'opp-alert-success\'>¡Correcto! La programada es deliberada por el fabricante; la percibida, inducida por marketing/moda.</div>";
    } else {
        fb.innerHTML = "<div class=\'opp-alert-danger\'>Incorrecto. Revisa la definición: programada implica ingeniería intencional de falla.</div>";
    }
}

function showError(id) {
    const div = document.getElementById(`error${id}`);
    div.style.display = div.style.display === \'none\' ? \'block\' : \'none\';
}
</script>',
