    'materia' => 'Ecosistemas',
    'slug' => 'fast-fashion-master',
    'titulo' => 'Fast Fashion: La Anatomía del Exceso',
    'contenido' => '
<div class="ffm-lesson-carbon fast-fashion-master">

    <div class="intro-header text-center mb-5">
        <h1 class="display-3 ffm-text-neon-pink">MODA DESECHABLE</h1>
        <p class="fs-4 mx-auto" style="max-width: 900px;">
            El <strong>Fast Fashion</strong> acelera la extracción lineal de recursos, convirtiendo materiales finitos en residuos tóxicos a un ritmo que excede la regeneración planetaria. Genera ~92 millones de toneladas de desechos textiles anuales, contribuye al 10% de emisiones globales de CO₂ y al 35% de microplásticos oceánicos.
        </p>
    </div>

    <div class="row mb-5">
        <div class="col-md-12">
            <div class="ffm-alert-carbon ffm-border-pink text-center">
                <h4 class="ffm-text-magenta"><i class="fas fa-tint"></i> Huella Hídrica de una Prenda (\\( W_f \\))</h4>
                <p>El consumo total incluye riego, procesamiento y dilución de contaminantes:</p>
                <div class="ffm-eq-box fs-3 py-4">
                    \\[ W_f = V_{\\text{riego}} + V_{\\text{proceso}} + V_{\\text{dilución}} \\]
                </div>
                <small class="text-muted">Para una camiseta de algodón: \\( W_f \\approx 2,700 \\) litros (equivalente a 900 días de agua potable para una persona).</small>
            </div>
        </div>
    </div>

    <h2 class="ffm-section-title ffm-text-pink">1. La Segunda Industria más Contaminante</h2>
    <div class="row mb-5">
        <div class="col-md-7">
            <p>La hiperproducción impacta tres frentes ecosistémicos clave:</p>
            <div class="ffm-stats-box p-4 bg-dark ffm-border-left-magenta">
                <ul class="list-unstyled">
                    <li class="mb-3">
                        <strong class="ffm-text-cyan"><i class="fas fa-microscope"></i> Microplásticos:</strong> 
                        35% de microplásticos primarios en océanos provienen del lavado de sintéticos (~500,000 toneladas/año).
                    </li>
                    <li class="mb-3">
                        <strong class="ffm-text-orange"><i class="fas fa-cloud-sun"></i> Emisiones:</strong> 
                        10% de CO₂ global (más que aviación + marítimo combinados).
                    </li>
                    <li class="mb-3">
                        <strong class="ffm-text-yellow"><i class="fas fa-skull-crossbones"></i> Toxicidad:</strong> 
                        ~20% de contaminación industrial de agua dulce por teñido y tratamientos.
                    </li>
                </ul>
            </div>
        </div>
        <div class="col-md-5">
            <!-- Espacio reservado -->
        </div>
    </div>

    <h2 class="ffm-section-title ffm-text-cyan">2. Del Fast Fashion al Ultra-Fast</h2>
    <div class="table-responsive mb-5">
        <table class="table ffm-table-dark ffm-table-hover ffm-border-magenta">
            <thead class="ffm-text-yellow">
                <tr>
                    <th>Modelo</th>
                    <th>Ciclo de Diseño</th>
                    <th>Prendas Nuevas / Día</th>
                    <th>Impacto Ético/Ambiental</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td><strong>Moda Tradicional</strong></td>
                    <td>6-9 meses</td>
                    <td>Mínimas</td>
                    <td>Bajo</td>
                </tr>
                <tr>
                    <td><strong>Fast Fashion (Zara)</strong></td>
                    <td>3-4 semanas</td>
                    <td>~500</td>
                    <td>Precariedad laboral</td>
                </tr>
                <tr class="bg-danger">
                    <td><strong>Ultra-Fast (Shein)</strong></td>
                    <td>3-7 días</td>
                    <td>6,000-10,000</td>
                    <td>Trabajo forzado denunciado + máximo desperdicio</td>
                </tr>
            </tbody>
        </table>
    </div>

    <h4 class="text-center mb-4 ffm-text-magenta">Ciclo Lineal vs. Circularidad</h4>
    <div class="ffm-svg-container mb-5" style="background: #0a0a0a; border-radius: 20px; border: 1px solid #ff1493;">
        <svg viewBox="0 0 800 450" xmlns="http://www.w3.org/2000/svg">
            <rect x="50" y="180" width="140" height="80" fill="#222" stroke="#ff00ff" stroke-width="3" rx="15" />
            <text x="120" y="225" fill="#ff00ff" font-size="14" text-anchor="middle">EXTRACCIÓN</text>

            <rect x="320" y="180" width="140" height="80" fill="#222" stroke="#00ffff" stroke-width="3" rx="15" />
            <text x="390" y="225" fill="#00ffff" font-size="14" text-anchor="middle">PRODUCCIÓN / CONSUMO</text>

            <rect x="590" y="180" width="140" height="80" fill="#222" stroke="#ff3333" stroke-width="3" rx="15" />
            <text x="660" y="225" fill="#ff3333" font-size="14" text-anchor="middle">VERTEDERO / INCINERACIÓN</text>

            <path d="M190 220 L320 220 M460 220 L590 220" stroke="#666" stroke-width="5" stroke-dasharray="10,5" />
            
            <circle r="8" fill="#ff3333" cx="460" cy="220">
                <animateMotion path="M460 220 L590 220" dur="3s" repeatCount="indefinite" />
            </circle>

            <path d="M390 180 Q390 50 120 180" fill="none" stroke="#00ff00" stroke-width="4" opacity="0.7">
                <animate attributeName="opacity" values="0.7;1;0.7" dur="4s" repeatCount="indefinite" />
            </path>
            <text x="255" y="80" fill="#00ff00" font-size="14" text-anchor="middle">RECICLAJE / UPCYCLING</text>

            <defs>
                <marker id="arrow-green" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto">
                    <path d="M0,0 L10,5 L0,10 Z" fill="#00ff00" />
                </marker>
            </defs>
        </svg>
    </div>

    <div class="ffm-interactive-block mb-5 p-4 ffm-border-yellow">
        <h4 class="ffm-text-yellow mb-4"><i class="fas fa-tshirt"></i> Simulador: Regla #30Wears</h4>
        <p>¿Cuántas veces usarás esa prenda nueva?</p>
        <div class="row">
            <div class="col-md-6 text-center">
                <button class="ffm-btn-outline-danger w-100 mb-2" onclick="calcModa(\'less\')">Menos de 10 veces</button>
                <button class="ffm-btn-outline-success w-100" onclick="calcModa(\'more\')">Más de 30 veces</button>
            </div>
            <div class="col-md-6">
                <div id="modaFeedback" class="p-3 ffm-bg-black ffm-border-dashed-cyan" style="min-height: 120px; font-family: \'VT323\';"></div>
            </div>
        </div>
        <div class="mt-4">
            <label for="usesSlider">Ajusta usos previstos: </label>
            <input type="range" id="usesSlider" min="1" max="100" value="10" oninput="updateWears(this.value)">
            <p id="wearsResult">Huella calculada: Esperando...</p>
        </div>
    </div>

    <h2 class="ffm-section-title ffm-text-green">3. Estrategias de Mitigación: Hacia la Slow Fashion</h2>
    <div class="row mb-5">
        <div class="col-md-12">
            <div class="p-3 bg-dark ffm-border-cyan">
                <ul>
                    <li>Compra segunda mano o alquiler.</li>
                    <li>Reparación y upcycling.</li>
                    <li>Armario cápsula y materiales sostenibles (orgánico/reciclado).</li>
                    <li>Apoyo a regulaciones UE para recolección separada de textiles (2025+).</li>
                </ul>
            </div>
        </div>
    </div>

    <div class="ffm-interactive-block mt-5 p-4 ffm-border-magenta">
        <h4 class="ffm-text-magenta">🧠 Quiz Autoevaluado</h4>
        <p class="fs-5">¿Cuál es el principal origen de microplásticos en océanos relacionado con moda?</p>
        <button class="ffm-btn-outline-danger w-100 mb-2" onclick="ansQuiz(1)">Desecho de prendas enteras</button>
        <button class="ffm-btn-outline-success w-100 mb-2" onclick="ansQuiz(2)">Lavado de fibras sintéticas</button>
        <button class="ffm-btn-outline-danger w-100 mb-2" onclick="ansQuiz(3)">Producción de algodón</button>
        <div id="quizFeedback" class="mt-3"></div>
    </div>

    <h2 class="ffm-section-title ffm-text-yellow">4. Errores Comunes del Estudiante</h2>
    <p>Haz clic para revelar explicaciones de errores frecuentes en exámenes:</p>
    <ul class="ffm-errors-list">
        <li onclick="showError(1)">Subestimar el % de emisiones CO₂ de la industria textil.</li>
        <div id="error1" style="display:none;">Explicación: 10% global, más que aviación + marítimo; clave para análisis de perturbaciones antropogénicas.</div>
        <li onclick="showError(2)">Confundir origen de microplásticos con plásticos macro.</li>
        <div id="error2" style="display:none;">Explicación: 35% proviene de lavado sintéticos, no botellas; afecta cadenas tróficas marinas.</div>
        <li onclick="showError(3)">Ignorar diferencia fast vs. ultra-fast.</li>
        <div id="error3" style="display:none;">Explicación: Ultra-fast (Shein) multiplica impactos por volumen extremo.</div>
    </ul>

    <h2 class="ffm-section-title ffm-text-cyan">5. Conexión con la Materia Base: Ecosistemas</h2>
    <p>Este subtema se alinea con contenidos oficiales de Ecosistemas: impactos antropogénicos en ciclos hídricos, biogeoquímicos (C, N, P vía contaminantes) y biodiversidad marina (microplásticos). Fast fashion altera flujos de materiales y genera perturbaciones irreversibles, evaluable en exámenes de sostenibilidad y ética ambiental.</p>

    <h2 class="ffm-section-title ffm-text-green">6. Problemas Tipo Examen</h2>
    <div class="ffm-exam-problem">
        <p><strong>Problema 1:</strong> Calcula la huella hídrica acumulada de 10 camisetas de algodón y explica su impacto en ecosistemas acuáticos continentales.</p>
    </div>
    <div class="ffm-exam-problem">
        <p><strong>Problema 2:</strong> Analiza cómo el modelo ultra-fast agrava la generación de ~92 Mt de desechos textiles anuales, relacionándolo con ciclos de nutrientes.</p>
    </div>
    <div class="ffm-exam-problem">
        <p><strong>Problema 3:</strong> Propón medidas basadas en economía circular para mitigar microplásticos textiles, evaluando efectos en biodiversidad oceánica.</p>
    </div>

    <h2 class="ffm-section-title ffm-text-magenta">7. Cierre Metacognitivo</h2>
    <p class="ffm-reflection">Reflexiona: ¿Cómo influye tu consumo de moda en ecosistemas globales? ¿Qué cambios personales adoptarías aplicando #30Wears? ¿Por qué es crucial regular ultra-fast fashion para preservar ciclos biogeoquímicos?</p>

</div>

<script>
function calcModa(type) {
    const fb = document.getElementById(\'modaFeedback\');
    if(type === \'less\') {
        fb.innerHTML = "<span class=\'text-danger\'>IMPACTO ALTO:</span><br>Alimentas el ciclo lineal: +microplásticos por lavados, +desechos rápidos y mayor extracción recursos.";
    } else {
        fb.innerHTML = "<span class=\'text-success\'>IMPACTO REDUCIDO:</span><br>Extiendes vida útil: -80% huella relativa, menos emisiones y apoyo a circularidad.";
    }
}

function updateWears(uses) {
    const baseWater = 2700; // Litros por camiseta
    const impact = uses < 30 ? \'alto\' : \'bajo\';
    const reduction = uses > 30 ? ((uses - 30)/uses * 100).toFixed(0) : 0;
    document.getElementById(\'wearsResult\').innerHTML = `Usos: ${uses}<br>Huella relativa: ${impact} ${reduction > 0 ? `(reducción ~${reduction}%)` : \'\'}`;
}

function ansQuiz(option) {
    const fb = document.getElementById(\'quizFeedback\');
    if(option === 2) {
        fb.innerHTML = "<div class=\'ffm-alert-success\'>¡Correcto! El lavado de sintéticos libera microfibras (35% microplásticos oceánicos).</div>";
    } else {
        fb.innerHTML = "<div class=\'ffm-alert-danger\'>Incorrecto. El principal es lavado de poliéster/nylon, no desechos macro o algodón.</div>";
    }
}

function showError(id) {
    const div = document.getElementById(`error${id}`);
    div.style.display = div.style.display === \'none\' ? \'block\' : \'none\';
}
</script>',
