    'materia' => 'Ecosistemas',
    'slug' => 'esclavitud-moderna-master',
    'titulo' => 'Esclavitud Moderna: El Motor Oculto de la Economía Lineal',
    'contenido' => '
<div class="esm-lesson-carbon modern-slavery-master">

    <div class="intro-header text-center mb-5">
        <h1 class="display-3 esm-text-neon-red">ESCLAVITUD MODERNA</h1>
        <p class="fs-4 mx-auto" style="max-width: 900px;">
            En 2025, la <strong>esclavitud moderna</strong> afecta a ~50 millones de personas globalmente (ILO/Walk Free 2021-2023 estimates). Es un mecanismo de reducción de costos en cadenas de suministro que intersecta con degradación ambiental: la destrucción de ecosistemas genera vulnerabilidad humana, perpetuando explotación y ecocidio.
        </p>
    </div>

    <div class="row mb-5">
        <div class="col-md-12">
            <div class="esm-alert-carbon esm-border-red text-center">
                <h4 class="esm-text-red"><i class="fas fa-users-slash"></i> Huella de Esclavitud en Consumo (\\( S_f \\))</h4>
                <p>Estima el riesgo acumulado de explotación en productos consumidos:</p>
                <div class="esm-eq-box fs-3 py-4">
                    \\[ S_f = \\sum_{i=1}^{n} (C_i \\times R_i) \\]
                </div>
                <small class="text-muted">Donde \\( C_i \\) es consumo del producto i y \\( R_i \\) coeficiente de riesgo por industria/región (ej. alto en minería cobalto, pesca, textiles).</small>
            </div>
        </div>
    </div>

    <h2 class="esm-section-title esm-text-orange">1. Nexo Ecocidio-Explotación Humana</h2>
    <div class="row mb-5">
        <div class="col-md-7">
            <p>La degradación ambiental crea "zonas de sacrificio" donde comunidades pierden medios de vida, aumentando vulnerabilidad a servidumbre por deuda o trabajo forzado.</p>
            <div class="esm-stats-box p-4 bg-dark esm-border-left-red">
                <ul class="list-unstyled">
                    <li class="mb-3">
                        <strong class="esm-text-yellow"><i class="fas fa-hammer"></i> Minería Cobalto (RDC):</strong> 
                        ~70% suministro global; miles de niños en minas artesanales (estimados 40,000+), riesgos tóxicos y colapsos.
                    </li>
                    <li class="mb-3">
                        <strong class="esm-text-cyan"><i class="fas fa-fish"></i> Pesca (Sudeste Asiático):</strong> 
                        Trabajadores migrantes retenidos en barcos, abuso y condiciones degradantes persisten en 2025.
                    </li>
                    <li class="mb-3">
                        <strong class="esm-text-green"><i class="fas fa-tree"></i> Deforestación (Amazonas):</strong> 
                        Trabajo forzado en ganadería ilegal y minería impulsa pérdida de biodiversidad.
                    </li>
                </ul>
            </div>
        </div>
        <div class="col-md-5">
            <!-- Espacio reservado -->
        </div>
    </div>

    <h2 class="esm-section-title esm-text-red">2. Formas de Esclavitud Moderna en 2025</h2>
    <div class="table-responsive mb-5">
        <table class="table esm-table-dark esm-table-hover esm-border-red">
            <thead class="esm-text-neon-yellow">
                <tr>
                    <th>Forma</th>
                    <th>Mecanismo</th>
                    <th>Ejemplos Industriales</th>
                </tr>
            </thead>
            <tbody>
                <tr>
                    <td><strong>Servidumbre por Deuda</strong></td>
                    <td>Tarifas reclutamiento impagables.</td>
                    <td>Agricultura, construcción.</td>
                </tr>
                <tr>
                    <td><strong>Trabajo Infantil Forzado</strong></td>
                    <td>Explotación vulnerabilidad familiar.</td>
                    <td>Minería cobalto, cacao.</td>
                </tr>
                <tr>
                    <td><strong>Trata y Trabajo Forzado</strong></td>
                    <td>Engaño y retención.</td>
                    <td>Pesca, textiles.</td>
                </tr>
                <tr>
                    <td><strong>Esclavitud Estatal</strong></td>
                    <td>Impuesta por gobiernos.</td>
                    <td>Algodón (ej. regiones específicas).</td>
                </tr>
            </tbody>
        </table>
    </div>

    <h4 class="text-center mb-4 esm-text-red">Cadena de Suministro Opaca</h4>
    <div class="esm-svg-container mb-5" style="background: #0a0a0a; border-radius: 20px; border: 1px solid #ff0000;">
        <svg viewBox="0 0 800 400" xmlns="http://www.w3.org/2000/svg">
            <rect x="50" y="250" width="150" height="100" fill="#300" stroke="#ff0000" stroke-width="3" rx="10" />
            <text x="125" y="300" fill="#ff0000" font-size="14" text-anchor="middle">TIER 3: EXTRACCIÓN</text>
            <text x="125" y="320" fill="#fff" font-size="10" text-anchor="middle">(Explotación Infantil/Forzada)</text>

            <rect x="300" y="150" width="150" height="100" fill="#222" stroke="#ff8c00" stroke-width="3" rx="10" />
            <text x="375" y="200" fill="#ff8c00" font-size="14" text-anchor="middle">TIER 2: PROCESADO</text>
            <text x="375" y="220" fill="#fff" font-size="10" text-anchor="middle">(Condiciones Degradantes)</text>

            <rect x="550" y="50" width="150" height="100" fill="#033" stroke="#00ffff" stroke-width="3" rx="10" />
            <text x="625" y="100" fill="#00ffff" font-size="14" text-anchor="middle">TIER 1: MARCA</text>
            <text x="625" y="120" fill="#fff" font-size="10" text-anchor="middle">(Marketing Sostenible)</text>

            <path d="M200 300 L300 200 M450 200 L550 100" stroke="#666" stroke-width="4" stroke-dasharray="10,5" marker-end="url(#arrow-red)" />

            <defs>
                <marker id="arrow-red" markerWidth="10" markerHeight="10" refX="9" refY="5" orient="auto">
                    <path d="M0,0 L10,5 L0,10 Z" fill="#ff0000" />
                </marker>
            </defs>

            <rect x="0" y="0" width="800" height="400" fill="#300" opacity="0.3">
                <animate attributeName="opacity" values="0.3;0.6;0.3" dur="5s" repeatCount="indefinite" />
            </rect>
        </svg>
    </div>

    <div class="esm-interactive-block mb-5 p-4 esm-border-yellow">
        <h4 class="esm-text-yellow mb-4"><i class="fas fa-search"></i> Simulador: Calcula tu Huella de Esclavitud</h4>
        <p>Selecciona productos comunes y ve el riesgo estimado:</p>
        <label>Baterías EV/Smartphones (cobalto): </label>
        <input type="range" id="cobaltSlider" min="0" max="10" value="5" oninput="updateSf()">
        <label>Pesca/Camarones: </label>
        <input type="range" id="seafoodSlider" min="0" max="10" value="5" oninput="updateSf()">
        <label>Textiles/Ropa: </label>
        <input type="range" id="textileSlider" min="0" max="10" value="5" oninput="updateSf()">
        <p id="sfResult" class="mt-3">Huella: Calculando...</p>
        <button class="esm-btn-outline-warning w-100 mt-3" onclick="ethicsTips()">Consejos para Consumo Ético</button>
        <div id="ethicsOutput" class="mt-3 p-3 esm-bg-black" style="min-height: 100px; font-family: \'VT323\';"></div>
    </div>

    <h2 class="esm-section-title esm-text-green">3. Soluciones: Transparencia y Debida Diligencia</h2>
    <div class="row mb-5">
        <div class="col-md-12">
            <div class="p-3 bg-dark esm-border-cyan">
                <ul>
                    <li><strong>Blockchain y Trazabilidad:</strong> Registros inmutables para cadenas de suministro.</li>
                    <li><strong>CSDDD UE (2024-2025):</strong> Obliga due diligence en derechos humanos y ambiente; implementación progresiva con posibles ajustes Omnibus.</li>
                    <li><strong>Certificaciones:</strong> Fair Trade, GOTS, apps como Good On You.</li>
                </ul>
            </div>
        </div>
    </div>

    <div class="mt-5">
        <div class="monday-quiz-header">
            <div class="monday-quiz-icon">🧠</div>
            <h4 class="monday-quiz-title">Quiz Autoevaluado</h4>
        </div>

        <p class="monday-quiz-question">¿Cuál es el nexo principal entre esclavitud moderna y ecosistemas?</p>

        <div class="monday-quiz-options">
            <button class="monday-quiz-btn" onclick="ansQuiz(1)">Solo económico</button>
            <button class="monday-quiz-btn" onclick="ansQuiz(2)">Degradación ambiental genera vulnerabilidad humana</button>
            <button class="monday-quiz-btn" onclick="ansQuiz(3)">No hay relación</button>
        </div>

        <div id="quizFeedback"></div>
    </div>

    <h2 class="esm-section-title esm-text-yellow">4. Errores Comunes del Estudiante</h2>
    <p>Haz clic para explicaciones de errores típicos:</p>
    <ul class="esm-errors-list">
        <li onclick="showError(1)">Ver esclavitud moderna como solo histórica.</li>
        <div id="error1" style="display:none;">Explicación: Persiste en cadenas modernas; ~50M afectados en 2025.</div>
        <li onclick="showError(2)">Ignorar intersección ambiental-humana.</li>
        <div id="error2" style="display:none;">Explicación: Ecocidio desplaza comunidades, aumentando explotación.</div>
        <li onclick="showError(3)">Subestimar regulaciones como CSDDD.</li>
        <div id="error3" style="display:none;">Explicación: Obligan due diligence, impactando supply chains globales.</div>
    </ul>

    <h2 class="esm-section-title esm-text-cyan">5. Conexión con la Materia Base: Ecosistemas</h2>
    <p>Este tema integra perturbaciones antropogénicas en ecosistemas: explotación humana acelera degradación (deforestación, minería tóxica), alterando ciclos biogeoquímicos y biodiversidad. Evaluables en análisis de sostenibilidad socio-ambiental.</p>

    <h2 class="esm-section-title esm-text-green">6. Problemas Tipo Examen</h2>
    <div class="esm-exam-problem">
        <p><strong>Problema 1:</strong> Explica el nexo entre minería cobalto en RDC y esclavitud infantil; relaciona con impactos ecosistémicos.</p>
    </div>
    <div class="esm-exam-problem">
        <p><strong>Problema 2:</strong> Analiza cómo deforestación Amazonía involucra trabajo forzado; propone soluciones circulares.</p>
    </div>
    <div class="esm-exam-problem">
        <p><strong>Problema 3:</strong> Evalúa rol de CSDDD UE en mitigación esclavitud en supply chains; interpreta efectos en ecosistemas globales.</p>
    </div>

    <h2 class="esm-section-title esm-text-magenta">7. Cierre Metacognitivo</h2>
    <p class="esm-reflection">Reflexiona: ¿Cómo contribuye tu consumo a esclavitud moderna y degradación ecosistémica? ¿Qué acciones personales/promoverías para cadenas éticas? ¿Por qué es clave el nexo humano-ambiental en evaluaciones sostenibles?</p>

</div>

<script>
function updateSf() {
    const cobalt = document.getElementById(\'cobaltSlider\').value * 0.3;
    const seafood = document.getElementById(\'seafoodSlider\').value * 0.2;
    const textile = document.getElementById(\'textileSlider\').value * 0.15;
    const total = (cobalt + seafood + textile).toFixed(1);
    document.getElementById(\'sfResult\').innerHTML = `Huella estimada: ${total} (Alto >5; reduce consumo en riesgos altos)`;
}

function ethicsTips() {
    const out = document.getElementById(\'ethicsOutput\');
    out.innerHTML = "<span class=\'text-success\'>CONSEJOS:</span><br>- Certificaciones: Fair Trade, GOTS.<br>- Apps: Good On You, Slavery Footprint.<br>- Prefiere marcas con trazabilidad blockchain.<br>- Reduce consumo innecesario.";
}

function ansQuiz(option) {
    const fb = document.getElementById(\'quizFeedback\');
    const buttons = document.querySelectorAll(\'.monday-quiz-btn\');
    buttons.forEach(btn => btn.disabled = true);

    if(option === 2) {
        buttons[1].classList.add(\'correct\');
        fb.innerHTML = `
            <div class="monday-feedback">
                ¡Correcto! La pérdida de sustento ambiental aumenta vulnerabilidad a explotación.
            </div>`;
    } else {
        buttons[option-1].style.background = \'rgba(255,0,0,0.4)\';
        fb.innerHTML = `
            <div class="monday-feedback" style="background: linear-gradient(135deg, #ff0000, #800000); box-shadow: 0 0 20px rgba(255, 0, 0, 0.6);">
                Incorrecto. El nexo clave es que la degradación de ecosistemas desplaza comunidades y las hace vulnerables al trabajo forzado.
            </div>`;
    }
}

function showError(id) {
    const div = document.getElementById(`error${id}`);
    div.style.display = div.style.display === \'none\' ? \'block\' : \'none\';
}
</script>',
    'quiz' => 
    array (
      0 => 
      array (
        'pregunta' => 'Forma de esclavitud más común en la industria de la construcción:',
