    'slug' => 'efecto-invernadero-natural-master',
    'titulo' => 'Efecto Invernadero: El Termostato de la Biosfera',
    'contenido' => '
<div class="monday-lesson greenhouse-master">

    <div class="text-center mb-5">
        <h1 class="monday-title">BALANCE RADIATIVO</h1>
        <p class="monday-intro">
            El efecto invernadero natural es el mecanismo esencial que mantiene la temperatura media global en +15°C, permitiendo agua líquida y vida. Sin él, la Tierra tendría -18°C. Los GEI regulan el balance radiativo de la biosfera.
        </p>
    </div>

    <div class="monday-alert">
        <h4 class="text-yellow"><i class="fas fa-bolt"></i> Temperatura Efectiva vs Real</h4>
        <p>Sin atmósfera (cuerpo negro):</p>
        <div class="monday-eq-box">
            \\[ T_e = \\left( \\frac{S(1 - A)}{4\\sigma} \\right)^{1/4} \\approx 255\\, \\text{K} \\, (-18^\\circ\\text{C}) \\]
        </div>
        <p class="mt-3">Real: <strong>288 K (+15°C)</strong> → Diferencia de +33°C gracias a GEI naturales.</p>
    </div>

    <h2 class="monday-section-title">1. Gases de Efecto Invernadero</h2>
    <div class="row mb-5">
        <div class="col-md-8 mx-auto">
            <div class="monday-stats-box">
                <ul class="list-unstyled">
                    <li class="mb-4"><strong class="text-cyan">Vapor de Agua (H₂O):</strong> 60-70% del efecto, retroalimentación positiva.</li>
                    <li class="mb-4"><strong class="text-magenta">CO₂:</strong> Control a largo plazo, permanencia centenaria.</li>
                    <li class="mb-4"><strong class="text-orange">CH₄:</strong> ~28× más potente que CO₂ (100 años).</li>
                    <li class="mb-4"><strong class="text-yellow">N₂O y otros:</strong> Contribuciones menores pero significativas.</li>
                </ul>
            </div>
        </div>
    </div>

    <div class="monday-mini-lab">
        <h4 class="text-orange text-center"><i class="fas fa-flask"></i> Simulador: Impacto de Concentración GEI</h4>
        <p class="text-center mb-4">Ajusta niveles equivalentes de GEI (ppm CO₂ eq) y observa cambio en temperatura global (modelo simplificado).</p>
        <div class="row align-items-center">
            <div class="col-md-6 text-center">
                <label class="text-yellow fs-4">Concentración GEI (ppm eq):</label>
                <input type="range" class="monday-slider" id="geiRange" min="200" max="1200" value="280" oninput="updateSim()">
                <div class="fs-3 mt-3 text-cyan" id="ppmValue">280 ppm (Preindustrial)</div>
            </div>
            <div class="col-md-6 text-center">
                <div id="tempDisplay" class="monday-temp-display text-success">15.0°C</div>
                <p id="tempStatus" class="fs-3 text-success">Clima Estable / Habitable</p>
            </div>
        </div>
    </div>

    <h2 class="monday-section-title">2. El Albedo Planetario</h2>
    <div class="row text-center mb-5">
        <div class="col-md-4"><div class="monday-albedo-card"><h5 class="text-white">Hielo/Nieve</h5><p class="display-5">0.8-0.9</p><small>Alta reflexión</small></div></div>
        <div class="col-md-4"><div class="monday-albedo-card"><h5 class="text-green">Bosques</h5><p class="display-5">0.1-0.2</p><small>Absorción media</small></div></div>
        <div class="col-md-4"><div class="monday-albedo-card"><h5 class="text-blue">Océanos</h5><p class="display-5">0.06</p><small>Baja reflexión</small></div></div>
    </div>

    <h4 class="text-center text-cyan mb-4">Diagrama de Forzamiento Radiativo</h4>
    <div class="monday-svg-container">
        <svg viewBox="0 0 800 500" xmlns="http://www.w3.org/2000/svg">
            <rect width="800" height="500" fill="#000814" />
            <path d="M0 450 Q400 350 800 450" fill="#001f3f" />
            <text x="400" y="480" fill="#00ffff" font-size="24" text-anchor="middle">SUPERFICIE TERRESTRE</text>
            
            <circle cx="400" cy="50" r="40" fill="#ffff00" filter="url(#glow-sun)" />
            <text x="400" y="30" fill="#ffff00" font-size="16" text-anchor="middle">RADIACIÓN SOLAR</text>
            
            <path d="M400 90 L400 400" stroke="#ffff00" stroke-width="4" stroke-dasharray="10,5">
                <animate attributeName="stroke-dashoffset" from="0" to="-20" dur="3s" repeatCount="indefinite" />
            </path>
            <text x="420" y="200" fill="#ffff00" font-size="14">Visible ↓</text>
            
            <path d="M350 400 Q350 300 300 350 M450 400 Q450 300 500 350" stroke="#ff00ff" stroke-width="4">
                <animate attributeName="stroke-dashoffset" from="0" to="20" dur="4s" repeatCount="indefinite" />
            </path>
            <text x="320" y="320" fill="#ff00ff" font-size="14">IR ATRAPADO ↑↓</text>
            
            <defs>
                <filter id="glow-sun"><feGaussianBlur stdDeviation="10" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
            </defs>
        </svg>
    </div>

    <div class="mt-5">
        <div class="monday-quiz-header">
            <div class="monday-quiz-icon">🧠</div>
            <h4 class="monday-quiz-title">Quiz Autoevaluado</h4>
        </div>
        <p class="monday-quiz-question">¿Cuál es la diferencia de temperatura atribuida al efecto invernadero natural?</p>
        <div class="monday-quiz-options">
            <button class="monday-quiz-btn" onclick="ansQuiz(1)">+18°C</button>
            <button class="monday-quiz-btn" onclick="ansQuiz(2)">+33°C</button>
            <button class="monday-quiz-btn" onclick="ansQuiz(3)">-15°C</button>
        </div>
        <div id="quizFeedback"></div>
    </div>

    <h2 class="monday-section-title text-yellow">3. Errores Comunes del Estudiante</h2>
    <ul class="monday-errors-list mx-auto" style="max-width: 800px; list-style:none;">
        <li onclick="showError(1)" class="mb-3">Confundir efecto invernadero natural con antropogénico.</li>
        <div id="error1" style="display:none;" class="alert alert-info">El natural es esencial para la vida; el antropogénico lo intensifica.</div>
        <li onclick="showError(2)" class="mb-3">Pensar que N₂ y O₂ contribuyen al efecto.</li>
        <div id="error2" style="display:none;" class="alert alert-info">Son diatómicos simétricos → no absorben IR.</div>
    </ul>

    <h2 class="monday-section-title text-cyan">4. Conexión con Ecosistemas</h2>
    <p class="text-center fs-4">El efecto invernadero natural regula ciclos biogeoquímicos y biodiversidad. Perturbaciones antropogénicas alteran este balance, evaluable en impactos climáticos sobre ecosistemas.</p>

    <h2 class="monday-section-title text-green">5. Problemas Tipo Examen</h2>
    <div class="monday-exam-problem"><p><strong>1:</strong> Calcula T_e para albedo 0.3 y S=1366 W/m². Explica la diferencia con temperatura real.</p></div>
    <div class="monday-exam-problem"><p><strong>2:</strong> Analiza rol del vapor de agua como retroalimentación.</p></div>

    <h2 class="monday-section-title text-magenta">6. Cierre Metacognitivo</h2>
    <p class="monday-reflection">¿Cómo cambia tu visión del "efecto invernadero" como proceso natural esencial? ¿Qué implicaciones tiene para la regulación climática actual?</p>

</div>

<script>
function updateSim() {
    const val = parseInt(document.getElementById(\'geiRange\').value);
    document.getElementById(\'ppmValue\').innerText = val + " ppm eq";
    
    let temp = 15 + Math.log(val / 280) * 8.5;
    document.getElementById(\'tempDisplay\').innerText = temp.toFixed(1) + "°C";
    
    const disp = document.getElementById(\'tempDisplay\');
    const status = document.getElementById(\'tempStatus\');
    
    if(temp > 18) {
        disp.style.color = "#ff3333";
        status.innerText = "ALERTA: Calentamiento Acelerado";
        status.style.color = "#ff3333";
    } else if(temp < 12) {
        disp.style.color = "#00ffff";
        status.innerText = "Enfriamiento Extremo";
        status.style.color = "#00ffff";
    } else {
        disp.style.color = "#00ff00";
        status.innerText = "Clima Habitable";
        status.style.color = "#00ff00";
    }
}

function ansQuiz(option) {
    const fb = document.getElementById(\'quizFeedback\');
    const btns = document.querySelectorAll(\'.monday-quiz-btn\');
    btns.forEach(b => b.disabled = true);
    
    if(option === 2) {
        btns[1].style.background = \'#00ff00\';
        fb.innerHTML = \'<div class="monday-feedback">¡Correcto! +33°C es la contribución del efecto invernadero natural.</div>\';
    } else {
        btns[option-1].style.background = \'rgba(255,0,0,0.5)\';
        fb.innerHTML = \'<div class="monday-feedback" style="background: linear-gradient(135deg, #ff0000, #800000); box-shadow: 0 0 30px rgba(255,0,0,0.8);">Incorrecto. La diferencia es +33°C.</div>\';
    }
}

function showError(id) {
    const el = document.getElementById(\'error\' + id);
    el.style.display = el.style.display === \'none\' ? \'block\' : \'none\';
}
</script>',
