    'slug' => 'huella-ecologica-efecto-invernadero',
    'titulo' => 'Huella Ecológica y Efecto Invernadero: El Balance Roto',
    'contenido' => '
<div class="monday-lesson footprint-master">

    <div class="text-center mb-5">
        <h1 class="monday-title">HUELLA vs. BIOCAPACIDAD</h1>
        <p class="monday-intro">
            La <strong>Huella Ecológica</strong> mide la demanda humana de recursos bioproductivos (en global hectares, gha). La <strong>Biocapacidad</strong> es la oferta regenerativa del planeta. En 2025, humanidad consume equivalente a ~1.7 Tierras, con Earth Overshoot Day el 24 de julio. El forzamiento antropogénico intensifica el efecto invernadero, reduciendo biocapacidad vía retroalimentaciones.
        </p>
    </div>

    <div class="monday-alert">
        <h4 class="text-green"><i class="fas fa-calculator"></i> Déficit Ecológico</h4>
        <p>Déficit cuando huella supera biocapacidad:</p>
        <div class="monday-eq-box">
            \\[ Def = BC - EF \\]
        </div>
        <p class="mt-3">Global 2025: EF ≈ 2.7 gha/persona | BC ≈ 1.5 gha/persona → Déficit ~1.2 gha/persona (1.7-1.8 planetas).</p>
    </div>

    <h2 class="monday-section-title">1. Earth Overshoot Day 2025</h2>
    <div class="row mb-5">
        <div class="col-md-8 mx-auto">
            <div class="monday-stats-box">
                <p>El 24 de julio de 2025 marcó el Día del Sobregiro Terrestre: humanidad agotó recursos regenerables anuales.</p>
                <ul class="list-unstyled">
                    <li class="mb-4"><strong>Huella de Carbono:</strong> ~60% de huella total (área boscosa para secuestrar CO₂ excedente).</li>
                    <li class="mb-4"><strong>Número de Tierras:</strong> ~1.7-1.75 necesarias para sostener consumo actual.</li>
                    <li class="mb-4"><strong>Retroalimentación:</strong> Calentamiento reduce biocapacidad (pérdida suelos, sequías, incendios).</li>
                </ul>
            </div>
        </div>
    </div>

    <div class="monday-mini-lab">
        <h4 class="text-cyan text-center"><i class="fas fa-globe"></i> Simulador Personal: Tu Overshoot Day</h4>
        <p class="text-center mb-4">Ajusta hábitos y ve impacto en fecha sobregiro (modelo simplificado).</p>
        <div class="row text-center">
            <div class="col-md-3">
                <label class="text-white fs-4">Energía</label>
                <select id="energy" class="form-select monday-select" onchange="calcOvershoot()">
                    <option value="0.8">100% Renovable</option>
                    <option value="1.5" selected>Mix Actual</option>
                    <option value="3">Fósiles Dominante</option>
                </select>
            </div>
            <div class="col-md-3">
                <label class="text-white fs-4">Dieta</label>
                <select id="diet" class="form-select monday-select" onchange="calcOvershoot()">
                    <option value="0.8">Vegana/Local</option>
                    <option value="1.8" selected>Media</option>
                    <option value="3.5">Alta Carne Roja</option>
                </select>
            </div>
            <div class="col-md-3">
                <label class="text-white fs-4">Transporte</label>
                <select id="transport" class="form-select monday-select" onchange="calcOvershoot()">
                    <option value="0.7">Público/Bici</option>
                    <option value="1.5" selected>Coche Medio</option>
                    <option value="3">Avión/Coche Grande</option>
                </select>
            </div>
            <div class="col-md-3">
                <div id="overshootResult" class="monday-overshoot-display text-warning mt-4">24 Jul</div>
                <p id="overshootStatus" class="fs-3 text-warning">Overshoot Global 2025</p>
            </div>
        </div>
    </div>

    <h2 class="monday-section-title text-red">2. Comparación Internacional (gha/persona ~2023-2025)</h2>
    <div class="table-responsive mb-5">
        <table class="table monday-table-dark table-hover">
            <thead class="text-neon-green">
                <tr><th>País</th><th>Huella (gha/persona)</th><th>Planetas si Todos</th></tr>
            </thead>
            <tbody>
                <tr><td>Qatar</td><td>~14.4</td><td>~9</td></tr>
                <tr><td>EE.UU.</td><td>~8.1</td><td>~5</td></tr>
                <tr><td>España</td><td>~4.3</td><td>~2.6</td></tr>
                <tr><td><strong>Promedio Mundial</strong></td><td><strong>~2.7</strong></td><td><strong>~1.7</strong></td></tr>
                <tr><td>India</td><td>~1.2</td><td><0.8</td></tr>
            </tbody>
        </table>
    </div>

    <h4 class="text-center text-green mb-4">Retroalimentación Huella-Forzamiento</h4>
    <div class="monday-svg-container">
        <svg viewBox="0 0 800 450" xmlns="http://www.w3.org/2000/svg">
            <rect width="800" height="450" fill="#000814"/>
            <rect x="100" y="200" width="200" height="150" fill="#228B22" opacity="0.8">
                <animate attributeName="height" values="150;100;150" dur="6s" repeatCount="indefinite"/>
            </rect>
            <text x="200" y="380" fill="#00ff00" font-size="18" text-anchor="middle">BIOCAPACIDAD (Regeneración)</text>

            <rect x="500" y="100" width="200" height="250" fill="#ff3333" opacity="0.8">
                <animate attributeName="height" values="250;300;250" dur="4s" repeatCount="indefinite"/>
                <animate attributeName="y" values="100;50;100" dur="4s" repeatCount="indefinite"/>
            </rect>
            <text x="600" y="380" fill="#ff3333" font-size="18" text-anchor="middle">HUELLA ECOLÓGICA (Demanda)</text>

            <path d="M300 275 Q400 150 500 175" stroke="#ffcc00" stroke-width="5" fill="none" stroke-dasharray="10,5">
                <animate attributeName="stroke-dashoffset" from="100" to="0" dur="5s" repeatCount="indefinite"/>
            </path>
            <text x="400" y="130" fill="#ffcc00" font-size="16" text-anchor="middle">FORZAMIENTO CO₂ → Pérdida BC</text>
        </svg>
    </div>

    <div class="mt-5">
        <div class="monday-quiz-header">
            <div class="monday-quiz-icon">🧠</div>
            <h4 class="monday-quiz-title">Quiz Autoevaluado</h4>
        </div>
        <p class="monday-quiz-question">¿En qué fecha cayó Earth Overshoot Day en 2025?</p>
        <div class="monday-quiz-options">
            <button class="monday-quiz-btn" onclick="ansQuiz(1)">2 de Agosto</button>
            <button class="monday-quiz-btn" onclick="ansQuiz(2)">24 de Julio</button>
            <button class="monday-quiz-btn" onclick="ansQuiz(3)">1 de Diciembre</button>
        </div>
        <div id="quizFeedback"></div>
    </div>

    <h2 class="monday-section-title text-yellow">3. Errores Comunes del Estudiante</h2>
    <ul class="list-unstyled mx-auto" style="max-width:800px;">
        <li onclick="showError(1)" class="mb-3 p-3 bg-dark rounded">Confundir huella ecológica con huella de carbono sola.</li>
        <div id="error1" style="display:none;" class="alert alert-info">Huella total incluye carbono (~60%), cultivos, pastizales, pesca, bosque, área construida.</div>
        <li onclick="showError(2)" class="mb-3 p-3 bg-dark rounded">Pensar que overshoot es reversible automáticamente.</li>
        <div id="error2" style="display:none;" class="alert alert-info">Déficit acumula degradación (pérdida suelos, biodiversidad).</div>
    </ul>

    <h2 class="monday-section-title text-cyan">4. Conexión con Ecosistemas</h2>
    <p class="text-center fs-4">Huella ecológica cuantifica presión antropogénica sobre ciclos biogeoquímicos y servicios ecosistémicos. Forzamiento radiativo antropogénico altera balance, reduciendo biocapacidad y resiliencia ecosistémica.</p>

    <h2 class="monday-section-title text-green">5. Problemas Tipo Examen</h2>
    <div class="monday-exam-problem"><p><strong>1:</strong> Calcula planetas necesarios si todos consumieran como Qatar (~14 gha/persona), asumiendo BC global 1.5 gha.</p></div>
    <div class="monday-exam-problem"><p><strong>2:</strong> Explica retroalimentación entre huella carbono y pérdida biocapacidad.</p></div>
    <div class="monday-exam-problem"><p><strong>3:</strong> Propón medidas para mover Overshoot Day hacia fin año.</p></div>

    <h2 class="monday-section-title text-magenta">6. Cierre Metacognitivo</h2>
    <p class="monday-reflection">¿Cómo contribuye tu huella personal al déficit global? ¿Qué cambios implementarías para reducirla, considerando nexo con forzamiento climático? ¿Por qué es urgente actuar en 2025?</p>

</div>

<script>
function calcOvershoot() {
    const e = parseFloat(document.getElementById(\'energy\').value);
    const d = parseFloat(document.getElementById(\'diet\').value);
    const t = parseFloat(document.getElementById(\'transport\').value);
    const factor = (e + d + t) / 3; // Promedio simplificado
    
    const result = document.getElementById(\'overshootResult\');
    const status = document.getElementById(\'overshootStatus\');
    
    if(factor < 1.2) {
        result.innerText = "Noviembre";
        result.style.color = "#00ff00";
        status.innerText = "Sostenible Personal";
        status.style.color = "#00ff00";
    } else if(factor < 2) {
        result.innerText = "24 Jul";
        result.style.color = "#ff9800";
        status.innerText = "Overshoot Global";
        status.style.color = "#ff9800";
    } else {
        result.innerText = "Abril";
        result.style.color = "#ff3333";
        status.innerText = "Alta Presión";
        status.style.color = "#ff3333";
    }
}

function ansQuiz(option) {
    const fb = document.getElementById(\'quizFeedback\');
    const btns = document.querySelectorAll(\'.monday-quiz-btn\');
    btns.forEach(b => b.disabled = true);
    
    if(option === 2) {
        btns[1].style.background = \'#00ff00\';
        fb.innerHTML = \'<div class="monday-feedback">¡Correcto! Earth Overshoot Day 2025: 24 de julio.</div>\';
    } else {
        btns[option-1].style.background = \'rgba(255,0,0,0.5)\';
        fb.innerHTML = \'<div class="monday-feedback" style="background: linear-gradient(135deg, #ff0000, #800000);">Incorrecto. Fue el 24 de julio de 2025.</div>\';
    }
}

function showError(id) {
    const el = document.getElementById(\'error\' + id);
    el.style.display = el.style.display === \'none\' ? \'block\' : \'none\';
}
</script>',
