    'materia' => 'Ecosistemas',
    'slug' => 'desertificacion-restauracion-sistemas-avanzados',
    'titulo' => 'Desertificación y Restauración: Dinámicas del Suelo, Clima y Resiliencia Ecosistémica',
    'contenido' => '<div class="desertificacion-master">

    <!-- ================= INTRODUCCIÓN ================= -->
    <div class="text-center mb-5">
        <h1 class="monday-title">DESERTIFICACIÓN Y RESTAURACIÓN ECOSISTÉMICA AVANZADA</h1>
        <p class="monday-intro">
            La desertificación no es un proceso natural, sino una degradación inducida por actividades humanas y variabilidad climática.
            Afecta al <strong>40% de la superficie terrestre</strong> y compromete la seguridad alimentaria, hídrica y climática.
            En esta lección analizarás los <em>mecanismos físicos, biológicos y climáticos</em> que la provocan, así como estrategias
            de restauración basadas en evidencia científica.
        </p>
    </div>

    <div class="monday-alert">
        <strong>UNCCD:</strong> degradación persistente de tierras áridas, semiáridas y subhúmedas secas causada por factores humanos y climáticos.
        No implica expansión natural del desierto, sino pérdida de productividad del suelo.
    </div>

    <!-- ================= TEORÍA ================= -->
    <h2 class="monday-section-title">1. Mecanismos de Degradación del Suelo</h2>
    <p>
        La desertificación surge de la interacción entre prácticas humanas y procesos naturales que alteran la estructura,
        fertilidad y estabilidad del suelo.
    </p>

    <div class="row">
        <div class="col-md-7">
            <table class="table monday-table">
                <thead>
                    <tr>
                        <th>Factor</th>
                        <th>Proceso</th>
                        <th>Consecuencia</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td>Sobrepastoreo</td>
                        <td>Compactación y pérdida de cobertura vegetal</td>
                        <td>Erosión eólica severa</td>
                    </tr>
                    <tr>
                        <td>Deforestación</td>
                        <td>Pérdida de raíces estabilizadoras</td>
                        <td>Escorrentía y erosión hídrica</td>
                    </tr>
                    <tr>
                        <td>Riego inadecuado</td>
                        <td>Acumulación de sales</td>
                        <td>Salinización y toxicidad</td>
                    </tr>
                    <tr>
                        <td>Daño al criptobioma</td>
                        <td>Destrucción de costras biológicas</td>
                        <td>Pérdida de nitrógeno y estabilidad</td>
                    </tr>
                </tbody>
            </table>
        </div>

        <div class="col-md-5">
            <div class="monday-eq-box">
                \\[
                A = R \\times K \\times LS \\times C \\times P
                \\]
                <p class="mt-3">
                    <strong>USLE:</strong> los factores <em>C</em> (cobertura) y <em>P</em> (manejo)
                    pueden ser modificados directamente mediante restauración.
                </p>
            </div>
        </div>
    </div>

    <!-- ================= SVG OPTIMIZADO ================= -->
    <h2 class="monday-section-title">2. Visualización Dinámica: Ciclo Degradación–Restauración</h2>

    <div class="monday-svg-container">
        <svg viewBox="0 0 800 420" xmlns="http://www.w3.org/2000/svg">
            <defs>
                <linearGradient id="soilGrad" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stop-color="#a0522d"/>
                    <stop offset="100%" stop-color="#5c3317"/>
                </linearGradient>
            </defs>

            <!-- Suelo -->
            <rect x="0" y="260" width="800" height="160" fill="url(#soilGrad)"/>

            <!-- Vegetación -->
            <g id="plants">
                <circle cx="150" cy="230" r="35" fill="#2ecc71"/>
                <circle cx="350" cy="240" r="30" fill="#27ae60"/>
                <circle cx="550" cy="225" r="40" fill="#2ecc71"/>
                <circle cx="680" cy="240" r="28" fill="#27ae60"/>
            </g>

            <!-- Viento -->
            <path d="M50 180 Q400 120 750 180"
                  stroke="#d2b48c" stroke-width="7" fill="none"
                  stroke-dasharray="18">
                <animate attributeName="stroke-dashoffset"
                         from="0" to="-200"
                         dur="6s" repeatCount="indefinite"/>
            </path>

            <!-- Restauración -->
            <g id="restoreLabel" opacity="0">
                <rect x="300" y="290" width="200" height="70" rx="18" fill="#145a32"/>
                <text x="400" y="335" fill="#eafff4" font-size="22" text-anchor="middle">
                    RESTAURACIÓN
                </text>
            </g>

            <!-- Animaciones -->
            <animate xlink:href="#plants"
                     attributeName="opacity"
                     values="1;0.25;0.15;0.4;1"
                     dur="10s" repeatCount="indefinite"/>

            <animate xlink:href="#restoreLabel"
                     attributeName="opacity"
                     values="0;0;1;1;0"
                     begin="5s" dur="10s"
                     repeatCount="indefinite"/>
        </svg>

        <p class="small mt-3 text-center">
            La pérdida de vegetación incrementa la erosión; la restauración interrumpe el ciclo.
        </p>
    </div>

    <!-- ================= SIMULADOR 1 ================= -->
    <h2 class="monday-section-title">3. Simulador 1: Erosión del Suelo (USLE)</h2>

    <div class="monday-simulator">
        <label>Cobertura vegetal (C)</label>
        <input type="range" id="cSlider" min="0" max="1" step="0.05" value="0.6">

        <label>Prácticas de manejo (P)</label>
        <input type="range" id="pSlider" min="0" max="1" step="0.05" value="0.7">

        <div id="usleOutput"></div>
    </div>

    <!-- ================= SIMULADOR 2 ================= -->
    <h2 class="monday-section-title">4. Simulador 2: Albedo – Clima Local</h2>

    <div class="monday-simulator">
        <label>Cobertura vegetal (%)</label>
        <input type="range" id="vegSlider" min="0" max="100" step="5" value="60">

        <label>Albedo superficial</label>
        <input type="range" id="albSlider" min="0.1" max="0.5" step="0.02" value="0.25">

        <div id="albedoOutput"></div>
    </div>

    <!-- ================= QUIZ ================= -->
    <h2 class="monday-section-title">5. Quiz de Comprensión</h2>

    <p><strong>¿Por qué la pérdida de vegetación acelera la desertificación?</strong></p>
    <div class="d-flex flex-wrap justify-content-center">
        <button class="monday-quiz-btn" onclick="quiz(1)">Reduce el albedo</button>
        <button class="monday-quiz-btn" onclick="quiz(2)">Aumenta erosión y retroalimentación climática</button>
        <button class="monday-quiz-btn" onclick="quiz(3)">Incrementa la fertilidad</button>
    </div>
    <div id="quizFeedback"></div>

    <!-- ================= ERRORES ================= -->
    <h2 class="monday-section-title">6. Errores Comunes del Estudiante</h2>

    <div class="error-item" onclick="toggleError(1)">Confundir desertificación con sequía</div>
    <div id="error1" class="error-detail">La sequía es temporal; la desertificación implica degradación estructural del suelo.</div>

    <div class="error-item" onclick="toggleError(2)">Ignorar el papel del albedo</div>
    <div id="error2" class="error-detail">El aumento del albedo reduce convección y precipitación local.</div>

    <!-- ================= CONEXIÓN ================= -->
    <h2 class="monday-section-title">7. Conexión con Ecosistemas</h2>
    <p>
        Tema evaluable: biomas áridos, ciclos del nitrógeno, servicios ecosistémicos,
        cambio climático y resiliencia ambiental.
    </p>

    <!-- ================= EXAMEN ================= -->
    <h2 class="monday-section-title">8. Problemas Tipo Examen</h2>
    <div class="monday-exam-problem">Explica cómo la restauración vegetal modifica los factores C y P de la USLE.</div>
    <div class="monday-exam-problem">Relaciona albedo, precipitación y desertificación en un ecosistema árido.</div>

    <!-- ================= METACOGNICIÓN ================= -->
    <h2 class="monday-section-title">9. Cierre Metacognitivo</h2>
    <p class="monday-reflection">
        ¿Qué decisiones humanas aceleran la desertificación en tu región?
        ¿Cómo podría la restauración cambiar el clima local a largo plazo?
    </p>

</div>

<script>
/* ===== SIMULADOR USLE ===== */
function updateUSLE() {
    const C = parseFloat(document.getElementById(\'cSlider\').value);
    const P = parseFloat(document.getElementById(\'pSlider\').value);
    const A = 120 * 0.25 * 1.5 * C * P;

    document.getElementById(\'usleOutput\').innerHTML =
        \'<strong>Erosión:</strong> \' + A.toFixed(2) + \' t/ha/año<br>\' +
        \'<strong>Riesgo:</strong> \' + (A > 15 ? \'ALTO\' : \'MODERADO\');
}

/* ===== SIMULADOR ALBEDO ===== */
function updateAlbedo() {
    const veg = document.getElementById(\'vegSlider\').value;
    const alb = document.getElementById(\'albSlider\').value;
    const temp = (1 - alb) * 35;
    const rain = veg * 0.4;

    document.getElementById(\'albedoOutput\').innerHTML =
        `<strong>Temperatura superficial:</strong> ${temp.toFixed(1)} °C<br>
         <strong>Potencial de precipitación:</strong> ${rain.toFixed(1)} %`;
}

/* ===== QUIZ ===== */
function quiz(opt) {
    document.getElementById(\'quizFeedback\').innerHTML =
        opt === 2
        ? \'<div class="monday-feedback correct">Correcto: erosión + retroalimentación climática.</div>\'
        : \'<div class="monday-feedback error">Incorrecto. Revisa mecanismos de degradación.</div>\';
}

/* ===== ERRORES ===== */
function toggleError(id) {
    const el = document.getElementById(\'error\'+id);
    el.style.display = el.style.display === \'block\' ? \'none\' : \'block\';
}

/* INIT */
document.addEventListener(\'DOMContentLoaded\', () => {
    updateUSLE();
    updateAlbedo();
    document.getElementById(\'cSlider\').oninput = updateUSLE;
    document.getElementById(\'pSlider\').oninput = updateUSLE;
    document.getElementById(\'vegSlider\').oninput = updateAlbedo;
    document.getElementById(\'albSlider\').oninput = updateAlbedo;
});
</script>',
