  array (
    'materia' => 'Ecosistemas',
    'slug' => 'deforestacion-global-y-clima-avanzado',
    'titulo' => 'Deforestación: El Colapso de los Sumideros de Carbono',
    'contenido' => '<div class="deforestacion-master">

    <!-- ================= INTRODUCCIÓN ================= -->
    <div class="text-center mb-5">
        <h1 class="def-title">DEFORESTACIÓN Y COLAPSO CLIMÁTICO GLOBAL</h1>
        <p class="def-intro">
            La deforestación representa la pérdida de los sistemas más eficientes de regulación climática del planeta.
            Los bosques no solo almacenan carbono: controlan el ciclo del agua, estabilizan suelos y sostienen la biodiversidad.
            Su degradación transforma sumideros en <strong>emisores netos de CO₂</strong>.
        </p>
    </div>

    <!-- ================= ESTADO GLOBAL ================= -->
    <h2 class="def-section">1. Estado de los Bosques Globales (2025)</h2>
    <p>
        Actualmente se pierden cerca de <strong>13 millones de hectáreas de bosque al año</strong>.
        Esta pérdida tiene impactos acumulativos sobre el clima, los servicios ecosistémicos y la estabilidad socioeconómica.
    </p>

    <div class="row">
        <div class="col-md-7">
            <ul class="def-list">
                <li><strong>70% – Ganadería y forraje:</strong> conversión directa a pastizales y soja.</li>
                <li><strong>20% – Palma aceitera y caucho:</strong> destrucción de turberas ricas en carbono.</li>
                <li><strong>10% – Minería e infraestructura:</strong> fragmentación irreversible del paisaje.</li>
            </ul>
        </div>
        <div class="col-md-5">
            <div class="def-alert">
                <strong>Punto de no retorno amazónico</strong>
                <p>
                    La Amazonía recicla hasta el 50% de su precipitación.
                    Superar el <strong>20–25%</strong> de deforestación rompe el sistema hidrológico,
                    iniciando un proceso de <strong>sabanización irreversible</strong>.
                </p>
                <small>Estado actual: ~18.2% deforestado</small>
            </div>
        </div>
    </div>

    <!-- ================= BOMBA BIÓTICA ================= -->
    <h2 class="def-section">2. Bomba Biótica y Ríos Voladores</h2>
    <p>
        Los bosques tropicales funcionan como una bomba atmosférica.
        Mediante la evapotranspiración, los árboles liberan enormes volúmenes de vapor de agua,
        generando flujos de humedad conocidos como <strong>ríos voladores</strong>.
    </p>

    <!-- ================= CICLO DEL CARBONO ================= -->
    <h2 class="def-section">3. Termodinámica del Carbono Forestal</h2>
    <p>
        La biomasa forestal representa carbono almacenado en un estado de baja entropía.
        La deforestación oxida rápidamente este carbono, liberándolo a la atmósfera.
    </p>

    <div class="def-eq">
        $$C_{stock} = A \\times \\rho_{biomasa} \\times f_{carbono}$$
        <p class="small">
            <strong>A:</strong> área (ha) ·
            <strong>ρ:</strong> densidad (t/ha) ·
            <strong>f:</strong> fracción de carbono (~0.50)
        </p>
        <p class="small"><em>Las turberas tropicales almacenan hasta 10× más carbono por hectárea.</em></p>
    </div>

    <!-- ================= SVG ================= -->
    <h2 class="def-section">4. Visualización: De Sumidero a Emisor</h2>

    <div class="def-svg">
        <svg viewBox="0 0 700 320" xmlns="http://www.w3.org/2000/svg">
            <rect x="0" y="220" width="700" height="100" fill="#5b3a1e"/>
            
            <g id="forest">
                <circle cx="120" cy="200" r="35" fill="#2ecc71"/>
                <circle cx="200" cy="190" r="45" fill="#27ae60"/>
                <circle cx="300" cy="205" r="30" fill="#2ecc71"/>
            </g>

            <animate xlink:href="#forest"
                attributeName="opacity"
                values="1;0.3;0.1;0.3;1"
                dur="10s"
                repeatCount="indefinite" />

            <g id="co2">
                <circle cx="450" cy="200" r="8" fill="#ff5733">
                    <animate attributeName="cy" from="200" to="40" dur="2s" repeatCount="indefinite"/>
                </circle>
                <circle cx="480" cy="210" r="12" fill="#ff5733" opacity="0.6">
                    <animate attributeName="cy" from="210" to="60" dur="3s" repeatCount="indefinite"/>
                </circle>
            </g>

            <text x="350" y="40" text-anchor="middle" fill="#ffcc00" font-size="18">
                COLAPSO DEL SUMIDERO DE CARBONO
            </text>
        </svg>
    </div>

    <!-- ================= SIMULADOR ================= -->
    <h2 class="def-section">5. Simulador: Pérdida de Carbono</h2>

    <div class="def-sim">
        <label>Área deforestada (ha)</label>
        <input type="range" id="areaSlider" min="10" max="1000" step="10" value="200">

        <label>Densidad biomasa (t/ha)</label>
        <input type="range" id="densSlider" min="50" max="300" step="10" value="150">

        <div id="carbonOutput"></div>
    </div>

    <!-- ================= QUIZ ================= -->
    <h2 class="def-section">6. Quiz de Evaluación</h2>
    <p><strong>¿Por qué la deforestación convierte al bosque en emisor neto?</strong></p>

    <button class="def-btn" onclick="quizDef(1)">Porque reduce la biodiversidad</button>
    <button class="def-btn" onclick="quizDef(2)">Porque oxida el carbono almacenado</button>
    <button class="def-btn" onclick="quizDef(3)">Porque enfría el clima</button>

    <div id="quizDefFeedback"></div>

    <!-- ================= ERRORES ================= -->
    <h2 class="def-section">7. Errores Comunes del Estudiante</h2>

    <div class="def-error" onclick="toggleDef(1)">Confundir deforestación con reforestación neta</div>
    <div id="defErr1" class="def-error-detail">
        Plantar árboles jóvenes no compensa la pérdida de bosques maduros en escalas climáticas.
    </div>

    <div class="def-error" onclick="toggleDef(2)">Ignorar el papel del agua</div>
    <div id="defErr2" class="def-error-detail">
        La deforestación altera precipitación regional, no solo el CO₂.
    </div>

    <!-- ================= EXAMEN ================= -->
    <h2 class="def-section">8. Problemas Tipo Examen</h2>
    <div class="def-exam">Explica el concepto de bomba biótica y su relación con la Amazonía.</div>
    <div class="def-exam">Analiza por qué REDD+ enfrenta desafíos de gobernanza.</div>

    <!-- ================= METACOGNICIÓN ================= -->
    <h2 class="def-section">9. Cierre Metacognitivo</h2>
    <p class="def-reflection">
        ¿Puede la economía global desacoplarse de la deforestación?
        ¿Qué rol juega el consumo individual en este proceso?
    </p>

</div>

<script>
function updateCarbon() {
    var A = document.getElementById(\'areaSlider\').value;
    var D = document.getElementById(\'densSlider\').value;
    var C = A * D * 0.5;
    document.getElementById(\'carbonOutput\').innerHTML =
        \'<strong>Carbono liberado:</strong> \' + C.toFixed(0) + \' toneladas\';
}

function quizDef(opt) {
    document.getElementById(\'quizDefFeedback\').innerHTML =
        opt === 2
        ? \'<div class="def-ok">Correcto: oxidación del carbono almacenado.</div>\'
        : \'<div class="def-bad">Incorrecto. Revisa el ciclo del carbono.</div>\';
}

function toggleDef(id) {
    var el = document.getElementById(\'defErr\' + id);
    el.style.display = el.style.display === \'block\' ? \'none\' : \'block\';
}

document.addEventListener(\'DOMContentLoaded\', function () {
    updateCarbon();
    document.getElementById(\'areaSlider\').oninput = updateCarbon;
    document.getElementById(\'densSlider\').oninput = updateCarbon;
});
</script>',
