    'contenido' => '<div class="leccion-sucesion">

<!-- ================= 1. INTRODUCCIÓN CONCEPTUAL ================= -->
<div class="concepto-maestro">
    <strong>🌱 CONCEPTO MAESTRO:</strong>  
    La sucesión primaria describe la <strong>emergencia de complejidad ecológica</strong> en sistemas sin vida previa ni suelo.
    Es un proceso termodinámico de reducción local de entropía impulsado por energía solar.
</div>

<h2 class="text-primary mt-4">Del Caos al Orden: La Construcción de Ecosistemas</h2>
<p>La sucesión ecológica es el proceso ordenado de cambio en la estructura de una comunidad a lo largo del tiempo. 
La <strong>sucesión primaria</strong> ocurre en lugares donde no existe suelo previo: rocas recién expuestas, lava volcánica, 
retroceso de glaciares o dunas de arena recién formadas.</p>

<div class="alert alert-info">
    <strong>📌 Ejemplo del mundo real:</strong> La isla de Surtsey, surgida en 1963 por erupción volcánica frente a Islandia, 
    es un laboratorio natural de sucesión primaria donde se ha documentado cada etapa desde roca desnuda hasta ecosistema complejo.
</div>

<!-- ================= 2. DESARROLLO TEÓRICO ================= -->
<h3 class="text-primary mt-4">2.1 Colonizadores del Vacío: Biología Extrema</h3>
<p>Los primeros organismos no compiten: <strong>crean las condiciones para la vida futura</strong>. 
Son ingenieros de ecosistemas que transforman el sustrato abiótico.</p>

<div class="row mt-3">
    <div class="col-md-6">
        <div class="card h-100">
            <div class="card-body">
                <h5 class="card-title">🧫 Organismos Pioneros</h5>
                <ul class="list-group list-group-flush">
                    <li class="list-group-item"><strong>Líquenes:</strong> Simbiosis alga-hongo. Meteorización química + fijación de carbono.</li>
                    <li class="list-group-item"><strong>Cianobacterias:</strong> Fijan N₂ → NH₃ (base del ciclo del nitrógeno).</li>
                    <li class="list-group-item"><strong>Musgos:</strong> Retención hídrica y acumulación de detritos orgánicos.</li>
                    <li class="list-group-item"><strong>Helechos:</strong> Primeros en desarrollar sistemas vasculares complejos.</li>
                </ul>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card h-100">
            <div class="card-body">
                <h5 class="card-title">⚗️ Procesos Biogeoquímicos Iniciales</h5>
                <div class="text-center p-3 bg-light rounded">
                    <h6>Meteorización Química</h6>
                    <p class="mb-2">$$CaCO_3 + 2H^+ \\rightarrow Ca^{2+} + CO_2 + H_2O$$</p>
                    <small class="text-muted">Los ácidos orgánicos (líquenes) aceleran la pedogénesis 1000x</small>
                    
                    <hr class="my-3">
                    
                    <h6>Fijación de Nitrógeno</h6>
                    <p class="mb-2">$$N_2 + 8H^+ + 8e^- \\rightarrow 2NH_3 + H_2$$</p>
                    <small class="text-muted">Catalizado por nitrogenasa (cianobacterias)</small>
                </div>
            </div>
        </div>
    </div>
</div>

<!-- ================= 3. VISUALIZACIÓN INTERACTIVA ================= -->
<h3 class="text-primary mt-5">3. Evolución Temporal del Ecosistema</h3>

<div class="svg-animado">
<svg id="svgSucesion" viewBox="0 0 800 400" xmlns="http://www.w3.org/2000/svg" style="width: 100%; height: auto; background: #0d47a1;">

<!-- Leyenda animada -->
<rect x="20" y="20" width="760" height="360" rx="10" fill="rgba(255,255,255,0.1)" stroke="#fff" stroke-width="2"/>

<!-- Suelo en evolución -->
<rect id="sueloBase" x="50" y="320" width="700" height="0" fill="#5d4037">
    <animate attributeName="height" begin="0s" dur="8s" fill="freeze" values="0;0;0;20;40;60;80"/>
    <animate attributeName="y" begin="0s" dur="8s" fill="freeze" values="320;320;320;300;280;260;240"/>
</rect>

<!-- Capas de suelo -->
<rect id="sueloHumus" x="50" y="360" width="700" height="0" fill="#3e2723" opacity="0">
    <animate attributeName="height" begin="4s" dur="4s" fill="freeze" from="0" to="40"/>
    <animate attributeName="opacity" begin="4s" dur="1s" fill="freeze" from="0" to="1"/>
</rect>

<!-- Etapa 1: Rocas (0-20 años) -->
<g id="etapaRocas" opacity="1">
    <rect x="100" y="300" width="40" height="20" fill="#78909c" rx="5"/>
    <rect x="180" y="280" width="60" height="40" fill="#78909c" rx="5"/>
    <rect x="300" y="290" width="50" height="30" fill="#78909c" rx="5"/>
    <rect x="450" y="310" width="70" height="10" fill="#78909c" rx="5"/>
    <animate attributeName="opacity" begin="0s" dur="1s" fill="freeze" values="1;0.5;0;0;0;0;0"/>
</g>

<!-- Etapa 2: Líquenes (20-50 años) -->
<g id="etapaLiquenes" opacity="0">
    <circle cx="120" cy="280" r="8" fill="#b0bec5"/>
    <circle cx="200" cy="260" r="6" fill="#b0bec5"/>
    <circle cx="320" cy="270" r="10" fill="#b0bec5"/>
    <circle cx="480" cy="290" r="7" fill="#b0bec5"/>
    <animate attributeName="opacity" begin="1s" dur="1s" fill="freeze" values="0;1;0.8;0.3;0;0;0"/>
</g>

<!-- Etapa 3: Musgos y herbáceas (50-100 años) -->
<g id="etapaMusgos" opacity="0">
    <rect x="150" y="250" width="30" height="30" fill="#66bb6a" rx="5"/>
    <rect x="250" y="240" width="40" height="40" fill="#66bb6a" rx="5"/>
    <rect x="400" y="260" width="35" height="35" fill="#66bb6a" rx="5"/>
    <animate attributeName="opacity" begin="2s" dur="1s" fill="freeze" values="0;0;1;0.6;0.2;0;0"/>
</g>

<!-- Etapa 4: Arbustos (100-200 años) -->
<g id="etapaArbustos" opacity="0">
    <path d="M200 200 L220 150 L240 200 Z" fill="#2e7d32"/>
    <path d="M350 210 L370 160 L390 210 Z" fill="#2e7d32"/>
    <path d="M500 220 L520 170 L540 220 Z" fill="#2e7d32"/>
    <animate attributeName="opacity" begin="3s" dur="1s" fill="freeze" values="0;0;0;1;0.7;0.3;0"/>
</g>

<!-- Etapa 5: Bosque joven (200-300 años) -->
<g id="etapaBosqueJoven" opacity="0">
    <rect x="250" y="180" width="15" height="40" fill="#5d4037"/>
    <circle cx="257" cy="160" r="25" fill="#1b5e20"/>
    
    <rect x="450" y="190" width="15" height="40" fill="#5d4037"/>
    <circle cx="457" cy="170" r="28" fill="#1b5e20"/>
    <animate attributeName="opacity" begin="4s" dur="1s" fill="freeze" values="0;0;0;0;1;0.8;0.4"/>
</g>

<!-- Etapa 6: Bosque maduro (300-500+ años) -->
<g id="etapaBosqueMaduro" opacity="0">
    <rect x="150" y="150" width="20" height="60" fill="#3e2723"/>
    <circle cx="160" cy="120" r="35" fill="#004d40"/>
    
    <rect x="350" y="130" width="22" height="70" fill="#3e2723"/>
    <circle cx="361" cy="100" r="40" fill="#004d40"/>
    
    <rect x="550" y="140" width="20" height="60" fill="#3e2723"/>
    <circle cx="560" cy="110" r="38" fill="#004d40"/>
    <animate attributeName="opacity" begin="5s" dur="2s" fill="freeze" values="0;0;0;0;0;1;1"/>
</g>

<!-- Texto dinámico -->
<text id="textoTiempo" x="400" y="50" fill="#fff" font-size="24" text-anchor="middle" font-weight="bold">
    AÑO 0: ROCA DESNUDA
</text>

<!-- Escala de tiempo -->
<line x1="50" x2="750" y1="380" y2="380" stroke="#fff" stroke-width="2"/>
