<!-- ================= 4.1 SIMULADOR 1: CRONOSECUENCIA ================= -->
<h3 class="text-primary mt-5">4.1 🧪 Simulador: Cronosecuencia Ecológica</h3>

<div class="card-simulador border-success">
    <div class="card-header-simulador bg-success text-white">
        🕰️ Evolución Temporal del Ecosistema
    </div>
    <div class="card-body-simulador">
        <p>Explora cómo cambian los parámetros ecológicos a lo largo de la sucesión:</p>
        
        <div class="d-flex flex-wrap gap-2 mb-4">
            <button class="boton-etapa" onclick="mostrarEtapa(0)">Año 0: Roca</button>
            <button class="boton-etapa" onclick="mostrarEtapa(20)">Año 20: Pioneras</button>
            <button class="boton-etapa" onclick="mostrarEtapa(50)">Año 50: Herbáceas</button>
            <button class="boton-etapa" onclick="mostrarEtapa(100)">Año 100: Arbustos</button>
            <button class="boton-etapa" onclick="mostrarEtapa(200)">Año 200: Bosque joven</button>
            <button class="boton-etapa" onclick="mostrarEtapa(500)">Año 500+: Clímax</button>
        </div>
        
        <div id="resultadoEtapa" class="resultado-simulador">
            <em>Selecciona una etapa para ver las características ecológicas...</em>
        </div>
        
        <div id="detallesEtapa" class="mt-4 p-3 bg-white border rounded" style="display: none;">
            <h6>📊 Parámetros medibles:</h6>
            <div class="row mt-2">
                <div class="col-md-4">
                    <div class="p-2 border rounded">
                        <strong>Biomasa:</strong> <span id="biomasa">--</span> g/m²
                    </div>
                </div>
                <div class="col-md-4">
                    <div class="p-2 border rounded">
                        <strong>Diversidad:</strong> <span id="diversidad">--</span> especies
                    </div>
                </div>
                <div class="col-md-4">
                    <div class="p-2 border rounded">
                        <strong>Prof. suelo:</strong> <span id="suelo">--</span> cm
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

<!-- ================= 4.2 SIMULADOR 2: ALBEDO Y MICROCLIMA ================= -->
<h3 class="text-primary mt-5">4.2 🌡️ Simulador: Albedo y Microclima</h3>

<div class="card-simulador border-info">
    <div class="card-header-simulador bg-info text-white">
        🌍 Impacto de la Cobertura Vegetal en el Clima Local
    </div>
    <div class="card-body-simulador">
        <p>El <strong>albedo</strong> es el porcentaje de radiación solar que una superficie refleja. 
        La vegetación modifica el albedo y crea microclimas.</p>
        
        <div class="controles-simulador">
            <div class="slider-container">
                <div class="slider-etiqueta">
                    <span>Cobertura vegetal</span>
                    <span id="valorCobertura">10%</span>
                </div>
                <input type="range" min="0" max="100" value="10" class="form-range" id="coberturaSlider" oninput="actualizarMicroclima()">
            </div>
            
            <div class="slider-container">
                <div class="slider-etiqueta">
                    <span>Humedad del suelo</span>
                    <span id="valorHumedad">5%</span>
                </div>
                <input type="range" min="0" max="100" value="5" class="form-range" id="humedadSlider" oninput="actualizarMicroclima()">
            </div>
        </div>
        
        <div id="resultadoMicroclima" class="resultado-simulador">
            Ajusta los parámetros para ver los cambios en el microclima...
        </div>
        
        <div class="mt-4">
            <canvas id="graficoMicroclima" width="800" height="200"></canvas>
        </div>
    </div>
</div>

<!-- ================= 4.3 QUIZ AUTOEVALUADO ================= -->
<h3 class="text-primary mt-5">4.3 🧠 Quiz de Comprensión</h3>

<div class="quiz-pregunta">
    <p><strong>Pregunta 1:</strong> ¿Cuál de estos es un organismo pionero TÍPICO en la sucesión primaria?</p>
    
