<!-- ================= 5. ERRORES COMUNES ================= -->
<h3 class="text-primary mt-5">5. ⚠️ Errores Comunes del Estudiante</h3>

<div class="border p-4 rounded bg-warning bg-opacity-10">
    <p><strong>¡Atención! Estos errores son frecuentes en exámenes:</strong></p>
    
    <div class="error-comun" onclick="mostrarError(1)">
        <strong>Error 1:</strong> Confundir sucesión primaria con secundaria
    </div>
    <div class="error-detalle" id="detalleError1">
        <strong>Corrección:</strong> La sucesión <strong>primaria</strong> parte de sustrato sin vida ni suelo (rocas, lava). 
        La <strong>secundaria</strong> ocurre donde hubo comunidad previa (después de incendio, tala).
    </div>
    
    <div class="error-comun" onclick="mostrarError(2)">
        <strong>Error 2:</strong> Creer que los líquenes son una sola especie
    </div>
    <div class="error-detalle" id="detalleError2">
        <strong>Corrección:</strong> Los líquenes son <strong>simbiosis</strong> entre hongo (micobionte) y alga o cianobacteria (fotobionte). 
        No son un solo organismo sino una asociación mutualista.
    </div>
    
    <div class="error-comun" onclick="mostrarError(3)">
        <strong>Error 3:</strong> Suponer que el clímax es permanente e inmutable
    </div>
    <div class="error-detalle" id="detalleError3">
        <strong>Corrección:</strong> El "clímax" es dinámico (clímax pulsante). Cambios climáticos, perturbaciones 
        naturales y evolución hacen que los ecosistemas nunca sean completamente estables.
    </div>
</div>

