<!-- ================= JAVASCRIPT COMPLETO ================= -->
<script>
// ========== ANIMACIÓN SVG ==========
function animarSucesion() {
    const svg = document.getElementById(\'svgSucesion\');
    const elementos = [
        \'etapaRocas\', \'etapaLiquenes\', \'etapaMusgos\', 
        \'etapaArbustos\', \'etapaBosqueJoven\', \'etapaBosqueMaduro\',
        \'sueloBase\', \'sueloHumus\'
    ];
    
    const textos = [
        "AÑO 0: ROCA DESNUDA",
        "AÑO 20: LÍQUENES PIONEROS", 
        "AÑO 50: MUSGOS Y HERBÁCEAS",
        "AÑO 100: COMUNIDAD DE ARBUSTOS",
        "AÑO 200: BOSQUE JOVEN",
        "AÑO 500+: BOSQUE MADURO (CLÍMAX)"
    ];
    
    const textoElem = document.getElementById(\'textoTiempo\');
    let etapa = 0;
    
    // Reiniciar animaciones
    elementos.forEach(id => {
        const elem = document.getElementById(id);
        if(elem) {
            elem.getElementsByTagName(\'animate\').forEach(anim => {
                anim.beginElement();
            });
        }
    });
    
    // Actualizar texto secuencialmente
    const intervalo = setInterval(() => {
        if(etapa < textos.length) {
            textoElem.textContent = textos[etapa];
            etapa++;
        } else {
            clearInterval(intervalo);
        }
    }, 1300);
}

function reiniciarAnimacion() {
    const svg = document.getElementById(\'svgSucesion\');
    const textoElem = document.getElementById(\'textoTiempo\');
    textoElem.textContent = "AÑO 0: ROCA DESNUDA";
    
    // Restaurar opacidades iniciales
    document.getElementById(\'etapaRocas\').setAttribute(\'opacity\', \'1\');
    document.getElementById(\'etapaLiquenes\').setAttribute(\'opacity\', \'0\');
    document.getElementById(\'etapaMusgos\').setAttribute(\'opacity\', \'0\');
    document.getElementById(\'etapaArbustos\').setAttribute(\'opacity\', \'0\');
    document.getElementById(\'etapaBosqueJoven\').setAttribute(\'opacity\', \'0\');
    document.getElementById(\'etapaBosqueMaduro\').setAttribute(\'opacity\', \'0\');
    document.getElementById(\'sueloBase\').setAttribute(\'height\', \'0\');
    document.getElementById(\'sueloBase\').setAttribute(\'y\', \'320\');
    document.getElementById(\'sueloHumus\').setAttribute(\'height\', \'0\');
    document.getElementById(\'sueloHumus\').setAttribute(\'opacity\', \'0\');
}

// ========== SIMULADOR 1: CRONOSECUENCIA ==========
function mostrarEtapa(anios) {
    const datos = {
        0: {
            nombre: "Roca desnuda",
            descripcion: "🌑 Sustrato inicial: roca madre expuesta, sin suelo ni materia orgánica. pH extremo (8-9), sin nutrientes disponibles. Temperatura superficial muy variable.",
            biomasa: "0",
            diversidad: "0-1",
            suelo: "0"
        },
        20: {
            nombre: "Comunidad pionera",
            descripcion: "🪨 Líquenes crustáceos dominan. Comienza meteorización biológica. Primeros 2mm de \'suelo\' (regolito + materia orgánica). pH 7.5-8.0.",
            biomasa: "5-20",
            diversidad: "2-5",
            suelo: "0.2-0.5"
        },
        50: {
            nombre: "Etapa herbácea",
            descripcion: "🌱 Musgos, hepáticas y algunas herbáceas anuales. Acumulación de hojarasca. Suelo incipiente (5-10cm). Primeros artrópodos del suelo. pH 6.5-7.5.",
            biomasa: "100-300",
            diversidad: "10-20",
            suelo: "5-10"
        },
        100: {
            nombre: "Comunidad de arbustos",
            descripcion: "🌿 Arbustos leñosos (salix, rubus) y herbáceas perennes. Suelo desarrollado (20-30cm) con horizonte A. Aparecen lombrices. pH 6.0-7.0.",
            biomasa: "800-1500",
            diversidad: "25-40",
            suelo: "20-30"
        },
        200: {
            nombre: "Bosque joven",
            descripcion: "🌳 Árboles pioneros (álamos, abedules) forman dosel abierto. Suelo con horizontes A y B. Comunidad animal diversificada. pH 5.5-6.5.",
            biomasa: "5000-10000",
            diversidad: "50-80",
            suelo: "40-60"
        },
        500: {
            nombre: "Bosque maduro (clímax)",
            descripcion: "🌲🌳 Bosque complejo con estratificación: dosel, sotobosque, herbáceas. Especies tolerantes a la sombra reemplazan pioneras. Suelo profundo (>1m) con todos los horizontes. Alta biodiversidad y estabilidad. pH 5.0-6.0.",
            biomasa: "20000-40000",
            diversidad: "100-200+",
            suelo: "80-120"
        }
    };
    
    const etapa = datos[anios];
    const resultado = document.getElementById(\'resultadoEtapa\');
    const detalles = document.getElementById(\'detallesEtapa\');
    
    resultado.innerHTML = `<h5>${etapa.nombre} (${anios} años)</h5><p>${etapa.descripcion}</p>`;
    
    document.getElementById(\'biomasa\').textContent = etapa.biomasa;
    document.getElementById(\'diversidad\').textContent = etapa.diversidad;
    document.getElementById(\'suelo\').textContent = etapa.suelo;
    
    detalles.style.display = \'block\';
    
    // Actualizar botones activos
    document.querySelectorAll(\'.boton-etapa\').forEach(boton => {
        boton.classList.remove(\'activo\');
    });
    event.target.classList.add(\'activo\');
}

// ========== SIMULADOR 2: MICROCLIMA ==========
let graficoMicroclima = null;

function actualizarMicroclima() {
    const cobertura = parseInt(document.getElementById(\'coberturaSlider\').value);
    const humedad = parseInt(document.getElementById(\'humedadSlider\').value);
    
    document.getElementById(\'valorCobertura\').textContent = cobertura + \'%\';
    document.getElementById(\'valorHumedad\').textContent = humedad + \'%\';
    
    // Cálculos ecológicos
    const albedo = (0.35 - (cobertura/100)*0.2).toFixed(2);
    const tempSuperficial = (30 - cobertura*0.05 - humedad*0.02).toFixed(1);
    const evapotranspiracion = (humedad * 0.8 + cobertura * 0.5).toFixed(0);
    const carbonoSecuestrado = (cobertura * 2.5).toFixed(0);
    
    const resultado = document.getElementById(\'resultadoMicroclima\');
    resultado.innerHTML = `
        <div class="row text-center">
            <div class="col-md-3">
                <div class="p-2 border rounded bg-light">
                    <strong>Albedo</strong><br>
                    <span class="h5">${albedo}</span>
                </div>
            </div>
            <div class="col-md-3">
                <div class="p-2 border rounded bg-light">
                    <strong>Temperatura</strong><br>
                    <span class="h5">${tempSuperficial}°C</span>
                </div>
            </div>
            <div class="col-md-3">
                <div class="p-2 border rounded bg-light">
                    <strong>Evapotranspiración</strong><br>
                    <span class="h5">${evapotranspiracion} mm/día</span>
                </div>
            </div>
            <div class="col-md-3">
                <div class="p-2 border rounded bg-light">
                    <strong>Carbono secuestrado</strong><br>
                    <span class="h5">${carbonoSecuestrado} t/ha</span>
                </div>
            </div>
        </div>
        <p class="mt-3"><em>Más cobertura vegetal = menor albedo = menos calor reflejado = mayor absorción = microclima más estable</em></p>
    `;
    
    actualizarGraficoMicroclima(cobertura, humedad);
}

function actualizarGraficoMicroclima(cobertura, humedad) {
    const canvas = document.getElementById(\'graficoMicroclima\');
    const ctx = canvas.getContext(\'2d\');
    
    // Limpiar canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    
    // Datos para el gráfico
    const datos = [];
    for(let i = 0; i <= 100; i += 10) {
        const temp = 30 - (i * 0.05) - (humedad * 0.02);
        datos.push(temp);
    }
    
    // Dibujar gráfico
    ctx.strokeStyle = \'#e53935\';
    ctx.lineWidth = 3;
    ctx.beginPath();
    
    datos.forEach((temp, index) => {
        const x = 50 + (index * 70);
        const y = 150 - (temp * 4);
        
        if(index === 0) {
            ctx.moveTo(x, y);
        } else {
            ctx.lineTo(x, y);
        }
    });
    
    ctx.stroke();
    
    // Ejes
    ctx.strokeStyle = \'#666\';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(50, 50);
    ctx.lineTo(50, 150);
    ctx.lineTo(750, 150);
    ctx.stroke();
    
    // Etiquetas
    ctx.fillStyle = \'#333\';
    ctx.font = \'14px Arial\';
    ctx.fillText(\'Temperatura (°C)\', 30, 30);
    ctx.fillText(\'Cobertura vegetal (%)\', 400, 180);
    
    // Puntos de datos
    datos.forEach((temp, index) => {
        const x = 50 + (index * 70);
        const y = 150 - (temp * 4);
        
        ctx.fillStyle = \'#e53935\';
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fill();
        
        ctx.fillStyle = \'#666\';
        ctx.fillText(`${index * 10}%`, x - 10, 170);
        ctx.fillText(`${temp.toFixed(1)}°`, x - 15, y - 10);
    });
}

// ========== QUIZ ==========
function verificarQuiz(numPregunta, respuestaCorrecta) {
    const respuestas = {
        1: {correcta: \'B\', explicacion: \'Los líquenes crustáceos son pioneros típicos. Los robles son especies climax, el diente de león y frambuesa son de sucesión secundaria.\'},
        2: {correcta: \'C\', explicacion: \'La meteorización biológica (por líquenes principalmente) es esencial para crear suelo a partir de roca.\'}
    };
    
    const feedbackId = `feedbackQuiz${numPregunta}`;
    const feedback = document.getElementById(feedbackId);
    
    // Obtener la opción seleccionada (simplificado)
    const opcionSeleccionada = event.target.textContent.trim().charAt(0);
    
    if(opcionSeleccionada === respuestaCorrecta) {
        feedback.innerHTML = `<div class="alert alert-success">✅ Correcto! ${respuestas[numPregunta].explicacion}</div>`;
    } else {
        feedback.innerHTML = `<div class="alert alert-danger">❌ Incorrecto. ${respuestas[numPregunta].explicacion}</div>`;
    }
    
    feedback.classList.add(\'feedback-visible\');
}

// ========== ANÁLISIS DE DEBATE ==========
function mostrarArgumento(modelo) {
    const argumentosDiv = document.getElementById(\'argumentosDebate\');
    const argumentos = {
        clements: `
            <h6>Argumentos a favor del modelo Clementsiano:</h6>
            <ul>
                <li><strong>Patrones observables:</strong> En muchas cronosecuencias se ven etapas predecibles</li>
                <li><strong>Convergencia:</strong> Ecosistemas similares en climas similares tienden a comunidades climax parecidas</li>
                <li><strong>Utilidad práctica:</strong> Modelo útil para restauración ecológica y predicción</li>
                <li><strong>Evidencia paleoecológica:</strong> Registro fósil muestra secuencias ordenadas tras glaciaciones</li>
            </ul>
            <p class="text-muted"><em>Críticas: Muy determinista, ignora el papel del azar y la historia única de cada sitio.</em></p>
        `,
        gleason: `
            <h6>Argumentos a favor del modelo Gleasoniano:</h6>
            <ul>
                <li><strong>Evidencia empírica:</strong> Estudios detallados muestran alta variabilidad entre sitios</li>
                <li><strong>Importancia del azar:</strong> Eventos estocásticos (tormentas, llegada de propágulos) afectan la trayectoria</li>
                <li><strong>Individualismo:</strong> Cada especie responde individualmente al ambiente, no como "superorganismo"</li>
                <li><strong>Contingencia histórica:</strong> La historia única de cada lugar influye en el resultado</li>
            </ul>
            <p class="text-muted"><em>Críticas: Demasiado relativista, difícil hacer predicciones generales.</em></p>
        `
    };
    
    argumentosDiv.innerHTML = argumentos[modelo];
    argumentosDiv.style.display = \'block\';
}

// ========== ERRORES COMUNES ==========
function mostrarError(numError) {
    // Ocultar todos primero
    for(let i = 1; i <= 3; i++) {
        document.getElementById(`detalleError${i}`).style.display = \'none\';
    }
    // Mostrar el seleccionado
    document.getElementById(`detalleError${numError}`).style.display = \'block\';
}

// ========== METACOGNICIÓN ==========
function calificarComprension(nivel) {
    const puntuaciones = {
        1: {texto: "Básica (1-3)", clase: "bg-danger"},
        2: {texto: "Intermedia (4-6)", clase: "bg-warning"},
        3: {texto: "Avanzada (7-10)", clase: "bg-success"}
    };
    
    const elem = document.getElementById(\'puntuacionReflexion\');
    elem.textContent = puntuaciones[nivel].texto;
    elem.className = `badge ${puntuaciones[nivel].clase}`;
}

function guardarReflexiones() {
    const reflexiones = {
        fecha: new Date().toLocaleString(),
        tema: "Sucesión Primaria",
        comprension: document.getElementById(\'puntuacionReflexion\').textContent,
        conexiones: document.getElementById(\'reflexionConexiones\').value,
        aplicacion: document.getElementById(\'reflexionAplicacion\').value
    };
    
    localStorage.setItem(\'reflexionesSucesion\', JSON.stringify(reflexiones));
    alert(\'✅ Reflexiones guardadas. Puedes revisarlas antes del examen.\');
}

function generarResumen() {
    const resumen = `
        RESUMEN DE APRENDIZAJE - SUCESIÓN PRIMARIA
        ==========================================
        
        Conceptos clave dominados:
        • Proceso de colonización en sustratos sin vida
        • Organismos pioneros: líquenes → musgos → herbáceas
        • Desarrollo del suelo: de regolito a horizontes
        • Debate Clements vs. Gleason
        
        Aplicaciones prácticas:
        • Restauración ecológica de minas
        • Predicción de cambios post-glaciación
        • Diseño de corredores biológicos
        
        Reflexiones personales guardadas en localStorage.
    `;
    
    alert(resumen);
}

// ========== INICIALIZACIÓN ==========
