<!-- ============ JAVASCRIPT CYBERPUNK ============ -->
<script>
// ============ EFECTO MATRIX DROPS ============
function createMatrixDrops() {
    const container = document.getElementById(\'matrixContainer\');
    const chars = \'01\';
    
    for(let i = 0; i < 15; i++) {
        const drop = document.createElement(\'div\');
        drop.className = \'matrix-drop\';
        drop.textContent = chars.charAt(Math.floor(Math.random() * chars.length));
        
        drop.style.left = Math.random() * 100 + \'%\';
        drop.style.animationDelay = Math.random() * 5 + \'s\';
        drop.style.animationDuration = (Math.random() * 3 + 2) + \'s\';
        drop.style.animationName = \'matrix-drop\';
        drop.style.animationIterationCount = \'infinite\';
        
        container.appendChild(drop);
    }
}

// ============ SIMULADOR DE RESILIENCIA ============
function updateSim() {
    const bio = parseInt(document.getElementById(\'bioRange\').value);
    const valEco = document.getElementById(\'valEco\');
    const valFiltro = document.getElementById(\'valFiltro\');
    const bioValue = document.getElementById(\'bioValue\');
    const feedback = document.getElementById(\'simFeedback\');
    const progress = document.getElementById(\'progressVisual\');
    
    // Actualizar valor mostrado del slider
    bioValue.textContent = bio + \'%\';
    
    // Lógica no lineal (umbral crítico)
    const ecoValue = Math.round(15000 * (bio / 100));
    const filtroValue = bio;
    
    // Formatear con comas
    valEco.textContent = \'$\' + ecoValue.toLocaleString();
    valFiltro.textContent = filtroValue + \'%\';
    
    // Actualizar barra de progreso
    progress.style.width = bio + \'%\';
    
    // Cambiar colores según estado
    if (bio < 30) {
        // ESTADO CRÍTICO
        valEco.style.color = "#ff4444";
        valFiltro.style.color = "#ff4444";
        progress.style.background = "linear-gradient(90deg, #ff0000, #ff4444)";
        bioValue.style.color = "#ff4444";
        
        feedback.innerHTML = `
            <div class="d-flex align-items-center justify-content-center">
                <span class="text-danger me-2">⚠</span>
                <span class="text-danger">ALERTA: COLAPSO DEL SISTEMA</span>
            </div>
            <div class="small text-danger mt-1">
                Se requieren plantas de tratamiento artificiales (Costos exorbitantes)
            </div>
        `;
        
        // Efecto glitch en el slider value
        bioValue.style.animation = \'glitch 0.3s infinite\';
        
    } else if (bio < 70) {
        // ESTADO INTERMEDIO
        valEco.style.color = "#ffcc00";
        valFiltro.style.color = "#ffcc00";
        progress.style.background = "linear-gradient(90deg, #ffcc00, #ffdd44)";
        bioValue.style.color = "#ffcc00";
        
        feedback.innerHTML = `
            <div class="d-flex align-items-center justify-content-center">
                <span class="text-warning me-2">⚠</span>
                <span class="text-warning">SISTEMA DEGRADADO</span>
            </div>
            <div class="small text-warning mt-1">
                Pérdida de resiliencia, riesgo de colapso ante perturbaciones
            </div>
        `;
        
        bioValue.style.animation = \'\';
        
    } else {
        // ESTADO ÓPTIMO
        valEco.style.color = "#00ff88";
        valFiltro.style.color = "#00ff88";
        progress.style.background = "linear-gradient(90deg, #00ff88, #44ffaa)";
        bioValue.style.color = "#00ff88";
        
        feedback.innerHTML = `
            <div class="d-flex align-items-center justify-content-center">
                <span class="text-success me-2">●</span>
                <span class="text-success">SISTEMA ÓPTIMO</span>
            </div>
            <div class="small text-success mt-1">
                Funcionalidad biofísica completa, alta resiliencia
            </div>
        `;
        
        bioValue.style.animation = \'\';
    }
}

// ============ QUIZ INTERACTIVO ============
function checkQuiz(btn, isCorrect) {
    const feedback = document.getElementById(\'quizFeedback\');
    const btns = document.querySelectorAll(\'.option-btn\');
    
    // Desactivar todos los botones
    btns.forEach(b => {
        b.disabled = true;
        b.classList.remove(\'correct\', \'incorrect\');
    });
    
    // Aplicar clases de respuesta
    if (isCorrect) {
        btn.classList.add(\'correct\');
        feedback.innerHTML = `
            <div class="alert-success p-3 border border-success">
                <div class="d-flex align-items-center">
                    <span class="text-success me-2">✓</span>
                    <div>
                        <strong class="text-success">CORRECTO!</strong>
                        <div class="mt-1 small">
                            La protección contra tormentas y erosión es una función de control de procesos biofísicos (Regulación).
                        </div>
                    </div>
                </div>
                <div class="mt-2 small text-cyan">
                    [NOTA: La Provisión se refiere a bienes tangibles (madera, peces)]
                </div>
            </div>
        `;
    } else {
        btn.classList.add(\'incorrect\');
        feedback.innerHTML = `
            <div class="alert-danger p-3 border border-danger">
                <div class="d-flex align-items-center">
                    <span class="text-danger me-2">✗</span>
                    <div>
                        <strong class="text-danger">INCORRECTO</strong>
                        <div class="mt-1 small">
                            La respuesta correcta es <span class="text-warning">Regulación</span>.
                        </div>
                    </div>
                </div>
                <div class="mt-2 small text-cyan">
                    [AYUDA: Los servicios de regulación controlan procesos ambientales]
                </div>
            </div>
        `;
    }
    
    feedback.style.display = "block";
    
    // Efecto de sonido (simulado con animación)
    if(isCorrect) {
        btn.style.animation = \'pulse-glow 0.5s\';
    }
}

// ============ LABORATORIO TEEB ============
function calcValue() {
    const price = parseInt(document.getElementById(\'carbonPrice\').value) || 40;
    const area = 5000;
    const capture = 15;
    const total = area * capture * price;
    
    const resultElement = document.getElementById(\'labResult\');
    const oldValue = parseInt(resultElement.textContent.replace(/,/g, \'\'));
    
    // Formatear con comas
    resultElement.textContent = total.toLocaleString();
    
    // Efecto visual de cambio
    resultElement.classList.remove(\'value-pulse\');
    void resultElement.offsetWidth; // Trigger reflow
    resultElement.classList.add(\'value-pulse\');
    
    // Efecto de color según cambio
    if(total > oldValue) {
        resultElement.style.color = \'#00ff88\';
    } else if(total < oldValue) {
        resultElement.style.color = \'#ff4444\';
    }
    
    // Actualizar título con efecto
    setTimeout(() => {
        resultElement.style.color = \'#ffcc00\';
    }, 500);
}

// ============ INTERACTIVIDAD SVG ============
function initSVGInteractivity() {
    const nodes = document.querySelectorAll(\'.cyber-node\');
    
    nodes.forEach(node => {
        node.addEventListener(\'mouseenter\', function() {
            this.style.filter = \'url(#glow)\';
            this.style.transform = \'scale(1.02)\';
            this.style.transition = \'transform 0.3s\';
        });
        
        node.addEventListener(\'mouseleave\', function() {
            this.style.filter = \'none\';
            this.style.transform = \'scale(1)\';
        });
    });
}

// ============ INICIALIZACIÓN ============
document.addEventListener(\'DOMContentLoaded\', function() {
    // Crear efecto Matrix
    createMatrixDrops();
    
    // Inicializar simulador
    updateSim();
    
    // Inicializar interactividad SVG
    initSVGInteractivity();
    
    // Configurar valor inicial del laboratorio
    calcValue();
    
    // Efecto de terminal typing (simulado)
    const terminalText = document.querySelector(\'.terminal-prompt .text-warning\');
    if(terminalText) {
        const originalText = terminalText.textContent;
        terminalText.textContent = \'\';
        
        let i = 0;
        const typeWriter = () => {
            if(i < originalText.length) {
                terminalText.textContent += originalText.charAt(i);
                i++;
                setTimeout(typeWriter, 50);
            }
        };
        
        setTimeout(typeWriter, 1000);
    }
});

// ============ UTILIDADES VISUALES ============
// Añadir clases de colores para CSS
document.head.insertAdjacentHTML(\'beforeend\', `
<style>
    .text-cyan { color: #00d4ff !important; }
    .text-purple { color: #cc66ff !important; }
    .border-cyan { border-color: #00d4ff !important; }
    .border-purple { border-color: #cc66ff !important; }
    .bg-cyan { background-color: #00d4ff !important; }
    .bg-warning { background-color: #ffcc00 !important; }
    .bg-purple { background-color: #cc66ff !important; }
    
    .cyber-dot {
        width: 10px;
        height: 10px;
        border-radius: 50%;
        display: inline-block;
    }
    
    .terminal-header {
        background: rgba(0, 20, 40, 0.8);
        border: 2px solid #00d4ff;
        font-family: \'VT323\', monospace;
    }
    
    .progress-container {
        background: #000;
        border: 2px solid #30363d;
        padding: 5px;
        border-radius: 0;
    }
    
    .progress-bar-bg {
        height: 20px;
        background: #002;
        position: relative;
        overflow: hidden;
    }
    
    .progress-bar-fill {
        height: 100%;
        background: linear-gradient(90deg, #00ff88, #44ffaa);
        transition: width 0.5s ease-out;
        position: relative;
    }
    
    .progress-bar-fill::after {
        content: \'\';
        position: absolute;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background: linear-gradient(90deg, 
            transparent, 
            rgba(255, 255, 255, 0.2), 
            transparent
        );
        animation: scanline 2s linear infinite;
    }
</p>
`);
</script>',
    'ejercicios' => 
    array (
      0 => 
      array (
        'enunciado' => '¿Cuál es la diferencia fundamental entre un servicio de soporte y uno de provisión?',
        'respuesta' => 'El de soporte es un proceso base (ej. fotosíntesis) necesario para que todos los demás existan; el de provisión es el producto final consumible (ej. frutas, madera).',
      ),
      1 => 
      array (
        'enunciado' => '¿Qué significa que un servicio ecosistémico sea "no comercial"?',
        'respuesta' => 'Significa que aporta bienestar (como la belleza escénica o la regulación climática) pero no suele tener un precio de mercado directo, aunque tenga un valor económico inmenso.',
      ),
      2 => 
      array (
        'enunciado' => 'Explique el concepto de "Internalización de externalidades" en el contexto de servicios ambientales.',
        'respuesta' => 'Es el acto de incluir el costo del daño a la naturaleza o el valor de sus servicios en los precios de los productos y presupuestos nacionales.',
      ),
      3 => 
      array (
        'enunciado' => '¿Por qué la polinización se considera un servicio de regulación y no de provisión?',
        'respuesta' => 'Porque es un proceso biológico que controla la reproducción vegetal; el fruto es el servicio de provisión, pero el acto de polinizar regula la producción.',
      ),
      4 => 
      array (
        'enunciado' => '¿Qué es un PSA (Pago por Servicios Ambientales)?',
        'respuesta' => 'Un mecanismo financiero donde los beneficiarios de un servicio (ej. usuarios de agua) pagan a los proveedores (ej. dueños de bosques río arriba) para asegurar su conservación.',
      ),
      5 => 
      array (
        'enunciado' => 'Mencione un ejemplo de servicio cultural en un ecosistema urbano.',
        'respuesta' => 'Parques públicos que ofrecen salud mental, recreación y valor espiritual a los ciudadanos.',
      ),
      6 => 
      array (
        'enunciado' => '¿Qué reportó el MEA en 2005 sobre el estado de los servicios globales?',
        'respuesta' => 'Que aproximadamente el 60% de los servicios ecosistémicos examinados se están degradando o se usan de manera insostenible.',
      ),
      7 => 
      array (
        'enunciado' => '¿Cómo afecta la pérdida de biodiversidad a la resiliencia de los servicios de regulación?',
        'respuesta' => 'Reduce la redundancia funcional; si desaparece una especie clave, el servicio (ej. control de plagas) puede colapsar repentinamente.',
      ),
