        </div>
        <div class="terminal-status">
            <span class="badge border border-green text-green">ODS_12</span>
            <span class="badge border border-cyan text-cyan ms-2">CIRCULAR_ECONOMY</span>
            <span class="badge border border-orange text-orange ms-2">INDUSTRIAL_ECO</span>
        </div>
    </div>
</div>

<!-- ============ TÍTULO PRINCIPAL ============ -->
<h1>ECOLOGÍA INDUSTRIAL Y ODS 12</h1>

<!-- ============ CONCEPT HEADER ============ -->
<div class="concept-header">
    <div class="d-flex align-items-start">
        <span class="text-orange me-3">⚠</span>
        <div>
            <p class="lead">
                La sustentabilidad no es una "acción verde", es el rediseño de los flujos de materia y energía. 
                El <strong>ODS 12</strong> busca romper el desacoplamiento entre crecimiento económico y degradación ambiental.
            </p>
            <div class="mt-3">
                <span class="badge border border-green">3R+</span>
                <span class="badge border border-cyan ms-2">CRADLE_TO_CRADLE</span>
                <span class="badge border border-orange ms-2">CARBON_NEGATIVE</span>
            </div>
        </div>
    </div>
</div>

<!-- ============ DIAGRAMA SISTÉMICO CYBERPUNK ============ -->
<div class="svg-container">
    <div class="text-center mb-4">
