                <stop offset="50%" stop-color="#003366"/>
                <stop offset="100%" stop-color="#00d4ff"/>
            </linearGradient>
            
            <linearGradient id="gradBio" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="#001a0d"/>
                <stop offset="50%" stop-color="#00331a"/>
                <stop offset="100%" stop-color="#00ff9d"/>
