            <animate attributeName="stroke-dashoffset" values="0;30;0" dur="3s" repeatCount="indefinite"/>
        </path>
        
        <g class="tech-cycle" filter="url(#glow-blue)">
            <circle cx="550" cy="200" r="45" fill="#000" stroke="#00d4ff" stroke-width="3"/>
