<!-- ============ SIMULADOR DE METABOLISMO URBANO ============ -->
<div class="sim-panel">
    <h4>🎮 SIMULADOR DE METABOLISMO URBANO</h4>
    
    <div class="terminal-instructions mb-4 p-3 border border-cyan">
        <span class="text-cyan">INSTRUCCIONES:</span>
        <span class="text-light ms-2">Modifica la eficiencia de los hábitos ciudadanos y observa el impacto en la <strong>Huella de Carbono</strong> y el <strong>Estrés Hídrico</strong>.</span>
    </div>
    
    <div class="row g-4">
        <div class="col-md-4">
            <!-- Panel de control de sliders -->
            <div class="slider-group">
                <label class="stat-label">TASA DE RECICLAJE (%)</label>
                <div class="d-flex justify-content-between mb-2">
                    <span class="text-danger">0%</span>
                    <span class="text-warning" id="recycleValue">13%</span>
                    <span class="text-success">100%</span>
                </div>
                <input type="range" class="form-range" id="rangeRecycle" min="0" max="100" value="13" oninput="updateSim()">
                <div class="slider-status mt-2">
                    <span class="small text-muted">Estado actual: </span>
                    <span id="recycleStatus" class="small text-warning">BAJO</span>
                </div>
            </div>
            
            <div class="slider-group mt-4">
                <label class="stat-label">DIETA (BASADA EN PLANTAS %)</label>
                <div class="d-flex justify-content-between mb-2">
                    <span class="text-danger">0%</span>
                    <span class="text-warning" id="dietValue">20%</span>
                    <span class="text-success">100%</span>
                </div>
                <input type="range" class="form-range" id="rangeDiet" min="0" max="100" value="20" oninput="updateSim()">
                <div class="slider-status mt-2">
                    <span class="small text-muted">Impacto hídrico: </span>
                    <span id="dietStatus" class="small text-warning">ALTO</span>
                </div>
            </div>
        </div>
        
        <div class="col-md-8">
            <!-- Dashboard de métricas -->
            <div class="row g-3">
                <div class="col-md-4">
                    <div class="dashboard-stat">
