<!-- ============ JAVASCRIPT CYBERPUNK ============ -->
<script>
// ============ MATRIX DROPS EFFECT ============
function createMatrixDrops() {
    const container = document.getElementById(\'matrixContainer\');
    const chars = \'01\';
    
    for(let i = 0; i < 20; i++) {
        const drop = document.createElement(\'div\');
        drop.className = \'matrix-drop\';
        drop.textContent = chars.charAt(Math.floor(Math.random() * chars.length));
        
        drop.style.left = Math.random() * 100 + \'%\';
        drop.style.animationDelay = Math.random() * 5 + \'s\';
        drop.style.animationDuration = (Math.random() * 3 + 2) + \'s\';
        drop.style.animationName = \'matrix-drop\';
        drop.style.animationIterationCount = \'infinite\';
        
        container.appendChild(drop);
    }
}

// ============ SIMULADOR DE METABOLISMO URBANO ============
let impactChart = null;

function updateSim() {
    const recycle = parseInt(document.getElementById(\'rangeRecycle\').value);
    const diet = parseInt(document.getElementById(\'rangeDiet\').value);
    
    // Actualizar valores mostrados
    document.getElementById(\'recycleValue\').textContent = recycle + \'%\';
    document.getElementById(\'dietValue\').textContent = diet + \'%\';
    
    // Lógica de impacto con base científica
    const co2 = (15 - (recycle * 0.05) - (diet * 0.08)).toFixed(1);
    const h2o = (2000 - (diet * 15)).toFixed(0);
    const life = (5 + (recycle * 0.25)).toFixed(1);
    
    // Actualizar valores
    document.getElementById(\'valCO2\').textContent = co2;
    document.getElementById(\'valH2O\').textContent = h2o + \' M3\';
    document.getElementById(\'valFill\').textContent = life + \' AÑOS\';
    
    // Actualizar estados
    updateStatus(\'recycleStatus\', recycle, [30, 70]);
    updateStatus(\'dietStatus\', diet, [20, 60]);
    
    // Feedback sistémico
    const feedback = document.getElementById(\'simFeedback\');
    let statusText = \'\';
    let statusColor = \'\';
    
    if(recycle > 70 && diet > 60) {
        statusText = \'● REGENERACIÓN ACTIVA - HUELLA MÍNIMA\';
        statusColor = \'#00ff9d\';
    } else if(recycle > 40 || diet > 40) {
        statusText = \'● TRANSICIÓN - IMPACTO MODERADO\';
        statusColor = \'#ff9d00\';
    } else {
        statusText = \'● CONSUMO LINEAL - ALTO IMPACTO\';
        statusColor = \'#ff4444\';
    }
    
    feedback.innerHTML = `<span style="color:${statusColor}">${statusText}</span>`;
    
    // Actualizar gráfico
    updateImpactChart(recycle, diet);
}

function updateStatus(elementId, value, thresholds) {
    const element = document.getElementById(elementId);
    const [low, medium] = thresholds;
    
    if(value < low) {
        element.textContent = \'BAJO\';
        element.className = \'small text-danger\';
    } else if(value < medium) {
        element.textContent = \'MEDIO\';
        element.className = \'small text-warning\';
    } else {
        element.textContent = \'ALTO\';
        element.className = \'small text-success\';
    }
}

function updateImpactChart(recycle, diet) {
    const canvas = document.getElementById(\'impactChart\');
    const ctx = canvas.getContext(\'2d\');
    
    // Limpiar canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    
    // Datos para el gráfico
    const data = [
        {label: \'Reciclaje\', value: recycle, color: \'#00d4ff\'},
        {label: \'Dieta Plantas\', value: diet, color: \'#00ff9d\'},
        {label: \'Impacto CO2\', value: 100 - (recycle * 0.3 + diet * 0.4), color: \'#ff9d00\'},
        {label: \'Estrés Hídrico\', value: 100 - (diet * 0.6), color: \'#cc66ff\'}
    ];
    
    // Dibujar gráfico de barras
    const barWidth = 60;
    const spacing = 30;
    const startX = 50;
    
    data.forEach((item, index) => {
        const x = startX + (barWidth + spacing) * index;
        const height = (item.value / 100) * 100;
        const y = 140 - height;
        
        // Barra
        ctx.fillStyle = item.color;
        ctx.fillRect(x, y, barWidth, height);
        
        // Efecto de brillo
        ctx.fillStyle = \'rgba(255, 255, 255, 0.2)\';
        ctx.fillRect(x, y, 10, height);
        
        // Texto
        ctx.fillStyle = \'#fff\';
        ctx.font = \'12px "VT323"\';
        ctx.textAlign = \'center\';
        ctx.fillText(item.label, x + barWidth/2, 155);
        
        // Valor
        ctx.fillStyle = item.color;
        ctx.font = \'14px "VT323"\';
        ctx.fillText(item.value + \'%\', x + barWidth/2, y - 10);
    });
    
    // Línea de referencia
    ctx.strokeStyle = \'#666\';
    ctx.setLineDash([5, 3]);
    ctx.beginPath();
    ctx.moveTo(40, 90);
    ctx.lineTo(750, 90);
    ctx.stroke();
    ctx.setLineDash([]);
    
    // Etiqueta de referencia
    ctx.fillStyle = \'#8af\';
    ctx.font = \'10px "Courier New"\';
    ctx.fillText(\'Objetivo ODS 12\', 30, 85);
}

// ============ LABORATORIO DE ADSORBENTES ============
function calcAdsorption() {
    const temp = parseInt(document.getElementById(\'tempAct\').value) || 600;
    const surfaceElement = document.getElementById(\'surfaceArea\');
    const effElement = document.getElementById(\'remEff\');
    const tempVisual = document.getElementById(\'tempVisual\');
    const tempStatus = document.getElementById(\'tempStatus\');
    
    // Modelo simplificado: pico a 800 grados
    let area, eff;
    
    if(temp <= 800) {
        // Zona de activación
        area = 400 + (temp * 0.67);
        eff = 40 + (temp * 0.075);
    } else {
        // Zona de sinterización (pérdida)
        area = 1200 - ((temp - 800) * 1.5);
        eff = 100 - ((temp - 800) * 0.2);
    }
    
    // Limitar valores
    area = Math.max(300, Math.min(area, 1200));
    eff = Math.max(30, Math.min(eff, 99));
    
    // Actualizar valores con animación
    animateValue(surfaceElement, Math.round(area));
    animateValue(effElement, Math.round(eff));
    
    // Actualizar indicador visual de temperatura
    const tempPercent = ((temp - 300) / 900) * 100;
    tempVisual.style.width = Math.min(Math.max(tempPercent, 0), 100) + \'%\';
    
    // Actualizar color del indicador
    if(temp >= 600 && temp <= 800) {
        tempVisual.style.background = \'linear-gradient(90deg, #00ff9d, #00d4ff)\';
        tempStatus.textContent = \'[OPTIMAL]\';
        tempStatus.className = \'text-green blink ms-2\';
    } else if(temp < 600) {
        tempVisual.style.background = \'linear-gradient(90deg, #ff4444, #ff9d00)\';
        tempStatus.textContent = \'[UNDER]\';
        tempStatus.className = \'text-warning blink ms-2\';
    } else {
        tempVisual.style.background = \'linear-gradient(90deg, #ff9d00, #ff4444)\';
        tempStatus.textContent = \'[OVER]\';
        tempStatus.className = \'text-danger blink ms-2\';
    }
}

function animateValue(element, targetValue) {
    const currentValue = parseInt(element.textContent.replace(/[^0-9]/g, \'\'));
    const increment = Math.sign(targetValue - currentValue);
    let current = currentValue;
    
    const animate = () => {
        current += increment * Math.ceil(Math.abs(targetValue - current) / 10);
        
        if((increment > 0 && current >= targetValue) || 
           (increment < 0 && current <= targetValue)) {
            current = targetValue;
        }
        
        if(element.id === \'remEff\') {
            element.textContent = current + \'%\';
        } else {
            element.textContent = current;
        }
        
        if(current !== targetValue) {
            requestAnimationFrame(animate);
        } else {
            // Efecto final
            element.style.transform = \'scale(1.1)\';
            setTimeout(() => {
                element.style.transform = \'scale(1)\';
            }, 200);
        }
    };
    
    animate();
}

// ============ QUIZ INTERACTIVO ============
function checkQuiz(btn, isCorrect, feedback) {
    const result = document.getElementById(\'quizResult\');
    const buttons = document.querySelectorAll(\'.opt-btn\');
    
    // Desactivar todos los botones
    buttons.forEach(b => {
        b.disabled = true;
        b.classList.remove(\'correct\', \'incorrect\');
    });
    
    if(isCorrect) {
        btn.classList.add(\'correct\');
        result.innerHTML = `
            <div class="alert-success p-4 border border-green">
                <div class="d-flex align-items-start">
                    <span class="text-green me-3">✓</span>
                    <div>
                        <strong class="text-green h5">[CORRECTO]</strong>
                        <div class="mt-2">
                            ${feedback}
                        </div>
                        <div class="mt-3 small text-cyan">
                            <strong>Nota conceptual:</strong> En la jerarquía de residuos, Reducir > Reutilizar > Reciclar > Recuperar energía > Disposición.
                        </div>
                    </div>
                </div>
            </div>
        `;
    } else {
        btn.classList.add(\'incorrect\');
        result.innerHTML = `
            <div class="alert-danger p-4 border border-danger">
                <div class="d-flex align-items-start">
                    <span class="text-danger me-3">✗</span>
                    <div>
                        <strong class="text-danger h5">[ERROR]</strong>
                        <div class="mt-2">
                            ${feedback}
                        </div>
                        <div class="mt-3 small text-cyan">
                            <strong>Ayuda:</strong> Considera el consumo energético y la pérdida de calidad del material en cada ciclo.
                        </div>
                    </div>
                </div>
            </div>
        `;
    }
    
    result.style.display = "block";
    
    // Efecto visual
    if(isCorrect) {
        btn.style.animation = \'pulse-green 0.5s\';
    } else {
        btn.style.animation = \'glitch 0.3s\';
    }
}

// ============ INTERACTIVIDAD SVG ============
function initSVGInteractivity() {
    const cycles = document.querySelectorAll(\'.tech-cycle, .bio-cycle, .design-node\');
    
    cycles.forEach(cycle => {
        cycle.addEventListener(\'mouseenter\', function() {
            this.style.transform = \'scale(1.05)\';
            this.style.transition = \'transform 0.3s\';
            this.style.filter = \'brightness(1.2)\';
        });
        
        cycle.addEventListener(\'mouseleave\', function() {
            this.style.transform = \'scale(1)\';
            this.style.filter = \'brightness(1)\';
        });
        
        cycle.addEventListener(\'click\', function() {
            const info = this.classList.contains(\'tech-cycle\') ? 
                \'Ciclo Técnico: Materiales que deben mantenerse en circuito cerrado (metales, plásticos técnicos)\' :
                this.classList.contains(\'bio-cycle\') ?
                \'Ciclo Biológico: Materiales que pueden regresar de forma segura a la biosfera\' :
                \'Nodo de Diseño: Punto crítico donde se determinan los flujos metabólicos\';
            
            alert(`[SISTEM_INFO]\\n\\n${info}`);
        });
    });
}

// ============ INICIALIZACIÓN ============
document.addEventListener(\'DOMContentLoaded\', function() {
    // Crear efecto Matrix
    createMatrixDrops();
    
    // Inicializar simulador
    updateSim();
    
    // Inicializar laboratorio
    calcAdsorption();
    
    // Inicializar interactividad SVG
    initSVGInteractivity();
    
    // Efecto de carga terminal
    const terminalPrompt = document.querySelector(\'.terminal-prompt .text-green\');
    if(terminalPrompt) {
        const originalText = terminalPrompt.textContent;
        terminalPrompt.textContent = \'\';
        
        let i = 0;
        const typeWriter = () => {
            if(i < originalText.length) {
                terminalPrompt.textContent += originalText.charAt(i);
                i++;
                setTimeout(typeWriter, 50);
            } else {
                terminalPrompt.innerHTML += \'<span class="blink">_</span>\';
            }
        };
        
        setTimeout(typeWriter, 500);
    }
    
    // Configurar estilos dinámicos
    const style = document.createElement(\'style\');
    style.textContent = `
        .cyber-dot {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            display: inline-block;
        }
        
        .impact-chart {
            background: #000;
            border: 2px solid #00d4ff;
            padding: 10px;
            border-radius: 0;
        }
        
        .temp-bar {
            height: 20px;
            background: #002;
            position: relative;
            overflow: hidden;
        }
        
        .temp-fill {
            height: 100%;
            background: linear-gradient(90deg, #ff4444, #ff9d00, #00ff9d, #ff9d00, #ff4444);
            transition: width 0.5s ease-out;
        }
        
        .insight-card {
            background: rgba(0, 0, 0, 0.5);
            transition: transform 0.3s, box-shadow 0.3s;
        }
        
        .insight-card:hover {
            transform: translateY(-5px);
            box-shadow: 0 10px 20px rgba(0, 255, 157, 0.2);
        }
    `;
    document.head.appendChild(style);
});
</script>',
    'ejercicios' => 
    array (
      0 => 
      array (
        'enunciado' => 'Calcula el ahorro de agua anual de una persona que cambia su dieta de carne roja (15,000 L/kg) a lentejas (1,200 L/kg), asumiendo un consumo de 20kg al año.',
        'respuesta' => 'Ahorro = 20kg * (15,000 - 1,200) = 276,000 litros de agua al año.',
      ),
      1 => 
      array (
        'enunciado' => 'Explica la relación entre el Carbono Activado y la Economía Circular utilizando el ejemplo de la cáscara de coco.',
