    'titulo' => 'Urbanismo Sistémico: La Ingeniería de Comunidades Sustentables',
    'contenido' => '<div class="leccion-urbanismo">

<!-- ============ CITY GRID EFFECT ============ -->
<div class="city-grid" id="cityGrid"></div>

<!-- ============ TERMINAL HEADER ============ -->
<div class="terminal-header">
    <div class="d-flex justify-content-between align-items-center">
        <div class="terminal-prompt">
            <span class="text-cyan">CITY_SYSTEM></span>
            <span class="text-green ms-2">URBAN_METABOLISM</span>
            <span class="text-gold blink ms-2">[ANALYSIS_MODE]</span>
        </div>
        <div class="terminal-status">
            <span class="badge border border-cyan text-cyan">ODS_11</span>
            <span class="badge border border-green text-green ms-2">RESILIENCE_ENG</span>
            <span class="badge border border-gold text-gold ms-2">SYSTEMIC_DESIGN</span>
        </div>
    </div>
</div>

<!-- ============ HEADER PRINCIPAL ============ -->
<div class="main-header">
    <div class="row align-items-center">
        <div class="col-lg-8">
            <h1>ODS 11: METABOLISMO URBANO</h1>
            <p class="lead">
                Una comunidad sustentable no es solo un espacio geográfico, es un 
                <strong>ORGANISMO TERMODINÁMICO</strong> que procesa materia, energía e información 
                con eficiencia regenerativa.
            </p>
            
            <div class="mt-4">
                <button class="btn-action me-3" onclick="showSystemInfo()">
                    <span class="me-2">📊</span> VER SISTEMA
                </button>
                <button class="btn-action" onclick="runDiagnostic()">
                    <span class="me-2">⚡</span> DIAGNÓSTICO
                </button>
            </div>
        </div>
        
        <div class="col-lg-4 mt-4 mt-lg-0">
            <div class="status-monitor">
                <span class="ui-label">SYSTEM STATUS MONITOR</span>
                <div>> Resiliencia: <span id="resilienceScore" class="text-green">65</span>%</div>
                <div>> Huella Hídrica: <span id="waterFootprint" class="text-cyan">NORMAL</span></div>
                <div>> Cobertura Verde: <span id="greenCoverage" class="text-green">30</span>%</div>
                <div>> Densidad de Servicios: <span id="serviceDensity" class="text-gold">45</span>%</div>
                <div>> Autonomía Energética: <span id="energyAutonomy" class="text-cyan">20</span>%</div>
                
                <div class="status-indicator mt-4">
                    <div class="progress" style="height: 10px; background: #002;">
                        <div class="progress-bar bg-green" id="systemHealth" style="width: 65%;"></div>
                    </div>
                    <div class="d-flex justify-content-between mt-1">
                        <span class="small text-danger">CRÍTICO</span>
                        <span class="small text-warning">MODERADO</span>
                        <span class="small text-success">ÓPTIMO</span>
                    </div>
                </div>
            </div>
        </div>
    </div>
</div>

<!-- ============ DIAGRAMA METABÓLICO ============ -->
<div class="svg-container">
    <div class="text-center mb-4">
        <span class="badge border border-green">METABOLIC_FLOW_DIAGRAM</span>
        <span class="text-muted ms-2">v4.1 - Sistema Urbano Complejo</span>
    </div>
    
    <svg viewBox="0 0 900 500" xmlns="http://www.w3.org/2000/svg" style="width: 100%; height: auto;">
        <defs>
            <!-- Gradientes cibernéticos -->
            <linearGradient id="gradCity" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="#001a33"/>
                <stop offset="50%" stop-color="#004466"/>
                <stop offset="100%" stop-color="#00f2ff"/>
            </linearGradient>
            
            <linearGradient id="gradEnergy" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="#332200"/>
                <stop offset="50%" stop-color="#665500"/>
                <stop offset="100%" stop-color="#ffcc00"/>
            </linearGradient>
            
            <linearGradient id="gradBio" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="#003300"/>
                <stop offset="50%" stop-color="#006600"/>
                <stop offset="100%" stop-color="#39ff14"/>
            </linearGradient>
            
            <filter id="glow-cyan">
                <feGaussianBlur stdDeviation="3" result="blur"/>
                <feMerge>
                    <feMergeNode in="blur"/>
                    <feMergeNode in="SourceGraphic"/>
                </feMerge>
            </filter>
            
            <filter id="glow-green">
                <feGaussianBlur stdDeviation="2.5" result="blur"/>
                <feMerge>
                    <feMergeNode in="blur"/>
                    <feMergeNode in="SourceGraphic"/>
                </feMerge>
            </filter>
        </defs>
        
        <!-- Fondo de ciudad -->
        <rect x="50" y="50" width="800" height="400" rx="15" fill="none" stroke="#00f2ff" stroke-width="3" stroke-dasharray="10,5"/>
        
        <!-- Núcleo Urbano -->
        <g class="urban-core" filter="url(#glow-cyan)">
