            <path d="M250 100 L230 110 L250 120 Z" fill="#ffcc00"/>
            <path d="M250 350 L230 340 L250 330 Z" fill="#ffcc00"/>
        </g>
        
        <!-- Puntos de interconexión -->
        <circle cx="450" cy="170" r="8" fill="#00f2ff">
            <animate attributeName="r" values="8;12;8" dur="1.5s" repeatCount="indefinite"/>
        </circle>
        
        <circle cx="450" cy="330" r="8" fill="#00f2ff">
            <animate attributeName="r" values="8;12;8" dur="1.5s" repeatCount="indefinite"/>
