<!-- ============ JAVASCRIPT CYBERPUNK ============ -->
<script>
// ============ CITY GRID EFFECT ============
function createCityGrid() {
    const grid = document.getElementById(\'cityGrid\');
    const width = window.innerWidth;
    const height = window.innerHeight;
    const spacing = 100;
    
    // Líneas horizontales
    for(let y = 0; y < height; y += spacing) {
        const line = document.createElement(\'div\');
        line.className = \'grid-line grid-horizontal\';
        line.style.top = y + \'px\';
        line.style.opacity = 0.2 + (Math.random() * 0.3);
        grid.appendChild(line);
    }
    
    // Líneas verticales
    for(let x = 0; x < width; x += spacing) {
        const line = document.createElement(\'div\');
        line.className = \'grid-line grid-vertical\';
        line.style.left = x + \'px\';
        line.style.opacity = 0.2 + (Math.random() * 0.3);
        grid.appendChild(line);
    }
}

// ============ SIMULADOR DE PLANEACIÓN ============
let trendChart = null;

function runSim() {
    // Obtener valores de los sliders
    const transport = parseInt(document.getElementById(\'simTransport\').value);
    const energy = parseInt(document.getElementById(\'simEnergy\').value);
    const green = parseInt(document.getElementById(\'simGreen\').value);
    
    // Actualizar valores mostrados
    document.getElementById(\'transportValue\').textContent = transport + \'%\';
    document.getElementById(\'energyValue\').textContent = energy + \'%\';
    document.getElementById(\'greenValue\').textContent = green + \'%\';
    
    // Calcular métricas (modelo simplificado)
    const aqi = Math.max(15, 120 - (transport * 0.8) - (green * 0.3)).toFixed(0);
    const independence = Math.min(100, (energy * 0.9) + (green * 0.1)).toFixed(0);
    const resilience = ((transport * 0.3) + (energy * 0.4) + (green * 0.3)).toFixed(0);
    const cost = (2000 + (transport * 20) + (energy * 30) + (green * 15)).toFixed(0);
    
    // Actualizar valores principales
    document.getElementById(\'valAQI\').textContent = aqi;
    document.getElementById(\'valIndep\').textContent = independence + \'%\';
    document.getElementById(\'valResilience\').textContent = resilience + \'%\';
    document.getElementById(\'valCost\').textContent = \'$\' + cost;
    
    // Actualizar barras de progreso
    document.getElementById(\'aqiBar\').style.width = (aqi / 3) + \'%\';
    document.getElementById(\'indepBar\').style.width = independence + \'%\';
    document.getElementById(\'resilienceBar\').style.width = resilience + \'%\';
    document.getElementById(\'costBar\').style.width = (cost / 100) + \'%\';
    
    // Actualizar estado del sistema
    updateSystemStatus(aqi, independence, resilience, cost);
    
    // Actualizar impactos calculados
    document.getElementById(\'transportImpact\').textContent = \'-\' + (transport * 0.25) + \'% AQI\';
    document.getElementById(\'energyImpact\').textContent = \'+\' + (energy * 0.9) + \'%\';
    document.getElementById(\'greenImpact\').textContent = \'-\' + (green * 0.05) + \'°C\';
    
    // Actualizar gráfico de tendencias
    updateTrendChart(transport, energy, green, aqi, independence, resilience);
    
    // Actualizar log del sistema
    updateSystemLog(aqi, independence, resilience);
}

function updateSystemStatus(aqi, independence, resilience, cost) {
    // Actualizar estado de AQI
    const aqiStatus = document.getElementById(\'aqiStatus\');
    const aqiBar = document.getElementById(\'aqiBar\');
    function isDark() { return document.documentElement.classList.contains(\'dark\') || document.body.classList.contains(\'dark\'); }
    if(aqi < 50) {
        aqiStatus.textContent = \'● EXCELENTE\';
        aqiStatus.className = \'small text-success\';
        if(!isDark()) { aqiBar.style.background = \'#39ff14\'; } else { aqiBar.style.background = \'\'; }
    } else if(aqi < 100) {
        aqiStatus.textContent = \'● MODERADO\';
        aqiStatus.className = \'small text-warning\';
        if(!isDark()) { aqiBar.style.background = \'#ffcc00\'; } else { aqiBar.style.background = \'\'; }
    } else {
        aqiStatus.textContent = \'● PELIGROSO\';
        aqiStatus.className = \'small text-danger\';
        if(!isDark()) { aqiBar.style.background = \'#ff4444\'; } else { aqiBar.style.background = \'\'; }
    }
    
    // Actualizar estado de independencia
    const indepStatus = document.getElementById(\'indepStatus\');
    if(independence < 30) {
        indepStatus.textContent = \'● BAJA\';
        indepStatus.className = \'small text-danger\';
    } else if(independence < 70) {
        indepStatus.textContent = \'● MEDIA\';
        indepStatus.className = \'small text-warning\';
    } else {
        indepStatus.textContent = \'● ALTA\';
        indepStatus.className = \'small text-success\';
    }
    
    // Actualizar estado de resiliencia
    const resilienceStatus = document.getElementById(\'resilienceStatus\');
    if(resilience < 40) {
        resilienceStatus.textContent = \'● BAJA\';
        resilienceStatus.className = \'small text-danger\';
    } else if(resilience < 80) {
        resilienceStatus.textContent = \'● MEDIA\';
        resilienceStatus.className = \'small text-warning\';
    } else {
        resilienceStatus.textContent = \'● ALTA\';
        resilienceStatus.className = \'small text-success\';
    }
    
    // Actualizar estado de costo
    const costStatus = document.getElementById(\'costStatus\');
    if(cost < 1500) {
        costStatus.textContent = \'● BAJO\';
        costStatus.className = \'small text-success\';
    } else if(cost < 3000) {
        costStatus.textContent = \'● MODERADO\';
        costStatus.className = \'small text-warning\';
    } else {
        costStatus.textContent = \'● ALTO\';
        costStatus.className = \'small text-danger\';
    }
    
    // Actualizar salud general del sistema
    const systemHealth = document.getElementById(\'systemHealth\');
    const avgHealth = (100 - (aqi / 3) + parseInt(independence) + parseInt(resilience) - (cost / 100)) / 3;
    systemHealth.style.width = Math.max(0, Math.min(avgHealth, 100)) + \'%\';
    
    if(avgHealth < 40) {
        systemHealth.className = \'progress-bar bg-danger\';
    } else if(avgHealth < 70) {
        systemHealth.className = \'progress-bar bg-warning\';
    } else {
        systemHealth.className = \'progress-bar bg-success\';
    }
}

function updateSystemLog(aqi, independence, resilience) {
    const log = document.getElementById(\'simLog\');
    const avg = (parseInt(aqi) + parseInt(independence) + parseInt(resilience)) / 3;
    
    let message = \'\';
    let color = \'\';
    
    if(avg < 40) {
        message = \'● SISTEMA CRÍTICO - INTERVENCIÓN URGENTE REQUERIDA\';
        color = \'#ff4444\';
    } else if(avg < 70) {
        message = \'● SISTEMA EN TRANSICIÓN - OPTIMIZACIÓN RECOMENDADA\';
        color = \'#ffcc00\';
    } else {
        message = \'● SISTEMA ÓPTIMO - OPERACIÓN SOSTENIBLE CONFIRMADA\';
        color = \'#39ff14\';
    }
    
    log.innerHTML = `<span style="color:${color}">${message}</span>`;
    
    // Efecto de parpadeo para sistemas críticos
    if(avg < 40) {
        log.classList.add(\'blink\');
    } else {
        log.classList.remove(\'blink\');
    }
}

function updateTrendChart(transport, energy, green, aqi, independence, resilience) {
    const canvas = document.getElementById(\'trendChart\');
    const ctx = canvas.getContext(\'2d\');
    
    // Limpiar canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    
    // Datos para el gráfico
    const datasets = [
        {
            label: \'Transporte\',
            values: [transport, transport * 0.9, transport * 0.8, transport * 0.7],
            color: \'#ffcc00\'
        },
        {
            label: \'Energía\',
            values: [energy, energy * 1.1, energy * 1.2, energy * 1.3],
            color: \'#39ff14\'
        },
        {
            label: \'Infra Verde\',
            values: [green, green * 1.05, green * 1.1, green * 1.15],
            color: \'#00f2ff\'
        }
    ];
    
    // Dibujar gráfico de líneas
    const width = 700;
    const height = 150;
    const offsetX = 50;
    const offsetY = 30;
    const stepX = width / 4;
    
    // Ejes
    ctx.strokeStyle = \'#666\';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(offsetX, offsetY);
    ctx.lineTo(offsetX, offsetY + height);
    ctx.lineTo(offsetX + width, offsetY + height);
    ctx.stroke();
    
    // Etiquetas del eje X
    const years = [\'2024\', \'2025\', \'2026\', \'2027\'];
    years.forEach((year, i) => {
        ctx.fillStyle = \'#8af\';
        ctx.font = \'12px "VT323"\';
        ctx.textAlign = \'center\';
        ctx.fillText(year, offsetX + (i * stepX) + (stepX / 2), offsetY + height + 20);
    });
    
    // Dibujar líneas de cada dataset
    datasets.forEach(dataset => {
        ctx.strokeStyle = dataset.color;
        ctx.lineWidth = 3;
        ctx.beginPath();
        
        dataset.values.forEach((value, i) => {
            const x = offsetX + (i * stepX) + (stepX / 2);
            const y = offsetY + height - (value / 100 * height);
            
            if(i === 0) {
                ctx.moveTo(x, y);
            } else {
                ctx.lineTo(x, y);
            }
            
            // Puntos
            ctx.fillStyle = dataset.color;
            ctx.beginPath();
            ctx.arc(x, y, 6, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = \'#000\';
            ctx.beginPath();
            ctx.arc(x, y, 3, 0, Math.PI * 2);
            ctx.fill();
        });
        
        ctx.stroke();
    });
    
    // Leyenda
    datasets.forEach((dataset, i) => {
        ctx.fillStyle = dataset.color;
        ctx.font = \'14px "VT323"\';
        ctx.fillText(dataset.label, offsetX + width + 20, offsetY + 30 + (i * 25));
        
        // Cuadro de color
        ctx.fillStyle = dataset.color;
        ctx.fillRect(offsetX + width + 10, offsetY + 20 + (i * 25), 8, 8);
    });
}

function optimizeSystem() {
    // Optimización automática del sistema
    document.getElementById(\'simTransport\').value = 75;
    document.getElementById(\'simEnergy\').value = 65;
    document.getElementById(\'simGreen\').value = 80;
    
    runSim();
    
    // Mostrar mensaje de optimización
    const log = document.getElementById(\'simLog\');
    log.innerHTML = \'<span class="text-green">● SISTEMA OPTIMIZADO - PARÁMETROS AJUSTADOS PARA MÁXIMA RESILIENCIA</span>\';
    
    // Efecto visual
    log.classList.add(\'glitch\');
    setTimeout(() => log.classList.remove(\'glitch\'), 500);
}

function resetSim() {
    // Restaurar valores por defecto
    document.getElementById(\'simTransport\').value = 30;
    document.getElementById(\'simEnergy\').value = 20;
    document.getElementById(\'simGreen\').value = 45;
    
    runSim();
    
    // Mostrar mensaje de reinicio
    const log = document.getElementById(\'simLog\');
    log.innerHTML = \'<span class="text-gold">● SISTEMA REINICIADO - VALORES POR DEFECTO RESTAURADOS</span>\';
}

// ============ EVALUACIÓN MASTER ============
function checkMaster(idx, btn) {
    const feedback = document.getElementById(\'masterFeedback\');
    const explanation = document.getElementById(\'quizExplanation\');
    const buttons = document.querySelectorAll(\'.quiz-btn\');
    
    // Remover clases anteriores
    buttons.forEach(b => {
        b.classList.remove(\'activated\', \'correct\', \'incorrect\');
    });
    
    // Activar el botón clickeado
    btn.classList.add(\'activated\');
    
    // Mostrar feedback
    if(idx === 1) {
        // Respuesta correcta
        btn.classList.add(\'correct\');
        feedback.innerHTML = `
            <div class="alert-success p-4">
                <div class="d-flex align-items-start">
                    <span class="text-green me-3">✓</span>
                    <div>
                        <strong class="text-green h5">[RESPUESTA CORRECTA]</strong>
                        <div class="mt-2 text-light">
                            Has identificado correctamente la diferencia fundamental. La sustentabilidad 
                            requiere integración sistémica de tecnología, equidad social y viabilidad económica.
                        </div>
                    </div>
                </div>
            </div>
        `;
    } else {
        // Respuesta incorrecta
        btn.classList.add(\'incorrect\');
        feedback.innerHTML = `
            <div class="alert-danger p-4">
                <div class="d-flex align-items-start">
                    <span class="text-danger me-3">✗</span>
                    <div>
                        <strong class="text-danger h5">[ANÁLISIS INCOMPLETO]</strong>
                        <div class="mt-2 text-light">
                            Tu respuesta no captura la complejidad sistémica del ODS 11. 
                            Revisa el marco de los tres pilares de la sustentabilidad.
                        </div>
                    </div>
                </div>
            </div>
        `;
    }
    
    feedback.style.display = "block";
    explanation.style.display = "block";
    
    // Efecto visual
    if(idx === 1) {
        btn.style.animation = \'pulse-cyan 0.5s\';
    } else {
        btn.style.animation = \'glitch 0.5s\';
    }
}

// ============ FUNCIONES AUXILIARES ============
function showSystemInfo() {
    alert(\'[SYSTEM_INFO]\\n\\nSistema de Análisis Urbano v4.2\\nModelo basado en:\\n• IPCC Ciudades 2025\\n• ODS 11 Metas\\n• Economía Circular\\n• Resiliencia Climática\');
}

function runDiagnostic() {
    const diagnostic = document.getElementById(\'simLog\');
    diagnostic.innerHTML = \'<span class="text-cyan">● EJECUTANDO DIAGNÓSTICO SISTÉMICO COMPLETO...</span>\';
    
    setTimeout(() => {
        diagnostic.innerHTML = \'<span class="text-green">● DIAGNÓSTICO COMPLETO - SISTEMA OPERATIVO CON 92% DE EFICIENCIA</span>\';
        diagnostic.classList.add(\'glitch\');
        setTimeout(() => diagnostic.classList.remove(\'glitch\'), 500);
    }, 2000);
}

function showNodeInfo(type) {
    const info = type === \'input\' ? 
        \'Nodo de Entrada: Recursos materiales, energéticos e informacionales que ingresan al sistema urbano.\' :
        \'Nodo de Salida: Productos, servicios y residuos procesados que salen del sistema urbano.\';
    
    alert(`[NODE_INFO: ${type.toUpperCase()}]\\n\\n${info}`);
}

// ============ INICIALIZACIÓN ============
document.addEventListener(\'DOMContentLoaded\', function() {
    // Crear grid de ciudad
    createCityGrid();
    
    // Inicializar simulador
    runSim();
    
    // Efecto de carga terminal
    const terminalPrompt = document.querySelector(\'.terminal-prompt .text-cyan\');
    if(terminalPrompt) {
        const originalText = terminalPrompt.textContent;
        terminalPrompt.textContent = \'\';
        
        let i = 0;
        const typeWriter = () => {
            if(i < originalText.length) {
                terminalPrompt.textContent += originalText.charAt(i);
                i++;
                setTimeout(typeWriter, 60);
            }
        };
        
        setTimeout(typeWriter, 800);
    }
    
    // Configurar estilos dinámicos
    const style = document.createElement(\'style\');
    style.textContent = `
        .cyber-dot {
            width: 12px;
            height: 12px;
            border-radius: 50%;
            display: inline-block;
        }
        
        .trend-chart {
            background: #000;
            border: 2px solid #00f2ff;
            padding: 15px;
            border-radius: 0;
        }
        
        .evolution-card {
            background: rgba(0, 0, 0, 0.5);
            transition: transform 0.3s, box-shadow 0.3s;
        }
        
        .evolution-card:hover {
            transform: translateY(-10px);
            box-shadow: 0 15px 30px rgba(0, 242, 255, 0.3);
        }
        
        .quiz-explanation ul {
            list-style-type: none;
            padding-left: 20px;
        }
        
        .quiz-explanation li {
            margin-bottom: 8px;
            position: relative;
            padding-left: 20px;
        }
        
        .quiz-explanation li::before {
            content: \'▶\';
            color: #39ff14;
            position: absolute;
            left: 0;
        }
    `;
    document.head.appendChild(style);
    
    // Animar elementos de la ciudad
    const core = document.querySelector(\'.urban-core\');
    if(core) {
        core.addEventListener(\'mouseenter\', () => {
            core.style.transform = \'scale(1.05)\';
            core.style.filter = \'brightness(1.3)\';
        });
        
        core.addEventListener(\'mouseleave\', () => {
            core.style.transform = \'scale(1)\';
            core.style.filter = \'brightness(1)\';
        });
    }
});
