<!-- ============ HEADER SECTION COMPACTA ============ -->
<div class="header-section">
    <h1>EPISTEMOLOGÍA DE LA CIENCIA ECOLÓGICA</h1>
    <p class="lead">
        El método científico no es una receta, es un <strong>MECANISMO DE CORRECCIÓN DE ERRORES</strong>. 
        En ecología, donde los sistemas son complejos y estocásticos, el rigor en la falsación es la única 
        defensa contra la pseudociencia.
    </p>
</div>

<!-- ============ DIAGRAMA CIENTÍFICO COMPACTO ============ -->
<div class="svg-container">
    <div class="text-center mb-3">
        <span class="stat-label">LOOP DE RETROALIMENTACIÓN CIENTÍFICA</span>
        <span class="text-muted ms-2">v2.1 - Modelo Popper-Kuhn</span>
    </div>
    
    <svg viewBox="0 0 700 300" xmlns="http://www.w3.org/2000/svg" style="width: 100%; height: 200px;">
        <defs>
            <linearGradient id="gradScience" x1="0%" y1="0%" x2="100%" y2="100%">
                <stop offset="0%" stop-color="#001a33"/>
                <stop offset="50%" stop-color="#004466"/>
                <stop offset="100%" stop-color="#00d4ff"/>
            </linearGradient>
            
            <filter id="glow-compact">
                <feGaussianBlur stdDeviation="2" result="blur"/>
                <feMerge>
                    <feMergeNode in="blur"/>
                    <feMergeNode in="SourceGraphic"/>
                </feMerge>
            </filter>
        </defs>
        
        <!-- Ciclo principal -->
        <path d="M350 50 A120 120 0 1 1 349 50" 
              fill="none" stroke="#21262d" stroke-width="30"/>
        
        <path d="M350 50 A120 120 0 1 1 349 50" 
              fill="none" stroke="url(#gradScience)" stroke-width="2" 
              stroke-dasharray="8 4" filter="url(#glow-compact)">
            <animate attributeName="stroke-dashoffset" values="0;20;0" dur="3s" repeatCount="indefinite"/>
        </path>
        
        <!-- Etapas del método -->
        <g class="science-node" transform="translate(350, 50)">
            <circle r="12" fill="#39ff14" filter="url(#glow-compact)">
                <animate attributeName="r" values="12;14;12" dur="2s" repeatCount="indefinite"/>
            </circle>
            <text y="25" fill="#39ff14" text-anchor="middle" font-family="\'VT323\'" font-size="10" font-weight="bold">
                OBSERVACIÓN
            </text>
        </g>
        
        <g class="science-node" transform="translate(470, 170)">
            <circle r="12" fill="#bc13fe" filter="url(#glow-compact)">
                <animate attributeName="r" values="12;14;12" dur="2.2s" repeatCount="indefinite"/>
            </circle>
            <text x="20" y="5" fill="#bc13fe" font-family="\'VT323\'" font-size="10" font-weight="bold">
                HIPÓTESIS
            </text>
        </g>
        
        <g class="science-node" transform="translate(350, 290)">
            <circle r="12" fill="#ffcc00" filter="url(#glow-compact)">
                <animate attributeName="r" values="12;14;12" dur="2.4s" repeatCount="indefinite"/>
            </circle>
            <text y="-20" fill="#ffcc00" text-anchor="middle" font-family="\'VT323\'" font-size="10" font-weight="bold">
                EXPERIMENTACIÓN
            </text>
        </g>
        
        <g class="science-node" transform="translate(230, 170)">
            <circle r="12" fill="#ff3366" filter="url(#glow-compact)">
                <animate attributeName="r" values="12;14;12" dur="2.6s" repeatCount="indefinite"/>
            </circle>
            <text x="-20" y="5" fill="#ff3366" text-anchor="end" font-family="\'VT323\'" font-size="10" font-weight="bold">
                FALSACIÓN
            </text>
        </g>
        
        <!-- Conexiones de datos -->
        <path d="M350 62 L350 120" stroke="#00d4ff" stroke-width="2" stroke-dasharray="4 2">
            <animate attributeName="stroke-dashoffset" values="0;10;0" dur="1.5s" repeatCount="indefinite"/>
        </path>
        
        <!-- Núcleo de conocimiento -->
        <circle cx="350" cy="170" r="40" fill="#000" stroke="#00d4ff" stroke-width="2"/>
        <circle cx="350" cy="170" r="35" fill="#001a33" opacity="0.9"/>
        
        <text x="350" y="165" fill="#fff" text-anchor="middle" font-family="\'VT323\'" font-size="14" font-weight="bold">
            CONOCIMIENTO
        </text>
        <text x="350" y="180" fill="#8b949e" text-anchor="middle" font-family="\'Courier New\'" font-size="9">
            BASADO EN EVIDENCIA
        </text>
        
        <circle cx="350" cy="170" r="8" fill="#00d4ff">
            <animate attributeName="r" values="8;10;8" dur="1.8s" repeatCount="indefinite"/>
        </circle>
        
        <!-- Título del sistema -->
        <text x="350" y="30" fill="#00d4ff" text-anchor="middle" font-family="\'VT323\'" font-size="16" font-weight="bold">
            MÉTODO CIENTÍFICO
        </text>
        <text x="350" y="45" fill="#bc13fe" text-anchor="middle" font-family="\'Courier New\'" font-size="10">
            Sistema Autocorrectivo de Errores
        </text>
    </svg>
    
    <div class="mt-3 text-center">
        <div class="d-flex justify-content-center flex-wrap gap-3">
            <div class="d-flex align-items-center">
                <div class="cyber-dot bg-green me-1"></div>
                <span class="small text-green">Observación</span>
            </div>
            <div class="d-flex align-items-center">
                <div class="cyber-dot bg-purple me-1"></div>
                <span class="small text-purple">Hipótesis</span>
            </div>
            <div class="d-flex align-items-center">
                <div class="cyber-dot bg-warning me-1"></div>
                <span class="small text-warning">Experimentación</span>
            </div>
            <div class="d-flex align-items-center">
                <div class="cyber-dot bg-pink me-1"></div>
                <span class="small text-pink">Falsación</span>
            </div>
        </div>
    </div>
</div>

<!-- ============ LABORATORIO VIRTUAL COMPACTO ============ -->
<div class="lab-terminal">
    <span class="stat-label">VIRTUAL LAB: ANÁLISIS DE SIGNIFICANCIA ESTADÍSTICA</span>
    
    <div class="terminal-instructions mb-3 p-2 border border-cyan" style="font-size: 11px;">
        <span class="text-cyan">ESCENARIO:</span>
        <span class="text-light ms-1">
            Estás probando si un nuevo fertilizante orgánico aumenta la tasa de fijación de nitrógeno. 
            Si $p < 0.05$, rechazas la hipótesis nula ($H_0$).
        </span>
    </div>
    
    <div class="row align-items-center g-3">
        <div class="col-md-6">
            <!-- Control de variables -->
            <div class="control-group mb-3">
                <label class="stat-label">VARIABILIDAD EN LA MUESTRA (RUIDO)</label>
                <div class="d-flex justify-content-between mb-1">
                    <span class="small text-danger">Baja</span>
                    <span class="small text-warning" id="noiseValue">50%</span>
                    <span class="small text-danger">Alta</span>
                </div>
                <input type="range" class="form-range" id="noiseLevel" min="1" max="100" value="50" oninput="runExperiment()">
                <div class="slider-info mt-1">
                    <span class="small text-muted">Error estándar estimado: </span>
                    <span id="noiseImpact" class="small text-warning">±0.15</span>
                </div>
            </div>
            
            <div class="control-group">
                <label class="stat-label">TAMAÑO DE LA MUESTRA ($n$)</label>
                <div class="d-flex justify-content-between mb-1">
                    <span class="small text-danger">10</span>
                    <span class="small text-warning" id="sampleValue">100</span>
                    <span class="small text-success">1000</span>
                </div>
                <input type="range" class="form-range" id="sampleSize" min="10" max="1000" value="100" oninput="runExperiment()">
                <div class="slider-info mt-1">
                    <span class="small text-muted">Poder estadístico: </span>
                    <span id="powerImpact" class="small text-warning">0.78</span>
                </div>
            </div>
        </div>
        
        <div class="col-md-6">
            <!-- Resultados -->
            <div class="results-display text-center p-3 border border-purple">
                <label class="stat-label">RESULTADO ESTADÍSTICO</label>
                
                <div class="p-value-display mt-2 mb-3">
                    <span class="small text-muted">$p$-value =</span>
                    <span id="pValDisplay" class="h3 ms-1" style="font-family: \'Courier New\'; font-weight: bold;">0.042</span>
                </div>
                
                <div id="resultLabel" class="badge border border-success text-success py-1">
                    <span class="me-1">✓</span> SIGNIFICATIVO
                </div>
                
                <div class="interpretation mt-3">
                    <span id="interpretationText" class="small text-light">
                        $H_0$: No hay efecto del fertilizante<br>
                        $H_1$: El fertilizante aumenta la fijación
                    </span>
                </div>
            </div>
        </div>
    </div>
    
    <!-- Estadísticas adicionales -->
    <div class="stats-grid mt-3">
        <div class="row g-2">
            <div class="col-4">
                <div class="stat-box p-2 border border-cyan text-center">
                    <span class="small text-cyan">Intervalo 95%</span>
                    <div class="small text-light" id="confidenceInterval">[0.02, 0.18]</div>
                </div>
            </div>
            <div class="col-4">
                <div class="stat-box p-2 border border-purple text-center">
                    <span class="small text-purple">Tamaño efecto</span>
                    <div class="small text-light" id="effectSize">d = 0.45</div>
                </div>
            </div>
            <div class="col-4">
                <div class="stat-box p-2 border border-green text-center">
                    <span class="small text-green">Potencia</span>
                    <div class="small text-light" id="statisticalPower">78%</div>
                </div>
            </div>
        </div>
    </div>
</div>

<!-- ============ DESAFÍO DE PENSAMIENTO CRÍTICO ============ -->
<div class="interactive-card">
    <span class="stat-label">DESAFÍO DE PENSAMIENTO CRÍTICO</span>
    
    <div class="quiz-scenario mb-3 p-2 border border-green">
        <span class="text-green">PROBLEMA EPISTEMOLÓGICO:</span>
        <span class="text-light ms-1">
            Karl Popper argumentó que una teoría que "explica todo" no es científica. 
            ¿Por qué la <strong>FALSABILIDAD</strong> es vital en la ecología moderna?
        </span>
    </div>
    
    <div class="quiz-options">
        <button class="list-group-item" onclick="checkMaster(0, this)">
            <span class="step-badge">A</span>
            Porque permite demostrar que una teoría es una verdad absoluta e incuestionable.
        </button>
        
        <button class="list-group-item" onclick="checkMaster(1, this)">
            <span class="step-badge">B</span>
            Porque obliga a los científicos a definir qué evidencia, de existir, probaría que su hipótesis es errónea.
        </button>
        
        <button class="list-group-item" onclick="checkMaster(2, this)">
            <span class="step-badge">C</span>
            Porque asegura que todos los experimentos den resultados positivos y confirmen las predicciones.
        </button>
        
        <button class="list-group-item" onclick="checkMaster(3, this)">
            <span class="step-badge">D</span>
            Porque simplifica el proceso científico al eliminar la necesidad de replicación experimental.
        </button>
    </div>
    
    <div id="quizFeedback" class="mt-3" style="display: none;">
        <!-- Se llena con JavaScript -->
    </div>
    
    <!-- Explicación -->
    <div class="explanation-box mt-3 p-2 border border-cyan" style="display: none;" id="quizExplanation">
        <span class="text-cyan small">EXPLICACIÓN FILOSÓFICA:</span>
        <div class="mt-1">
            <p class="small text-light mb-1">
                Según Popper, una teoría científica debe hacer <strong>predicciones arriesgadas</strong> 
                que puedan ser refutadas por la evidencia empírica. Las teorías no falsables:
            </p>
            <ul class="small text-light mb-0">
                <li>No pueden ser sometidas a prueba empírica</li>
                <li>Se ajustan a cualquier observación (ej: astrología)</li>
                <li>Impiden el progreso científico</li>
            </ul>
        </div>
    </div>
</div>

<!-- ============ CONCLUSIÓN SISTÉMICA ============ -->
<div class="footer-note">
    <div class="d-flex">
        <span class="text-purple me-2">⚠</span>
        <div>
            <p class="small mb-1">
                <strong>CONCLUSIÓN SISTÉMICA:</strong> El método científico en 2025 integra 
                Inteligencia Artificial y Big Data, pero el núcleo permanece igual: la curiosidad 
                humilde ante la complejidad del ecosistema y el rechazo a la validación sin evidencia robusta.
            </p>
            <div class="mt-1">
                <span class="badge border border-cyan text-cyan me-1">RIGOR</span>
                <span class="badge border border-purple text-purple me-1">TRANSPARENCIA</span>
                <span class="badge border border-green text-green">REPLICABILIDAD</span>
            </div>
        </div>
    </div>
</div>

</div>

<!-- ============ JAVASCRIPT COMPACTO ============ -->
<script>
// ============ LABORATORIO VIRTUAL ============
function runExperiment() {
    // Obtener valores
    const noise = parseInt(document.getElementById(\'noiseLevel\').value);
    const sample = parseInt(document.getElementById(\'sampleSize\').value);
    
    // Actualizar valores mostrados
    document.getElementById(\'noiseValue\').textContent = noise + \'%\';
    document.getElementById(\'sampleValue\').textContent = sample;
    
    // Cálculo del p-value (modelo simplificado)
    // Más ruido → p más alto, más muestra → p más bajo
    let p = (noise / sample) * 0.5;
    p = Math.min(Math.max(p, 0.001), 0.999);
    
    // Actualizar display del p-value
    const pDisplay = document.getElementById(\'pValDisplay\');
    pDisplay.textContent = p.toFixed(3);
    
    // Actualizar interpretación
    const resultLabel = document.getElementById(\'resultLabel\');
    const interpretation = document.getElementById(\'interpretationText\');
    
    if (p < 0.05) {
        // Resultado significativo
        pDisplay.style.color = "#39ff14";
        resultLabel.innerHTML = \'<span class="me-1">✓</span> SIGNIFICATIVO\';
        resultLabel.className = \'badge border border-success text-success py-1\';
        interpretation.innerHTML = \'$H_0$ <span class="text-danger">Rechazada</span><br>$H_1$ <span class="text-success">Aceptada</span>\';
    } else {
        // Resultado no significativo
        pDisplay.style.color = "#ff3366";
        resultLabel.innerHTML = \'<span class="me-1">✗</span> NO SIGNIFICATIVO\';
        resultLabel.className = \'badge border border-danger text-danger py-1\';
        interpretation.innerHTML = \'$H_0$ <span class="text-success">Mantenida</span><br>$H_1$ <span class="text-danger">No soportada</span>\';
    }
    
    // Actualizar estadísticas adicionales
    updateStatistics(noise, sample, p);
    
    // Efecto visual en el p-value
    pDisplay.style.transform = \'scale(1.1)\';
    setTimeout(() => pDisplay.style.transform = \'scale(1)\', 200);
}

function updateStatistics(noise, sample, p) {
    // Calcular estadísticas derivadas
    const ciLower = Math.max(0, p - 0.1).toFixed(2);
    const ciUpper = Math.min(1, p + 0.1).toFixed(2);
    const effectSize = (0.5 - (noise / 200)).toFixed(2);
    const power = Math.min(99, (sample / 1000 * 100)).toFixed(0);
    
    // Actualizar displays
    document.getElementById(\'confidenceInterval\').textContent = `[${ciLower}, ${ciUpper}]`;
    document.getElementById(\'effectSize\').textContent = `d = ${effectSize}`;
    document.getElementById(\'statisticalPower\').textContent = `${power}%`;
    
    // Actualizar impactos
    document.getElementById(\'noiseImpact\').textContent = `±${(noise/100).toFixed(2)}`;
    document.getElementById(\'powerImpact\').textContent = `0.${power}`;
}

// ============ QUIZ INTERACTIVO ============
function checkMaster(idx, btn) {
    const feedback = document.getElementById(\'quizFeedback\');
    const explanation = document.getElementById(\'quizExplanation\');
    const buttons = document.querySelectorAll(\'.list-group-item\');
    
    // Remover selecciones anteriores
    buttons.forEach(b => {
        b.classList.remove(\'selected-correct\', \'selected-incorrect\');
    });
    
    // Mostrar feedback
    feedback.style.display = "block";
    explanation.style.display = "block";
    
    if (idx === 1) {
        // Respuesta correcta
        btn.classList.add(\'selected-correct\');
        feedback.innerHTML = `
            <div class="alert-success p-2 border border-green">
                <div class="d-flex align-items-start">
                    <span class="text-green me-2">✓</span>
                    <div>
                        <strong class="text-green small">CORRECTO</strong>
                        <div class="mt-1 small text-light">
                            Exactamente. La falsabilidad requiere que las hipótesis hagan predicciones 
                            específicas que puedan ser contrastadas empíricamente. Si nada puede refutarlas, 
                            no son científicas.
                        </div>
                    </div>
                </div>
            </div>
        `;
    } else {
        // Respuesta incorrecta
        btn.classList.add(\'selected-incorrect\');
        feedback.innerHTML = `
            <div class="alert-danger p-2 border border-danger">
                <div class="d-flex align-items-start">
                    <span class="text-danger me-2">✗</span>
                    <div>
                        <strong class="text-danger small">ERROR CONCEPTUAL</strong>
                        <div class="mt-1 small text-light">
                            La ciencia no busca verdades absolutas (A) ni solo confirmaciones (C). 
                            La falsabilidad hace a la ciencia <strong>autocorrectiva</strong>.
                        </div>
                    </div>
                </div>
            </div>
        `;
    }
    
    // Efecto visual
    if(idx === 1) {
        btn.style.animation = \'pulse-blue-fast 0.3s\';
    } else {
        btn.style.animation = \'blink-fast 0.3s\';
    }
    
    setTimeout(() => btn.style.animation = \'\', 300);
}

// ============ INTERACTIVIDAD SVG ============
function initScienceNodes() {
    const nodes = document.querySelectorAll(\'.science-node\');
    
    nodes.forEach(node => {
        node.addEventListener(\'mouseenter\', function() {
            this.style.transform += \' scale(1.1)\';
            this.style.filter = \'brightness(1.3)\';
        });
        
        node.addEventListener(\'mouseleave\', function() {
            this.style.transform = this.style.transform.replace(\' scale(1.1)\', \'\');
            this.style.filter = \'brightness(1)\';
        });
        
        node.addEventListener(\'click\', function() {
            const stages = {
                0: \'OBSERVACIÓN: Recopilación sistemática de datos empíricos\',
                1: \'HIPÓTESIS: Explicación provisional que hace predicciones\',
                2: \'EXPERIMENTACIÓN: Prueba controlada de las predicciones\',
                3: \'FALSACIÓN: Intento de refutación mediante evidencia\'
            };
            
            const index = Array.from(nodes).indexOf(this);
            alert(`[STAGE_INFO: ${index+1}/4]\\n\\n${stages[index]}`);
        });
    });
}

// ============ INICIALIZACIÓN ============
document.addEventListener(\'DOMContentLoaded\', function() {
    // Inicializar laboratorio
    runExperiment();
    
    // Inicializar interactividad
    initScienceNodes();
    
    // Efecto de terminal
    const terminal = document.querySelector(\'.terminal-prompt .text-cyan\');
    if(terminal) {
        const text = terminal.textContent;
        terminal.textContent = \'\';
        
        let i = 0;
        const type = () => {
            if(i < text.length) {
                terminal.textContent += text.charAt(i);
                i++;
                setTimeout(type, 40);
            } else {
                terminal.innerHTML += \'<span class="blink">_</span>\';
            }
        };
        
        setTimeout(type, 300);
    }
    
    // Configurar estilos dinámicos
    const style = document.createElement(\'style\');
    style.textContent = `
        .cyber-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            display: inline-block;
        }
        
        .bg-green { background-color: #39ff14 !important; }
        .bg-purple { background-color: #bc13fe !important; }
        .bg-warning { background-color: #ffcc00 !important; }
        .bg-pink { background-color: #ff3366 !important; }
        .bg-cyan { background-color: #00d4ff !important; }
        
        .text-warning { color: #ffcc00 !important; }
        
        .alert-success {
            background: rgba(57, 255, 20, 0.1) !important;
            border-color: #39ff14 !important;
        }
        
        .alert-danger {
            background: rgba(255, 51, 102, 0.1) !important;
            border-color: #ff3366 !important;
        }
        
        .control-group {
            background: rgba(0, 0, 0, 0.5);
            padding: 10px;
            border: 1px solid #30363d;
        }
        
        .results-display {
            background: rgba(0, 0, 0, 0.7);
        }
        
        .stat-box {
            background: rgba(0, 0, 0, 0.5);
        }
        
        .explanation-box {
            background: rgba(0, 20, 40, 0.8);
        }
        
        .explanation-box ul {
            list-style-type: none;
            padding-left: 15px;
            margin-bottom: 0;
        }
        
        .explanation-box li {
            margin-bottom: 2px;
            position: relative;
            padding-left: 12px;
        }
        
        .explanation-box li::before {
            content: \'▶\';
            color: #39ff14;
            position: absolute;
            left: 0;
            font-size: 10px;
        }
        
        .p-value-display {
            font-family: \'Courier New\', monospace;
        }
    `;
    document.head.appendChild(style);
});
</script>',
    'ejercicios' => 
    array (
      0 => 
      array (
        'enunciado' => 'Plantea una hipótesis falsable para el fenómeno de la disminución de abejas en una zona agrícola.',
        'respuesta' => 'Si el uso de neonicotinoides reduce la capacidad de navegación de las abejas, entonces las colonias expuestas a 10ppm del pesticida mostrarán un 30% menos de retorno al panal que el grupo control.',
      ),
      1 => 
      array (
        'enunciado' => 'Diferencia entre Variable Independiente y Dependiente en un estudio de acidificación oceánica sobre corales.',
        'respuesta' => 'Independiente: Nivel de pH del agua (manipulado). Dependiente: Tasa de calcificación del esqueleto del coral (medido).',
      ),
      2 => 
      array (
        'enunciado' => '¿Por qué es necesario un "Grupo Control"?',
        'respuesta' => 'Para establecer una línea base que permita asegurar que los cambios observados en el grupo experimental se deben a la variable independiente y no a factores externos.',
      ),
      3 => 
      array (
        'enunciado' => 'Calcula el grado de libertad ($df$) para un t-test de dos muestras independientes con $n_1=25$ y $n_2=25$.',
        'respuesta' => '$df = (n_1 + n_2) - 2 = (25+25)-2 = 48$.',
      ),
      4 => 
      array (
        'enunciado' => 'Explica el concepto de "Revisión por Pares" (Peer Review).',
        'respuesta' => 'Proceso donde expertos independientes evalúan el rigor, la metodología y la validez de un estudio antes de su publicación para garantizar la calidad científica.',
      ),
      5 => 
      array (
        'enunciado' => '¿Qué ocurre si los datos de un experimento contradicen la hipótesis original?',
        'respuesta' => 'La hipótesis se rechaza o se refina, y se inicia un nuevo ciclo del método científico; esto no es un fracaso, sino progreso.',
      ),
      6 => 
      array (
        'enunciado' => 'Define "Muestreo Aleatorio" y su importancia.',
        'respuesta' => 'Técnica donde cada individuo de la población tiene la misma probabilidad de ser elegido; evita sesgos y permite generalizar resultados.',
      ),
